import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "psalmody-midnight-sunday",
    title: { en: "Sunday Midnight Praises", ar: "تسبحة نصف الليل ليوم الأحد" },
    blocks: [
      { kind: 'note', text: { en: "The complete fixed annual Sunday (Adam) Midnight Psalmody.", ar: "النصوص الثابتة الكاملة للإبصلمودية السنوية لنصف الليل ليوم الأحد (آدام)." } },
      { kind: 'heading', text: { en: "Ten-theno", ar: "تين ثينو" } },
      { kind: 'prayer', text: { en: "Arise O children of the light, let us praise the Lord of hosts.", ar: "قوموا يا بني النور، لنسبح رب القوات." } },
      { kind: 'prayer', text: { en: "That He may grant us the salvation of our souls.", ar: "لكي ينعم لنا بخلاص نفوسنا." } },
      { kind: 'prayer', text: { en: "Whenever we stand before You in the flesh.", ar: "عندما نقف أمامك جسدياً." } },
      { kind: 'prayer', text: { en: "Cast away from our minds the slumber of sleep.", ar: "إنزع عن عقولنا نوم الغفلة." } },
      { kind: 'prayer', text: { en: "Grant us sobriety O Lord, that we may know how to stand before You at times of prayer.", ar: "أعطنا يا رب يقظة، لكي نفهم أن نقف أمامك وقت الصلاة." } },
      { kind: 'prayer', text: { en: "And ascribe unto You the befitting glorification, and win the forgiveness of our many sins. Glory be to You O Lover of Mankind.", ar: "ونرسل لك إلى فوق التمجيد اللائق، ونفوز بغفران خطايانا الكثيرة. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Behold bless the Lord all you servants of the Lord. Glory be to You O Lover of Mankind.", ar: "ها باركوا الرب يا عبيد الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "You who stand in the house of the Lord, in the courts of the house of our God. Glory be to You O Lover of Mankind.", ar: "القائمين في بيت الرب، في ديار بيت إلهنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "By night lift up your hands O you saints and bless the Lord. Glory be to You O Lover of Mankind.", ar: "بالليالي إرفعوا أيديكم إلى فوق أيها القديسون باركوا الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "The Lord bless you from Zion, who created heaven and earth. Glory be to You O Lover of Mankind.", ar: "يباركك الرب من صهيون، الذي خلق السماء والأرض. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my cry come before You O Lord, give me understanding according to Your word. Glory be to You O Lover of Mankind.", ar: "فلتدن وسيلتي قدامك يا رب، كقولك فهمني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my supplication come before You, deliver me according to Your word. Glory be to You O Lover of Mankind.", ar: "ليدخل إبتهالي أمامك، ككلمتك أحيني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My lips shall overflow with praise, when You have taught me Your statutes. Glory be to You O Lover of Mankind.", ar: "تفيض شفتاي السُبح، إذا ما علمتني حقوقك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My tongue shall speak of Your words for all Your commandments are righteous. Glory be to You O Lover of Mankind.", ar: "لساني يجيب بأقوالك لأن جميع وصاياك هي حق. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let Your hand help me for I have chosen Your precepts. Glory be to You O Lover of Mankind.", ar: "لتكن يدك لتخلصني لأني إشتهيت وصاياك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have longed for Your salvation O Lord, and Your Law is my delight. Glory be to You O Lover of Mankind.", ar: "إشتقت إلى خلاصك يا رب، وناموسك هو تلاوتي. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my soul live and it shall praise You, and let Your judgments help me. Glory be to You O Lover of Mankind.", ar: "تحيا نفسي وتسبحك، وأحكامك تعينني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have gone astray like a lost sheep, seek Your servant for I do not forget Your commandments. Glory be to You O Lover of Mankind.", ar: "ضللت مثل الخروف الضال، فأُطلب عبدك لأني لوصاياك لم أنس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Now and forever and unto the age of all ages Amen. Glory be to You O Lover of Mankind.", ar: "الآن وكل أوان وإلى دهر الدهور آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit, now and forever and unto all the ages Amen. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس منذ الآن وإلى أبد الأبدين كلها آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O good One the Lover of Mankind, glory be to Your Mother the Virgin and all Your saints. Glory be to You O Lover of Mankind.", ar: "المجد لك يا محب البشر الصالح، المجد لأُمك العذراء وجميع قديسيك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O only-begotten One, O holy Trinity have mercy upon us. Glory be to You O Lover of Mankind.", ar: "المجد لك أيها الوحيد، أيها الثالوث القدوس إرحمنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let God arise and let all His enemies be scattered and let all that hate His holy name flee from before His face. Glory be to You O Lover of Mankind.", ar: "ليقم الله ولتتبدَّد جميع أعدائه وليهرب من قدام وجهه كل مُبغضي إسمه القدوس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "As for Your people let them be blessed, a thousand thousand fold and ten thousand ten thousand fold, doing Your will.", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادتك." } },
      { kind: 'prayer', text: { en: "O Lord open my lips, and my mouth shall declare Your praise.", ar: "يا رب إفتح شفتيَ ولينطق فمي بتسبحتك." } },
      { kind: 'heading', text: { en: "The First Hoos", ar: "الهوس الأول" } },
      { kind: 'hymn', text: { en: "Then Moses and the children of Israel sang this song to the Lord and spoke saying, \"I will sing to the Lord for He has triumphed gloriously.\"", ar: "حينئذ سبح موسى وبنو إسرائيل بهذه التسبحة للرب وقالوا، \"فلنسبح للرب لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider He has thrown into the sea. The Lord is my strength and song, and He has become my salvation.", ar: "الفَرس وراكبه طرحهما في البحر. مُعيني وساتري، صار لي خلاصاً." } },
      { kind: 'hymn', text: { en: "He is my God and I will glorify Him, my father´s God and I will exalt Him.", ar: "هذا هو إلهي فأمجده، إله أبي فأرفعه." } },
      { kind: 'hymn', text: { en: "The Lord is a Man of war, the Lord is His name. Pharaoh's chariots and his army He has cast into the sea.", ar: "الرب مكسر الحروب، الرب إسمه. مركبات فرعون وكل قوته طرحهما في البحر." } },
      { kind: 'hymn', text: { en: "His chosen captains also are drowned in the Red Sea.", ar: "ركباناً منتخبين ذي ثلاث جنبات غرقهم في البحر الأحمر." } },
      { kind: 'hymn', text: { en: "The depths have covered them; they sank to the bottom as a stone.", ar: "غطاهم الماء، إنغمسوا إلى العمق مثل الحجر." } },
      { kind: 'hymn', text: { en: "Your right hand O Lord has become glorious in power. Your right hand O Lord has dashed the enemy in pieces.", ar: "يمينك يا رب تمجدت بالقوة. يدك اليمنى يا إلهي أهلكت أعداءك." } },
      { kind: 'hymn', text: { en: "And in the greatness of Your excellence, You have overthrown those who rose up against You, You sent forth Your wrath, it consumed them like stubble.", ar: "بكثرة مجدك، سحقت الذين يقاوموننا، أرسلت غضبك، فأكلهم مثل الهشيم." } },
      { kind: 'hymn', text: { en: "And with the blast of Your nostrils the waters were gathered together, the flood stood upright like a wall, and the depths were congealed in the heart of the sea.", ar: "وبروح غضبك وقف الماء، وإرتفعت الماء مثل السور، وجمدت الأمواج في وسط البحر." } },
      { kind: 'hymn', text: { en: "The enemy said, \"I will pursue, I will overtake, I will divide the spoil, my lust shall be satisfied upon them, I will draw my sword and my hand shall destroy them.\"", ar: "قال العدو، \"إني أسرع فأدرك، وأقسم الغنائم، وأشبع نفسي، وأقتل بسيفي ويدي تتسلط.\"" } },
      { kind: 'hymn', text: { en: "You blew with Your wind, the sea covered them, they sank like lead in the mighty waters.", ar: "أرسلت روحك، فغطاهم البحر، وغطسوا إلى أسفل كالرصاص في مياه كثيرة." } },
      { kind: 'hymn', text: { en: "Who is like You O Lord among the gods? Who is like You, glorified in His saints, amazing in glory, performing wonders.", ar: "من يشبهك في الآلهة. يا رب من يشبهك، مُمجداً في قديسيك، متعجباً منك بالمجد، صانعاً عجائب." } },
      { kind: 'hymn', text: { en: "You stretched out Your right hand, the earth swallowed them. You in Your mercy have led forth the people whom You have redeemed, You have guided them in Your strength, to Your holy habitation.", ar: "مددت يمينك فإبتلعتهم الأرض. هديت شعبك بالحقيقة، هذا الذي إخترته، وقويته بتعزيتك، إلى موضع راحة قدسك." } },
      { kind: 'hymn', text: { en: "The people will hear and be afraid, sorrow will take hold of the inhabitants of Palestine.", ar: "سمعت الأمم وغضبت، والمخاض أخذ سكان فلسطين." } },
      { kind: 'hymn', text: { en: "Then the dukes of Edom will be amazed, the mighty men of Moab trembling will take hold of them.", ar: "حينئذ أسرع وُلاة أدوم، ورؤساء المؤابيين أخذتهم الرعدة." } },
      { kind: 'hymn', text: { en: "All the inhabitants of Canaan will melt away, fear and dread will fall on them.", ar: "ذاب كل سكان كنعان، وأتت عليهم الرعدة والخوف." } },
      { kind: 'hymn', text: { en: "By the greatness of Your arm they will be as still as stone, till Your people pass over O Lord, till Your people pass over whom You have purchased.", ar: "بكثرة ساعدك فليصيروا كالحجر، حتى يجتاز شعبك يا رب، حتى يجتاز شعبك هذا الذي إقتنيته." } },
      { kind: 'hymn', text: { en: "You will bring them in and plant them in the mountain of Your inheritance, in the place O Lord, which You have made for You to dwell in.", ar: "أدخلهم وأغرسهم على جبل ميراثك، وفي مسكنك المُعَد، هذا الذي صنعته يا رب." } },
      { kind: 'hymn', text: { en: "In Your sanctuary O Lord which Your hands have established, the Lord shall reign forever and ever.", ar: "موضعك المقدس يا رب الذي أعددته يداك، يا رب تمَلُك منذ الأزل والآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "For the horses of pharaoh went with his chariots and his horsemen into the sea.", ar: "لأنه قد دخل إلى البحر خيل فرعون ومركباته وفرسانه." } },
      { kind: 'hymn', text: { en: "And the Lord brought back the waters of the sea upon them, but the children of Israel went on dry land in the midst of the sea.", ar: "والرب غمرهم بماء البحر، أما بنو إسرائيل فكانوا يمشون على اليابسة في وسط البحر." } },
      { kind: 'hymn', text: { en: "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand, and all the women went out after her with timbrels and with praises.", ar: "فأخذت مريم النبية، أخت هرون، الدُف بيديها، وخرج في إثرها جميع النسوة بالدُفوف والتسابيح." } },
      { kind: 'hymn', text: { en: "And Miriam answered them saying, \"Sing to the Lord, for He has triumphed gloriously.\"", ar: "وبدأت مريم في مقدمتهنَّ تقول، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider, He has thrown into the sea. \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "الفرس ورُاكب الفرس، طرحهما في البحر. \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'heading', text: { en: "The First Hoos Lobsh", ar: "لبش الهوس الأول" } },
      { kind: 'hymn', text: { en: "With the split, the waters of the sea split, and the very deep, became a walkway.", ar: "قطعاً إنقطع، ماء البحر، والعمق العميق، صار مَسلكاً." } },
      { kind: 'hymn', text: { en: "A hidden earth, was shone upon by the sun, and an untrodden road, was walked upon.", ar: "أرض غير ظاهرة، أشرقت الشمس عليها، وطريق غير مسلوكة، مشوا عليها." } },
      { kind: 'hymn', text: { en: "The flowing water, stood still, by a miraculous, act of wonder.", ar: "ماء مُنحل، وقف، بفِعل عجيب، مُعِجز." } },
      { kind: 'hymn', text: { en: "Pharaoh and his chariots, were drowned, and the children of Israel, crossed the sea.", ar: "غرق فرعون، ومركباته، وعبر بنو إسرائيل، البحر." } },
      { kind: 'hymn', text: { en: "And in front of them was, Moses the prophet praising, until he brought them, to the wilderness of Sinai.", ar: "وكان موسى النبي، يسبح قدامهم، حتى أدخلهم، برية سيناء." } },
      { kind: 'hymn', text: { en: "And they were praising God, with this new psalmody, saying \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "وكانوا يسبحون الله، بهذه التسبحة الجديدة قائلين، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "Through the prayers, of Moses the archprophet, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، موسى رئيس الأنبياء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع أبيك الصالح، والروح القدس، لأنك (قُمتأتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Second Hoos", ar: "الهوس الثاني" } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord for He is good, Alleluia His mercy endures forever.", ar: "أُشكروا الرب لأنه صالح وخيِّر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of gods, Alleluia His mercy endures forever.", ar: "أُشكروا إله الآلهة، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords, Alleluia His mercy endures forever.", ar: "أُشكروا رب الأرباب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who alone does great wonders, Alleluia His mercy endures forever.", ar: "الصانع العجائب العظام وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who by wisdom made the heavens, Alleluia His mercy endures forever.", ar: "الذي خلق السموات بفهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who stretched out the earth above the waters, Alleluia His mercy endures forever.", ar: "الذي ثبَّت الأرض على المياه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who made great lights, Alleluia His mercy endures forever.", ar: "الذي خلق نيرين عظيمين وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The sun to rule by day, Alleluia His mercy endures forever.", ar: "الشمس لحكم النهار، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The moon and stars to rule by night, Alleluia His mercy endures forever.", ar: "القمر والنجوم لحكم الليل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote Egypt in their firstborn, Alleluia His mercy endures forever.", ar: "الذي ضرب المصريين مع أبكارهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And brought out Israel from among them, Alleluia His mercy endures forever.", ar: "وأخرج إسرائيل من وسطهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "With a strong hand and with a stretched out arm, Alleluia His mercy endures forever.", ar: "بيد عزيزة وذراع عالية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who divided the Red Sea into parts, Alleluia His mercy endures forever.", ar: "الذي شق البحر الأحمر إلى أقسام، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And made Israel to pass through the midst of it, Alleluia His mercy endures forever.", ar: "وأجاز إسرائيل في وسطه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "But overthrew pharaoh and his hosts in the Red Sea, Alleluia His mercy endures forever.", ar: "وطرح فرعون وكل قوته في البحر الأحمر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who led His people through the wilderness, Alleluia His mercy endures forever.", ar: "الذي أخرج شعبه إلى البرية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who retrieved water from a rock, Alleluia His mercy endures forever.", ar: "الذي أخرج ماء من صخرة صماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote great kings, Alleluia His mercy endures forever.", ar: "الذي ضرب ملوكاً عُظماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And slew famous kings, Alleluia His mercy endures forever.", ar: "وقتل ملوكاً عجيبين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Sihon the king of the Amorites, Alleluia His mercy endures forever.", ar: "سيحون ملك الأموريين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And Og the king of Bashan, Alleluia His mercy endures forever.", ar: "وعوج ملك باشان، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And gave their lands for a heritage, Alleluia His mercy endures forever.", ar: "أعطى أرضهم ميراثاً، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "A heritage unto Israel His servant, Alleluia His mercy endures forever.", ar: "ميراثاً لعبده إسرائيل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who remembered us in our low estate, Alleluia His mercy endures forever.", ar: "في تواضعنا ذكرنا الرب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And has redeemed us from our enemies, Alleluia His mercy endures forever.", ar: "وخلصنا من أيدي أعدائنا، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who gives food to all flesh, Alleluia His mercy endures forever.", ar: "الذي يعطي طعاماً لكل جسد حي، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of heaven, Alleluia His mercy endures forever.", ar: "إحمدوا إله السماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords for He is good, Alleluia His mercy endures forever.", ar: "إحمدوا رب الأرباب لأنه طيب وصالح، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'heading', text: { en: "The Second Hoos Lobsh", ar: "لبش الهوس الثاني" } },
      { kind: 'hymn', text: { en: "Let us give thanks, to Christ our God, with David the prophet, and psalmist.", ar: "فلنشكر، المسيح إلهنا، مع المرتل، داود النبي." } },
      { kind: 'hymn', text: { en: "For He has made the heavens, and all its hosts, and established the earth, on the waters.", ar: "لأنه خلق السموات، وجنودها، وأسَّس الأرض، على المياه." } },
      { kind: 'hymn', text: { en: "These two great stars, the sun and the moon, He has made to enlighten, the firmament.", ar: "هذان الكوكبان العظيمان، الشمس والقمر، جعلهما ينيران، في الفلك." } },
      { kind: 'hymn', text: { en: "He brought forth the winds, out of His treasure box, He breathed unto the trees, and they blossomed.", ar: "أخرج الرياح، من خباياها، نفخ في الأشجار، حتى أزهرت." } },
      { kind: 'hymn', text: { en: "He caused the rain to fall, upon the face of the earth, and it sprouted, and gave its fruit.", ar: "أمطرا مطراً، على وجه الأرض، حتى أنبتت، وأعطت ثمرها." } },
      { kind: 'hymn', text: { en: "He brought forth water, out of a rock, and gave it to His people, in the wilderness.", ar: "أخرج ماء، من صخرة صماء، وسقى شعبه، في البرية." } },
      { kind: 'hymn', text: { en: "He made man, in His image, and His likeness, that he may praise Him.", ar: "صنع الإنسان، كشبهه، وصورته، لكي يباركه." } },
      { kind: 'hymn', text: { en: "Let us praise Him, and exalt His name, and give thanks to Him, His mercy endures forever.", ar: "فلنسبحه، ونرفع إسمه، ونشكره لأن رحمته، كائنة إلى الأبد." } },
      { kind: 'hymn', text: { en: "Through the prayers, of David the psalmist, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، المرتل داود، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله، القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of all the heavenly hosts, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، كل صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Blessed are You indeed, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "مبارك أنت بالحقيقة، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Third Hoos", ar: "الهوس الثالث" } },
      { kind: 'hymn', text: { en: "Blessed are You O Lord God of our fathers, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الرب إله أبائنا، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed is Your holy name and Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك إسم مجدك القدوس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the holy temple of Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في هيكل مجدك المقدس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You who beholds the depths and sits upon the Cherubim, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الناظر إلى الأعماق الجالس على الشاروبيم، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You on the throne of Your kingdom, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت على عرش مُلكك، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the firmament of heaven, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في فلك السماء، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you works of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع أعمال الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السموات، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you angels of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا جميع ملائكة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you waters above the heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع المياه التي فوق السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you powers of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع قوات الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O sun and moon, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها الشمس والقمر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you stars of heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا سائر نجوم السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you rain and dew, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأمطار مع الأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you clouds and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السُحب والرياح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you spirits, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع الأرواح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O fire and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها النار والحرارة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O cold and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والحر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you dew and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأهوية والأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you nights and days, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الليالي والأيام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O light and darkness, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها النور والظلمة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O frost and cold, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والصقيع، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O snow and ice, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها الجليد والثلج، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you lightnings and clouds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البروق والسحب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all the earth, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأرض كلها، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you mountains and all hills, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الجبال وجميع الآكام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you things that spring up on the earth, praise Him and exalt Him above all forever.", ar: "بارك الرب يا جميع ما يَنبت على وجه الأرض، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you fountains, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الينابيع، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you seas and rivers, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البحار والأنهار، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you whales and all that moves in the waters, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الحيتان وجميع ما يتحرك في الماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you birds of the sky, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع طيور السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you wild beasts and cattle, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الوحوش وكل البهائم، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you sons of men, worship the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا بني البشر، وأُسجدوا للرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Israel, praise Him and exalt Him above all forever.", ar: "بارك الرب يا إسرائيل، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you priests of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا كهنة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you servants of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عبيد الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you spirits and souls of the just, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا أرواح وأنفس الصديقين، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you holy and humble of heart, praise Him and exalt Him above all forever.", ar: "باركوا الرب أيها القديسون والمتواضعو القلوب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all\nforever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "The Third Hoos — Esmo Epchois", ar: "الهوس الثالث — إسمو إبشويس" } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "Psali for the Three Saintly Children", ar: "إبصالية للثلاثة فتية القديسين" } },
      { kind: 'hymn', text: { en: "O sing unto Him who was crucified, buried and resurrected, who trampled and abolished death, praise Him and exalt Him above all.\nTake off the old man, and put on the new and superior one, come closer to greatness of mercy, praise Him and exalt Him above all.", ar: "رتلوا للذي صُلب عنا، وقُبر وقام، وأبطل الموت وأهانه، سبحوه وزيدوه علواً.\nإخلعوا الإنسان العتيق، وألبسوا الجديد الفاخر، وإقتربوا إلى عِظَم الرحمة، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "All you Christian people, the priests and the deacons, glorify the Lord for He is worthy, praise Him and exalt Him above all.\nCome to us O three children, whom Christ our God has lifted, and from the Devil has delivered, praise Him and exalt Him above all.", ar: "يا جنس المسيحيين، القسوس والشمامسة، أعطوا مجداً للرب لأنه مستوجب، سبحوه وزيدوه علواً.\nهَلُمَّ إلينا أيها الثلاثة فتية، الذين رفعهم المسيح إلهنا، وأنقذهم من إبليس، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "For the sake of your God the Messiah, the Giver of all good things, come unto us O Hananiah, praise Him and exalt Him above all.\nO Azariah the zealot, morning and noon and the evening, glorify the power of the Trinity, praise Him and exalt Him above all.", ar: "من أجل إلهك ماسيا، المانح الإحسان، هَلُمَّ إلينا يا حنانيا، سبحوه وزيدوه علواً.\nيا عزاريا الغيور، عشية وبكرة والظهيرة، أعط مجداً لقوة الثالوث، سبّحه وزده علواً." } },
      { kind: 'hymn', text: { en: "Behold Emmanuel [our Lord], is now in our midst O Mishael, proclaim with the voice of joy, praise Him and exalt Him above all.\nGather now and persevere, and proclaim with the priests, bless the Lord all His works, praise Him and exalt Him above all.", ar: "فها هوذا عمانوئيل، في وسطنا يا ميصائيل، تكلم بصوت التهليل، سبّحه وزده علواً.\nإجتمعوا وثابروا جميعاً، تكلموا مع القسوس، وسبحي الرب يا جميع أعماله، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "The heavens declare the glory, of God until this day, O you angels whom He has made, praise Him and exalt Him above all.\nNow all you powers of the Lord, bless His honored name, O sun and moon and all the stars, praise Him and exalt Him above all.", ar: "ها السموات تنطق بمجد الله، إلى هذا اليوم، يا أيها الملائكة الذين أنشأهم، سبحوه وزيدوه علواً.\nوالآن يا قوات الرب، باركوا إسمه الكريم، أيتها الشمس والقمر والنجوم، سبحيه وزيديه علواً." } },
      { kind: 'hymn', text: { en: "And also you rain and dew, sing praises unto our Savior, for He is the God of our fathers, praise Him and exalt Him above all.\nGlorify the Lord O clouds and winds, together with the souls and the spirits, O you cold and fire and heat, praise Him and exalt Him above all.", ar: "وأيضاً أيتها الأمطار والأنداء، إمدحي مخلصنا، لأنه هو إله آبائنا، سبحيه وزيديه علواً.\nأعطي مجداً أيتها السحب معاً، والأهوية والنفوس والأرواح، والبرد والنار والحرارة، سبحيه وزيده علوا." } },
      { kind: 'hymn', text: { en: "You also nights and days, light and darkness and lightning, glorify the Lover of Mankind, praise Him and exalt Him above all.\nYou trees and all that springs on the earth, and all that moves in the sea, mountains and the forests, praise Him and exalt Him above all.", ar: "أيتها الليالي والأيام أيضاً، والنور والظلمة والبروق، قائلة المجد لك يا محب البشر، سبحوه وزيدوه علواً.\nأيتها الأشجار وجميع ما ينبُت، في الأرض وكل ما يتحرك، في المياه والجبال والغياض، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Praise without ceasing, the Lord the King of the kings, O you rivers and seas, praise Him and exalt Him above all.\nAnd we also seeing them, let us say with all these things, bless the Lord all you birds, praise Him and exalt Him above all.", ar: "وأيضاً سبحي بغير فتور، الرب ملك الملوك، أيتها البحار والأنهار، سبحيه وزيديه علواً.\nهكذا نحن إذ ننظر إليهم، فلنقل مع هذه الموجودات جميعها، باركي الرب يا جميع الطيور، سبحيه وزيده علواً." } },
      { kind: 'hymn', text: { en: "O snow and ice, cattle and wild beasts, bless the Lord of lords, praise Him and exalt Him above all.\nBless the Lord as befits Him, and not like the heretics, all you sons of men, praise Him and exalt Him above all.", ar: "أيها الجليد والثلج، والبهائم والوحوش، باركي رب الأرباب، سبحيه وزيديه علواً.\nسبحوا الرب كما يليق به، وليس كالمخالفين، يا أبناء البشر، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "O Israel offer before Him, honor and glory in a joyful voice, all you priests of Emmanuel, praise Him and exalt Him above all.\nYou servants of the true God, the souls of the righteous, and the humble and the charitable, praise Him and exalt Him above all.", ar: "مجداً وإكراماً قدم أمامه، يا إسرائيل بصوت التهليل، يا كهنة عمانوئيل، سبحوه وزيدوه علواً.\nيا خدام الله الحقيقي، وأنفس الأبرار، المتواضعين المحبين، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "God my God is the One, who saved you from danger, O Sedrach Misach and Abednago, praise Him and exalt Him above all.\nHurry with great haste, O you righteous of the Lord, and all the creatures He has made, praise Him and exalt Him above all.", ar: "الله إلهي أنا، هو مخلصكم من الخطر، يا سدراك وميساك وأبدناغو، سبحوه وزيدوه علوا.\nأسرعوا بحرص عظيم، يا أتقياء الرب، وكل الطبائع التي صنعها، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Coolness and repose without ceasing, grant unto all of us, that we may joyfully proclaim, praise Him and exalt Him above all.\nAnd also Your poor servant Sarkis, make him without condemnation, that he may join all those and say, praise Him and exalt Him above all.", ar: "برودة ونياحاً أعطنا، كلنا بغير إنقطاع، لنقول بتمتُع، سبحوه وزيدوه علواً.\nكذلك عبدك المسكين سركيس، إجعله بغير دينونة، ليقول مع هؤلاء كشريك، سبحوه وزيدوه علواً." } },
      { kind: 'heading', text: { en: "Ten-oueh Ensok", ar: "تين أويه إنسوك" } },
      { kind: 'hymn', text: { en: "We follow You with all our hearts, and fear You, and we seek Your face, O God do not forsake us.", ar: "نتبعك بكل قلوبنا، ونخافك، ونطلب وجهك، يا الله لا تخزنا." } },
      { kind: 'hymn', text: { en: "But rather deal with us, according to Your meekness, and according to Your great mercy, O Lord help us.", ar: "بل إصنع معنا، بحسب دعتك، وكثرة رحمتك، يا رب أعنَّا." } },
      { kind: 'hymn', text: { en: "May our prayers ascend to You, O our Master, like burnt offerings of lambs, and fat calves.", ar: "فلتصعد صلاتنا، أمامك يا سيدنا، مثل محرقات كباش، وعجول سِمان." } },
      { kind: 'hymn', text: { en: "Do not forget the covenant, which You have made with our fathers, Abraham Isaac and Jacob, Israel Your saint.", ar: "لا تنس العهد الذي، قطعته مع آبائنا، إبراهيم وإسحق ويعقوب، إسرائيل قديسك." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you nations, the tribes and all kinds of tongues, praise Him and glorify Him, above all forever.", ar: "باركوا الرب يا جميع الشعوب، والقبائل ولغات الألسن، سبحوه ومجدوه، وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Pray to the Lord on our behalf, O three saintly children, Sedrach Misach and Abednego, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة فتية القديسين، سدراك وميساك وأبدناغو، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints", ar: "مجمع القديسين" } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the Lady of us all the Mother of God, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، يا سيدتنا كلنا السيدة والدة الإله، مريم أُم مخلصنا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Michael and Gabriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، ميخائيل وغبريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Raphael and Souriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، رافائيل وسوريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Sedakiel Sarathiel and Ananiel, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا رؤساء الملائكة الأطهار، سداكيال وسراتيال وأنانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O thrones dominions and powers, the Cherubim and the Seraphim, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، أيتها الكراسي والأرباب والقوات، والشيروبيم والسرافيم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O four incorporeal beasts, the ministering flames of fire, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها الأربعة الحيوانات غير المتجسدين، الخدام الملتهبين ناراً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O priests of the truth, the twenty four presbyters, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا كهنة الحق، الأربعة والعشرين قسيساً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O angelic hosts, and all the heavenly multitudes, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها العساكر الملائكية، والطغمات السمائية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lords the fathers the patriarchs, Abraham Isaac and Jacob, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء البطاركة، إبراهيم وإسحق ويعقوب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O perfect man, the righteous and just Enoch, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الرجل الكامل، البار أخنوخ الصديق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Elijah the tishbite, and Elisha his disciple, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيليا التسبيتي، وإليشع تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Moses the archprophet, and Isaiah and Jeremiah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا موسى رئيس الأنبياء، وأشعياء وأرميا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O David the psalmist, Ezekiel and Daniel, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا داود المرتل، وحزقيال ودانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Joachim Anna and Joseph the elder, and the righteous Job Joseph and Nicodemus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا يواقيم وحنِّة ويوسف الشيخ، والصديق أيوب ويوسف ونيقوديموس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Melchizedek and Aaron, and Zacharias and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ملكي صادق وهرون، وزكريا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the prophets, and all the righteous and the just, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الأنبياء، والأبرار والصديقين، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O forerunner and baptizer, John the Baptist, that He may forgive us our sins.", ar: "إشفع فينا (أمام الرب)، أيها السابق الصابغ، يوحنا المعمدان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the hundred and forty four thousand, and the celibate evangelist, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها المئة والأربعة والأربعين ألفاً، والبتول الإنجيلي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters and fathers the Apostles, and the rest of the Disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء الرسل، وبقية التلاميذ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O blessed archdeacon, Stephen the first martyr, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا رئيس الشمامسة المبارك، إستفانوس الشهيد الأول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the apostle, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الناظر الإله الإنجيلي، أبا مرقس الرسول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyr, my lord prince George, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الشهيد المجاهد، سيدي الملك جيؤرجيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Theodore and Theodore, Leontius and Panicharus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ثيؤدوروس وثيؤدوروس، ولاونديوس، وبانيكاروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Philopater Mercurius, and Abba Mina and Abba Victor, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا فيلوباتير مرقوريوس، وأبا مينا وأبا بقطر، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Claudius and Theodore, Abba Eschyron and Abba Isaac, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي إقلاديوس وثيئودوروس، وأبا سخيرون وأبا إسحق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basilidis and Evsebius, Macarius and Philotheos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا واسيليدس وأرسابيوس، ومكاريوس وفيلوثيؤوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pisura and Abba Epshoy, Abba Isi and his sister Thecla, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بسورة وأبا بشاي، وأبا إيسي وتكلا أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Justus Apali and Theoklia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يسطس وآبالي وثيؤكليا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Jacob the Persian, Saint Sergius and Saint Bacchus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا يعقوب الفارسي، والقديس سرجيوس وواخس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Cosmas his brothers and their mother, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، قزمان وإخوته وأمهم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Kir and his brother John, and Barbara and Juliana and Demiana, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا قير ويوحنا أخوه، وبربارة ويوليانة ودميانة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, master Apatir and his sister Iraee, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، السيد أبادير وإيرائي أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Julius and those who were with him, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يوليوس ومَن معه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Mari Pahnam and his sister Sarah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، مار بهنام وسارة أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Sarapamon the bishop, Psate and Gallinikos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صرابامون الأسقف، وإبصادي وغلينيكوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, the forty saints of Sebaste, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، الأربعون قديساً بسبسطية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Piro and Athom, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بيروه وأتوم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Abba Bishoy and his friend Peter, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، أيها الشهيدان المجاهدان، أبا بيشوي وصديقه بطرس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Eklog the priest, and Abba Epgol and Abba Kav, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا إكلوج القس، وأبا بيجول وأبا كاڤ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba John of Heraclia, master Piphamon and Pistavros, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا يوحنا الهرقلي، والسيد بفامون وبسطوروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Isidore and Panteleon, Sophia and Euphemia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيسيذوروس وبندلاون، وصوفيا وإفومية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Apanoub and Ptolomeos, Apa Ekragon and Sousennius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي أبانوب وإبطلماوس، وإبا إكراجون وسوسونيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O great high priest, Abba Peter seal of the martyrs, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا رئيس الكهنة العظيم، أنبا بطرس خاتم الشهداء، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O new martyrs, Pistavros and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان الجديدان، بسطوروس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Michael the hegumen, and Michael the monk, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، يا ميخائيل القمص، وميخائيل الراهب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the martyrs, who suffered for the sake of Christ, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الشهداء، الذين تألموا من أجل المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Antony and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا أنطونيوس وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O three saints Macarii, and all their children the cross-bearers, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة مقارات القديسون، وأولادهم لباس الصليب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers the hegumens, Abba John and Abba Daniel, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين القمصين، أنبا يوحنا وأنبا دانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Bishoy and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا بيشوي وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our saintly Roman fathers, Maximus and Dometius, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أبوينا القديسين الروميين، مكسيموس ودوماديوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O forty nine martyrs, the elders of Shiheet, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها التسعة والأربعون شهيداً، شيوخ شيهات، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O strong saint Abba Moses, and John Kame, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، أيها القوي القديس أنبا موسى، ويحنس كاما، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pachomius of the Koinonia, and Theodore his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا باخوم أبا الشركة، وثيودورس تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Shenouda the archimandrite, and Abba Wisa his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا شنودة رئيس المتوحدين، وأنبا ويصا تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Nopher and Abba Karus, and our father Paphnutius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا نفر وأنبا كاروس، وأبانا بفنوتيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Samuel the confessor, and Justus and Apollo his disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صموئيل المعترف، ويسطس وأبوللو تلميذيه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Apollo and Abba Apip, and our father Abba Pigimi, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا أبوللو وأنبا أبيب، وأبانا أنبا بيچيمي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Evkin and Abba Ehron, Abba Hor and Abba Phis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا إڤكين وأنبا إهرون، وأبا هور وأبا فيس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Parsouma and Ephraim, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا برسوما وإفريم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Epiphanius and Ammounios, and Arshillidis and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إبيفانيوس وأمونيوس، وأرشليدس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the ascetic fathers, Abba Abraam and George, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين الناسكين، أنبا أبرآم وجيؤرجي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Athanasius the apostolic, Severus and Dioscorus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أثاناسيوس الرسولي، وساويرس وديسقورس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basil and Gregory, and our father Abba Cyril, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا باسيليوس وإغريغوريوس، وأبانا أنبا كيرلس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the three hundred and eighteen gathered, at Nicea for the faith, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 318 الذين إجتمعوا، في نيقية من أجل الإيمان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O the one hundred and fifty at Constantinople, and the two hundred at Ephesus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 150 بمدينة القسطنطينية، والمائتين بأفسس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Hadid and Abba John, our great father Parsouma and Abba Roweis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا حديد وأنبا يوحنا، وأبانا العظيم أنبا برسوما وأنبا رويس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Abraam the hegumen, and our father Abba Mark, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا أبرآم القمص، وأبانا أنبا مرقس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the cross-bearers, perfected in the wilderness, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا مصاف لباس الصليب، الذين كملوا في البراري، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lord king Constantine, and his mother queen Helen, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الملك قسطنطين، وهيلانة الملكة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O wise virgin ladies, the brides of Christ, that He may forgive us our sins.", ar: "أُطلبنَّ من الرب عنا، أيتها الفتيات العذارى الحكيمات، عرائس المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the saints of this day, everyone according to his name, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا قديسي هذا اليوم، كل واحد بإسمه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Likewise we exalt you, with David the psalmist, \"You are a priest forever, according to the order of Melchizedek.\"", ar: "كذلك نعظمك، مع المرتل داود قائلين، \"أنت هو الكاهن إلى الأبد، على طقس ملكي صادق.\"" } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our holy father the patriarch, Pope Abba Shenouda the high priest, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا أبانا القديس البطريرك، أنبا شنودة رئيس الكهنة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "If a Bishop is present:\nPray to the Lord on our behalf, O our holy and righteous father, Abba (...) the Bishop (Metropolitan), that He may forgive us our sins.", ar: "في حضور الآب الأسقف:\nأطلب من الرب عنا، يا أبينا القديس البار، أنبا (...) الأسقف (المطران)، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Doxology for the Virgin Mary", ar: "ذكصولوجية العذراء مريم" } },
      { kind: 'doxology', text: { en: "Your greatness O Mary, the undefiled Virgin, is likened to the height of the palm tree, spoken of by Solomon.", ar: "عظمتِك يا مريم، العذراء غير الدنسة، تشبه عُلو النخلة التي، تكلم عنها سليمان." } },
      { kind: 'doxology', text: { en: "You are the spring of living water, that flows from Lebanon, for out of you sprang unto us, the grace of the divinity.", ar: "أنتِ ينبوع ماء الحياة، الفائض من لبنان، التي نبعت لنا منه، نعمة اللاهوت." } },
      { kind: 'doxology', text: { en: "You gave birth to Emmanuel, out of your virginal womb, and He has made us heirs, to the kingdom of heaven.", ar: "ولدتِ لنا عمانوئيل، من أحشائِك البتول، وصيرنا وارثين، في ملكوت السموات." } },
      { kind: 'doxology', text: { en: "According to the promise, He promised to our father, King David the patriarch, He came and fulfilled to us.", ar: "كالوعد الذي وعد به، أبانا رئيس الآباء، الذي هو الملك داود، أتى وأكمله لنا." } },
      { kind: 'doxology', text: { en: "Hail to you O Virgin, the very and true Queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدت لنا عمانوئيل." } },
      { kind: 'doxology', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Fourth Hoos", ar: "الهوس الرابع" } },
      { kind: 'hymn', text: { en: "(Psalm 148)", ar: "(المزمور 148)" } },
      { kind: 'hymn', text: { en: "Praise the Lord from the heavens Alleluia. Praise Him in the heights.", ar: "سبحوا الرب من السموات هلليلويا. سبحوه في الأعالي." } },
      { kind: 'hymn', text: { en: "Praise Him all His angels Alleluia. Praise Him all His hosts.", ar: "سبحوه يا جميع ملائكته هلليلويا. سبحوه يا جميع جنوده." } },
      { kind: 'hymn', text: { en: "Praise Him sun and moon Alleluia. Praise Him all you stars of light.", ar: "سبحيه أيتها الشمس والقمر هلليلويا. سبحيه يا جميع كواكب النور." } },
      { kind: 'hymn', text: { en: "Praise Him you heavens of heavens Alleluia. And you waters above the heavens.", ar: "سبحيه يا سماء السموات هلليلويا. ويا أيتها المياه التي فوق السموات." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For He commanded and they were created.", ar: "لتسبح جميعها لإسم الرب هلليلويا. لأنه قال فكانت." } },
      { kind: 'hymn', text: { en: "He has ordered and they were created Alleluia. He has established them forever and ever.", ar: "وأمر فخلقت هلليلويا. أقامها إلى الأبد وإلى أبد الأبد." } },
      { kind: 'hymn', text: { en: "He has made a decree which shall not pass away Alleluia. Praise the Lord from the earth.", ar: "وضع لها أمراً فلن تتجاوزه هلليلويا. سبحي الرب من الأرض." } },
      { kind: 'hymn', text: { en: "You great sea creatures and all the depths Alleluia. Fire and hail, snow and clouds, stormy wind fulfilling His word.", ar: "أيتها التنانين وجميع الأعماق هلليلويا. النار والبرد والثلج والجليد والريح العاصفة الصانعة كلمته." } },
      { kind: 'hymn', text: { en: "Mountains and all hills Alleluia. Fruitful trees and all cedars.", ar: "الجبال العالية وجميع الآكام هلليلويا. الأشجار المثمره وكل الأرز." } },
      { kind: 'hymn', text: { en: "Beasts and all cattle Alleluia. Creeping things and flying birds.", ar: "الوحوش وكل البهائم هلليلويا. الهوام وكل الطيور ذات الأجنحة." } },
      { kind: 'hymn', text: { en: "Kings of the earth and all people Alleluia. Princes and all judges of the earth.", ar: "ملوك الأرض وكل الشعوب هلليلويا. الرؤساء وكل حكام الأرض." } },
      { kind: 'hymn', text: { en: "Both young men and maidens Alleluia. Old men and children.", ar: "الشبان والعذارى هلليلويا. الشيوخ والصبيان." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For His name alone is exalted.", ar: "فليسبحوا جميعاً إسم الرب هلليلويا. لأنه قد تعالى إسمه وحده." } },
      { kind: 'hymn', text: { en: "His glory is above the earth and heaven Alleluia. And He has exalted the horn of His people.", ar: "شكره كائن على الأرض وفي السماء هلليلويا. ويرفع قرن شعبه." } },
      { kind: 'hymn', text: { en: "The praise of all His saints Alleluia. The children of Israel, a people near unto Him.", ar: "سُبحاً لجميع قديسيه هلليلويا. بني إسرائيل، الشعب القريب إليه." } },
      { kind: 'hymn', text: { en: "(Psalm 149)", ar: "(المزمور 149)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Sing to the Lord a new song Alleluia. And His praise in the congregation of the saints.", ar: "إنشدوا للرب نشيداً جديداً هلليلويا. لأن تسبحته في بيعة القديسين." } },
      { kind: 'hymn', text: { en: "Let Israel rejoice in his Maker Alleluia. Let the children of Zion be joyful in their King.", ar: "فليفرح إسرئيل بخالقه هلليلويا. وبنوا صهيون فليتهللوا بملكهم." } },
      { kind: 'hymn', text: { en: "Let them praise His name in a chorus Alleluia. Let them sing praises unto Him with timbrel and harp.", ar: "فليسِّبحوا إسمه القدوس بصفِ هلليلويا. بدف ومزمار فليرتلوا له." } },
      { kind: 'hymn', text: { en: "For the Lord takes pleasure in His people Alleluia. He will raise the meek with salvation.", ar: "لأن الرب يُسر بشعبه هلليلويا. يعلي الودعاء بالخلاص." } },
      { kind: 'hymn', text: { en: "Let the saints be joyful in glory Alleluia. Let them sing aloud upon their beds.", ar: "يفتخر القديسون بمجد هلليلويا. ويتهللون على مضاجعهم." } },
      { kind: 'hymn', text: { en: "Let the high praises of God be in their mouth Alleluia. And a two edged sword in their hands.", ar: "تعليات الله في حناجرهم هلليلويا. وسيوف ذات حدين في أيديهم." } },
      { kind: 'hymn', text: { en: "To execute vengeance on the nations Alleluia. And punishments on the people.", ar: "ليصنعوا نقمة في الأمم هلليلويا. وتوبيخات في الشعوب." } },
      { kind: 'hymn', text: { en: "To bind their kings with chains Alleluia. And their nobles with fetters of iron.", ar: "ليوثقوا ملوكهم بقيود هلليلويا. وإشرافهم بأغلال للأيدي من حديد." } },
      { kind: 'hymn', text: { en: "To execute on them the written judgment Alleluia. This honor have all His saints.", ar: "ليصنعوا بهم حُكماً مكتوباً هلليلويا. هذا المجد كائن في جميع قديسيه." } },
      { kind: 'hymn', text: { en: "(Psalm 150)", ar: "(المزمور 150)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise God in all His saints Alleluia.", ar: "سبحوا الله في جميع قديسيه هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him in the firmament of His power Alleluia.", ar: "سبحوه في جلد قوته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him for His mighty acts Alleluia.", ar: "سبحوه على مقدرته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him according to the multitudes of His greatness Alleluia.", ar: "سبحوه ككثرة عظمته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with the sound of the trumpet Alleluia.", ar: "سبحوه بصوت البوق هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with psaltery and harp Alleluia.", ar: "سبحوه بالمزمار والقيثار هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with timbrel and chorus Alleluia.", ar: "سبحوه بدفوف وصفوف هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with strings and organs Alleluia.", ar: "سبحوه بأوتار وأرغن هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with pleasant sounding cymbals Alleluia.", ar: "سبحوه بصنوج حسنة الصوت هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him upon the cymbals of joy Alleluia.", ar: "سبحوه بصنوج التهليل هلليلويا." } },
      { kind: 'hymn', text: { en: "Let every thing that has breath praise the name of the Lord our God Alleluia.", ar: "كل نسمة فلتسبح إسم الرب الهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son and the Holy Spirit Alleluia.", ar: "المجد للآب والإبن والروح القدس هلليلويا." } },
      { kind: 'hymn', text: { en: "Now and forever and unto the age of all ages Amen Alleluia.", ar: "الآن وكل أوان وإلى دهر الدهور آمين هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory to You, O our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لك يا إلهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory be to our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لإلهنا هلليلويا." } },
      { kind: 'heading', text: { en: "The First Sunday Psali", ar: "إبصالية الأحد الأولى" } },
      { kind: 'hymn', text: { en: "I believe wherefore I spoke, with great strength, about Your great mercy, O Lord of powers.\nHelp me my Lord, Jesus the Compassionate, to glorify my Lady, Your Mother the bride.", ar: "آمنت لذلك، تكلمت بقوة، من أجل عِظَم رحمتك، يا رب القوات.\nأعنَّي يا ربي، يسوع الرءوف، لأُمجد سيدتي، أُمك العروس." } },
      { kind: 'hymn', text: { en: "For truly, this Virgin, who is full of honor, was greatly exalted.\nDavid spoke of her saying, \"The Lord has chosen Zion, He came and dwelt in her, in order to save us.\"", ar: "لأنها بالحقيقة، قد تعالت جداً، هذه العذراء، الممتلئة كرامة.\nداود تكلم من أجلها، قائلاً \"الرب إختار صهيون، وأتى وحل فيها، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "This is Mary, who brought unto us, the eternal, freedom.\nZachariah has said, \"The golden lampstand, which was made, with golden hands.\"", ar: "أي مريم، التي جلبت، إلينا الحرية، الأبدية.\nزكريا قال، \"أنها المنارة الذهب، المصنوعة، بأياد ذهبية.\"" } },
      { kind: 'hymn', text: { en: "Isaiah said to us, with a joyful voice, that \"She will give birth to, Emmanuel for us.\"\nThis is Jerusalem, the city of our God, the throne of all ranks, of the Cherubim.", ar: "أشعياء قال لنا، بصوت التهليل، أنها \"تلد لنا، عمانوئيل.\"\nهذه هي أورشليم، مدينة إلهنا، مركبة الشاروبيم، ذات الأنواع الكثيرة." } },
      { kind: 'hymn', text: { en: "Ezekiel has witnessed, and revealed this to us, saying \"I saw a door, to the east.\nThe Lord the Savior, entered into it, and it remained, thoroughly shut as before.\"", ar: "حزقيال شهد، وأظهر لنا هذا، قائلاً \"أني رأيت باباً، ناحية المشارق.\nالرب المخلص، دخل فيه، وبقى مغلقاً، جيداً بحاله.\"" } },
      { kind: 'hymn', text: { en: "All the nations sing, with different tongues, to the Theotokos, the Mother of the Messiah.\nMary the chaste, the joy of the righteous, and truly she is the joy, of the faithful.", ar: "كل الشعوب يسبحون، مع لغات الألسن، لوالدة الإله، أُم ماسيا.\nمريم العفيفة، بهجة الصديقين، وبالحقيقة، فرح المؤمنين." } },
      { kind: 'hymn', text: { en: "You are the tabernacle, and the ark, which Moses has made, with great honor.\nBeyond all the thoughts, of the heavens, is this mysterious matter, of the mercy seat.", ar: "أنتِ هي القبة، التي صنعها موسى، بعِظَم كرامة، والتابوت.\nمُتعال عن الأفكار، السمائية، هذا الأمر العجيب، الذي للغطاء." } },
      { kind: 'hymn', text: { en: "Great is the glory, of your virginity, O full of glory, O Saint Mary.\nThe honored vessel, and the lampstand, the pure censer, full of blessings.", ar: "عظيم هو مجد، بتوليتِك، أيتها الممتلئة مجداً، القديسة مريم.\nالقسط المُكرم، والمنارة، والمجمرة النقية، المملوءة بركة." } },
      { kind: 'hymn', text: { en: "All the high names, of the incorporeal, did not reach the height, of your blessedness.\nYou resemble the rod, of Aaron, which blossomed and budded, and produced its fruit.", ar: "كل الأسماء العالية، التي لغير المتجسدين، لم يبلغوا إلى، عُلوَ طوباويتِك.\nشُبِّهتِ بعصا، هرون التي، أزهرت ونبتت، وأعطت ثمرة." } },
      { kind: 'hymn', text: { en: "You are exalted, more than the Cherubim, and honored more, than the Seraphim.\nThe Son of God our God, you gave birth to, we glorify Him as God, and also worship Him.", ar: "مُرتفعة أنت جداً، أكثر من الشاروبيم، ومكرمة أكثر، من السيرافيم.\nإبن الله إلهنا، ولدتِه، نمجده كإله، ونسجد له." } },
      { kind: 'hymn', text: { en: "He who abides in light, whom no one can approach, showed us His miracles, and you fed Him.\nHail to you Mary, the beautiful dove, full of wisdom, the Mother of Jesus Christ.", ar: "الساكن في النور، الذي لا يُدنى منه، أظهر آياته، وأرضعتِه اللبن.\nالسلام لك يا مريم، الحمامة الحسنة، الممتلئة حكمة، أُم يسوع المسيح." } },
      { kind: 'hymn', text: { en: "For the rest of our days, we will praise you, O full of glory, and clothed with purity.\nBe patient O Lover of Man, with Your servant, and forgive us our sins, and accept us.", ar: "بقية أيامنا، نمدحِك، أيتها الممتلئة مجداً، أنتِ مشتملة بالطهارة.\nتأن يا محب البشر، على عبدك، وإغفر لنا خطايانا، وإقبلنا إليك." } },
      { kind: 'heading', text: { en: "The Second Sunday Psali", ar: "إبصالية الأحد الثانية" } },
      { kind: 'hymn', text: { en: "I sought after You, from the depths of my heart, my Lord Jesus, help me.\nLoosen for me, all the bonds of sin, my Lord Jesus Christ, help me.", ar: "طلبتك، من عمق قلبي، يا ربي يسوع، أعنِّي.\nحل عني، رباطات الخطية، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Be a help to me, so that You may save me, my Lord Jesus, help me.\nMay Your goodness, come speedily to me, my Lord Jesus Christ, help me.", ar: "كن لي معيناً، لكي تخلصني، يا ربي يسوع، أعنِّي.\nصلاحك، فليدركني سريعاً، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Overshadow me, with the shadow of Your wings, my Lord Jesus, help me.\nIn six days You have made, all the creation, my Lord Jesus Christ, help me.", ar: "ظلِّل عليَّ، بظِل جناحيك، يا ربي يسوع، أعنِّي.\nفي ستة أيام، صنعت كل الخليقة، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Seven times everyday, I will praise Your name, my Lord Jesus, help me.\nAll the creation, glorifies Your name, my Lord Jesus Christ, help me.", ar: "سبع مرات في اليوم، أبارك إسمك، يا ربي يسوع، أعنِّي.\nها كل البرية، تمجد إسمك، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Yours is the lordship, and the authority, my Lord Jesus, help me.\nMake haste O my God, so that You may save me, my Lord Jesus Christ, help me.", ar: "لك الربوبية، والسلطان، يا ربي يسوع، أعنِّي.\nأسرع يا إلهي، لتخلصني، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Every knee, bows down before You, my Lord Jesus, help me.\nAll the diverse tongues, together bless Your name, my Lord Jesus Christ, help me.", ar: "كل ركبة، تجثو أمامك، يا ربي يسوع، أعنِّي.\nكل الألسنة معاً، تبارك إسمك، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Turn away Your face, from all of my sins, my Lord Jesus, help me.\nBlot out O God, all my iniquities, my Lord Jesus Christ, help me.", ar: "إصرف وجهك، عن خطاياي، يا ربي يسوع، أعنِّي.\nجميع آثامي، يا الله إمحها، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "You know my thoughts, and You search my reins, my Lord Jesus, help me.\nCreate in me, a clean heart, my Lord Jesus Christ, help me.", ar: "أنت تعرف أفكاري، وتفحص كليتي، يا ربي يسوع، أعنِّي.\nقلباً طاهراً أخلقه فيَّ، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Your Holy Spirit, do not take away from me, my Lord Jesus, help me.\nIncline Your ears, make haste and hear me, my Lord Jesus Christ, help me.", ar: "روحك القدوس، لا تنزعه منِّي، يا ربي يسوع، أعنِّي.\nأمِّل سمعك إليَّ، وإستجب لي عاجلاً، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Set before me a law, in the way of Your justice, my Lord Jesus, help me.\nYour kingdom O my God, is an eternal kingdom, my Lord Jesus Christ, help me.", ar: "قرِّر ليَّ ناموساً، في طريق عدلك، يا ربي يسوع، أعنِّي.\nملكوتك يا إلهي، ملكوت أبدي، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "You are the Son of God, I believe in You, my Lord Jesus, help me.\nYou who carries the sins of the world, have mercy upon me, my Lord Jesus Christ, help me.", ar: "أنت إبن الله، آمنت بك، يا ربي يسوع، أعنِّي.\nيا حامل خطية، العالم إرحمني، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Forgive me the multitude, of my transgressions, my Lord Jesus, help me.\nAll of the souls, together bless Your name, my Lord Jesus Christ, help me.", ar: "إغفر ليَّ، كثرة آثامي، يا ربي يسوع، أعنِّي.\nكل الأنفس معاً، تبارك إسمك، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Have patience with me, do not hasten to destroy me, my Lord Jesus, help me.\nEarly in the morning, I will rise and bless Your name, my Lord Jesus Christ, help me.", ar: "تأنَّ عليَّ، ولا تهلكني سريعاً، يا ربي يسوع، أعنِّي.\nأقوم وقت السحر، لأبارك إسمك، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Your yoke is sweet, and Your burden is light, my Lord Jesus, help me.\nIn the accepted time, hear me, my Lord Jesus Christ, help me.", ar: "حلوٌ هو نيرك، وحملك خفيف، يا ربي يسوع، أعنِّي.\nفي زمن مقبول، إستجب ليَّ، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "O how beloved, is Your holy name, my Lord Jesus, help me.\nDisperse away from me, all of the devils, my Lord Jesus Christ, help me.", ar: "محبوب هو، إسمك القدوس، يا ربي يسوع، أعنِّي.\nفرِّق عنِّي، كل الأبالسة، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'hymn', text: { en: "Sow within me, the seed of Your righteousness, my Lord Jesus, help me.\nGrant us Your true peace, and forgive us our sins, my Lord Jesus Christ, help me.", ar: "إغرس فيَّ، ثمرة بِرَك، يا ربي يسوع، أعنِّي.\nأعطنا سلامك الحقيقي، وإغفر لنا خطايانا، يا ربي يسوع المسيح، أعنِّي." } },
      { kind: 'heading', text: { en: "Introduction to the Sunday Theotokia — Leebon", ar: "مقدمة ثيؤطوكية الأحد — ليبون" } },
      { kind: 'hymn', text: { en: "And whenever we, gather for prayer, let us bless the name, of my Lord Jesus.", ar: "وأيضاً إذا ما إجتمعنا، للصلاة، فلنبارك إسم، ربي يسوع." } },
      { kind: 'hymn', text: { en: "We bless You, O my Lord Jesus, deliver us through Your name, for we have hope in You.", ar: "لأننا نباركك، يا ربي يسوع، نجنا بإسمك، لأننا توكلنا عليك." } },
      { kind: 'hymn', text: { en: "That we may praise You, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "لكي نسبحك، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son, and the Holy Spirit, now and forever and unto, the age of all ages Amen.", ar: "المجد للآب والإبن، والروح القدوس، الآن وكل أوان، وإلى دهر الدهور آمين." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 1", ar: "ثيؤطوكية الأحد — القطعة الأولى" } },
      { kind: 'hymn', text: { en: "You are called righteous, O blessed one, among women, the second tabernacle.", ar: "مدعوة صديقة، أيتها المباركة، في النساء، القبة الثانية." } },
      { kind: 'hymn', text: { en: "Which is called, the holy of holies, wherein are the tablets, of the covenant.", ar: "التي تدعى، قدس الأقداس، وفيها، لوحا العهد." } },
      { kind: 'hymn', text: { en: "Whereupon is, the ten commandments, these which are written, by the finger of God.", ar: "والعشر، الكلمات، هذة المكتوبة، بأصبع الله." } },
      { kind: 'hymn', text: { en: "They have directed us, to the Iota, the name of salvation, of Jesus Christ.", ar: "سبقت أن دلتنا، على اليوطة، إسم الخلاص، الذي ليسوع المسيح." } },
      { kind: 'hymn', text: { en: "Who was incarnate, of you without change, and became the Mediator, of a new covenant.", ar: "هذا الذي تجسد، منكِ بغير تغيير، وصار وسيطاً، لعهدٍ جديد." } },
      { kind: 'hymn', text: { en: "Through the shedding, of His holy Blood, He purified the faithful, to be a justified people.", ar: "من قِبَل رشاش، دمه المقدس، طهر المؤمنين، شعباً مبرراً." } },
      { kind: 'hymn', text: { en: "Wherefore everyone, magnifies you, O my Lady the Mother of God, the ever-holy.", ar: "من أجل هذا، كل واحد يعظمِك، يا سيدتي والدة الإله، القديسة كل حين." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمة، بشفاعاتِك، عند محب البشر." } },
      { kind: 'hymn', text: { en: "Who can speak of, the honor of the tabernacle, which Moses had made, on Mount Sinai.", ar: "من يقدر أن ينطق، بكرامة القبة، التي صنعها موسى، على جبل سيناء." } },
      { kind: 'hymn', text: { en: "He made it with glory, as commanded by the Lord, according to the patterns, shown unto him.", ar: "صنعها بمجد، كقول الرب، وكجميع المثالات، التي أعلنت له." } },
      { kind: 'hymn', text: { en: "Therein Aaron, and his sons served, the example of the highest, in the shadow of the heavenly ones.", ar: "تلك التي كان، هرون وبنوة يخدمون فيها، بمثال العلاء، وظِل السمائيات." } },
      { kind: 'hymn', text: { en: "They likened it to you, O Virgin Mary, the true tabernacle, wherein dwelt God.", ar: "شبهوكِ بها، يا مريم العذراء، القبة الحقيقية، التي في داخلها الله." } },
      { kind: 'hymn', text: { en: "Wherefore we, magnify you befittingly, with prophetic, hymnology.", ar: "من أجل هذا، نعظمِك، بإستحقاقٍ، بتماجيد نبوية." } },
      { kind: 'hymn', text: { en: "For they spoke of you, with great honor, O holy city, of the great King.", ar: "لأنهم تكلموا، من أجلِك بأعمال كريمة، أيتها المدينة المقدسة، التي للملك العظيم." } },
      { kind: 'hymn', text: { en: "We entreat and pray, that we may win mercy, through your intercessions, with the Lover of Mankind.", ar: "نسأل ونطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 2", ar: "ثيؤطوكية الأحد — القطعة الثانية" } },
      { kind: 'hymn', text: { en: "The ark overlaid, roundabout with gold, that was made, with wood that would not decay.", ar: "التابوت المصفح، بالذهب من كل ناحية، المصنوع من خشب، لا يُسَوس." } },
      { kind: 'hymn', text: { en: "It foretold the sign, of God the Word, who became man, without separation.", ar: "سبق أن دلنا، على الله الكلمة، الذي صار إنساناً، بغير إفتراق." } },
      { kind: 'hymn', text: { en: "One nature out of two, a holy divinity, co-essential with the Father, and incorruptible.", ar: "واحد من إثنين، لاهوت قدوس، بغير فساد، مساوي للآب." } },
      { kind: 'hymn', text: { en: "A holy humanity, begotten without seed, co-essential with us, according to the Economy.", ar: "وناسوت طاهر، بغير مباضعة، مساوي لنا، كالتدبير." } },
      { kind: 'hymn', text: { en: "This which He has taken, from you O undefiled, He made one with Him, as a hypostasis.", ar: "هذا الذي أخذه منكِ، أيتها الغير الدنسة، وإتحد، به كأُقنوم." } },
      { kind: 'hymn', text: { en: "Wherefore everyone, magnifies you, O my Lady the Mother of God, the ever-holy.", ar: "من أجل هذا، كل واحد يعظمِك، يا سيدتي والدة الإله، القديسة كل حين." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'hymn', text: { en: "All the souls together, of the children of Israel, brought offering unto, the tabernacle of the Lord.", ar: "كل الأنفس معاً، من بني إسرائيل، قدموا قرابين، إلى قبة الرب." } },
      { kind: 'hymn', text: { en: "Gold and silver, and precious stone, purple and scarlet, and fine linen.", ar: "الذهب والفضة، والحجر الكريم، والحرير المغزول، والأرجوان." } },
      { kind: 'hymn', text: { en: "And they made an ark, of wood that would not decay, overlaid with gold, within and without.", ar: "صنعوا تابوتاً، من خشب لا يُسوَس، وصفَّحوه بالذهب، داخلاً وخارجاً." } },
      { kind: 'hymn', text: { en: "You too O Mary, are clothed with the glory, of the divinity, within and without.", ar: "وأنت أيضاً يا مريم، العذراء متسربلة، بمجد اللاهوت، داخلاً وخارجاً." } },
      { kind: 'hymn', text: { en: "For you have brought, unto God your Son, many people, through your purity.", ar: "لأنكِ قدمتِ، شعباً كثيراً، لله إبنِك، من قِبَل طهارتك." } },
      { kind: 'hymn', text: { en: "Wherefore we, magnify you befittingly, with prophetic, hymnology.", ar: "من أجل هذا، نعظمِك، بإستحقاقٍ، بتماجيد نبوية." } },
      { kind: 'hymn', text: { en: "For they spoke of you, with great honor, O holy city, of the great King.", ar: "لأنهم تكلموا، من أجلِك بأعمال كريمة، أيتها المدينة المقدسة، التي للملك العظيم." } },
      { kind: 'hymn', text: { en: "We entreat and pray, that we may win mercy, through your intercessions, with the Lover of Mankind.", ar: "نسأل ونطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 3", ar: "ثيؤطوكية الأحد — القطعة الثالثة" } },
      { kind: 'hymn', text: { en: "The mercy seat, was overshadowed by, the forged Cherubim, from all sides.", ar: "الغطاء، المظلل عليه، بالشاروبيم، المصورين." } },
      { kind: 'hymn', text: { en: "Was a symbol of God the Word, who was incarnate, of you without change, O undefiled.", ar: "أي الله الكلمة، الذي تجسد منكِ، أيتها التي بلا عيب، بغير تغير." } },
      { kind: 'hymn', text: { en: "He became the purification, of our sins, and the forgiveness, of our iniquities.", ar: "وصار تطهيراً، لخطايانا، وغافراً، لآثامنا." } },
      { kind: 'hymn', text: { en: "Wherefore everyone, magnifies you, O my Lady the Mother of God, the ever-holy.", ar: "من أجل هذا، كل واحد يعظمِك، يا سيدتي والدة الإله، القديسة كل حين." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'hymn', text: { en: "The two golden Cherubim, continually covered, with their wings, the mercy seat.", ar: "كروباً ذهب، مصوران مظللان، على الغطاء، بأجنحتهما كل حين." } },
      { kind: 'hymn', text: { en: "Overshadowing, the place of the holy, of the holies, in the second tabernacle.", ar: "يظللان على، موضع قدس، الأقداس، في القبة الثانية." } },
      { kind: 'hymn', text: { en: "You too O Mary, thousands of thousands, and myriads of myriads, overshadow you.", ar: "وأنت أيضاً يا مريم، ألوف ألوف، وربوات ربوات، يظللون عليك." } },
      { kind: 'hymn', text: { en: "Praising their Creator, who was in your womb, and took our likeness, without sin or alteration.", ar: "مُسبحين خالقهم، وهو في بطنِك، هذا الذي أخذ شبهنا، ما خلا الخطية والتغيير." } },
      { kind: 'hymn', text: { en: "Wherefore we, magnify you befittingly, with prophetic, hymnology.", ar: "من أجل هذا، نعظمِك، بإستحقاقٍ، بتماجيد نبوية." } },
      { kind: 'hymn', text: { en: "For they spoke of you, with great honor, O holy city, of the great King.", ar: "لأنهم تكلموا، من أجلِك بأعمال كريمة، أيتها المدينة المقدسة، التي للملك العظيم." } },
      { kind: 'hymn', text: { en: "We entreat and pray, that we may win mercy, through your intercessions, with the Lover of Mankind.", ar: "نسأل ونطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 4", ar: "ثيؤطوكية الأحد — القطعة الرابعة" } },
      { kind: 'hymn', text: { en: "You are the pot, made of pure gold, wherein was hidden, the true Manna.", ar: "أنت هي قسط، الذهب النقي، المخفي المَنَّ، في وسطه." } },
      { kind: 'hymn', text: { en: "The Bread of life, which came down from heaven, and gave life, unto the world.", ar: "خبز الحياة، الذي نزل لنا، من السماء، وأعطى الحياة للعالم." } },
      { kind: 'hymn', text: { en: "Wherefore everyone, magnifies you, O my Lady the Mother of God, the ever-holy.", ar: "من أجل هذا، كل واحد يعظمِك، يا سيدتي والدة الإله، القديسة كل حين." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمة، بشفاعاتِك، عند محب البشر." } },
      { kind: 'hymn', text: { en: "It befits you, to be called, the golden pot, where the manna was hidden.", ar: "يليق بكِ أن، يدعى إسمِك، قسط الذهب، المخفي فيه المَنَّ." } },
      { kind: 'hymn', text: { en: "For that was kept, in the tabernacle, as a testimony, to the children of Israel.", ar: "فذلك وُضع، في القبة، شهادة لبني، إسرائيل." } },
      { kind: 'hymn', text: { en: "Of the good things, that the Lord God, did unto them, in the wilderness of Sinai.", ar: "من أجل الخيرات، التي صنعها معهم، الرب الإله، في برية سيناء." } },
      { kind: 'hymn', text: { en: "You too O Mary, have carried in your womb, the rational Manna, that came from the Father.", ar: "وأنتِ أيضاً يا مريم، حملتِ في بطنِك، المَنَّ العقلي، الذي أتى من الآب." } },
      { kind: 'hymn', text: { en: "You bore Him without blemish, He gave unto us, His honored Body and Blood, and we lived forever.", ar: "وولدته بغير دنس، وأعطانا جسده، ودمه الكريمين، فحيينا إلى الأبد." } },
      { kind: 'hymn', text: { en: "Wherefore we, magnify you befittingly, with prophetic, hymnology.", ar: "من أجل هذا، نعظمِك، بإستحقاقٍ، بتماجيد نبوية." } },
      { kind: 'hymn', text: { en: "For they spoke of you, with great honor, O holy city, of the great King.", ar: "لأنهم تكلموا، من أجلِك بأعمال كريمة، أيتها المدينة المقدسة، التي للملك العظيم." } },
      { kind: 'hymn', text: { en: "We entreat and pray, that we may win mercy, through your intercessions, with the Lover of Mankind.", ar: "نسأل ونطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 5", ar: "ثيؤطوكية الأحد — القطعة الخامسة" } },
      { kind: 'hymn', text: { en: "You are the lampstand, made of pure gold, carrying, the ever-burning Lamp.", ar: "أنت المنارة، الذهب النقي، الحاملة المصباح، المتقد كل حين." } },
      { kind: 'hymn', text: { en: "That is the unapproachable, Light of the world, that proceeds from, the unapproachable Light.", ar: "الذي هو نور العالم، غير المقترب إليه، الذي من النور، غير المُدني منه." } },
      { kind: 'hymn', text: { en: "The true God, out of true God, who was incarnate, of you without change.", ar: "الإله الحق، من الإله الحق، الذي تجسد منكِ، بغير تغيير." } },
      { kind: 'hymn', text: { en: "By His appearing, He gave light to us, we who sit in the darkness, and in the shadow of death.", ar: "بظهوره، آضاء علينا نحن، الجلوس في الظلمة، وظلال الموت." } },
      { kind: 'hymn', text: { en: "And He guided our feet, in the path of peace, through the communion, of His holy sacraments.", ar: "وقوَّم أرجلنا، إلى طريق السلام، بشركة، أسراره المقدسة." } },
      { kind: 'hymn', text: { en: "Wherefore everyone, magnifies you, O my Lady the Mother of God, the ever-holy.", ar: "من أجل هذا، كل واحد يعظمِك، يا سيدتي والدة الإله، القديسة كل حين." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'hymn', text: { en: "All the ranks on high, cannot resemble you, O golden lampstand, that carries the true Light.", ar: "كل الرتب العلوية، لم تقدر أن تشبهكِ، أيتها المنارة الذهبية، حاملة النور الحقيقي." } },
      { kind: 'hymn', text: { en: "That was made of, pure and elect gold, and was placed in, the tabernacle.", ar: "فتلك صُنعت، من ذهب، مختار نقي، ووُضعت في القبة." } },
      { kind: 'hymn', text: { en: "That was made, by the hands of men, who brought oil for its lamps, by day and by night.", ar: "تدبر، بأيدي البشر إذ، يعطى زيت لمصابيحها، نهاراً وليلاً." } },
      { kind: 'hymn', text: { en: "He who dwells in your womb, O Virgin Mary, gives light to every man, who comes into the world.", ar: "والذي في بطنِك، يا مريم العذراء، أضاء لكل أنسان، آت إلى العالم." } },
      { kind: 'hymn', text: { en: "For He whom you have born, is the Sun of righteousness, and He has healed us, of all our sins.", ar: "لأنه هو، شمس البر، ولدتِه وشفانا، من خطايانا." } },
      { kind: 'hymn', text: { en: "Wherefore we, magnify you befittingly, with prophetic, hymnology.", ar: "من أجل هذا، نعظمِك، بإستحقاقٍ، بتماجيد نبوية." } },
      { kind: 'hymn', text: { en: "For they spoke of you, with great honor, O holy city, of the great King.", ar: "لأنهم تكلموا، من أجلِك بأعمال كريمة، أيتها المدينة المقدسة، التي للملك العظيم." } },
      { kind: 'hymn', text: { en: "We entreat and pray, that we may win mercy, through your intercessions, with the Lover of Mankind.", ar: "نسأل ونطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 6", ar: "ثيؤطوكية الأحد — القطعة السادسة" } },
      { kind: 'hymn', text: { en: "You are the censer, made of pure gold, carrying the blessed, and live coal.", ar: "أنت هي المجمرة، الذهب النقي، حاملة جمر، النار المباركة." } },
      { kind: 'hymn', text: { en: "That is taken, from the altar, to purge the sins, and take away the iniquities.", ar: "الذي يُؤخذ، من المذبح، يُطهر الخطايا، ويمحو الآثام." } },
      { kind: 'hymn', text: { en: "Which is God the Word, who took flesh from you, and offered Himself as incense, to God His Father.", ar: "أي الله الكلمة، الذي تجسد منكِ، ورفع ذاته بخوراً، إلى الله أبيه." } },
      { kind: 'hymn', text: { en: "Wherefore everyone, magnifies you, O my Lady the Mother of God, the ever-holy.", ar: "من أجل هذا، كل واحد يعظمِك، يا سيدتي والدة الإله، القديسة كل حين." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'hymn', text: { en: "Wherefore truly, I do not err, whenever I call you, the golden censer.", ar: "حينئذ بالحقيقة، لا أخطيئ في شئ، إذا ما دعوتك، المجمرة الذهب." } },
      { kind: 'hymn', text: { en: "For therein, is offered, the choice incense, before the Holies.", ar: "فتلك يُرفع، فيها البخور، المختار، أمام الأقدس." } },
      { kind: 'hymn', text: { en: "Wherein God takes away, the sins of the people, through the burnt offerings, and the aroma of incense.", ar: "ويرفع الله هناك، خطايا الشعب، من قِبَل المحرقات، ورائحة البخور." } },
      { kind: 'hymn', text: { en: "You too O Mary, have carried in your womb, the Invisible, Word of the Father.", ar: "وأنتِ يا مريم، حملتِ في بطنِك، الغير منظور، كلمة الآب." } },
      { kind: 'hymn', text: { en: "He who offered Himself, as an acceptable sacrifice, upon the Cross, for the salvation of our race.", ar: "هذا الذي أصعد، ذاته ذبيحة، مقبولة على الصليب، عن خلاص جنسنا." } },
      { kind: 'hymn', text: { en: "Wherefore we, magnify you befittingly, with prophetic, hymnology.", ar: "من أجل هذا، نعظمِك، بإستحقاقٍ، بتماجيد نبوية." } },
      { kind: 'hymn', text: { en: "For they spoke of you, with great honor, O holy city, of the great King.", ar: "لأنهم تكلموا، من أجلِك بأعمال كريمة، أيتها المدينة المقدسة، التي للملك العظيم." } },
      { kind: 'hymn', text: { en: "We entreat and pray, that we may win mercy, through your intercessions, with the Lover of Mankind.", ar: "نسأل ونطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "The Gospel According to Saint Luke", ar: "الإنجيل لمعلمنا مار لوقا" } },
      { kind: 'gospel', text: { en: "Holy, holy, holy, a chapter reading from the Gospel according to our teacher Saint Luke the Evangelist. May his blessings be with us all. Amen.", ar: "قدوس قدوس قدوس، فصل من الإنجيل لمعلمنا مار لوقا البشير. بركاته على جميعناً. آمين." } },
      { kind: 'gospel', text: { en: "Luke 2:29-32", ar: "لوقا 2: 29-32" } },
      { kind: 'gospel', text: { en: "\"Lord, now You are letting Your servant depart in peace, according to Your word. For my eyes have seen Your salvation which You have prepared before the face of all peoples. A light to bring revelation to the Gentiles, and the glory of Your people Israel.\"", ar: "\"الآن يا سيدي أطلق عبدك بسلام بحسب قولك. لأن عيني قد أبصرتا خلاصك الذي أعددته قدام جميع الشعوب. نوراً تجلى للأمم، ومجداً لشعبك إسرائيل.\"" } },
      { kind: 'gospel', text: { en: "Glory be to God forever. Amen.", ar: "والمجد لله دائماً. آمين." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 7: Shere ne Maria", ar: "ثيؤطوكية الأحد — القطعة السابعة: شيري نيه ماريا" } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the beautiful dove, who gave birth to, God the Word.", ar: "السلام لكِ يا مريم، الحمامة الحسنة، التي ولدِت لنا، الله الكلمة." } },
      { kind: 'hymn', text: { en: "You are the flower, of incense, that has blossomed, from the root of Jesse.", ar: "أنتِ زهرة، البخور التي، أينعت من، أصل يسَّى." } },
      { kind: 'hymn', text: { en: "The rod of Aaron, which blossomed, without planting or watering, resembles you.", ar: "عصا هرون، التي أزهرت، بغير غرس ولا سقي، هي مثال لكِ." } },
      { kind: 'hymn', text: { en: "O who gave birth to Christ, our true God, without the seed of man, and remained a virgin.", ar: "يا مَنْ ولدِت المسيح، إلهنا بالحقيقة، وبغير زرع بشر، وأنتِ عذراء." } },
      { kind: 'hymn', text: { en: "Wherefore everyone, magnifies you, O my Lady the Mother of God, the ever-holy.", ar: "من أجل هذا، كل واحد يعظمِك، يا سيدتي والدة الإله، القديسة كل حين." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 7: Semoti", ar: "ثيؤطوكية الأحد — القطعة السابعة: سيموتي" } },
      { kind: 'hymn', text: { en: "You are called righteous, O Saint Mary, the second tabernacle, belonging to the holies.", ar: "مدعوة أنت، بالحقيقة، أيتها القديسة مريم، القبة التي للأقداس." } },
      { kind: 'hymn', text: { en: "Wherein is placed, the rod of Aaron, and the holy flower, of incense.", ar: "تلك الموضوع فيها، عصا هرون، والزهرة المقدسة، التي للبخور." } },
      { kind: 'hymn', text: { en: "You are clothed with purity, within and without, O pure tabernacle, the dwelling of the righteous.", ar: "أنت مشتملة بالطهارة، من داخل ومن خارج، أيتها القبة النقية، مسكن الصديقين." } },
      { kind: 'hymn', text: { en: "The hosts of the high standings, and the chorus of the just, glorify you, and your blessedness.", ar: "طغمات العلاء، وصفوف الأبرار، يمجدون، طوباويتك." } },
      { kind: 'hymn', text: { en: "Wherefore we, magnify you befittingly, with prophetic, hymnology.", ar: "من أجل هذا، نعظمِك، بإستحقاقٍ، بتماجيد نبوية." } },
      { kind: 'hymn', text: { en: "For they spoke of you, with great honor, O holy city, of the great King.", ar: "لأنهم تكلموا، من أجلِك بأعمال كريمة، أيتها المدينة المقدسة، التي للملك العظيم." } },
      { kind: 'hymn', text: { en: "We entreat and pray, that we may win mercy, through your intercessions, with the Lover of Mankind.", ar: "نسأل ونطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 8: Shashf Ensop", ar: "ثيؤطوكية الأحد — القطعة الثامنة: شاشف إنسوب" } },
      { kind: 'hymn', text: { en: "Seven times every day, I will praise Your name, with all my heart, O God of everyone.", ar: "سبع مرات كل يوم، من كل قلبي، أُبارك أسمك، يا رب الكل." } },
      { kind: 'hymn', text: { en: "I remembered Your name, and I was comforted, O King of the ages, and God of all gods.", ar: "ذكرت إسمك، فتعزيت، يا ملك الدهور، وإله الآلهة." } },
      { kind: 'hymn', text: { en: "Jesus Christ our true God, who has come, for our salvation, was incarnate.", ar: "يسوع المسيح إلهنا، الحقيقي الذي، أتى من أجل خلاصنا، متجسداً." } },
      { kind: 'hymn', text: { en: "He was incarnate, of the Holy Spirit, and of Mary, the pure bride.", ar: "وتجسد من، الروح القدس، ومن مريم، العروس الطاهرة." } },
      { kind: 'hymn', text: { en: "And changed our sorrow, and all our troubles, to joy for our hearts, and total rejoicing.", ar: "وقلب حُزننا، وكل ضيقنا، إلى فرح قلب، وتهليل كُلي." } },
      { kind: 'hymn', text: { en: "Let us worship Him, and sing about His Mother, the Virgin Mary, the beautiful dove.", ar: "فلنسجد له، ونرتل لأمه، مريم، الحمامة الحسنة." } },
      { kind: 'hymn', text: { en: "And let us all proclaim, with a voice of joy, saying hail to you Mary, the Mother of Emmanuel.", ar: "ونصرخ، بصوت التهليل قائلين، السلام لك يا مريم، أُم عمانوئيل." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the salvation of our father Adam, hail... the Mother of the Refuge, hail... the rejoicing of Eve, hail... the joy of all generations.", ar: "السلام لك يا مريم، خلاص أبينا آدم، السلام... أُم الملجأ، السلام... تهليل حواء، السلام... فرح الأجيال." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the joy of the righteous Abel, hail... the true Virgin, hail... the salvation of Noah, hail... the chaste and undefiled.", ar: "السلام لك يا مريم، فرح هابيل البار، السلام... العذراء الحقيقية، السلام... خلاص نوح، السلام... غير الدنسة الهادئة." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the grace of Abraham, hail... the unfading crown, hail... the redemption of St. Isaac, hail... the Mother of the Holy.", ar: "السلام لك يا مريم، نعمة إبراهيم، السلام... الإكليل غير المُضمحل، السلام... خلاص إسحق القديس، السلام... أُم القدوس." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the rejoicing of Jacob, hail... myriads of myriads, hail... the pride of Judah, hail... the Mother of the Master.", ar: "السلام لك يا مريم، تهليل يعقوب، السلام... ربوات مضاعفة، السلام... فخر يهوذا، السلام... أُم السيد." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the preaching of Moses, hail... the Mother of the Master, hail... the honor of Samuel, hail... the pride of Israel.", ar: "السلام لك يا مريم، كرازة موسى، السلام... والدة السيد، السلام... كرامة صموئيل، السلام... فخر إسرائيل." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the steadfastness of Job the righteous, hail... the precious stone, hail... the Mother of the Beloved, hail... the daughter of King David.", ar: "السلام لك يا مريم، ثبات أيوب البار، السلام... الحجر الكريم، السلام... أُم الحبيب، السلام... إبنة الملك داود." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the friend of Solomon, hail... the exaltation of the just, hail... the redemption of Isaiah, hail... the healing of Jeremiah.", ar: "السلام لك يا مريم، صديقة سليمان، السلام... رفعة الصديقين، السلام... خلاص أشعياء، السلام... شفاء أرميا." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the knowledge of Ezekiel, hail... the grace of Daniel, hail... the power of Elijah, hail... the grace of Elisha.", ar: "السلام لك يا مريم، عِلم حزقيال، السلام... نعمة دانيال، السلام... قوة إيليا، السلام... نعمة إليشع." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, the Mother of God, hail... the Mother of Jesus Christ, hail... the beautiful dove, hail... the Mother of the Son of God.", ar: "السلام لك يا مريم، والدة الإله، السلام... أم يسوع المسيح، السلام... الحمامة الحسناء، السلام... أم إبن الله." } },
      { kind: 'hymn', text: { en: "Hail to you Mary, who was witnessed by, all the prophets, and they said.\nBehold God the Word, took flesh from you, in an undescribable, unity.", ar: "السلام لمريم، التي شهد لها، جميع الأنبياء، وقالوا.\nهوذا الله الكلمة، الذي تجسد منكِ، بوحدانية، لا يُنطق بمِثلها." } },
      { kind: 'hymn', text: { en: "You are truly exalted, more than the rod, of Aaron, O full of grace.\nWhat is the rod, but Mary, for it is the symbol, of her virginity.", ar: "مرتفعة، أنت بالحقيقة، أكثر من عصا هرون، أيتها المُمتلئة نعمة.\nما هيَّ العصا، إلا مريم، لأنها مِثال، بتوليتها." } },
      { kind: 'hymn', text: { en: "She conceived and gave birth, without a man, to the Son of the Highest, the Word Himself.\nThrough her prayers, and intercessions, O Lord open unto us, the gates of the Church.", ar: "حبلت وولدت، بغير مباضعة، إبن العليِّ، الكلمة الذاتي.\nبصلواتها، وشفاعاتها، إفتح لنا يا رب، باب الكنيسة." } },
      { kind: 'hymn', text: { en: "I entreat you, O Mother of God, keep the gates of the church, open to the faithful.\nLet us ask her, to intercede for us, before her Beloved, that He may forgive us.", ar: "أسالكِ، يا والدة الإله، إجعلي أبواب الكنائس، مفتوحة للمؤمنين.\nفلنسألها، أن تطلب عنا، عند حبيبها، ليغفر لنا." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 9", ar: "ثيؤطوكية الأحد — القطعة التاسعة" } },
      { kind: 'hymn', text: { en: "You are called, O Virgin Mary, the holy flower, of the incense.", ar: "دعيتِ، يا مريم العذراء، الزهرة المقدسة، التي للبخور." } },
      { kind: 'hymn', text: { en: "Which came out, and blossomed, from the roots of the patriarchs, and the prophets.", ar: "التي طلعت، وأزهرت، من أصل رؤساء الآباء، والأنبياء." } },
      { kind: 'hymn', text: { en: "Like the rod, of Aaron the priest, which blossomed, and brought forth fruit.", ar: "مِثل عصا، هرون الكاهن، أزهرت، وأوسقت ثمراً." } },
      { kind: 'hymn', text: { en: "For you gave birth to the Word, without the seed of man, and your virginity, was not corrupted.", ar: "لأنكِ ولدتِ الكلمة، بغير زرع بشر، وبتوليتِك، بغير فساد." } },
      { kind: 'hymn', text: { en: "Wherefore we magnify you, as the Mother of God, ask your Son, to forgive us.", ar: "فلهذا نمجدكِ، كوالدة الإله، إسألي إبنِك، ليغفر لنا." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 10: Teoi Enhekanos", ar: "ثيؤطوكية الأحد — القطعة العاشرة: تي أوي إنهيكانوس" } },
      { kind: 'hymn', text: { en: "You are more worthy, than all of the saints, to ask on our behalf, O full of grace.", ar: "أنتِ مستحقة، أكثر من جميع القديسين، أن تطلبي عنا، أيتها الممتلئة نعمة." } },
      { kind: 'hymn', text: { en: "You are exalted, more than the patriarchs, and honored more, than the prophets.", ar: "أنتِ مرتفعة جداً، أكثر من رؤساء الآباء، ومكرمة أفضل، من الأنبياء." } },
      { kind: 'hymn', text: { en: "And you have a seeking, more special, than the Cherubim, and the Seraphim.", ar: "ولك سعيً، بدالة، أكثر من الشاروبيم، والسيرافيم." } },
      { kind: 'hymn', text: { en: "For you are truly, the pride of our race, and the intercessor, of our souls.", ar: "لأنكِ أنتِ بالحقيقة، فخر جنسنا، وشفيعة، نفوسنا." } },
      { kind: 'hymn', text: { en: "Intercede for us, before our Savior, that He may keep us firm, in the upright faith.", ar: "إشفعي فينا، أمام مخلصنا، لكي يثبتنا، في الإيمان المستقيم." } },
      { kind: 'hymn', text: { en: "That He may grant us, the forgiveness of our sins, in order to win mercy, through your intercessions.", ar: "وينعم لنا، بمغفرة خطايانا، لنفوز برحمةٍ، بشفاعاتِك." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 11", ar: "ثيؤطوكية الأحد — القطعة الحادية عشرة" } },
      { kind: 'hymn', text: { en: "All the high names, of the incorporeal, thousands of angels, and archangels.", ar: "كل الأسماء العالية، التي لغير المتجسدين، ألوف الملائكة، ورؤساء الملائكة." } },
      { kind: 'hymn', text: { en: "They did not attain, your high blessedness, O who is clothed in, the glory of the Lord of hosts.", ar: "لم يبلغوا، عظمة طوباوياتِك، أيتها المشتملة، بمجد رب الجنود." } },
      { kind: 'hymn', text: { en: "You are more brighter, than the sun, and more sparkling, than the Cherubim.", ar: "أنتِ مضيئة، أكثر من الشمس، ولامعة أكثر، من الشاروبيم." } },
      { kind: 'hymn', text: { en: "And the Seraphim, with the six wings, which are joyfully, hovering over you.", ar: "والسيرافيم، ذوى الستة الأجنحة، يرفرف عليكِ، بتهليل." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 12", ar: "ثيؤطوكية الأحد — القطعة الثانية عشرة" } },
      { kind: 'hymn', text: { en: "Your glory O Mary, is higher than the heaven, you are more honored than the earth, and its inhabitants.", ar: "مجدِك يا مريم، أرفع من السماء، وأنت أكرم من الأرض، وسكانها." } },
      { kind: 'hymn', text: { en: "For you are truly, the real path, leading up, to the heavens.", ar: "لأنكِ أنتِ بالحقيقة، الطريق الحقيقي، المؤدي، إلى السموات." } },
      { kind: 'hymn', text: { en: "You are clothed, with joy and gladness, and girdled with power, O daughter of Zion.", ar: "لبسِت الفرح، والتهليل، وتمنطقتِ بالقوة، يا إبنة صهيون." } },
      { kind: 'hymn', text: { en: "O who was clothed, with the garments of the heavenly, so that you covered Adam, with the garments of grace.", ar: "يا مَنْ لبسِت، لباس السمائيين، حتى سترتِ آدم، بلباس النعمة." } },
      { kind: 'hymn', text: { en: "And restored him again, to the Paradise, the rejoicing place, and dwelling of the righteous.", ar: "ورددته مرة أخري، إلى الفردوس، موضع الفرح، ومسكن الصديقين." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 13", ar: "ثيؤطوكية الأحد — القطعة الثالثة عشرة" } },
      { kind: 'hymn', text: { en: "A true tabernacle, is Mary the Virgin, placed in its midst, the true testimonies.", ar: "قبة حقيقية، هي مريم العذراء، موضوع في وسطها، الشهادات الصادقة." } },
      { kind: 'hymn', text: { en: "The undefiled ark, overlaid roundabout with gold, and the mercy seat, of the Cherubim.", ar: "التابوت الغير الدنس، المصَّفح بالذهب، من كل ناحية، والغطاء الكاروبي." } },
      { kind: 'hymn', text: { en: "The golden vessel, where the manna was hidden, behold the Word of the Father, came and took flesh from you.", ar: "القسط الذهبي، المخفي فيه المَنَّ، هوذا كلمة الآب، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "The golden lampstand, carrying the true Light, who is the unapproachable, Light of the world.", ar: "المنارة الذهبية، الحاملة النور الحقيقي، الذي هو نور العالم، الذي لا يُدنى منه." } },
      { kind: 'hymn', text: { en: "The golden censer, carrying the live coal, and the chosen incense, with a rich aroma.", ar: "المجمرة الذهبية، الحاملة جمر النار، والبخور المختار، العنبري." } },
      { kind: 'hymn', text: { en: "The rod of Aaron, that blossomed, and the holy flower, of the incense.", ar: "عصا هارون، التي أزهرت، والزهرة المقدسة، التي للبخور." } },
      { kind: 'hymn', text: { en: "All these together, direct us to, the miraculous Birth, O Virgin Mary.", ar: "هذة جميعها معاً، تدُلنا على، ولادتك العجيبة، يا مريم العذراء." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 14", ar: "ثيؤطوكية الأحد — القطعة الرابعة عشرة" } },
      { kind: 'hymn', text: { en: "You decorated our souls, O Moses the prophet, by the honor of the tabernacle, which you have adorned.", ar: "زينت نفوسنا، يا موسى النبي، بكرامة القبة، التي زينتها." } },
      { kind: 'hymn', text: { en: "The first tabernacle, which Moses had made, was the place of the forgiveness, for the children of Israel.", ar: "القبه الأولى، التي صنعها موسى، موضع مغفرة خطايا، بني إسرائيل." } },
      { kind: 'hymn', text: { en: "He made it with glory, as commanded by the Lord, and according to the patterns, shown unto him.", ar: "صنعها بمجد، كقول الرب، وكجميع المُثل، التي أعلمه بها." } },
      { kind: 'hymn', text: { en: "There was an ark, in the tabernacle, overlaid with gold, from within and without.", ar: "كان في القبة، تابوت مصَّفح، بالذهب من داخل، ومن خارج." } },
      { kind: 'hymn', text: { en: "There was a mercy seat, in the tabernacle, and the golden Cherubim, overshadowed it.", ar: "كان في القبة، غطاء وكاروبا، ذهب، يظللان عليه." } },
      { kind: 'hymn', text: { en: "There was a golden pot, in the tabernacle, and a measure of the manna, was hidden in it.", ar: "كان في القبة، قسط ذهبي، وكيل مَنَّ، مخفي فيه." } },
      { kind: 'hymn', text: { en: "There was a golden lampstand, in the tabernacle, and the seven lamps, shone upon it.", ar: "كان في القبة، منارة من ذهب، وسبعة سُرج، تضئ عليها." } },
      { kind: 'hymn', text: { en: "There was a golden censer, in the tabernacle, and the chosen aloe, was in its midst.", ar: "كان في القبة، مجمرة من ذهب، والعود المختار، في وسطها." } },
      { kind: 'hymn', text: { en: "There was a flower of incense, in the tabernacle, inhaled by all, the house of Israel.", ar: "كان في القبة، زهرة بخور، يستنشق رائحتها، جميع آل بيت إسرائيل." } },
      { kind: 'hymn', text: { en: "There was the rod of Aaron, in the tabernacle, this which has blossomed, without planting or watering.", ar: "كان في القبة، عصا هرون، هذه التي أزهرت، بغير غرس ولا سقي." } },
      { kind: 'hymn', text: { en: "There was a golden table, in the tabernacle, and the oblation bread, was placed upon it.", ar: "كان في القبة، مائدة ذهبية، وخبز التقدمة، موضوعاً عليها." } },
      { kind: 'hymn', text: { en: "There was a high priest, in the tabernacle, offering sacrifices, on account of the peoples sins.", ar: "كان في القبة، رئيس كهنة، يُصعد الذبائح، عن خطايا الشعب." } },
      { kind: 'hymn', text: { en: "When the Pantocrator, smelled the aroma, He lifted up the sins, of the people.", ar: "إذا إشتم رائحتها، ضابط الكل، يرفع هنالك، خطايا الشعب." } },
      { kind: 'hymn', text: { en: "Through Mary, the daughter of Joachim, we learned of the true Sacrifice, for the forgiveness of sin.", ar: "من قِبَل مريم، إبنة يواقيم، عرفنا الذبيحة الحقيقية، لمغفرة الخطايا." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 15: Aven Pi-arshee-erevs", ar: "ثيؤطوكية الأحد — القطعة الخامسة عشرة: أف إن بي أرشي إريفس" } },
      { kind: 'hymn', text: { en: "They likened the high priest, to our Savior, the true Sacrifice, for the forgiveness of sins.", ar: "شبهوا رئيس الكهنة، بمخلصنا، الذبيحة الحقيقية، لمغفرة الخطايا." } },
      { kind: 'hymn', text: { en: "He who offered Himself, as an acceptable sacrifice, upon the Cross, for the salvation of our race.", ar: "هذا الذي أصعد ذاته، ذبيحة مقبولة، على الصليب، عن خلاص جنسنا." } },
      { kind: 'hymn', text: { en: "His good Father, smelled Him, in the evening, on Golgotha.", ar: "فإشتمه، أبوه الصالح، وقت المساء، على الجلجثة." } },
      { kind: 'hymn', text: { en: "He opened the gate, of Paradise, and restored Adam again, to his authority.", ar: "فتح باب الفردوس، وردَّ آدم، إلى رئاسته، مرة أخرى." } },
      { kind: 'hymn', text: { en: "Through Mary, the daughter of Joachim, we learned of the true Sacrifice, for the forgiveness of sins.", ar: "من قِبَل مريم، إبنة يواقيم، عرفنا الذبيحة الحقيقية، لمغفرة الخطايا." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً، نطلب أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 16: Nim Ghar", ar: "ثيؤطوكية الأحد — القطعة السادسة عشرة: نيم غار" } },
      { kind: 'hymn', text: { en: "Who is likened unto You, O Lord among the gods, You are the true God, the Performer of miracles.", ar: "مَنْ في الآلهة، يشبهك يا رب، أنت هو الإله الحقيقي، الصانع العجائب." } },
      { kind: 'hymn', text: { en: "You revealed Your power, to the people, and You saved Your people, with Your arm.", ar: "أظهرت قوتك، في الشعوب، وخلصت شعبك، بذراعك." } },
      { kind: 'hymn', text: { en: "You descended into Hades, and brought up, those who were captives, in that place.", ar: "مضيت إلى الجحيم، وأصعدتَ، السبي من ذلك، المكان." } },
      { kind: 'hymn', text: { en: "And granted us again, the freedom, as a good God, for You have risen and saved us.", ar: "وأنعمت علينا، مرة أخرى بالحرية، كإله صالح، لأنك قُمت وخلصتنا." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 17", ar: "ثيؤطوكية الأحد — القطعة السابعة عشرة" } },
      { kind: 'hymn', text: { en: "Christ our God, has risen from the dead, He is the first-fruit, of those who departed.", ar: "المسيح إلهنا، قام من الأموات، وهو باكورة، الراقدين." } },
      { kind: 'hymn', text: { en: "He appeared to Mary, Magdalene, and spoke to her, and likewise said.", ar: "ظهر لمريم، المجدلية، وخاطبها، هكذا قائلاً." } },
      { kind: 'hymn', text: { en: "\"Tell My brethren, to proceed, to Galilee, and there they will see Me.\"", ar: "\"إعلمي إخوتي، أن يذهبوا، إلى الجليل، هناك يرونني.\"" } },
      { kind: 'hymn', text: { en: "So Mary came forth, to the disciples, and told them she had seen the Lord, and that He told her so.", ar: "فجاءت مريم، إلى التلاميذ، وقالت أنها رأت الرب، وأنه قال لها هذا." } },
      { kind: 'heading', text: { en: "Sunday Theotokia — Part 18", ar: "ثيؤطوكية الأحد — القطعة الثامنة عشرة" } },
      { kind: 'hymn', text: { en: "Truly indeed, it was good caring, of the Saint Mary, Magdalene.", ar: "كان بالحقيقة، إهتمام القديسة، مريم المجدلية، حسناً." } },
      { kind: 'hymn', text: { en: "She came to the grave, on one of the Sabbath days, seeking earnestly, the Resurrection of the Lord.", ar: "في أحد السبوت، أتت إلى القبر، طالبة باجتهاد، قيامة الرب." } },
      { kind: 'hymn', text: { en: "She saw the angel, sitting on the stone, proclaiming and saying, \"He is risen He is not here.\"", ar: "فرأت الملاك، جالساً على الحجر، صارخاً قائلاً، \"قد قام ليس هو ههنا.\"" } },
      { kind: 'hymn', text: { en: "Wherefore we glorify Him, proclaiming and saying, \"Blessed are You O my Lord Jesus, for You have risen and saved us.\"", ar: "فلهذا نمجده، صارخين قائلين، \"مبارك أنت يا ربي يسوع، لأنك قُمت وخلصتنا.\"" } },
      { kind: 'heading', text: { en: "Introduction to the Difnar — Adam", ar: "مقدمة الدفنار — آدام" } },
      { kind: 'hymn', text: { en: "O come let us worship, the Holy Trinity, the Father and the Son, and the Holy Spirit.", ar: "تعالوا فلنسجد، للثالوث القدوس، الذي هو الآب والإبن، والروح القُدُس." } },
      { kind: 'hymn', text: { en: "Hail to you O Mary, the beautiful dove, who gave birth to, God the Word for us.", ar: "السلام لكِ يا مريم، الحمامة الحسنة، التي ولدت لنا، الله الكلمة." } },
      { kind: 'heading', text: { en: "Conclusion of the Adam Theotokias", ar: "ختام الثيؤطوكيات الآدام" } },
      { kind: 'prayer', text: { en: "Your mercies O my God, are countless, and exceedingly plenteous, are Your compassion.", ar: "مراحمك يا إلهي، غير محصاة، وكثيرة جداً، هي رأفاتك." } },
      { kind: 'prayer', text: { en: "All the rain drops, are counted by You, and the sand of the sea, is before Your eyes.", ar: "قطرات المطر، محصاة عندك جميعها، ورمل البحر، كائن أمام عينيك." } },
      { kind: 'prayer', text: { en: "How much more are, the sins of my soul, manifest before You, O my Lord.", ar: "فكم بالحري، خطايا نفسي، هذه الظاهرة، أمامك يا ربي." } },
      { kind: 'prayer', text: { en: "The sins that I have committed, do not remember my Lord, and do not count, my iniquities.", ar: "الخطايا التي صنعتها، يا ربي لا تذكرها، ولا تحسب، آثامي." } },
      { kind: 'prayer', text: { en: "For You have chosen the publican, and the adulteress You have saved, and the right-hand thief, my Lord You have remembered.", ar: "فإن العشار إخترته، والزانية خلصتها، واللص اليمين، يا سيدي ذكرته." } },
      { kind: 'prayer', text: { en: "And me too, the sinner, teach me O my Master, to offer repentance.", ar: "وأنا أيضاً الخاطئ، يا سيدي، علمني، أن أصنع توبة." } },
      { kind: 'prayer', text: { en: "For You do not desire, the death of a sinner, but rather that he returns, and that his soul may live.", ar: "لأنك لا تشاء، موت الخاطئ، مثل أن يرجع، وتحيا نفسه." } },
      { kind: 'prayer', text: { en: "Restore us O God, to Your salvation, and deal with us, according to Your goodness.", ar: "ردنا يا الله، إلى خلاصك، وعاملنا، كصلاحك." } },
      { kind: 'prayer', text: { en: "For You are good, and merciful, let Your compassion, speedily come to us.", ar: "لأنك أنت صالح، ورحوم، فلتدركنا، رأفاتك سريعاً." } },
      { kind: 'prayer', text: { en: "Have compassion upon us all, O Lord God our Savior, and have mercy upon us, according to Your great mercy.", ar: "ترأف علينا كلنا، أيها الرب الإله، مخلصنا وإرحمنا، كعظيم رحمتك." } },
      { kind: 'prayer', text: { en: "Remember those, O Christ our Master, be among us, and proclaim and say.", ar: "هؤلاء أذكرهم، يا سيدنا المسيح، كن في وسطنا، صارخاً قائلاً:" } },
      { kind: 'prayer', text: { en: "\"My peace I, give to you, the peace of My Father, I leave with you.\"", ar: "\"سلامي أنا، أعطيكم، سلام أبي، أتركه معكم.\"" } },
      { kind: 'prayer', text: { en: "O King of peace, grant us Your peace, render unto us Your peace, and forgive us our sins.", ar: "يا ملك السلام، أعطنا سلامك، قرر لنا سلامك، وإغفر لنا خطايانا." } },
      { kind: 'prayer', text: { en: "Disperse the enemies, of the Church, and fortify her that she, may not be shaken forever.", ar: "فرِّق أعداء الكنيسة، وحصنها، فلا تتزعزع، إلى الأبد." } },
      { kind: 'prayer', text: { en: "Emmanuel our God, is now in our midst, with the glory of His Father, and the Holy Spirit.", ar: "عمانوئيل إلهنا، في وسطنا الآن، بمجد أبيه، والروح القدس." } },
      { kind: 'prayer', text: { en: "May He bless us all, and purify our hearts, and heal the sicknesses, of our souls and bodies.", ar: "ليباركنا كلنا، ويطهر قلوبنا، ويشفي أمراض، نفوسنا وأجسادنا." } },
      { kind: 'prayer', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع إبيك الصالح، والروح القدس، لأنك (قمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Concluding Litany", ar: "طلبة الختام" } },
      { kind: 'litany', text: { en: "Kerie leysoun (Lord have mercy) is said three times before every part", ar: "يقال كيريي ليسون (يا رب إرحم) ثلاث مرات قبل كل ربع" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." } },
      { kind: 'litany', text: { en: "Kerie leysoun (3).", ar: "كيريي ليسون (3)." } },
      { kind: 'litany', text: { en: "O God have mercy on us.", ar: "يا الله إرحمنا." } },
      { kind: 'litany', text: { en: "O God hear us.", ar: "يا الله إسمعنا." } },
      { kind: 'litany', text: { en: "O God look to us.", ar: "يا الله أُنظر إلينا." } },
      { kind: 'litany', text: { en: "O God behold us.", ar: "يا الله إطَّلع علينا." } },
      { kind: 'litany', text: { en: "O God have compassion on us.", ar: "يا الله تراءف علينا." } },
      { kind: 'litany', text: { en: "We are Your people.", ar: "نحن شعبك." } },
      { kind: 'litany', text: { en: "We are Your creation.", ar: "نحن جبلتك." } },
      { kind: 'litany', text: { en: "Deliver us from our enemies.", ar: "نجنا من أعدائنا." } },
      { kind: 'litany', text: { en: "Deliver us from inflation.", ar: "نجنا من الغلاء." } },
      { kind: 'litany', text: { en: "We are Your servants.", ar: "نحن عبيدك." } },
      { kind: 'litany', text: { en: "You are the Son of God.", ar: "أنت إبن الله." } },
      { kind: 'litany', text: { en: "We believe in You.", ar: "آمنا بك." } },
      { kind: 'litany', text: { en: "For You have (risen/come) and saved us.", ar: "لأنك (قُمت/أتيت) وخلَّصتنا." } },
      { kind: 'litany', text: { en: "Visit us with Your salvation.", ar: "تعهدنا بخلاصك." } },
      { kind: 'litany', text: { en: "And forgive us our sins.", ar: "وإغفر لنا خطايانا." } },
      { kind: 'litany', text: { en: "Kerie leysoun.", ar: "كيريي ليسون." } },
      { kind: 'heading', text: { en: "The Morning Doxology", ar: "ذكصولوجية باكر" } },
      { kind: 'doxology', text: { en: "We worship the Father and the Son, and the Holy Spirit, hail to the church, the house of the angels.", ar: "نسجد للآب والإبن، والروح القدس، السلام للكنيسة، بيت الملائكة." } },
      { kind: 'doxology', text: { en: "Hail to the Virgin, who gave birth to our Savior, hail to Gabriel, who announced to her the good news.", ar: "السلام للعذراء، التي ولدت مخلصنا، السلام لغبريال، الذي بشرها." } },
      { kind: 'doxology', text: { en: "Hail to Michael, the archangel, hail to the twenty four, presbyters.", ar: "السلام لميخائيل، رئيس الملائكة، السلام للأربعة والعشرين، قسيساً." } },
      { kind: 'doxology', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the hosts, of the heavens.", ar: "السلام للشاروبيم، السلام للسارافيم، السلام لجميع الطغمات، السمائية." } },
      { kind: 'doxology', text: { en: "Hail to John, the great forerunner, hail to the, twelve Apostles.", ar: "السلام ليوحنا، السابق العظيم، السلام للإثنى عشر، رسولاً." } },
      { kind: 'doxology', text: { en: "Hail to our father Mark, the Evangelist, the destroyer, of the idols.", ar: "السلام لأبينا مرقس، الإنجيلي، مُبَدِد، الأوثان." } },
      { kind: 'doxology', text: { en: "Hail to Stephen, the first martyr, hail to George, the morning star.", ar: "السلام لإستفانوس، الشهيد الأول، السلام لجرجس، كوكب الصبح." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the martyrs, hail to Abba Antony, and the three Macarii.", ar: "السلام لجميع صفوف، الشهداء، السلام لأنبا أنطونيوس، والثلاثة المقارات." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the cross-bearers, hail to all the saints, who have pleased the Lord.", ar: "السلام لجميع صفوف، لُباس الصليب، السلام لجميع القديسين، الذين أرضوا الرب." } },
      { kind: 'doxology', text: { en: "Through their prayers, O Christ our King, have mercy upon us, in Your kingdom.", ar: "أيها المسيح ملكنا، بصلواتهم، إصنع معنا رحمة، في ملكوتك." } },
      { kind: 'doxology', text: { en: "(For Our Lord Jesus Christ)", ar: "(لأجل ربنا يسوع المسيح)" } },
      { kind: 'doxology', text: { en: "O true Light, that gives light, to every man, that comes into the world.", ar: "أيها النور الحقيقي، الذي يضئ، لكل إنسان، آتٍ إلى العالم." } },
      { kind: 'doxology', text: { en: "You came into the world, through Your love for man, and all the creation, rejoiced at Your coming.", ar: "أتيت إلى العالم، بمحبتك للبشر، وكل الخليقة، تهللت بمجيئك." } },
      { kind: 'doxology', text: { en: "You have saved Adam, from seduction, and delivered Eve, from the pangs of death.", ar: "خلصَّت آدم، من الغواية، وعتقت حواء، من طلقات الموت." } },
      { kind: 'doxology', text: { en: "You gave unto us, the Spirit of sonship, we praise and bless You, with Your angels.", ar: "أعطيتنا، روح النبوة، نسبحك ونباركك، مع ملائكتك." } },
      { kind: 'doxology', text: { en: "When the morning hour, comes upon us, O Christ our God, the true Light.", ar: "عندما يدخل، وقت باكر إلينا، أيها المسيح إلهنا، النور الحقيقي." } },
      { kind: 'doxology', text: { en: "Let the thought of light, shine within us, and do not let the darkness, of pain cover us.", ar: "فلتشرق فينا، حواس النور، ولا تغطينا، ظلمة الآلام." } },
      { kind: 'doxology', text: { en: "That we may praise You, with understanding, proclaiming and saying, with David.", ar: "لكي نسبحك، عقلياً، مع داود، صارخين، نحوك قائلين." } },
      { kind: 'doxology', text: { en: "\"My eyes have reached, the morning watch, that I may meditate, upon all Your words.\"", ar: "\"سبق أن بلغت، عيناي وقت السحر، لأتلو، جميع أقوالك.\"" } },
      { kind: 'doxology', text: { en: "Hear our voices, according to Your great mercy, save us O Lord our God, according to Your compassion.", ar: "إسمع صوتنا، كعظيم رحمتك، ونجنا أيها الرب إلهنا، حسب رأفاتك." } },
      { kind: 'doxology', text: { en: "O caring God, the Maker of all good things, who governs well, with His chosen ones.", ar: "يا الله المُهْتم، صانع الخيرات، مُدبر مُختاريه، حسناً." } },
      { kind: 'doxology', text: { en: "The strong Governor for those, who take refuge in Him, who longs for the salvation, and deliverance of everyone.", ar: "المدبر القوي، للملتجئين، المتشوق لخلاص، ونجاة كل أحد." } },
      { kind: 'doxology', text: { en: "Through Your goodness, You provided us the night, grant us to pass, this day without sin.", ar: "بصلاحك هيأت، لنا الليل، أنعم لنا بهذا اليوم، ونحن بغير خطية." } },
      { kind: 'doxology', text: { en: "That we may be worthy, to lift up our hands, before You without anger, or evil thoughts.", ar: "لنستحق أن نرفع، أيدينا إليك، أمامك بغير غضب، ولا فكر ردئ." } },
      { kind: 'doxology', text: { en: "At this dawn, make straight our coming in, and our going out, in the joy of Your protection.", ar: "في هذا السحر، سهل طرقنا، الداخلية والخارجية، بسترك المفرح." } },
      { kind: 'doxology', text: { en: "That we may proclaim, Your righteousness daily, and praise Your power, with David the prophet.", ar: "لننطق بعدلك، كل يوم، ونمجد قوتك، مع داود النبي." } },
      { kind: 'doxology', text: { en: "Saying \"In Your peace, O Christ our Savior, we slept and arose, for we have hoped in You.", ar: "قائلين \"بسلامك، أيها المسيح مخلصنا، رقدنا وقمنا، لأننا توكلنا عليك." } },
      { kind: 'doxology', text: { en: "Behold how beneficent, and how pleasant, it is for brethren, to dwell together in unity.\"", ar: "ها ما هو الحسن، وما هو الحلو، إلا إتفاق إخوة، ساكنين معاً.\"" } },
      { kind: 'doxology', text: { en: "United, in the true, evangelic love, like the Apostles.", ar: "مُتفقين، بمحبة حقيقية، إنجيلية، كمثل الرسل." } },
      { kind: 'doxology', text: { en: "It is like the fragrant oil, on the head of Christ, running down the beard, down to the feet.", ar: "مثل الطيب، على رأس المسيح، النازل على اللحية، إلى أسفل الرجلين." } },
      { kind: 'doxology', text: { en: "That anoints every day, the elders, the children and young men, and the deacons.", ar: "يمسح كل يوم، الشيوخ، والصبيان والفتيات، والخدام." } },
      { kind: 'doxology', text: { en: "Those whom the Holy Spirit, has attuned together, as a stringed instrument, always blessing God.", ar: "هؤلاء الذين، ألَّفهم الروح القدس معاً، مثل قيثارة مُسبحين، الله كل حين." } },
      { kind: 'doxology', text: { en: "By psalms and hymns, and spiritual songs, by day and by night, with an incessant heart.", ar: "بمزامير وتسابيح، وترانيم روحية، النهار والليل، بقلب لا يفتر." } },
      { kind: 'doxology', text: { en: "(For the Virgin)", ar: "(لأجل العذراء)" } },
      { kind: 'doxology', text: { en: "You are the Mother of the Light, the honored Mother of God, you have carried, the Uncircumscript Logos.", ar: "أنتِ يا أم النور، المكرمة والدة الإله، حملتِ الكلمة، غير المحوي." } },
      { kind: 'doxology', text: { en: "After you gave birth to Him, you remained a virgin, with praises and blessings, we magnify you.", ar: "ومن بعد أن ولدتِه، بقيتِ عذراء، نعظمكِ بتسابيح، وبركات." } },
      { kind: 'doxology', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والروح القدس، آتى وخلصنا." } },
      { kind: 'doxology', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً، نطلب أن نفوز، برحمة بشفاعاتك، لدى محب البشر." } },
      { kind: 'doxology', text: { en: "The select incense, of your virginity, ascended to the throne, of the Father.", ar: "البخور المختار، الذي لبتوليتك، صعد إلى، كرسي الآب." } },
      { kind: 'doxology', text: { en: "Better than the incense, of the Cherubim, and the Seraphim, O Virgin Mary.", ar: "أفضل من بخور، الشاروبيم، والسارافيم، يا مريم العذراء." } },
      { kind: 'doxology', text: { en: "Hail to the new heaven, whom the Father has created, and made a place of rest, for His beloved Son.", ar: "السلام للسماء الجديدة، التي صنعها الآب، وجعلها موضع راحة، لإبنه الحبيب." } },
      { kind: 'doxology', text: { en: "Hail to the royal throne, of Him who is, carried by, the Cherubim.", ar: "السلام للكرسي، الملوكي، الذي للمحمول، على الشاروبيم." } },
      { kind: 'doxology', text: { en: "Hail to the advocate, of our souls, you are indeed, the pride of our race.", ar: "السلام لشفيعة، نفوسنا، أنت بالحقيقة، فخر جنسنا." } },
      { kind: 'doxology', text: { en: "Intercede on our behalf, O full of grace, before our Savior, our Lord Jesus Christ.", ar: "إشفعي فينا، يا ممتلئة نعمة، أمام مخلصنا، ربنا يسوع المسيح." } },
      { kind: 'doxology', text: { en: "That He may confirm us, in the upright faith, and grant us the forgiveness, of our sins.", ar: "لكي يثبتنا، في الإيمان المستقيم، وينعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Angels)", ar: "(لأجل الملائكة)" } },
      { kind: 'doxology', text: { en: "Thousands of thousands, and myriads of myriads, of archangels, and holy angels.", ar: "ألوف ألوف، وربوات ربوات، رؤساء ملائكة، وملائكة مُقدسيين." } },
      { kind: 'doxology', text: { en: "They stand before, the throne, of the Pantocrator, proclaiming and saying.", ar: "وقوف أمام، كرسي، ضابط الكل، صارخين قائلين:" } },
      { kind: 'doxology', text: { en: "\"Holy holy, holy in truth, the glory and the honor, befit the Trinity.\"", ar: "\"قدوس قدوس، قدوس بالحقيقة، المجد والكرامة، يليقان بالثالوث.\"" } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the whole choir of the angels, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، جميع صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Apostles)", ar: "(لأجل الرسل)" } },
      { kind: 'doxology', text: { en: "Our fathers the Apostles, preached unto the nations, the Gospel, of Jesus Christ.", ar: "آباؤنا الرسل، بشروا في الأمم، بإنجيل، يسوع المسيح." } },
      { kind: 'doxology', text: { en: "Their voices went forth, into all the earth, and their words have reached, the ends of the world.", ar: "خرجت أصواتهم، إلى الأرض كلها، وبلغ كلامهم، إلى أقطار المسكونة." } },
      { kind: 'doxology', text: { en: "Through the prayers, of my masters the fathers the Apostles, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، سادتي الآباء الرسل، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Martyrs)", ar: "(لأجل الشهداء)" } },
      { kind: 'doxology', text: { en: "Unfading crowns, the Lord has placed, upon the whole choir, of the martyrs.", ar: "أكاليل غير مضمحلة، جعلها الرب، على جميع، صفوف الشهداء." } },
      { kind: 'doxology', text: { en: "He saved and delivered them, because they took refuge in Him, they celebrated with Him, in His kingdom.", ar: "أنقذهم وخلصهم، لأنهم إلتجأوا إليه، وعيدوا معه، في ملكوته." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the martyrs, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، جميع صفوف الشهداء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Saints)", ar: "(لأجل القديسين)" } },
      { kind: 'doxology', text: { en: "Your saints bless You, and they speak, of the glory, of Your kingdom.", ar: "قديسوك، يباركونك، وينطقون بمجد، ملكوتك." } },
      { kind: 'doxology', text: { en: "Your kingdom O my God, is an eternal kingdom, and Your Lordship, is unto all ages.", ar: "ملكوتك يا إلهي، ملكوت أبدي، وربوبيتك، إلى كل الأجيال." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the cross-bearers, the righteous and the just, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، كافة مصاف لابسي الصليب، والأبرار والصديقين، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Patriarchs and the Prophets)", ar: "(لأجل الآباء والأنبياء)" } },
      { kind: 'doxology', text: { en: "Hail to Elijah, the prophet of temperance, and Elisha, his elect disciple.", ar: "السلام لإيليا، النبي المتعفف، وإليشع، تلميذه المختار." } },
      { kind: 'doxology', text: { en: "The great Evangelist, of the land of Egypt, Mark the Apostle, the first prelate.", ar: "المبشر العظيم، في كورة مصر، مرقس الرسول، مدبرها الأول." } },
      { kind: 'doxology', text: { en: "You are the Mother of God, O Virgin Mary, ask Him on our behalf, to have mercy upon our race.", ar: "أنت هي أم الله، يا مريم العذراء، أُطلبي منه عنا، أن يرحم جنسنا." } },
      { kind: 'doxology', text: { en: "The great patriarch, our father Abba Severus, whose holy teachings, enlightened our minds.", ar: "البطريرك العظيم، أبونا أنبا ساويرس، الذي أنارت تعاليمه، المقدسة عقولنا." } },
      { kind: 'doxology', text: { en: "Our father the confessor, Abba Dioscorus, defended the faith, against the heretics.", ar: "أبونا المعترف، أنبا ديسقوروس، حارب عن الإيمان، ضد الهراطقة." } },
      { kind: 'doxology', text: { en: "And all of our fathers, who have pleased the Lord, may their holy blessings, be a guard unto us.", ar: "وكل آبائنا، الذين أرضوا الرب، بركتهم المقدسة، تكون لنا حارساً." } },
      { kind: 'doxology', text: { en: "Through their prayers, O God grant us, the forgiveness of our sins, and give us peace.", ar: "بصلواتهم، إنعم لنا يا الله، بمغفرة خطايانا، وأعطنا سلاماً." } }
    ],
  },
  {
    id: "psalmody-midnight-monday",
    title: { en: "Monday Midnight Praises", ar: "تسبحة نصف الليل ليوم الإثنين" },
    blocks: [
      { kind: 'note', text: { en: "The complete fixed annual Monday (Adam) Midnight Psalmody.", ar: "النصوص الثابتة الكاملة للإبصلمودية السنوية لنصف الليل ليوم الإثنين (آدام)." } },
      { kind: 'heading', text: { en: "Ten-theno", ar: "تين ثينو" } },
      { kind: 'prayer', text: { en: "Arise O children of the light, let us praise the Lord of hosts.", ar: "قوموا يا بني النور، لنسبح رب القوات." } },
      { kind: 'prayer', text: { en: "That He may grant us the salvation of our souls.", ar: "لكي ينعم لنا بخلاص نفوسنا." } },
      { kind: 'prayer', text: { en: "Whenever we stand before You in the flesh.", ar: "عندما نقف أمامك جسدياً." } },
      { kind: 'prayer', text: { en: "Cast away from our minds the slumber of sleep.", ar: "إنزع عن عقولنا نوم الغفلة." } },
      { kind: 'prayer', text: { en: "Grant us sobriety O Lord, that we may know how to stand before You at times of prayer.", ar: "أعطنا يا رب يقظة، لكي نفهم أن نقف أمامك وقت الصلاة." } },
      { kind: 'prayer', text: { en: "And ascribe unto You the befitting glorification, and win the forgiveness of our many sins. Glory be to You O Lover of Mankind.", ar: "ونرسل لك إلى فوق التمجيد اللائق، ونفوز بغفران خطايانا الكثيرة. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Behold bless the Lord all you servants of the Lord. Glory be to You O Lover of Mankind.", ar: "ها باركوا الرب يا عبيد الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "You who stand in the house of the Lord, in the courts of the house of our God. Glory be to You O Lover of Mankind.", ar: "القائمين في بيت الرب، في ديار بيت إلهنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "By night lift up your hands O you saints and bless the Lord. Glory be to You O Lover of Mankind.", ar: "بالليالي إرفعوا أيديكم إلى فوق أيها القديسون باركوا الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "The Lord bless you from Zion, who created heaven and earth. Glory be to You O Lover of Mankind.", ar: "يباركك الرب من صهيون، الذي خلق السماء والأرض. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my cry come before You O Lord, give me understanding according to Your word. Glory be to You O Lover of Mankind.", ar: "فلتدن وسيلتي قدامك يا رب، كقولك فهمني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my supplication come before You, deliver me according to Your word. Glory be to You O Lover of Mankind.", ar: "ليدخل إبتهالي أمامك، ككلمتك أحيني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My lips shall overflow with praise, when You have taught me Your statutes. Glory be to You O Lover of Mankind.", ar: "تفيض شفتاي السُبح، إذا ما علمتني حقوقك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My tongue shall speak of Your words for all Your commandments are righteous. Glory be to You O Lover of Mankind.", ar: "لساني يجيب بأقوالك لأن جميع وصاياك هي حق. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let Your hand help me for I have chosen Your precepts. Glory be to You O Lover of Mankind.", ar: "لتكن يدك لتخلصني لأني إشتهيت وصاياك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have longed for Your salvation O Lord, and Your Law is my delight. Glory be to You O Lover of Mankind.", ar: "إشتقت إلى خلاصك يا رب، وناموسك هو تلاوتي. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my soul live and it shall praise You, and let Your judgments help me. Glory be to You O Lover of Mankind.", ar: "تحيا نفسي وتسبحك، وأحكامك تعينني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have gone astray like a lost sheep, seek Your servant for I do not forget Your commandments. Glory be to You O Lover of Mankind.", ar: "ضللت مثل الخروف الضال، فأُطلب عبدك لأني لوصاياك لم أنس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Now and forever and unto the age of all ages Amen. Glory be to You O Lover of Mankind.", ar: "الآن وكل أوان وإلى دهر الدهور آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit, now and forever and unto all the ages Amen. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس منذ الآن وإلى أبد الأبدين كلها آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O good One the Lover of Mankind, glory be to Your Mother the Virgin and all Your saints. Glory be to You O Lover of Mankind.", ar: "المجد لك يا محب البشر الصالح، المجد لأُمك العذراء وجميع قديسيك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O only-begotten One, O holy Trinity have mercy upon us. Glory be to You O Lover of Mankind.", ar: "المجد لك أيها الوحيد، أيها الثالوث القدوس إرحمنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let God arise and let all His enemies be scattered and let all that hate His holy name flee from before His face. Glory be to You O Lover of Mankind.", ar: "ليقم الله ولتتبدَّد جميع أعدائه وليهرب من قدام وجهه كل مُبغضي إسمه القدوس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "As for Your people let them be blessed, a thousand thousand fold and ten thousand ten thousand fold, doing Your will.", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادتك." } },
      { kind: 'prayer', text: { en: "O Lord open my lips, and my mouth shall declare Your praise.", ar: "يا رب إفتح شفتيَ ولينطق فمي بتسبحتك." } },
      { kind: 'heading', text: { en: "The First Hoos", ar: "الهوس الأول" } },
      { kind: 'hymn', text: { en: "Then Moses and the children of Israel sang this song to the Lord and spoke saying, \"I will sing to the Lord for He has triumphed gloriously.\"", ar: "حينئذ سبح موسى وبنو إسرائيل بهذه التسبحة للرب وقالوا، \"فلنسبح للرب لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider He has thrown into the sea. The Lord is my strength and song, and He has become my salvation.", ar: "الفَرس وراكبه طرحهما في البحر. مُعيني وساتري، صار لي خلاصاً." } },
      { kind: 'hymn', text: { en: "He is my God and I will glorify Him, my father´s God and I will exalt Him.", ar: "هذا هو إلهي فأمجده، إله أبي فأرفعه." } },
      { kind: 'hymn', text: { en: "The Lord is a Man of war, the Lord is His name. Pharaoh's chariots and his army He has cast into the sea.", ar: "الرب مكسر الحروب، الرب إسمه. مركبات فرعون وكل قوته طرحهما في البحر." } },
      { kind: 'hymn', text: { en: "His chosen captains also are drowned in the Red Sea.", ar: "ركباناً منتخبين ذي ثلاث جنبات غرقهم في البحر الأحمر." } },
      { kind: 'hymn', text: { en: "The depths have covered them; they sank to the bottom as a stone.", ar: "غطاهم الماء، إنغمسوا إلى العمق مثل الحجر." } },
      { kind: 'hymn', text: { en: "Your right hand O Lord has become glorious in power. Your right hand O Lord has dashed the enemy in pieces.", ar: "يمينك يا رب تمجدت بالقوة. يدك اليمنى يا إلهي أهلكت أعداءك." } },
      { kind: 'hymn', text: { en: "And in the greatness of Your excellence, You have overthrown those who rose up against You, You sent forth Your wrath, it consumed them like stubble.", ar: "بكثرة مجدك، سحقت الذين يقاوموننا، أرسلت غضبك، فأكلهم مثل الهشيم." } },
      { kind: 'hymn', text: { en: "And with the blast of Your nostrils the waters were gathered together, the flood stood upright like a wall, and the depths were congealed in the heart of the sea.", ar: "وبروح غضبك وقف الماء، وإرتفعت الماء مثل السور، وجمدت الأمواج في وسط البحر." } },
      { kind: 'hymn', text: { en: "The enemy said, \"I will pursue, I will overtake, I will divide the spoil, my lust shall be satisfied upon them, I will draw my sword and my hand shall destroy them.\"", ar: "قال العدو، \"إني أسرع فأدرك، وأقسم الغنائم، وأشبع نفسي، وأقتل بسيفي ويدي تتسلط.\"" } },
      { kind: 'hymn', text: { en: "You blew with Your wind, the sea covered them, they sank like lead in the mighty waters.", ar: "أرسلت روحك، فغطاهم البحر، وغطسوا إلى أسفل كالرصاص في مياه كثيرة." } },
      { kind: 'hymn', text: { en: "Who is like You O Lord among the gods? Who is like You, glorified in His saints, amazing in glory, performing wonders.", ar: "من يشبهك في الآلهة. يا رب من يشبهك، مُمجداً في قديسيك، متعجباً منك بالمجد، صانعاً عجائب." } },
      { kind: 'hymn', text: { en: "You stretched out Your right hand, the earth swallowed them. You in Your mercy have led forth the people whom You have redeemed, You have guided them in Your strength, to Your holy habitation.", ar: "مددت يمينك فإبتلعتهم الأرض. هديت شعبك بالحقيقة، هذا الذي إخترته، وقويته بتعزيتك، إلى موضع راحة قدسك." } },
      { kind: 'hymn', text: { en: "The people will hear and be afraid, sorrow will take hold of the inhabitants of Palestine.", ar: "سمعت الأمم وغضبت، والمخاض أخذ سكان فلسطين." } },
      { kind: 'hymn', text: { en: "Then the dukes of Edom will be amazed, the mighty men of Moab trembling will take hold of them.", ar: "حينئذ أسرع وُلاة أدوم، ورؤساء المؤابيين أخذتهم الرعدة." } },
      { kind: 'hymn', text: { en: "All the inhabitants of Canaan will melt away, fear and dread will fall on them.", ar: "ذاب كل سكان كنعان، وأتت عليهم الرعدة والخوف." } },
      { kind: 'hymn', text: { en: "By the greatness of Your arm they will be as still as stone, till Your people pass over O Lord, till Your people pass over whom You have purchased.", ar: "بكثرة ساعدك فليصيروا كالحجر، حتى يجتاز شعبك يا رب، حتى يجتاز شعبك هذا الذي إقتنيته." } },
      { kind: 'hymn', text: { en: "You will bring them in and plant them in the mountain of Your inheritance, in the place O Lord, which You have made for You to dwell in.", ar: "أدخلهم وأغرسهم على جبل ميراثك، وفي مسكنك المُعَد، هذا الذي صنعته يا رب." } },
      { kind: 'hymn', text: { en: "In Your sanctuary O Lord which Your hands have established, the Lord shall reign forever and ever.", ar: "موضعك المقدس يا رب الذي أعددته يداك، يا رب تمَلُك منذ الأزل والآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "For the horses of pharaoh went with his chariots and his horsemen into the sea.", ar: "لأنه قد دخل إلى البحر خيل فرعون ومركباته وفرسانه." } },
      { kind: 'hymn', text: { en: "And the Lord brought back the waters of the sea upon them, but the children of Israel went on dry land in the midst of the sea.", ar: "والرب غمرهم بماء البحر، أما بنو إسرائيل فكانوا يمشون على اليابسة في وسط البحر." } },
      { kind: 'hymn', text: { en: "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand, and all the women went out after her with timbrels and with praises.", ar: "فأخذت مريم النبية، أخت هرون، الدُف بيديها، وخرج في إثرها جميع النسوة بالدُفوف والتسابيح." } },
      { kind: 'hymn', text: { en: "And Miriam answered them saying, \"Sing to the Lord, for He has triumphed gloriously.\"", ar: "وبدأت مريم في مقدمتهنَّ تقول، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider, He has thrown into the sea. \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "الفرس ورُاكب الفرس، طرحهما في البحر. \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'heading', text: { en: "The First Hoos Lobsh", ar: "لبش الهوس الأول" } },
      { kind: 'hymn', text: { en: "With the split, the waters of the sea split, and the very deep, became a walkway.", ar: "قطعاً إنقطع، ماء البحر، والعمق العميق، صار مَسلكاً." } },
      { kind: 'hymn', text: { en: "A hidden earth, was shone upon by the sun, and an untrodden road, was walked upon.", ar: "أرض غير ظاهرة، أشرقت الشمس عليها، وطريق غير مسلوكة، مشوا عليها." } },
      { kind: 'hymn', text: { en: "The flowing water, stood still, by a miraculous, act of wonder.", ar: "ماء مُنحل، وقف، بفِعل عجيب، مُعِجز." } },
      { kind: 'hymn', text: { en: "Pharaoh and his chariots, were drowned, and the children of Israel, crossed the sea.", ar: "غرق فرعون، ومركباته، وعبر بنو إسرائيل، البحر." } },
      { kind: 'hymn', text: { en: "And in front of them was, Moses the prophet praising, until he brought them, to the wilderness of Sinai.", ar: "وكان موسى النبي، يسبح قدامهم، حتى أدخلهم، برية سيناء." } },
      { kind: 'hymn', text: { en: "And they were praising God, with this new psalmody, saying \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "وكانوا يسبحون الله، بهذه التسبحة الجديدة قائلين، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "Through the prayers, of Moses the archprophet, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، موسى رئيس الأنبياء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع أبيك الصالح، والروح القدس، لأنك (قُمتأتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Second Hoos", ar: "الهوس الثاني" } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord for He is good, Alleluia His mercy endures forever.", ar: "أُشكروا الرب لأنه صالح وخيِّر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of gods, Alleluia His mercy endures forever.", ar: "أُشكروا إله الآلهة، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords, Alleluia His mercy endures forever.", ar: "أُشكروا رب الأرباب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who alone does great wonders, Alleluia His mercy endures forever.", ar: "الصانع العجائب العظام وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who by wisdom made the heavens, Alleluia His mercy endures forever.", ar: "الذي خلق السموات بفهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who stretched out the earth above the waters, Alleluia His mercy endures forever.", ar: "الذي ثبَّت الأرض على المياه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who made great lights, Alleluia His mercy endures forever.", ar: "الذي خلق نيرين عظيمين وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The sun to rule by day, Alleluia His mercy endures forever.", ar: "الشمس لحكم النهار، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The moon and stars to rule by night, Alleluia His mercy endures forever.", ar: "القمر والنجوم لحكم الليل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote Egypt in their firstborn, Alleluia His mercy endures forever.", ar: "الذي ضرب المصريين مع أبكارهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And brought out Israel from among them, Alleluia His mercy endures forever.", ar: "وأخرج إسرائيل من وسطهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "With a strong hand and with a stretched out arm, Alleluia His mercy endures forever.", ar: "بيد عزيزة وذراع عالية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who divided the Red Sea into parts, Alleluia His mercy endures forever.", ar: "الذي شق البحر الأحمر إلى أقسام، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And made Israel to pass through the midst of it, Alleluia His mercy endures forever.", ar: "وأجاز إسرائيل في وسطه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "But overthrew pharaoh and his hosts in the Red Sea, Alleluia His mercy endures forever.", ar: "وطرح فرعون وكل قوته في البحر الأحمر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who led His people through the wilderness, Alleluia His mercy endures forever.", ar: "الذي أخرج شعبه إلى البرية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who retrieved water from a rock, Alleluia His mercy endures forever.", ar: "الذي أخرج ماء من صخرة صماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote great kings, Alleluia His mercy endures forever.", ar: "الذي ضرب ملوكاً عُظماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And slew famous kings, Alleluia His mercy endures forever.", ar: "وقتل ملوكاً عجيبين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Sihon the king of the Amorites, Alleluia His mercy endures forever.", ar: "سيحون ملك الأموريين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And Og the king of Bashan, Alleluia His mercy endures forever.", ar: "وعوج ملك باشان، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And gave their lands for a heritage, Alleluia His mercy endures forever.", ar: "أعطى أرضهم ميراثاً، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "A heritage unto Israel His servant, Alleluia His mercy endures forever.", ar: "ميراثاً لعبده إسرائيل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who remembered us in our low estate, Alleluia His mercy endures forever.", ar: "في تواضعنا ذكرنا الرب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And has redeemed us from our enemies, Alleluia His mercy endures forever.", ar: "وخلصنا من أيدي أعدائنا، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who gives food to all flesh, Alleluia His mercy endures forever.", ar: "الذي يعطي طعاماً لكل جسد حي، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of heaven, Alleluia His mercy endures forever.", ar: "إحمدوا إله السماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords for He is good, Alleluia His mercy endures forever.", ar: "إحمدوا رب الأرباب لأنه طيب وصالح، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'heading', text: { en: "The Second Hoos Lobsh", ar: "لبش الهوس الثاني" } },
      { kind: 'hymn', text: { en: "Let us give thanks, to Christ our God, with David the prophet, and psalmist.", ar: "فلنشكر، المسيح إلهنا، مع المرتل، داود النبي." } },
      { kind: 'hymn', text: { en: "For He has made the heavens, and all its hosts, and established the earth, on the waters.", ar: "لأنه خلق السموات، وجنودها، وأسَّس الأرض، على المياه." } },
      { kind: 'hymn', text: { en: "These two great stars, the sun and the moon, He has made to enlighten, the firmament.", ar: "هذان الكوكبان العظيمان، الشمس والقمر، جعلهما ينيران، في الفلك." } },
      { kind: 'hymn', text: { en: "He brought forth the winds, out of His treasure box, He breathed unto the trees, and they blossomed.", ar: "أخرج الرياح، من خباياها، نفخ في الأشجار، حتى أزهرت." } },
      { kind: 'hymn', text: { en: "He caused the rain to fall, upon the face of the earth, and it sprouted, and gave its fruit.", ar: "أمطرا مطراً، على وجه الأرض، حتى أنبتت، وأعطت ثمرها." } },
      { kind: 'hymn', text: { en: "He brought forth water, out of a rock, and gave it to His people, in the wilderness.", ar: "أخرج ماء، من صخرة صماء، وسقى شعبه، في البرية." } },
      { kind: 'hymn', text: { en: "He made man, in His image, and His likeness, that he may praise Him.", ar: "صنع الإنسان، كشبهه، وصورته، لكي يباركه." } },
      { kind: 'hymn', text: { en: "Let us praise Him, and exalt His name, and give thanks to Him, His mercy endures forever.", ar: "فلنسبحه، ونرفع إسمه، ونشكره لأن رحمته، كائنة إلى الأبد." } },
      { kind: 'hymn', text: { en: "Through the prayers, of David the psalmist, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، المرتل داود، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله، القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of all the heavenly hosts, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، كل صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Blessed are You indeed, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "مبارك أنت بالحقيقة، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Third Hoos", ar: "الهوس الثالث" } },
      { kind: 'hymn', text: { en: "Blessed are You O Lord God of our fathers, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الرب إله أبائنا، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed is Your holy name and Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك إسم مجدك القدوس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the holy temple of Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في هيكل مجدك المقدس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You who beholds the depths and sits upon the Cherubim, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الناظر إلى الأعماق الجالس على الشاروبيم، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You on the throne of Your kingdom, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت على عرش مُلكك، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the firmament of heaven, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في فلك السماء، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you works of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع أعمال الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السموات، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you angels of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا جميع ملائكة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you waters above the heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع المياه التي فوق السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you powers of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع قوات الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O sun and moon, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها الشمس والقمر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you stars of heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا سائر نجوم السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you rain and dew, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأمطار مع الأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you clouds and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السُحب والرياح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you spirits, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع الأرواح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O fire and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها النار والحرارة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O cold and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والحر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you dew and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأهوية والأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you nights and days, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الليالي والأيام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O light and darkness, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها النور والظلمة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O frost and cold, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والصقيع، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O snow and ice, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها الجليد والثلج، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you lightnings and clouds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البروق والسحب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all the earth, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأرض كلها، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you mountains and all hills, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الجبال وجميع الآكام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you things that spring up on the earth, praise Him and exalt Him above all forever.", ar: "بارك الرب يا جميع ما يَنبت على وجه الأرض، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you fountains, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الينابيع، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you seas and rivers, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البحار والأنهار، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you whales and all that moves in the waters, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الحيتان وجميع ما يتحرك في الماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you birds of the sky, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع طيور السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you wild beasts and cattle, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الوحوش وكل البهائم، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you sons of men, worship the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا بني البشر، وأُسجدوا للرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Israel, praise Him and exalt Him above all forever.", ar: "بارك الرب يا إسرائيل، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you priests of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا كهنة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you servants of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عبيد الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you spirits and souls of the just, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا أرواح وأنفس الصديقين، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you holy and humble of heart, praise Him and exalt Him above all forever.", ar: "باركوا الرب أيها القديسون والمتواضعو القلوب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all\nforever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "The Third Hoos — Esmo Epchois", ar: "الهوس الثالث — إسمو إبشويس" } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "Psali for the Three Saintly Children", ar: "إبصالية للثلاثة فتية القديسين" } },
      { kind: 'hymn', text: { en: "O sing unto Him who was crucified, buried and resurrected, who trampled and abolished death, praise Him and exalt Him above all.\nTake off the old man, and put on the new and superior one, come closer to greatness of mercy, praise Him and exalt Him above all.", ar: "رتلوا للذي صُلب عنا، وقُبر وقام، وأبطل الموت وأهانه، سبحوه وزيدوه علواً.\nإخلعوا الإنسان العتيق، وألبسوا الجديد الفاخر، وإقتربوا إلى عِظَم الرحمة، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "All you Christian people, the priests and the deacons, glorify the Lord for He is worthy, praise Him and exalt Him above all.\nCome to us O three children, whom Christ our God has lifted, and from the Devil has delivered, praise Him and exalt Him above all.", ar: "يا جنس المسيحيين، القسوس والشمامسة، أعطوا مجداً للرب لأنه مستوجب، سبحوه وزيدوه علواً.\nهَلُمَّ إلينا أيها الثلاثة فتية، الذين رفعهم المسيح إلهنا، وأنقذهم من إبليس، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "For the sake of your God the Messiah, the Giver of all good things, come unto us O Hananiah, praise Him and exalt Him above all.\nO Azariah the zealot, morning and noon and the evening, glorify the power of the Trinity, praise Him and exalt Him above all.", ar: "من أجل إلهك ماسيا، المانح الإحسان، هَلُمَّ إلينا يا حنانيا، سبحوه وزيدوه علواً.\nيا عزاريا الغيور، عشية وبكرة والظهيرة، أعط مجداً لقوة الثالوث، سبّحه وزده علواً." } },
      { kind: 'hymn', text: { en: "Behold Emmanuel [our Lord], is now in our midst O Mishael, proclaim with the voice of joy, praise Him and exalt Him above all.\nGather now and persevere, and proclaim with the priests, bless the Lord all His works, praise Him and exalt Him above all.", ar: "فها هوذا عمانوئيل، في وسطنا يا ميصائيل، تكلم بصوت التهليل، سبّحه وزده علواً.\nإجتمعوا وثابروا جميعاً، تكلموا مع القسوس، وسبحي الرب يا جميع أعماله، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "The heavens declare the glory, of God until this day, O you angels whom He has made, praise Him and exalt Him above all.\nNow all you powers of the Lord, bless His honored name, O sun and moon and all the stars, praise Him and exalt Him above all.", ar: "ها السموات تنطق بمجد الله، إلى هذا اليوم، يا أيها الملائكة الذين أنشأهم، سبحوه وزيدوه علواً.\nوالآن يا قوات الرب، باركوا إسمه الكريم، أيتها الشمس والقمر والنجوم، سبحيه وزيديه علواً." } },
      { kind: 'hymn', text: { en: "And also you rain and dew, sing praises unto our Savior, for He is the God of our fathers, praise Him and exalt Him above all.\nGlorify the Lord O clouds and winds, together with the souls and the spirits, O you cold and fire and heat, praise Him and exalt Him above all.", ar: "وأيضاً أيتها الأمطار والأنداء، إمدحي مخلصنا، لأنه هو إله آبائنا، سبحيه وزيديه علواً.\nأعطي مجداً أيتها السحب معاً، والأهوية والنفوس والأرواح، والبرد والنار والحرارة، سبحيه وزيده علوا." } },
      { kind: 'hymn', text: { en: "You also nights and days, light and darkness and lightning, glorify the Lover of Mankind, praise Him and exalt Him above all.\nYou trees and all that springs on the earth, and all that moves in the sea, mountains and the forests, praise Him and exalt Him above all.", ar: "أيتها الليالي والأيام أيضاً، والنور والظلمة والبروق، قائلة المجد لك يا محب البشر، سبحوه وزيدوه علواً.\nأيتها الأشجار وجميع ما ينبُت، في الأرض وكل ما يتحرك، في المياه والجبال والغياض، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Praise without ceasing, the Lord the King of the kings, O you rivers and seas, praise Him and exalt Him above all.\nAnd we also seeing them, let us say with all these things, bless the Lord all you birds, praise Him and exalt Him above all.", ar: "وأيضاً سبحي بغير فتور، الرب ملك الملوك، أيتها البحار والأنهار، سبحيه وزيديه علواً.\nهكذا نحن إذ ننظر إليهم، فلنقل مع هذه الموجودات جميعها، باركي الرب يا جميع الطيور، سبحيه وزيده علواً." } },
      { kind: 'hymn', text: { en: "O snow and ice, cattle and wild beasts, bless the Lord of lords, praise Him and exalt Him above all.\nBless the Lord as befits Him, and not like the heretics, all you sons of men, praise Him and exalt Him above all.", ar: "أيها الجليد والثلج، والبهائم والوحوش، باركي رب الأرباب، سبحيه وزيديه علواً.\nسبحوا الرب كما يليق به، وليس كالمخالفين، يا أبناء البشر، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "O Israel offer before Him, honor and glory in a joyful voice, all you priests of Emmanuel, praise Him and exalt Him above all.\nYou servants of the true God, the souls of the righteous, and the humble and the charitable, praise Him and exalt Him above all.", ar: "مجداً وإكراماً قدم أمامه، يا إسرائيل بصوت التهليل، يا كهنة عمانوئيل، سبحوه وزيدوه علواً.\nيا خدام الله الحقيقي، وأنفس الأبرار، المتواضعين المحبين، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "God my God is the One, who saved you from danger, O Sedrach Misach and Abednago, praise Him and exalt Him above all.\nHurry with great haste, O you righteous of the Lord, and all the creatures He has made, praise Him and exalt Him above all.", ar: "الله إلهي أنا، هو مخلصكم من الخطر، يا سدراك وميساك وأبدناغو، سبحوه وزيدوه علوا.\nأسرعوا بحرص عظيم، يا أتقياء الرب، وكل الطبائع التي صنعها، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Coolness and repose without ceasing, grant unto all of us, that we may joyfully proclaim, praise Him and exalt Him above all.\nAnd also Your poor servant Sarkis, make him without condemnation, that he may join all those and say, praise Him and exalt Him above all.", ar: "برودة ونياحاً أعطنا، كلنا بغير إنقطاع، لنقول بتمتُع، سبحوه وزيدوه علواً.\nكذلك عبدك المسكين سركيس، إجعله بغير دينونة، ليقول مع هؤلاء كشريك، سبحوه وزيدوه علواً." } },
      { kind: 'heading', text: { en: "Ten-oueh Ensok", ar: "تين أويه إنسوك" } },
      { kind: 'hymn', text: { en: "We follow You with all our hearts, and fear You, and we seek Your face, O God do not forsake us.", ar: "نتبعك بكل قلوبنا، ونخافك، ونطلب وجهك، يا الله لا تخزنا." } },
      { kind: 'hymn', text: { en: "But rather deal with us, according to Your meekness, and according to Your great mercy, O Lord help us.", ar: "بل إصنع معنا، بحسب دعتك، وكثرة رحمتك، يا رب أعنَّا." } },
      { kind: 'hymn', text: { en: "May our prayers ascend to You, O our Master, like burnt offerings of lambs, and fat calves.", ar: "فلتصعد صلاتنا، أمامك يا سيدنا، مثل محرقات كباش، وعجول سِمان." } },
      { kind: 'hymn', text: { en: "Do not forget the covenant, which You have made with our fathers, Abraham Isaac and Jacob, Israel Your saint.", ar: "لا تنس العهد الذي، قطعته مع آبائنا، إبراهيم وإسحق ويعقوب، إسرائيل قديسك." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you nations, the tribes and all kinds of tongues, praise Him and glorify Him, above all forever.", ar: "باركوا الرب يا جميع الشعوب، والقبائل ولغات الألسن، سبحوه ومجدوه، وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Pray to the Lord on our behalf, O three saintly children, Sedrach Misach and Abednego, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة فتية القديسين، سدراك وميساك وأبدناغو، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints", ar: "مجمع القديسين" } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the Lady of us all the Mother of God, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، يا سيدتنا كلنا السيدة والدة الإله، مريم أُم مخلصنا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Michael and Gabriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، ميخائيل وغبريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Raphael and Souriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، رافائيل وسوريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Sedakiel Sarathiel and Ananiel, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا رؤساء الملائكة الأطهار، سداكيال وسراتيال وأنانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O thrones dominions and powers, the Cherubim and the Seraphim, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، أيتها الكراسي والأرباب والقوات، والشيروبيم والسرافيم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O four incorporeal beasts, the ministering flames of fire, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها الأربعة الحيوانات غير المتجسدين، الخدام الملتهبين ناراً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O priests of the truth, the twenty four presbyters, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا كهنة الحق، الأربعة والعشرين قسيساً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O angelic hosts, and all the heavenly multitudes, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها العساكر الملائكية، والطغمات السمائية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lords the fathers the patriarchs, Abraham Isaac and Jacob, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء البطاركة، إبراهيم وإسحق ويعقوب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O perfect man, the righteous and just Enoch, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الرجل الكامل، البار أخنوخ الصديق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Elijah the tishbite, and Elisha his disciple, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيليا التسبيتي، وإليشع تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Moses the archprophet, and Isaiah and Jeremiah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا موسى رئيس الأنبياء، وأشعياء وأرميا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O David the psalmist, Ezekiel and Daniel, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا داود المرتل، وحزقيال ودانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Joachim Anna and Joseph the elder, and the righteous Job Joseph and Nicodemus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا يواقيم وحنِّة ويوسف الشيخ، والصديق أيوب ويوسف ونيقوديموس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Melchizedek and Aaron, and Zacharias and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ملكي صادق وهرون، وزكريا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the prophets, and all the righteous and the just, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الأنبياء، والأبرار والصديقين، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O forerunner and baptizer, John the Baptist, that He may forgive us our sins.", ar: "إشفع فينا (أمام الرب)، أيها السابق الصابغ، يوحنا المعمدان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the hundred and forty four thousand, and the celibate evangelist, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها المئة والأربعة والأربعين ألفاً، والبتول الإنجيلي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters and fathers the Apostles, and the rest of the Disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء الرسل، وبقية التلاميذ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O blessed archdeacon, Stephen the first martyr, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا رئيس الشمامسة المبارك، إستفانوس الشهيد الأول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the apostle, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الناظر الإله الإنجيلي، أبا مرقس الرسول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyr, my lord prince George, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الشهيد المجاهد، سيدي الملك جيؤرجيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Theodore and Theodore, Leontius and Panicharus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ثيؤدوروس وثيؤدوروس، ولاونديوس، وبانيكاروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Philopater Mercurius, and Abba Mina and Abba Victor, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا فيلوباتير مرقوريوس، وأبا مينا وأبا بقطر، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Claudius and Theodore, Abba Eschyron and Abba Isaac, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي إقلاديوس وثيئودوروس، وأبا سخيرون وأبا إسحق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basilidis and Evsebius, Macarius and Philotheos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا واسيليدس وأرسابيوس، ومكاريوس وفيلوثيؤوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pisura and Abba Epshoy, Abba Isi and his sister Thecla, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بسورة وأبا بشاي، وأبا إيسي وتكلا أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Justus Apali and Theoklia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يسطس وآبالي وثيؤكليا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Jacob the Persian, Saint Sergius and Saint Bacchus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا يعقوب الفارسي، والقديس سرجيوس وواخس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Cosmas his brothers and their mother, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، قزمان وإخوته وأمهم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Kir and his brother John, and Barbara and Juliana and Demiana, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا قير ويوحنا أخوه، وبربارة ويوليانة ودميانة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, master Apatir and his sister Iraee, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، السيد أبادير وإيرائي أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Julius and those who were with him, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يوليوس ومَن معه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Mari Pahnam and his sister Sarah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، مار بهنام وسارة أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Sarapamon the bishop, Psate and Gallinikos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صرابامون الأسقف، وإبصادي وغلينيكوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, the forty saints of Sebaste, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، الأربعون قديساً بسبسطية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Piro and Athom, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بيروه وأتوم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Abba Bishoy and his friend Peter, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، أيها الشهيدان المجاهدان، أبا بيشوي وصديقه بطرس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Eklog the priest, and Abba Epgol and Abba Kav, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا إكلوج القس، وأبا بيجول وأبا كاڤ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba John of Heraclia, master Piphamon and Pistavros, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا يوحنا الهرقلي، والسيد بفامون وبسطوروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Isidore and Panteleon, Sophia and Euphemia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيسيذوروس وبندلاون، وصوفيا وإفومية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Apanoub and Ptolomeos, Apa Ekragon and Sousennius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي أبانوب وإبطلماوس، وإبا إكراجون وسوسونيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O great high priest, Abba Peter seal of the martyrs, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا رئيس الكهنة العظيم، أنبا بطرس خاتم الشهداء، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O new martyrs, Pistavros and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان الجديدان، بسطوروس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Michael the hegumen, and Michael the monk, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، يا ميخائيل القمص، وميخائيل الراهب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the martyrs, who suffered for the sake of Christ, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الشهداء، الذين تألموا من أجل المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Antony and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا أنطونيوس وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O three saints Macarii, and all their children the cross-bearers, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة مقارات القديسون، وأولادهم لباس الصليب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers the hegumens, Abba John and Abba Daniel, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين القمصين، أنبا يوحنا وأنبا دانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Bishoy and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا بيشوي وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our saintly Roman fathers, Maximus and Dometius, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أبوينا القديسين الروميين، مكسيموس ودوماديوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O forty nine martyrs, the elders of Shiheet, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها التسعة والأربعون شهيداً، شيوخ شيهات، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O strong saint Abba Moses, and John Kame, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، أيها القوي القديس أنبا موسى، ويحنس كاما، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pachomius of the Koinonia, and Theodore his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا باخوم أبا الشركة، وثيودورس تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Shenouda the archimandrite, and Abba Wisa his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا شنودة رئيس المتوحدين، وأنبا ويصا تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Nopher and Abba Karus, and our father Paphnutius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا نفر وأنبا كاروس، وأبانا بفنوتيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Samuel the confessor, and Justus and Apollo his disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صموئيل المعترف، ويسطس وأبوللو تلميذيه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Apollo and Abba Apip, and our father Abba Pigimi, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا أبوللو وأنبا أبيب، وأبانا أنبا بيچيمي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Evkin and Abba Ehron, Abba Hor and Abba Phis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا إڤكين وأنبا إهرون، وأبا هور وأبا فيس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Parsouma and Ephraim, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا برسوما وإفريم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Epiphanius and Ammounios, and Arshillidis and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إبيفانيوس وأمونيوس، وأرشليدس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the ascetic fathers, Abba Abraam and George, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين الناسكين، أنبا أبرآم وجيؤرجي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Athanasius the apostolic, Severus and Dioscorus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أثاناسيوس الرسولي، وساويرس وديسقورس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basil and Gregory, and our father Abba Cyril, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا باسيليوس وإغريغوريوس، وأبانا أنبا كيرلس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the three hundred and eighteen gathered, at Nicea for the faith, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 318 الذين إجتمعوا، في نيقية من أجل الإيمان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O the one hundred and fifty at Constantinople, and the two hundred at Ephesus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 150 بمدينة القسطنطينية، والمائتين بأفسس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Hadid and Abba John, our great father Parsouma and Abba Roweis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا حديد وأنبا يوحنا، وأبانا العظيم أنبا برسوما وأنبا رويس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Abraam the hegumen, and our father Abba Mark, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا أبرآم القمص، وأبانا أنبا مرقس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the cross-bearers, perfected in the wilderness, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا مصاف لباس الصليب، الذين كملوا في البراري، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lord king Constantine, and his mother queen Helen, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الملك قسطنطين، وهيلانة الملكة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O wise virgin ladies, the brides of Christ, that He may forgive us our sins.", ar: "أُطلبنَّ من الرب عنا، أيتها الفتيات العذارى الحكيمات، عرائس المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the saints of this day, everyone according to his name, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا قديسي هذا اليوم، كل واحد بإسمه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Likewise we exalt you, with David the psalmist, \"You are a priest forever, according to the order of Melchizedek.\"", ar: "كذلك نعظمك، مع المرتل داود قائلين، \"أنت هو الكاهن إلى الأبد، على طقس ملكي صادق.\"" } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our holy father the patriarch, Pope Abba Shenouda the high priest, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا أبانا القديس البطريرك، أنبا شنودة رئيس الكهنة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "If a Bishop is present:\nPray to the Lord on our behalf, O our holy and righteous father, Abba (...) the Bishop (Metropolitan), that He may forgive us our sins.", ar: "في حضور الآب الأسقف:\nأطلب من الرب عنا، يا أبينا القديس البار، أنبا (...) الأسقف (المطران)، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Doxology for the Virgin Mary", ar: "ذكصولوجية العذراء مريم" } },
      { kind: 'doxology', text: { en: "Your greatness O Mary, the undefiled Virgin, is likened to the height of the palm tree, spoken of by Solomon.", ar: "عظمتِك يا مريم، العذراء غير الدنسة، تشبه عُلو النخلة التي، تكلم عنها سليمان." } },
      { kind: 'doxology', text: { en: "You are the spring of living water, that flows from Lebanon, for out of you sprang unto us, the grace of the divinity.", ar: "أنتِ ينبوع ماء الحياة، الفائض من لبنان، التي نبعت لنا منه، نعمة اللاهوت." } },
      { kind: 'doxology', text: { en: "You gave birth to Emmanuel, out of your virginal womb, and He has made us heirs, to the kingdom of heaven.", ar: "ولدتِ لنا عمانوئيل، من أحشائِك البتول، وصيرنا وارثين، في ملكوت السموات." } },
      { kind: 'doxology', text: { en: "According to the promise, He promised to our father, King David the patriarch, He came and fulfilled to us.", ar: "كالوعد الذي وعد به، أبانا رئيس الآباء، الذي هو الملك داود، أتى وأكمله لنا." } },
      { kind: 'doxology', text: { en: "Hail to you O Virgin, the very and true Queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدت لنا عمانوئيل." } },
      { kind: 'doxology', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Fourth Hoos", ar: "الهوس الرابع" } },
      { kind: 'hymn', text: { en: "(Psalm 148)", ar: "(المزمور 148)" } },
      { kind: 'hymn', text: { en: "Praise the Lord from the heavens Alleluia. Praise Him in the heights.", ar: "سبحوا الرب من السموات هلليلويا. سبحوه في الأعالي." } },
      { kind: 'hymn', text: { en: "Praise Him all His angels Alleluia. Praise Him all His hosts.", ar: "سبحوه يا جميع ملائكته هلليلويا. سبحوه يا جميع جنوده." } },
      { kind: 'hymn', text: { en: "Praise Him sun and moon Alleluia. Praise Him all you stars of light.", ar: "سبحيه أيتها الشمس والقمر هلليلويا. سبحيه يا جميع كواكب النور." } },
      { kind: 'hymn', text: { en: "Praise Him you heavens of heavens Alleluia. And you waters above the heavens.", ar: "سبحيه يا سماء السموات هلليلويا. ويا أيتها المياه التي فوق السموات." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For He commanded and they were created.", ar: "لتسبح جميعها لإسم الرب هلليلويا. لأنه قال فكانت." } },
      { kind: 'hymn', text: { en: "He has ordered and they were created Alleluia. He has established them forever and ever.", ar: "وأمر فخلقت هلليلويا. أقامها إلى الأبد وإلى أبد الأبد." } },
      { kind: 'hymn', text: { en: "He has made a decree which shall not pass away Alleluia. Praise the Lord from the earth.", ar: "وضع لها أمراً فلن تتجاوزه هلليلويا. سبحي الرب من الأرض." } },
      { kind: 'hymn', text: { en: "You great sea creatures and all the depths Alleluia. Fire and hail, snow and clouds, stormy wind fulfilling His word.", ar: "أيتها التنانين وجميع الأعماق هلليلويا. النار والبرد والثلج والجليد والريح العاصفة الصانعة كلمته." } },
      { kind: 'hymn', text: { en: "Mountains and all hills Alleluia. Fruitful trees and all cedars.", ar: "الجبال العالية وجميع الآكام هلليلويا. الأشجار المثمره وكل الأرز." } },
      { kind: 'hymn', text: { en: "Beasts and all cattle Alleluia. Creeping things and flying birds.", ar: "الوحوش وكل البهائم هلليلويا. الهوام وكل الطيور ذات الأجنحة." } },
      { kind: 'hymn', text: { en: "Kings of the earth and all people Alleluia. Princes and all judges of the earth.", ar: "ملوك الأرض وكل الشعوب هلليلويا. الرؤساء وكل حكام الأرض." } },
      { kind: 'hymn', text: { en: "Both young men and maidens Alleluia. Old men and children.", ar: "الشبان والعذارى هلليلويا. الشيوخ والصبيان." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For His name alone is exalted.", ar: "فليسبحوا جميعاً إسم الرب هلليلويا. لأنه قد تعالى إسمه وحده." } },
      { kind: 'hymn', text: { en: "His glory is above the earth and heaven Alleluia. And He has exalted the horn of His people.", ar: "شكره كائن على الأرض وفي السماء هلليلويا. ويرفع قرن شعبه." } },
      { kind: 'hymn', text: { en: "The praise of all His saints Alleluia. The children of Israel, a people near unto Him.", ar: "سُبحاً لجميع قديسيه هلليلويا. بني إسرائيل، الشعب القريب إليه." } },
      { kind: 'hymn', text: { en: "(Psalm 149)", ar: "(المزمور 149)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Sing to the Lord a new song Alleluia. And His praise in the congregation of the saints.", ar: "إنشدوا للرب نشيداً جديداً هلليلويا. لأن تسبحته في بيعة القديسين." } },
      { kind: 'hymn', text: { en: "Let Israel rejoice in his Maker Alleluia. Let the children of Zion be joyful in their King.", ar: "فليفرح إسرئيل بخالقه هلليلويا. وبنوا صهيون فليتهللوا بملكهم." } },
      { kind: 'hymn', text: { en: "Let them praise His name in a chorus Alleluia. Let them sing praises unto Him with timbrel and harp.", ar: "فليسِّبحوا إسمه القدوس بصفِ هلليلويا. بدف ومزمار فليرتلوا له." } },
      { kind: 'hymn', text: { en: "For the Lord takes pleasure in His people Alleluia. He will raise the meek with salvation.", ar: "لأن الرب يُسر بشعبه هلليلويا. يعلي الودعاء بالخلاص." } },
      { kind: 'hymn', text: { en: "Let the saints be joyful in glory Alleluia. Let them sing aloud upon their beds.", ar: "يفتخر القديسون بمجد هلليلويا. ويتهللون على مضاجعهم." } },
      { kind: 'hymn', text: { en: "Let the high praises of God be in their mouth Alleluia. And a two edged sword in their hands.", ar: "تعليات الله في حناجرهم هلليلويا. وسيوف ذات حدين في أيديهم." } },
      { kind: 'hymn', text: { en: "To execute vengeance on the nations Alleluia. And punishments on the people.", ar: "ليصنعوا نقمة في الأمم هلليلويا. وتوبيخات في الشعوب." } },
      { kind: 'hymn', text: { en: "To bind their kings with chains Alleluia. And their nobles with fetters of iron.", ar: "ليوثقوا ملوكهم بقيود هلليلويا. وإشرافهم بأغلال للأيدي من حديد." } },
      { kind: 'hymn', text: { en: "To execute on them the written judgment Alleluia. This honor have all His saints.", ar: "ليصنعوا بهم حُكماً مكتوباً هلليلويا. هذا المجد كائن في جميع قديسيه." } },
      { kind: 'hymn', text: { en: "(Psalm 150)", ar: "(المزمور 150)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise God in all His saints Alleluia.", ar: "سبحوا الله في جميع قديسيه هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him in the firmament of His power Alleluia.", ar: "سبحوه في جلد قوته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him for His mighty acts Alleluia.", ar: "سبحوه على مقدرته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him according to the multitudes of His greatness Alleluia.", ar: "سبحوه ككثرة عظمته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with the sound of the trumpet Alleluia.", ar: "سبحوه بصوت البوق هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with psaltery and harp Alleluia.", ar: "سبحوه بالمزمار والقيثار هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with timbrel and chorus Alleluia.", ar: "سبحوه بدفوف وصفوف هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with strings and organs Alleluia.", ar: "سبحوه بأوتار وأرغن هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with pleasant sounding cymbals Alleluia.", ar: "سبحوه بصنوج حسنة الصوت هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him upon the cymbals of joy Alleluia.", ar: "سبحوه بصنوج التهليل هلليلويا." } },
      { kind: 'hymn', text: { en: "Let every thing that has breath praise the name of the Lord our God Alleluia.", ar: "كل نسمة فلتسبح إسم الرب الهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son and the Holy Spirit Alleluia.", ar: "المجد للآب والإبن والروح القدس هلليلويا." } },
      { kind: 'hymn', text: { en: "Now and forever and unto the age of all ages Amen Alleluia.", ar: "الآن وكل أوان وإلى دهر الدهور آمين هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory to You, O our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لك يا إلهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory be to our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لإلهنا هلليلويا." } },
      { kind: 'heading', text: { en: "The Monday Psali", ar: "إبصالية الإثنين" } },
      { kind: 'hymn', text: { en: "Thousands and thousands, and myriads of myriads, praise and glorify, my Lord Jesus.\nEveryone who says, “My Lord Jesus,” is likened to a sword, casting down the enemy.", ar: "ألوفٌ ألوفٍ، وربواتٌ ربواتٍ، يسبحون ويمجدون، ربي يسوع.\nكل مَنْ يقول، \"يا ربي يسوع،\" كمَنْ بيده سيف، يصرع العدو." } },
      { kind: 'hymn', text: { en: "For truly, You were exalted, in heaven, and on earth.\nAll the righteous people, who have pleased God, meditated upon, the whole law.", ar: "لأنك بالحقيقة، قد تعاليت جداً، في السموات، وعلى الأرض.\nكل الصديقين، الذين أرضوا الله، يدرسون، الناموس كله." } },
      { kind: 'hymn', text: { en: "And God is always, present before them, and His holy name is always in their mouths.\nExceedingly great, are Your compassions, O fair Judge, O my Lord Jesus.", ar: "والله كائن، أمامهم، وإسمه القدوس، في أفواههم كل حين.\nكثيرة جداً، هي رأفاتك، أيها الحاكم العادل، يا ربي يسوع." } },
      { kind: 'hymn', text: { en: "God is Emmanuel, the true Food, the immortal, Tree of life.\nGather all, of my senses, to praise and glorify, my Lord Jesus.", ar: "الله هو عمانوئيل، الطعام الحقيقي، شجرة الحياة، العديمة الموت.\nتجمَّعي فيَّ، يا كل حواسي، لأُسبح وأُمجد، ربي يسوع." } },
      { kind: 'hymn', text: { en: "Jesus is my Lord, Jesus is my God, Jesus is the hope, of Christians.\nIn every small thing, we remember and glorify, Your holy name, O my Lord Jesus.", ar: "يسوع هو ربي، يسوع هو إلهي، يسوع هو رجاء، المسيحيين.\nفي القليل القليل، نذكرك، ونُمجد أسمك، يا ربي يسوع." } },
      { kind: 'hymn', text: { en: "All bad defects, let us cast away, and let us purify our hearts, in the name of my Lord.\nLet the name of the Lord, abide within us, so that He may shine upon, our inner being.", ar: "كل العلل الرديئة، فلنتركها عنا، ولنطهر قلوبنا، بإسم الرب.\nفليكن إسم الرب، فينا، ليضئ علينا، في إنساننا الداخلي." } },
      { kind: 'hymn', text: { en: "Who is likened unto You, O Lord among the gods, You are the true God, the Performer of miracles.\nBlessed are You indeed, with Your good Father, and the Holy Spirit, O my Lord Jesus.", ar: "مَنْ في الآلهة، يُشبهك يا رب، أنت هو الإله الحقيقي، الصانع العجائب.\nمُبارَك أنت بالحقيقة، يا ربي يسوع، مع أبيك الصالح، والرُّوح القُدُس." } },
      { kind: 'hymn', text: { en: "An aroma, that is very expensive, is Your holy name, O my Lord Jesus.\nThe true Lamb, of God the Father, have mercy on us, in Your kingdom.", ar: "عنبر، كثير الثمن، هو إسمك القدوس، يا ربي يسوع.\nأيها الحمَل الحقيقي، الذي لله الآب، إصنع معنا رحمة، في ملكوتك." } },
      { kind: 'hymn', text: { en: "For the mouth of Your Father, has given witness for You, saying “You are My Son, and today I gave birth to You.”\nYou are surrounded, by the Cherubim, and the Seraphim, and they can not see You.", ar: "لأن فم أبيك، يشهد لك، \"أنك أنت هو إبني، وأنا اليوم ولدتك.\"\nيقوم حولك، الشاروبيم، والسِّرافيم، ولا يستطيعون أن ينظروك." } },
      { kind: 'hymn', text: { en: "We look at You every day, upon the altar, and we partake of Your Body, and Your honored Blood.\nAll the blessings, of the law, do not have anything, that resembles You.", ar: "ونحن ننظرك كل يوم، على المذبح، ونتناول من جسدك، ودمك الكريمين.\nبركات، الناموس، ليس فيها شئ، يُشبهك." } },
      { kind: 'hymn', text: { en: "This is the true stone, that is of great price, which the merchant sold, all that he had and bought it.\nLeave now for us, this stone, to shine upon us, in our inner being.", ar: "هذا هو الحجر الحقيقي، الكثير الثمن، الذي باع الرجل التاجر، كل ماله واشتراه.\nأُترك لنا نحن أيضاً، الآن هذا الحجر، ليضئ علينا، في إنساننا الداخلي." } },
      { kind: 'hymn', text: { en: "The adornment of our souls, and the joy of our hearts, is Your holy name, O my Lord Jesus.\nO the Kind One, and the Merciful, plenteous in mercies, O my Lord Jesus.", ar: "زينة نفوسنا، وفرح قلوبنا، هو إسمك القدوس، يا ربي يسوع.\nأيها المتحنن، الرؤوف، الكثير الرحمة، يا ربي يسوع." } },
      { kind: 'hymn', text: { en: "The Cherubim clap, with their wings, and praise and glorify, my Lord Jesus.\nThe sun and moon, shall disappear in time, but You are the same, and Your years will never end.", ar: "الشاروبيم، يُصفقون بأجنحتهم، ويُسبحون ويُمجدون، ربي يسوع.\nتغيب الشمس والقمر، في زمانهما، وأنت هو أنت، وسنوك لن تفنى." } },
      { kind: 'hymn', text: { en: "By the care, of Your goodness, You bound the heavens, and You came down to us.\nAs a true physician, and a healer, You have healed all, our sicknesses.", ar: "بأهتمام، صلاحك، طأطأت السموات، ونزلت إلينا.\nكمثل طبيب حقيقي، ومُشفٍ، داويت جميع، أمراضنا." } },
      { kind: 'hymn', text: { en: "Behold us, O my Lord Jesus, with the kind eye, of Your goodness.\nImplant in us, an upright heart, that we may bless You, O my Lord Jesus.", ar: "أنظر إلينا، يا ربي يسوع، بعين التحنن، التي لصلاحك.\nوأغرس فينا، قلباً مستقيماً، لكي نباركك، يا ربي يسوع." } },
      { kind: 'hymn', text: { en: "I entreat You, O my Lord Jesus, to have mercy upon us, in Your kingdom.", ar: "أبتهل إليك، يا ربي يسوع، أن ترحمنا، في ملكوتك." } },
      { kind: 'heading', text: { en: "Introduction to the Sunday Theotokia — Leebon", ar: "مقدمة ثيؤطوكية الأحد — ليبون" } },
      { kind: 'hymn', text: { en: "And whenever we, gather for prayer, let us bless the name, of my Lord Jesus.", ar: "وأيضاً إذا ما إجتمعنا، للصلاة، فلنبارك إسم، ربي يسوع." } },
      { kind: 'hymn', text: { en: "We bless You, O my Lord Jesus, deliver us through Your name, for we have hope in You.", ar: "لأننا نباركك، يا ربي يسوع، نجنا بإسمك، لأننا توكلنا عليك." } },
      { kind: 'hymn', text: { en: "That we may praise You, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "لكي نسبحك، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son, and the Holy Spirit, now and forever and unto, the age of all ages Amen.", ar: "المجد للآب والإبن، والروح القدوس، الآن وكل أوان، وإلى دهر الدهور آمين." } },
      { kind: 'heading', text: { en: "The Monday Theotokia — Adam", ar: "ثيؤطوكية الإثنين — آدام" } },
      { kind: 'hymn', text: { en: "The First Part", ar: "القطعة الأولى" } },
      { kind: 'hymn', text: { en: "While Adam was sad, God was pleased, to bring him back, to his authority.", ar: "آدم بينما، هو حزين، سُرَّ الربُّ أن يردُّه، إلى رئاسته." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Second Part", ar: "القطعة الثانية" } },
      { kind: 'hymn', text: { en: "Eve who was tempted, by the serpent, was condemned, by the Lord.", ar: "حواء التي، أغرتها الحية، حُكم عليها، من قِبَل الرب." } },
      { kind: 'hymn', text: { en: "“For in abundance, I will greatly multiply, your sorrows, and your sighs.”", ar: "\"إن بالكثرة، أُكثِر، أحزانِك، وتنهداتِك.\"" } },
      { kind: 'hymn', text: { en: "Yet God felt compassionate, through his love for man, and was pleased, to free her once again.", ar: "تحنَّن الرب، من قِبَل محبته للبشر، وسُرَّ مرة أخرى، بعتقها." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Third Part", ar: "القطعة الثالثة" } },
      { kind: 'hymn', text: { en: "Jesus Christ the Word, who came and took flesh, He dwelt in us, and we saw His glory.", ar: "يسوع المسيح الكلمة، الذي تجسد، وحلَّ فينا، ورأينا مجده." } },
      { kind: 'hymn', text: { en: "Like the glory of the only Son, of His Father, He was pleased, to redeem us.", ar: "مثل مجد، إبن وحيد لأبيه، قد سُرَّ، أن يخلصنا." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Fourth Part", ar: "القطعة الرابعة" } },
      { kind: 'hymn', text: { en: "(Isaiah) has seen, the mystery, of Emmanuel, with prophetic insight.", ar: "كان ينظر، بأعين النبوة، إلى سر، عمانوئيل." } },
      { kind: 'hymn', text: { en: "Therefore Isaiah, the great prophet, cried out proclaiming, and saying.", ar: "أشعياء، النبي العظيم، فلهذا صرخ، قائلاً." } },
      { kind: 'hymn', text: { en: "“For unto us a Child is born, unto us a Son is given, the government shall be, upon His shoulder.", ar: "\"إنه وُلِدَ لنا ولدٌ، وأُعطينا أبناً، رئاسته، على كتفه." } },
      { kind: 'hymn', text: { en: "The powerful God, of authority, and the Angel of, the great counsel.”", ar: "الإله القوي، المتسلط، وملاكُ المشورة، العُظمى.\"" } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Fifth Part", ar: "القطعة الخامسة" } },
      { kind: 'hymn', text: { en: "Rejoice and be happy, O human race, for God so revealed, His love to the world.", ar: "إفرحوا وتهللوا، يا جنس البشر، لأنه هكذا، أحب الله العالم." } },
      { kind: 'hymn', text: { en: "That He gave, His beloved Son, for those who believe in Him, so that they may live forever.", ar: "حتى بذل، إبنه الحبيب، عن المؤمنين به، لكي يحيوا إلى الأبد." } },
      { kind: 'hymn', text: { en: "For He was overcome, by His compassion, and sent unto us, His almighty arm.", ar: "لأنه غُلِب، من رأفته، وأرسل لنا، ذراعه العالية." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Sixth Part", ar: "القطعة السادسة" } },
      { kind: 'hymn', text: { en: "He who is, and who was, who has come, who is to come again.", ar: "الكائن، الذي كان، الذي أتى، وأيضاً يأتي." } },
      { kind: 'hymn', text: { en: "Jesus Christ the Word, who was incarnate, without alteration, became a perfect man.", ar: "يسوع المسيح الكلمة، الذي تجسد، بغير تغيير، وصار إنساناً كاملاً." } },
      { kind: 'hymn', text: { en: "Without alteration of His being, or mingling or separation, of any kind, after the unity.", ar: "لم يفض ولم يختلط، ولم يفترق، بشئ من الأنواع، من بعد الإتحاد." } },
      { kind: 'hymn', text: { en: "But He is of one nature, one hypostasis, and one person, for God the Word.", ar: "بل بطبيعة واحدة، وأُقنوم واحد، وشخص واحد، لله الكلمة." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Seventh Part", ar: "القطعة السابعة" } },
      { kind: 'hymn', text: { en: "Hail to Bethlehem, the city of the prophets, in which was born Christ, the second Adam.", ar: "السلام لبيت لحم، مدينة الأنبياء، التي وُلِدَ فيها المسيح، آدم الثاني." } },
      { kind: 'hymn', text: { en: "In order to bring Adam, the first man, who was made of dust, back to Paradise.", ar: "لكي يرد آدم، الإنسان الأول، الترابي، إلى الفردوس." } },
      { kind: 'hymn', text: { en: "And to absolve, the decree of death saying, “Adam you are from dust, and to dust you shall return.”", ar: "ويحل قضية الموت، \"إنك يا آدم، أنت تراب وإلى، التراب تعود.\"" } },
      { kind: 'hymn', text: { en: "For in the place, where sin has abounded, the grace of Christ, has abounded more.", ar: "لأن الموضع، الذي كثرت فيها الخطية، تفاضلت فيه، نعمة المسيح." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Eighth Part", ar: "القطعة الثامنة" } },
      { kind: 'hymn', text: { en: "All the souls, rejoice and sing, with the angels, and praise Christ the King.", ar: "كل الأنفس، تفرح وترتل، مع الملائكة، مُسبحين الملك المسيح." } },
      { kind: 'hymn', text: { en: "Proclaiming and saying, “Glory to God in the highest, peace on earth, and goodwill toward men.”", ar: "وصارخين قائلين، \"المجد لله في الأعالي، وعلى الأرض السلام، وفي الناس المسرة.\"" } },
      { kind: 'hymn', text: { en: "For He has destroyed, the middle wall, and killed the enmity, with perfection.", ar: "لأنه حلَّ، الحاجز، وقتل العداوة، بالكمال." } },
      { kind: 'hymn', text: { en: "He has torn, the verdict of slavery, pronounced on Adam and Eve, and He freed them.", ar: "ومزَّق كتاب، يد العبودية، التي لآدم وحواء، وحررهما." } },
      { kind: 'hymn', text: { en: "He who was born for us, in the city of David, is our Savior Jesus, as the angel said.", ar: "الذي وُلِدَ لنا، في مدينة داود، مُخلِّصنا يسوع، كقول الملاك." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "The Ninth Part", ar: "القطعة التاسعة" } },
      { kind: 'hymn', text: { en: "God is light, He abides in light, and the angels of light, sing unto Him.", ar: "الله هو نور، وساكن في النور، تسبحه، ملائكة النور." } },
      { kind: 'hymn', text: { en: "The Light has shone, from Mary, and Elizabeth, gave birth to the forerunner.", ar: "النور أشرق، من مريم، وأليصابات، ولدت السابق." } },
      { kind: 'hymn', text: { en: "The Holy Spirit, woke up in David, and said “Arise and sing, for the Light has shone.”", ar: "الرُّوح القُدُس، أيقظ داود قائلاً، \"قم رتِّل لأن، النور قد أشرق.\"" } },
      { kind: 'hymn', text: { en: "So David the psalmist, and the holy one, rose up and took his, spiritual harp.", ar: "فقام داود، المُرتِّل القديس، وأخذ قيثارته، الروحية." } },
      { kind: 'hymn', text: { en: "He went to the church, the house of the angels, he praised and chanted to, the Holy Trinity.", ar: "ومضى إلى البيعة، بيت الملائكة، فسبَّح ورتَّل، للثالوث القدوس." } },
      { kind: 'hymn', text: { en: "Saying “In Your light, O Lord we will see light, let Your mercy come, to those who know You.”", ar: "قائلاً \"بنورك، يا رب نعاين نوراً، فلتأت رحمتك، للذين يعرفونك.\"" } },
      { kind: 'hymn', text: { en: "O true Light, that shines upon, every man, that comes into the world.", ar: "أيها النور الحقيقي، الذي يضئ، لكل إنسان، آتياً إلى العالم." } },
      { kind: 'hymn', text: { en: "You have come into the world, through Your love for man, and all the creation, rejoiced at Your coming.", ar: "أتيت إلى العالم، بمحبتك للبشر، وكل الخليقة، تهللت بمجيئك." } },
      { kind: 'hymn', text: { en: "You have saved Adam, from the seduction, and delivered Eve, from the pangs of death.", ar: "خلَّصت آدم، من الغواية، وعتقت حواء، من طلقات الموت." } },
      { kind: 'hymn', text: { en: "You gave unto us, the Spirit of sonship, we praise and bless You, with Your angels.", ar: "أعطيتنا، روح البنوة، نُسبحك ونُباركك، مع ملائكتك." } },
      { kind: 'hymn', text: { en: "He shone in the flesh, taken from the Virgin, without the seed of man, in order to save us.", ar: "أشرق جسدياً، من العذراء، بغير زرع بشرٍ، حتى خلصنا." } },
      { kind: 'heading', text: { en: "The Monday Theotokia Lobsh", ar: "لبش ثيؤطوكية الإثنين" } },
      { kind: 'hymn', text: { en: "My weak and sinful tongue, is not able, to speak of, your honor O Mary.", ar: "لسانى الضعيف، الخاطئ لا يقدر، أن ينطق، بكرامتِك يا مريم." } },
      { kind: 'hymn', text: { en: "Adam our father, the first creation, by the hands of God, the Creator.", ar: "لأن آدم، أبانا المخلوق، الأول بيدي، الله الخالق." } },
      { kind: 'hymn', text: { en: "Through the advice of Eve, our first mother, Adam ate from, the fruit of the tree.", ar: "بمشورة حواء، أُمنا الأولى، أكل آدم من، ثمرة الشجرة." } },
      { kind: 'hymn', text: { en: "So came to our race, and all the creation, the authority of death, and corruption.", ar: "فجاء على جنسنا، وكل الخليقة، سلطان الموت، والفساد." } },
      { kind: 'hymn', text: { en: "Through Mary, the Theotokos, Adam was restored again, to his authority.", ar: "ومن قِبَل مريم، والدة الإله، أُرجع آدم إلى، رئاسته دفعةً أخرى." } },
      { kind: 'hymn', text: { en: "The two exalted kings, David and Solomon, sing unto her, and honor her.", ar: "ها أن الملكين العاليين، داود وسليمان، يرتلان لها، ويكرمانها." } },
      { kind: 'hymn', text: { en: "David the prophet, spoke of her honor, and called her, “The city of God.”", ar: "داود النبي، تكلم بكرامتها، ودعاها، \"مدينة الله.\"" } },
      { kind: 'hymn', text: { en: "And also Solomon, the Ecclesiastes, this is what he says, in the Song of Songs.", ar: "وأيضاً سليمان، الجامعة، هكذا يقول في، نشيد الأناشيد." } },
      { kind: 'hymn', text: { en: "“My sister and my spouse, the perfect one, the smell of your garments, is an aroma.”", ar: "\"يا أختي وخليلتي، الكاملة، رائحة ثيابك، هي عنبر.\"" } },
      { kind: 'hymn', text: { en: "O all you virgins, love purity, in order to become daughters, of Saint Mary.", ar: "يا جميع العذارى، أحببنَّ الطهارة، لكي تصرنَّ بنات، للقديسة مريم." } },
      { kind: 'hymn', text: { en: "For through her, all women, find favor, before the Lord.", ar: "لأن من قِبَلها، وجدت النساء، دالةً، أمام الرب." } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Introduction to the Difnar — Adam", ar: "مقدمة الدفنار — آدام" } },
      { kind: 'hymn', text: { en: "O come let us worship, the Holy Trinity, the Father and the Son, and the Holy Spirit.", ar: "تعالوا فلنسجد، للثالوث القدوس، الذي هو الآب والإبن، والروح القُدُس." } },
      { kind: 'hymn', text: { en: "Hail to you O Mary, the beautiful dove, who gave birth to, God the Word for us.", ar: "السلام لكِ يا مريم، الحمامة الحسنة، التي ولدت لنا، الله الكلمة." } },
      { kind: 'heading', text: { en: "Conclusion of the Adam Theotokias", ar: "ختام الثيؤطوكيات الآدام" } },
      { kind: 'prayer', text: { en: "Your mercies O my God, are countless, and exceedingly plenteous, are Your compassion.", ar: "مراحمك يا إلهي، غير محصاة، وكثيرة جداً، هي رأفاتك." } },
      { kind: 'prayer', text: { en: "All the rain drops, are counted by You, and the sand of the sea, is before Your eyes.", ar: "قطرات المطر، محصاة عندك جميعها، ورمل البحر، كائن أمام عينيك." } },
      { kind: 'prayer', text: { en: "How much more are, the sins of my soul, manifest before You, O my Lord.", ar: "فكم بالحري، خطايا نفسي، هذه الظاهرة، أمامك يا ربي." } },
      { kind: 'prayer', text: { en: "The sins that I have committed, do not remember my Lord, and do not count, my iniquities.", ar: "الخطايا التي صنعتها، يا ربي لا تذكرها، ولا تحسب، آثامي." } },
      { kind: 'prayer', text: { en: "For You have chosen the publican, and the adulteress You have saved, and the right-hand thief, my Lord You have remembered.", ar: "فإن العشار إخترته، والزانية خلصتها، واللص اليمين، يا سيدي ذكرته." } },
      { kind: 'prayer', text: { en: "And me too, the sinner, teach me O my Master, to offer repentance.", ar: "وأنا أيضاً الخاطئ، يا سيدي، علمني، أن أصنع توبة." } },
      { kind: 'prayer', text: { en: "For You do not desire, the death of a sinner, but rather that he returns, and that his soul may live.", ar: "لأنك لا تشاء، موت الخاطئ، مثل أن يرجع، وتحيا نفسه." } },
      { kind: 'prayer', text: { en: "Restore us O God, to Your salvation, and deal with us, according to Your goodness.", ar: "ردنا يا الله، إلى خلاصك، وعاملنا، كصلاحك." } },
      { kind: 'prayer', text: { en: "For You are good, and merciful, let Your compassion, speedily come to us.", ar: "لأنك أنت صالح، ورحوم، فلتدركنا، رأفاتك سريعاً." } },
      { kind: 'prayer', text: { en: "Have compassion upon us all, O Lord God our Savior, and have mercy upon us, according to Your great mercy.", ar: "ترأف علينا كلنا، أيها الرب الإله، مخلصنا وإرحمنا، كعظيم رحمتك." } },
      { kind: 'prayer', text: { en: "Remember those, O Christ our Master, be among us, and proclaim and say.", ar: "هؤلاء أذكرهم، يا سيدنا المسيح، كن في وسطنا، صارخاً قائلاً:" } },
      { kind: 'prayer', text: { en: "\"My peace I, give to you, the peace of My Father, I leave with you.\"", ar: "\"سلامي أنا، أعطيكم، سلام أبي، أتركه معكم.\"" } },
      { kind: 'prayer', text: { en: "O King of peace, grant us Your peace, render unto us Your peace, and forgive us our sins.", ar: "يا ملك السلام، أعطنا سلامك، قرر لنا سلامك، وإغفر لنا خطايانا." } },
      { kind: 'prayer', text: { en: "Disperse the enemies, of the Church, and fortify her that she, may not be shaken forever.", ar: "فرِّق أعداء الكنيسة، وحصنها، فلا تتزعزع، إلى الأبد." } },
      { kind: 'prayer', text: { en: "Emmanuel our God, is now in our midst, with the glory of His Father, and the Holy Spirit.", ar: "عمانوئيل إلهنا، في وسطنا الآن، بمجد أبيه، والروح القدس." } },
      { kind: 'prayer', text: { en: "May He bless us all, and purify our hearts, and heal the sicknesses, of our souls and bodies.", ar: "ليباركنا كلنا، ويطهر قلوبنا، ويشفي أمراض، نفوسنا وأجسادنا." } },
      { kind: 'prayer', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع إبيك الصالح، والروح القدس، لأنك (قمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Concluding Litany", ar: "طلبة الختام" } },
      { kind: 'litany', text: { en: "Kerie leysoun (Lord have mercy) is said three times before every part", ar: "يقال كيريي ليسون (يا رب إرحم) ثلاث مرات قبل كل ربع" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." } },
      { kind: 'litany', text: { en: "Kerie leysoun (3).", ar: "كيريي ليسون (3)." } },
      { kind: 'litany', text: { en: "O God have mercy on us.", ar: "يا الله إرحمنا." } },
      { kind: 'litany', text: { en: "O God hear us.", ar: "يا الله إسمعنا." } },
      { kind: 'litany', text: { en: "O God look to us.", ar: "يا الله أُنظر إلينا." } },
      { kind: 'litany', text: { en: "O God behold us.", ar: "يا الله إطَّلع علينا." } },
      { kind: 'litany', text: { en: "O God have compassion on us.", ar: "يا الله تراءف علينا." } },
      { kind: 'litany', text: { en: "We are Your people.", ar: "نحن شعبك." } },
      { kind: 'litany', text: { en: "We are Your creation.", ar: "نحن جبلتك." } },
      { kind: 'litany', text: { en: "Deliver us from our enemies.", ar: "نجنا من أعدائنا." } },
      { kind: 'litany', text: { en: "Deliver us from inflation.", ar: "نجنا من الغلاء." } },
      { kind: 'litany', text: { en: "We are Your servants.", ar: "نحن عبيدك." } },
      { kind: 'litany', text: { en: "You are the Son of God.", ar: "أنت إبن الله." } },
      { kind: 'litany', text: { en: "We believe in You.", ar: "آمنا بك." } },
      { kind: 'litany', text: { en: "For You have (risen/come) and saved us.", ar: "لأنك (قُمت/أتيت) وخلَّصتنا." } },
      { kind: 'litany', text: { en: "Visit us with Your salvation.", ar: "تعهدنا بخلاصك." } },
      { kind: 'litany', text: { en: "And forgive us our sins.", ar: "وإغفر لنا خطايانا." } },
      { kind: 'litany', text: { en: "Kerie leysoun.", ar: "كيريي ليسون." } },
      { kind: 'heading', text: { en: "The Morning Doxology", ar: "ذكصولوجية باكر" } },
      { kind: 'doxology', text: { en: "We worship the Father and the Son, and the Holy Spirit, hail to the church, the house of the angels.", ar: "نسجد للآب والإبن، والروح القدس، السلام للكنيسة، بيت الملائكة." } },
      { kind: 'doxology', text: { en: "Hail to the Virgin, who gave birth to our Savior, hail to Gabriel, who announced to her the good news.", ar: "السلام للعذراء، التي ولدت مخلصنا، السلام لغبريال، الذي بشرها." } },
      { kind: 'doxology', text: { en: "Hail to Michael, the archangel, hail to the twenty four, presbyters.", ar: "السلام لميخائيل، رئيس الملائكة، السلام للأربعة والعشرين، قسيساً." } },
      { kind: 'doxology', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the hosts, of the heavens.", ar: "السلام للشاروبيم، السلام للسارافيم، السلام لجميع الطغمات، السمائية." } },
      { kind: 'doxology', text: { en: "Hail to John, the great forerunner, hail to the, twelve Apostles.", ar: "السلام ليوحنا، السابق العظيم، السلام للإثنى عشر، رسولاً." } },
      { kind: 'doxology', text: { en: "Hail to our father Mark, the Evangelist, the destroyer, of the idols.", ar: "السلام لأبينا مرقس، الإنجيلي، مُبَدِد، الأوثان." } },
      { kind: 'doxology', text: { en: "Hail to Stephen, the first martyr, hail to George, the morning star.", ar: "السلام لإستفانوس، الشهيد الأول، السلام لجرجس، كوكب الصبح." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the martyrs, hail to Abba Antony, and the three Macarii.", ar: "السلام لجميع صفوف، الشهداء، السلام لأنبا أنطونيوس، والثلاثة المقارات." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the cross-bearers, hail to all the saints, who have pleased the Lord.", ar: "السلام لجميع صفوف، لُباس الصليب، السلام لجميع القديسين، الذين أرضوا الرب." } },
      { kind: 'doxology', text: { en: "Through their prayers, O Christ our King, have mercy upon us, in Your kingdom.", ar: "أيها المسيح ملكنا، بصلواتهم، إصنع معنا رحمة، في ملكوتك." } },
      { kind: 'doxology', text: { en: "(For Our Lord Jesus Christ)", ar: "(لأجل ربنا يسوع المسيح)" } },
      { kind: 'doxology', text: { en: "O true Light, that gives light, to every man, that comes into the world.", ar: "أيها النور الحقيقي، الذي يضئ، لكل إنسان، آتٍ إلى العالم." } },
      { kind: 'doxology', text: { en: "You came into the world, through Your love for man, and all the creation, rejoiced at Your coming.", ar: "أتيت إلى العالم، بمحبتك للبشر، وكل الخليقة، تهللت بمجيئك." } },
      { kind: 'doxology', text: { en: "You have saved Adam, from seduction, and delivered Eve, from the pangs of death.", ar: "خلصَّت آدم، من الغواية، وعتقت حواء، من طلقات الموت." } },
      { kind: 'doxology', text: { en: "You gave unto us, the Spirit of sonship, we praise and bless You, with Your angels.", ar: "أعطيتنا، روح النبوة، نسبحك ونباركك، مع ملائكتك." } },
      { kind: 'doxology', text: { en: "When the morning hour, comes upon us, O Christ our God, the true Light.", ar: "عندما يدخل، وقت باكر إلينا، أيها المسيح إلهنا، النور الحقيقي." } },
      { kind: 'doxology', text: { en: "Let the thought of light, shine within us, and do not let the darkness, of pain cover us.", ar: "فلتشرق فينا، حواس النور، ولا تغطينا، ظلمة الآلام." } },
      { kind: 'doxology', text: { en: "That we may praise You, with understanding, proclaiming and saying, with David.", ar: "لكي نسبحك، عقلياً، مع داود، صارخين، نحوك قائلين." } },
      { kind: 'doxology', text: { en: "\"My eyes have reached, the morning watch, that I may meditate, upon all Your words.\"", ar: "\"سبق أن بلغت، عيناي وقت السحر، لأتلو، جميع أقوالك.\"" } },
      { kind: 'doxology', text: { en: "Hear our voices, according to Your great mercy, save us O Lord our God, according to Your compassion.", ar: "إسمع صوتنا، كعظيم رحمتك، ونجنا أيها الرب إلهنا، حسب رأفاتك." } },
      { kind: 'doxology', text: { en: "O caring God, the Maker of all good things, who governs well, with His chosen ones.", ar: "يا الله المُهْتم، صانع الخيرات، مُدبر مُختاريه، حسناً." } },
      { kind: 'doxology', text: { en: "The strong Governor for those, who take refuge in Him, who longs for the salvation, and deliverance of everyone.", ar: "المدبر القوي، للملتجئين، المتشوق لخلاص، ونجاة كل أحد." } },
      { kind: 'doxology', text: { en: "Through Your goodness, You provided us the night, grant us to pass, this day without sin.", ar: "بصلاحك هيأت، لنا الليل، أنعم لنا بهذا اليوم، ونحن بغير خطية." } },
      { kind: 'doxology', text: { en: "That we may be worthy, to lift up our hands, before You without anger, or evil thoughts.", ar: "لنستحق أن نرفع، أيدينا إليك، أمامك بغير غضب، ولا فكر ردئ." } },
      { kind: 'doxology', text: { en: "At this dawn, make straight our coming in, and our going out, in the joy of Your protection.", ar: "في هذا السحر، سهل طرقنا، الداخلية والخارجية، بسترك المفرح." } },
      { kind: 'doxology', text: { en: "That we may proclaim, Your righteousness daily, and praise Your power, with David the prophet.", ar: "لننطق بعدلك، كل يوم، ونمجد قوتك، مع داود النبي." } },
      { kind: 'doxology', text: { en: "Saying \"In Your peace, O Christ our Savior, we slept and arose, for we have hoped in You.", ar: "قائلين \"بسلامك، أيها المسيح مخلصنا، رقدنا وقمنا، لأننا توكلنا عليك." } },
      { kind: 'doxology', text: { en: "Behold how beneficent, and how pleasant, it is for brethren, to dwell together in unity.\"", ar: "ها ما هو الحسن، وما هو الحلو، إلا إتفاق إخوة، ساكنين معاً.\"" } },
      { kind: 'doxology', text: { en: "United, in the true, evangelic love, like the Apostles.", ar: "مُتفقين، بمحبة حقيقية، إنجيلية، كمثل الرسل." } },
      { kind: 'doxology', text: { en: "It is like the fragrant oil, on the head of Christ, running down the beard, down to the feet.", ar: "مثل الطيب، على رأس المسيح، النازل على اللحية، إلى أسفل الرجلين." } },
      { kind: 'doxology', text: { en: "That anoints every day, the elders, the children and young men, and the deacons.", ar: "يمسح كل يوم، الشيوخ، والصبيان والفتيات، والخدام." } },
      { kind: 'doxology', text: { en: "Those whom the Holy Spirit, has attuned together, as a stringed instrument, always blessing God.", ar: "هؤلاء الذين، ألَّفهم الروح القدس معاً، مثل قيثارة مُسبحين، الله كل حين." } },
      { kind: 'doxology', text: { en: "By psalms and hymns, and spiritual songs, by day and by night, with an incessant heart.", ar: "بمزامير وتسابيح، وترانيم روحية، النهار والليل، بقلب لا يفتر." } },
      { kind: 'doxology', text: { en: "(For the Virgin)", ar: "(لأجل العذراء)" } },
      { kind: 'doxology', text: { en: "You are the Mother of the Light, the honored Mother of God, you have carried, the Uncircumscript Logos.", ar: "أنتِ يا أم النور، المكرمة والدة الإله، حملتِ الكلمة، غير المحوي." } },
      { kind: 'doxology', text: { en: "After you gave birth to Him, you remained a virgin, with praises and blessings, we magnify you.", ar: "ومن بعد أن ولدتِه، بقيتِ عذراء، نعظمكِ بتسابيح، وبركات." } },
      { kind: 'doxology', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والروح القدس، آتى وخلصنا." } },
      { kind: 'doxology', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً، نطلب أن نفوز، برحمة بشفاعاتك، لدى محب البشر." } },
      { kind: 'doxology', text: { en: "The select incense, of your virginity, ascended to the throne, of the Father.", ar: "البخور المختار، الذي لبتوليتك، صعد إلى، كرسي الآب." } },
      { kind: 'doxology', text: { en: "Better than the incense, of the Cherubim, and the Seraphim, O Virgin Mary.", ar: "أفضل من بخور، الشاروبيم، والسارافيم، يا مريم العذراء." } },
      { kind: 'doxology', text: { en: "Hail to the new heaven, whom the Father has created, and made a place of rest, for His beloved Son.", ar: "السلام للسماء الجديدة، التي صنعها الآب، وجعلها موضع راحة، لإبنه الحبيب." } },
      { kind: 'doxology', text: { en: "Hail to the royal throne, of Him who is, carried by, the Cherubim.", ar: "السلام للكرسي، الملوكي، الذي للمحمول، على الشاروبيم." } },
      { kind: 'doxology', text: { en: "Hail to the advocate, of our souls, you are indeed, the pride of our race.", ar: "السلام لشفيعة، نفوسنا، أنت بالحقيقة، فخر جنسنا." } },
      { kind: 'doxology', text: { en: "Intercede on our behalf, O full of grace, before our Savior, our Lord Jesus Christ.", ar: "إشفعي فينا، يا ممتلئة نعمة، أمام مخلصنا، ربنا يسوع المسيح." } },
      { kind: 'doxology', text: { en: "That He may confirm us, in the upright faith, and grant us the forgiveness, of our sins.", ar: "لكي يثبتنا، في الإيمان المستقيم، وينعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Angels)", ar: "(لأجل الملائكة)" } },
      { kind: 'doxology', text: { en: "Thousands of thousands, and myriads of myriads, of archangels, and holy angels.", ar: "ألوف ألوف، وربوات ربوات، رؤساء ملائكة، وملائكة مُقدسيين." } },
      { kind: 'doxology', text: { en: "They stand before, the throne, of the Pantocrator, proclaiming and saying.", ar: "وقوف أمام، كرسي، ضابط الكل، صارخين قائلين:" } },
      { kind: 'doxology', text: { en: "\"Holy holy, holy in truth, the glory and the honor, befit the Trinity.\"", ar: "\"قدوس قدوس، قدوس بالحقيقة، المجد والكرامة، يليقان بالثالوث.\"" } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the whole choir of the angels, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، جميع صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Apostles)", ar: "(لأجل الرسل)" } },
      { kind: 'doxology', text: { en: "Our fathers the Apostles, preached unto the nations, the Gospel, of Jesus Christ.", ar: "آباؤنا الرسل، بشروا في الأمم، بإنجيل، يسوع المسيح." } },
      { kind: 'doxology', text: { en: "Their voices went forth, into all the earth, and their words have reached, the ends of the world.", ar: "خرجت أصواتهم، إلى الأرض كلها، وبلغ كلامهم، إلى أقطار المسكونة." } },
      { kind: 'doxology', text: { en: "Through the prayers, of my masters the fathers the Apostles, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، سادتي الآباء الرسل، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Martyrs)", ar: "(لأجل الشهداء)" } },
      { kind: 'doxology', text: { en: "Unfading crowns, the Lord has placed, upon the whole choir, of the martyrs.", ar: "أكاليل غير مضمحلة، جعلها الرب، على جميع، صفوف الشهداء." } },
      { kind: 'doxology', text: { en: "He saved and delivered them, because they took refuge in Him, they celebrated with Him, in His kingdom.", ar: "أنقذهم وخلصهم، لأنهم إلتجأوا إليه، وعيدوا معه، في ملكوته." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the martyrs, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، جميع صفوف الشهداء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Saints)", ar: "(لأجل القديسين)" } },
      { kind: 'doxology', text: { en: "Your saints bless You, and they speak, of the glory, of Your kingdom.", ar: "قديسوك، يباركونك، وينطقون بمجد، ملكوتك." } },
      { kind: 'doxology', text: { en: "Your kingdom O my God, is an eternal kingdom, and Your Lordship, is unto all ages.", ar: "ملكوتك يا إلهي، ملكوت أبدي، وربوبيتك، إلى كل الأجيال." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the cross-bearers, the righteous and the just, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، كافة مصاف لابسي الصليب، والأبرار والصديقين، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Patriarchs and the Prophets)", ar: "(لأجل الآباء والأنبياء)" } },
      { kind: 'doxology', text: { en: "Hail to Elijah, the prophet of temperance, and Elisha, his elect disciple.", ar: "السلام لإيليا، النبي المتعفف، وإليشع، تلميذه المختار." } },
      { kind: 'doxology', text: { en: "The great Evangelist, of the land of Egypt, Mark the Apostle, the first prelate.", ar: "المبشر العظيم، في كورة مصر، مرقس الرسول، مدبرها الأول." } },
      { kind: 'doxology', text: { en: "You are the Mother of God, O Virgin Mary, ask Him on our behalf, to have mercy upon our race.", ar: "أنت هي أم الله، يا مريم العذراء، أُطلبي منه عنا، أن يرحم جنسنا." } },
      { kind: 'doxology', text: { en: "The great patriarch, our father Abba Severus, whose holy teachings, enlightened our minds.", ar: "البطريرك العظيم، أبونا أنبا ساويرس، الذي أنارت تعاليمه، المقدسة عقولنا." } },
      { kind: 'doxology', text: { en: "Our father the confessor, Abba Dioscorus, defended the faith, against the heretics.", ar: "أبونا المعترف، أنبا ديسقوروس، حارب عن الإيمان، ضد الهراطقة." } },
      { kind: 'doxology', text: { en: "And all of our fathers, who have pleased the Lord, may their holy blessings, be a guard unto us.", ar: "وكل آبائنا، الذين أرضوا الرب، بركتهم المقدسة، تكون لنا حارساً." } },
      { kind: 'doxology', text: { en: "Through their prayers, O God grant us, the forgiveness of our sins, and give us peace.", ar: "بصلواتهم، إنعم لنا يا الله، بمغفرة خطايانا، وأعطنا سلاماً." } }
    ],
  },
  {
    id: "psalmody-midnight-tuesday",
    title: { en: "Tuesday Midnight Praises", ar: "تسبحة نصف الليل ليوم الثلاثاء" },
    blocks: [
      { kind: 'note', text: { en: "The complete fixed annual Tuesday (Adam) Midnight Psalmody.", ar: "النصوص الثابتة الكاملة للإبصلمودية السنوية لنصف الليل ليوم الثلاثاء (آدام)." } },
      { kind: 'heading', text: { en: "Ten-theno", ar: "تين ثينو" } },
      { kind: 'prayer', text: { en: "Arise O children of the light, let us praise the Lord of hosts.", ar: "قوموا يا بني النور، لنسبح رب القوات." } },
      { kind: 'prayer', text: { en: "That He may grant us the salvation of our souls.", ar: "لكي ينعم لنا بخلاص نفوسنا." } },
      { kind: 'prayer', text: { en: "Whenever we stand before You in the flesh.", ar: "عندما نقف أمامك جسدياً." } },
      { kind: 'prayer', text: { en: "Cast away from our minds the slumber of sleep.", ar: "إنزع عن عقولنا نوم الغفلة." } },
      { kind: 'prayer', text: { en: "Grant us sobriety O Lord, that we may know how to stand before You at times of prayer.", ar: "أعطنا يا رب يقظة، لكي نفهم أن نقف أمامك وقت الصلاة." } },
      { kind: 'prayer', text: { en: "And ascribe unto You the befitting glorification, and win the forgiveness of our many sins. Glory be to You O Lover of Mankind.", ar: "ونرسل لك إلى فوق التمجيد اللائق، ونفوز بغفران خطايانا الكثيرة. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Behold bless the Lord all you servants of the Lord. Glory be to You O Lover of Mankind.", ar: "ها باركوا الرب يا عبيد الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "You who stand in the house of the Lord, in the courts of the house of our God. Glory be to You O Lover of Mankind.", ar: "القائمين في بيت الرب، في ديار بيت إلهنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "By night lift up your hands O you saints and bless the Lord. Glory be to You O Lover of Mankind.", ar: "بالليالي إرفعوا أيديكم إلى فوق أيها القديسون باركوا الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "The Lord bless you from Zion, who created heaven and earth. Glory be to You O Lover of Mankind.", ar: "يباركك الرب من صهيون، الذي خلق السماء والأرض. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my cry come before You O Lord, give me understanding according to Your word. Glory be to You O Lover of Mankind.", ar: "فلتدن وسيلتي قدامك يا رب، كقولك فهمني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my supplication come before You, deliver me according to Your word. Glory be to You O Lover of Mankind.", ar: "ليدخل إبتهالي أمامك، ككلمتك أحيني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My lips shall overflow with praise, when You have taught me Your statutes. Glory be to You O Lover of Mankind.", ar: "تفيض شفتاي السُبح، إذا ما علمتني حقوقك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My tongue shall speak of Your words for all Your commandments are righteous. Glory be to You O Lover of Mankind.", ar: "لساني يجيب بأقوالك لأن جميع وصاياك هي حق. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let Your hand help me for I have chosen Your precepts. Glory be to You O Lover of Mankind.", ar: "لتكن يدك لتخلصني لأني إشتهيت وصاياك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have longed for Your salvation O Lord, and Your Law is my delight. Glory be to You O Lover of Mankind.", ar: "إشتقت إلى خلاصك يا رب، وناموسك هو تلاوتي. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my soul live and it shall praise You, and let Your judgments help me. Glory be to You O Lover of Mankind.", ar: "تحيا نفسي وتسبحك، وأحكامك تعينني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have gone astray like a lost sheep, seek Your servant for I do not forget Your commandments. Glory be to You O Lover of Mankind.", ar: "ضللت مثل الخروف الضال، فأُطلب عبدك لأني لوصاياك لم أنس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Now and forever and unto the age of all ages Amen. Glory be to You O Lover of Mankind.", ar: "الآن وكل أوان وإلى دهر الدهور آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit, now and forever and unto all the ages Amen. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس منذ الآن وإلى أبد الأبدين كلها آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O good One the Lover of Mankind, glory be to Your Mother the Virgin and all Your saints. Glory be to You O Lover of Mankind.", ar: "المجد لك يا محب البشر الصالح، المجد لأُمك العذراء وجميع قديسيك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O only-begotten One, O holy Trinity have mercy upon us. Glory be to You O Lover of Mankind.", ar: "المجد لك أيها الوحيد، أيها الثالوث القدوس إرحمنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let God arise and let all His enemies be scattered and let all that hate His holy name flee from before His face. Glory be to You O Lover of Mankind.", ar: "ليقم الله ولتتبدَّد جميع أعدائه وليهرب من قدام وجهه كل مُبغضي إسمه القدوس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "As for Your people let them be blessed, a thousand thousand fold and ten thousand ten thousand fold, doing Your will.", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادتك." } },
      { kind: 'prayer', text: { en: "O Lord open my lips, and my mouth shall declare Your praise.", ar: "يا رب إفتح شفتيَ ولينطق فمي بتسبحتك." } },
      { kind: 'heading', text: { en: "The First Hoos", ar: "الهوس الأول" } },
      { kind: 'hymn', text: { en: "Then Moses and the children of Israel sang this song to the Lord and spoke saying, \"I will sing to the Lord for He has triumphed gloriously.\"", ar: "حينئذ سبح موسى وبنو إسرائيل بهذه التسبحة للرب وقالوا، \"فلنسبح للرب لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider He has thrown into the sea. The Lord is my strength and song, and He has become my salvation.", ar: "الفَرس وراكبه طرحهما في البحر. مُعيني وساتري، صار لي خلاصاً." } },
      { kind: 'hymn', text: { en: "He is my God and I will glorify Him, my father´s God and I will exalt Him.", ar: "هذا هو إلهي فأمجده، إله أبي فأرفعه." } },
      { kind: 'hymn', text: { en: "The Lord is a Man of war, the Lord is His name. Pharaoh's chariots and his army He has cast into the sea.", ar: "الرب مكسر الحروب، الرب إسمه. مركبات فرعون وكل قوته طرحهما في البحر." } },
      { kind: 'hymn', text: { en: "His chosen captains also are drowned in the Red Sea.", ar: "ركباناً منتخبين ذي ثلاث جنبات غرقهم في البحر الأحمر." } },
      { kind: 'hymn', text: { en: "The depths have covered them; they sank to the bottom as a stone.", ar: "غطاهم الماء، إنغمسوا إلى العمق مثل الحجر." } },
      { kind: 'hymn', text: { en: "Your right hand O Lord has become glorious in power. Your right hand O Lord has dashed the enemy in pieces.", ar: "يمينك يا رب تمجدت بالقوة. يدك اليمنى يا إلهي أهلكت أعداءك." } },
      { kind: 'hymn', text: { en: "And in the greatness of Your excellence, You have overthrown those who rose up against You, You sent forth Your wrath, it consumed them like stubble.", ar: "بكثرة مجدك، سحقت الذين يقاوموننا، أرسلت غضبك، فأكلهم مثل الهشيم." } },
      { kind: 'hymn', text: { en: "And with the blast of Your nostrils the waters were gathered together, the flood stood upright like a wall, and the depths were congealed in the heart of the sea.", ar: "وبروح غضبك وقف الماء، وإرتفعت الماء مثل السور، وجمدت الأمواج في وسط البحر." } },
      { kind: 'hymn', text: { en: "The enemy said, \"I will pursue, I will overtake, I will divide the spoil, my lust shall be satisfied upon them, I will draw my sword and my hand shall destroy them.\"", ar: "قال العدو، \"إني أسرع فأدرك، وأقسم الغنائم، وأشبع نفسي، وأقتل بسيفي ويدي تتسلط.\"" } },
      { kind: 'hymn', text: { en: "You blew with Your wind, the sea covered them, they sank like lead in the mighty waters.", ar: "أرسلت روحك، فغطاهم البحر، وغطسوا إلى أسفل كالرصاص في مياه كثيرة." } },
      { kind: 'hymn', text: { en: "Who is like You O Lord among the gods? Who is like You, glorified in His saints, amazing in glory, performing wonders.", ar: "من يشبهك في الآلهة. يا رب من يشبهك، مُمجداً في قديسيك، متعجباً منك بالمجد، صانعاً عجائب." } },
      { kind: 'hymn', text: { en: "You stretched out Your right hand, the earth swallowed them. You in Your mercy have led forth the people whom You have redeemed, You have guided them in Your strength, to Your holy habitation.", ar: "مددت يمينك فإبتلعتهم الأرض. هديت شعبك بالحقيقة، هذا الذي إخترته، وقويته بتعزيتك، إلى موضع راحة قدسك." } },
      { kind: 'hymn', text: { en: "The people will hear and be afraid, sorrow will take hold of the inhabitants of Palestine.", ar: "سمعت الأمم وغضبت، والمخاض أخذ سكان فلسطين." } },
      { kind: 'hymn', text: { en: "Then the dukes of Edom will be amazed, the mighty men of Moab trembling will take hold of them.", ar: "حينئذ أسرع وُلاة أدوم، ورؤساء المؤابيين أخذتهم الرعدة." } },
      { kind: 'hymn', text: { en: "All the inhabitants of Canaan will melt away, fear and dread will fall on them.", ar: "ذاب كل سكان كنعان، وأتت عليهم الرعدة والخوف." } },
      { kind: 'hymn', text: { en: "By the greatness of Your arm they will be as still as stone, till Your people pass over O Lord, till Your people pass over whom You have purchased.", ar: "بكثرة ساعدك فليصيروا كالحجر، حتى يجتاز شعبك يا رب، حتى يجتاز شعبك هذا الذي إقتنيته." } },
      { kind: 'hymn', text: { en: "You will bring them in and plant them in the mountain of Your inheritance, in the place O Lord, which You have made for You to dwell in.", ar: "أدخلهم وأغرسهم على جبل ميراثك، وفي مسكنك المُعَد، هذا الذي صنعته يا رب." } },
      { kind: 'hymn', text: { en: "In Your sanctuary O Lord which Your hands have established, the Lord shall reign forever and ever.", ar: "موضعك المقدس يا رب الذي أعددته يداك، يا رب تمَلُك منذ الأزل والآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "For the horses of pharaoh went with his chariots and his horsemen into the sea.", ar: "لأنه قد دخل إلى البحر خيل فرعون ومركباته وفرسانه." } },
      { kind: 'hymn', text: { en: "And the Lord brought back the waters of the sea upon them, but the children of Israel went on dry land in the midst of the sea.", ar: "والرب غمرهم بماء البحر، أما بنو إسرائيل فكانوا يمشون على اليابسة في وسط البحر." } },
      { kind: 'hymn', text: { en: "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand, and all the women went out after her with timbrels and with praises.", ar: "فأخذت مريم النبية، أخت هرون، الدُف بيديها، وخرج في إثرها جميع النسوة بالدُفوف والتسابيح." } },
      { kind: 'hymn', text: { en: "And Miriam answered them saying, \"Sing to the Lord, for He has triumphed gloriously.\"", ar: "وبدأت مريم في مقدمتهنَّ تقول، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider, He has thrown into the sea. \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "الفرس ورُاكب الفرس، طرحهما في البحر. \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'heading', text: { en: "The First Hoos Lobsh", ar: "لبش الهوس الأول" } },
      { kind: 'hymn', text: { en: "With the split, the waters of the sea split, and the very deep, became a walkway.", ar: "قطعاً إنقطع، ماء البحر، والعمق العميق، صار مَسلكاً." } },
      { kind: 'hymn', text: { en: "A hidden earth, was shone upon by the sun, and an untrodden road, was walked upon.", ar: "أرض غير ظاهرة، أشرقت الشمس عليها، وطريق غير مسلوكة، مشوا عليها." } },
      { kind: 'hymn', text: { en: "The flowing water, stood still, by a miraculous, act of wonder.", ar: "ماء مُنحل، وقف، بفِعل عجيب، مُعِجز." } },
      { kind: 'hymn', text: { en: "Pharaoh and his chariots, were drowned, and the children of Israel, crossed the sea.", ar: "غرق فرعون، ومركباته، وعبر بنو إسرائيل، البحر." } },
      { kind: 'hymn', text: { en: "And in front of them was, Moses the prophet praising, until he brought them, to the wilderness of Sinai.", ar: "وكان موسى النبي، يسبح قدامهم، حتى أدخلهم، برية سيناء." } },
      { kind: 'hymn', text: { en: "And they were praising God, with this new psalmody, saying \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "وكانوا يسبحون الله، بهذه التسبحة الجديدة قائلين، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "Through the prayers, of Moses the archprophet, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، موسى رئيس الأنبياء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع أبيك الصالح، والروح القدس، لأنك (قُمتأتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Second Hoos", ar: "الهوس الثاني" } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord for He is good, Alleluia His mercy endures forever.", ar: "أُشكروا الرب لأنه صالح وخيِّر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of gods, Alleluia His mercy endures forever.", ar: "أُشكروا إله الآلهة، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords, Alleluia His mercy endures forever.", ar: "أُشكروا رب الأرباب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who alone does great wonders, Alleluia His mercy endures forever.", ar: "الصانع العجائب العظام وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who by wisdom made the heavens, Alleluia His mercy endures forever.", ar: "الذي خلق السموات بفهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who stretched out the earth above the waters, Alleluia His mercy endures forever.", ar: "الذي ثبَّت الأرض على المياه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who made great lights, Alleluia His mercy endures forever.", ar: "الذي خلق نيرين عظيمين وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The sun to rule by day, Alleluia His mercy endures forever.", ar: "الشمس لحكم النهار، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The moon and stars to rule by night, Alleluia His mercy endures forever.", ar: "القمر والنجوم لحكم الليل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote Egypt in their firstborn, Alleluia His mercy endures forever.", ar: "الذي ضرب المصريين مع أبكارهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And brought out Israel from among them, Alleluia His mercy endures forever.", ar: "وأخرج إسرائيل من وسطهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "With a strong hand and with a stretched out arm, Alleluia His mercy endures forever.", ar: "بيد عزيزة وذراع عالية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who divided the Red Sea into parts, Alleluia His mercy endures forever.", ar: "الذي شق البحر الأحمر إلى أقسام، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And made Israel to pass through the midst of it, Alleluia His mercy endures forever.", ar: "وأجاز إسرائيل في وسطه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "But overthrew pharaoh and his hosts in the Red Sea, Alleluia His mercy endures forever.", ar: "وطرح فرعون وكل قوته في البحر الأحمر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who led His people through the wilderness, Alleluia His mercy endures forever.", ar: "الذي أخرج شعبه إلى البرية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who retrieved water from a rock, Alleluia His mercy endures forever.", ar: "الذي أخرج ماء من صخرة صماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote great kings, Alleluia His mercy endures forever.", ar: "الذي ضرب ملوكاً عُظماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And slew famous kings, Alleluia His mercy endures forever.", ar: "وقتل ملوكاً عجيبين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Sihon the king of the Amorites, Alleluia His mercy endures forever.", ar: "سيحون ملك الأموريين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And Og the king of Bashan, Alleluia His mercy endures forever.", ar: "وعوج ملك باشان، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And gave their lands for a heritage, Alleluia His mercy endures forever.", ar: "أعطى أرضهم ميراثاً، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "A heritage unto Israel His servant, Alleluia His mercy endures forever.", ar: "ميراثاً لعبده إسرائيل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who remembered us in our low estate, Alleluia His mercy endures forever.", ar: "في تواضعنا ذكرنا الرب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And has redeemed us from our enemies, Alleluia His mercy endures forever.", ar: "وخلصنا من أيدي أعدائنا، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who gives food to all flesh, Alleluia His mercy endures forever.", ar: "الذي يعطي طعاماً لكل جسد حي، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of heaven, Alleluia His mercy endures forever.", ar: "إحمدوا إله السماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords for He is good, Alleluia His mercy endures forever.", ar: "إحمدوا رب الأرباب لأنه طيب وصالح، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'heading', text: { en: "The Second Hoos Lobsh", ar: "لبش الهوس الثاني" } },
      { kind: 'hymn', text: { en: "Let us give thanks, to Christ our God, with David the prophet, and psalmist.", ar: "فلنشكر، المسيح إلهنا، مع المرتل، داود النبي." } },
      { kind: 'hymn', text: { en: "For He has made the heavens, and all its hosts, and established the earth, on the waters.", ar: "لأنه خلق السموات، وجنودها، وأسَّس الأرض، على المياه." } },
      { kind: 'hymn', text: { en: "These two great stars, the sun and the moon, He has made to enlighten, the firmament.", ar: "هذان الكوكبان العظيمان، الشمس والقمر، جعلهما ينيران، في الفلك." } },
      { kind: 'hymn', text: { en: "He brought forth the winds, out of His treasure box, He breathed unto the trees, and they blossomed.", ar: "أخرج الرياح، من خباياها، نفخ في الأشجار، حتى أزهرت." } },
      { kind: 'hymn', text: { en: "He caused the rain to fall, upon the face of the earth, and it sprouted, and gave its fruit.", ar: "أمطرا مطراً، على وجه الأرض، حتى أنبتت، وأعطت ثمرها." } },
      { kind: 'hymn', text: { en: "He brought forth water, out of a rock, and gave it to His people, in the wilderness.", ar: "أخرج ماء، من صخرة صماء، وسقى شعبه، في البرية." } },
      { kind: 'hymn', text: { en: "He made man, in His image, and His likeness, that he may praise Him.", ar: "صنع الإنسان، كشبهه، وصورته، لكي يباركه." } },
      { kind: 'hymn', text: { en: "Let us praise Him, and exalt His name, and give thanks to Him, His mercy endures forever.", ar: "فلنسبحه، ونرفع إسمه، ونشكره لأن رحمته، كائنة إلى الأبد." } },
      { kind: 'hymn', text: { en: "Through the prayers, of David the psalmist, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، المرتل داود، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله، القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of all the heavenly hosts, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، كل صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Blessed are You indeed, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "مبارك أنت بالحقيقة، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Third Hoos", ar: "الهوس الثالث" } },
      { kind: 'hymn', text: { en: "Blessed are You O Lord God of our fathers, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الرب إله أبائنا، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed is Your holy name and Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك إسم مجدك القدوس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the holy temple of Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في هيكل مجدك المقدس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You who beholds the depths and sits upon the Cherubim, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الناظر إلى الأعماق الجالس على الشاروبيم، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You on the throne of Your kingdom, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت على عرش مُلكك، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the firmament of heaven, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في فلك السماء، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you works of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع أعمال الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السموات، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you angels of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا جميع ملائكة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you waters above the heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع المياه التي فوق السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you powers of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع قوات الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O sun and moon, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها الشمس والقمر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you stars of heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا سائر نجوم السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you rain and dew, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأمطار مع الأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you clouds and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السُحب والرياح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you spirits, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع الأرواح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O fire and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها النار والحرارة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O cold and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والحر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you dew and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأهوية والأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you nights and days, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الليالي والأيام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O light and darkness, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها النور والظلمة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O frost and cold, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والصقيع، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O snow and ice, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها الجليد والثلج، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you lightnings and clouds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البروق والسحب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all the earth, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأرض كلها، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you mountains and all hills, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الجبال وجميع الآكام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you things that spring up on the earth, praise Him and exalt Him above all forever.", ar: "بارك الرب يا جميع ما يَنبت على وجه الأرض، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you fountains, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الينابيع، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you seas and rivers, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البحار والأنهار، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you whales and all that moves in the waters, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الحيتان وجميع ما يتحرك في الماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you birds of the sky, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع طيور السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you wild beasts and cattle, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الوحوش وكل البهائم، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you sons of men, worship the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا بني البشر، وأُسجدوا للرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Israel, praise Him and exalt Him above all forever.", ar: "بارك الرب يا إسرائيل، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you priests of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا كهنة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you servants of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عبيد الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you spirits and souls of the just, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا أرواح وأنفس الصديقين، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you holy and humble of heart, praise Him and exalt Him above all forever.", ar: "باركوا الرب أيها القديسون والمتواضعو القلوب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all\nforever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "The Third Hoos — Esmo Epchois", ar: "الهوس الثالث — إسمو إبشويس" } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "Psali for the Three Saintly Children", ar: "إبصالية للثلاثة فتية القديسين" } },
      { kind: 'hymn', text: { en: "O sing unto Him who was crucified, buried and resurrected, who trampled and abolished death, praise Him and exalt Him above all.\nTake off the old man, and put on the new and superior one, come closer to greatness of mercy, praise Him and exalt Him above all.", ar: "رتلوا للذي صُلب عنا، وقُبر وقام، وأبطل الموت وأهانه، سبحوه وزيدوه علواً.\nإخلعوا الإنسان العتيق، وألبسوا الجديد الفاخر، وإقتربوا إلى عِظَم الرحمة، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "All you Christian people, the priests and the deacons, glorify the Lord for He is worthy, praise Him and exalt Him above all.\nCome to us O three children, whom Christ our God has lifted, and from the Devil has delivered, praise Him and exalt Him above all.", ar: "يا جنس المسيحيين، القسوس والشمامسة، أعطوا مجداً للرب لأنه مستوجب، سبحوه وزيدوه علواً.\nهَلُمَّ إلينا أيها الثلاثة فتية، الذين رفعهم المسيح إلهنا، وأنقذهم من إبليس، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "For the sake of your God the Messiah, the Giver of all good things, come unto us O Hananiah, praise Him and exalt Him above all.\nO Azariah the zealot, morning and noon and the evening, glorify the power of the Trinity, praise Him and exalt Him above all.", ar: "من أجل إلهك ماسيا، المانح الإحسان، هَلُمَّ إلينا يا حنانيا، سبحوه وزيدوه علواً.\nيا عزاريا الغيور، عشية وبكرة والظهيرة، أعط مجداً لقوة الثالوث، سبّحه وزده علواً." } },
      { kind: 'hymn', text: { en: "Behold Emmanuel [our Lord], is now in our midst O Mishael, proclaim with the voice of joy, praise Him and exalt Him above all.\nGather now and persevere, and proclaim with the priests, bless the Lord all His works, praise Him and exalt Him above all.", ar: "فها هوذا عمانوئيل، في وسطنا يا ميصائيل، تكلم بصوت التهليل، سبّحه وزده علواً.\nإجتمعوا وثابروا جميعاً، تكلموا مع القسوس، وسبحي الرب يا جميع أعماله، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "The heavens declare the glory, of God until this day, O you angels whom He has made, praise Him and exalt Him above all.\nNow all you powers of the Lord, bless His honored name, O sun and moon and all the stars, praise Him and exalt Him above all.", ar: "ها السموات تنطق بمجد الله، إلى هذا اليوم، يا أيها الملائكة الذين أنشأهم، سبحوه وزيدوه علواً.\nوالآن يا قوات الرب، باركوا إسمه الكريم، أيتها الشمس والقمر والنجوم، سبحيه وزيديه علواً." } },
      { kind: 'hymn', text: { en: "And also you rain and dew, sing praises unto our Savior, for He is the God of our fathers, praise Him and exalt Him above all.\nGlorify the Lord O clouds and winds, together with the souls and the spirits, O you cold and fire and heat, praise Him and exalt Him above all.", ar: "وأيضاً أيتها الأمطار والأنداء، إمدحي مخلصنا، لأنه هو إله آبائنا، سبحيه وزيديه علواً.\nأعطي مجداً أيتها السحب معاً، والأهوية والنفوس والأرواح، والبرد والنار والحرارة، سبحيه وزيده علوا." } },
      { kind: 'hymn', text: { en: "You also nights and days, light and darkness and lightning, glorify the Lover of Mankind, praise Him and exalt Him above all.\nYou trees and all that springs on the earth, and all that moves in the sea, mountains and the forests, praise Him and exalt Him above all.", ar: "أيتها الليالي والأيام أيضاً، والنور والظلمة والبروق، قائلة المجد لك يا محب البشر، سبحوه وزيدوه علواً.\nأيتها الأشجار وجميع ما ينبُت، في الأرض وكل ما يتحرك، في المياه والجبال والغياض، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Praise without ceasing, the Lord the King of the kings, O you rivers and seas, praise Him and exalt Him above all.\nAnd we also seeing them, let us say with all these things, bless the Lord all you birds, praise Him and exalt Him above all.", ar: "وأيضاً سبحي بغير فتور، الرب ملك الملوك، أيتها البحار والأنهار، سبحيه وزيديه علواً.\nهكذا نحن إذ ننظر إليهم، فلنقل مع هذه الموجودات جميعها، باركي الرب يا جميع الطيور، سبحيه وزيده علواً." } },
      { kind: 'hymn', text: { en: "O snow and ice, cattle and wild beasts, bless the Lord of lords, praise Him and exalt Him above all.\nBless the Lord as befits Him, and not like the heretics, all you sons of men, praise Him and exalt Him above all.", ar: "أيها الجليد والثلج، والبهائم والوحوش، باركي رب الأرباب، سبحيه وزيديه علواً.\nسبحوا الرب كما يليق به، وليس كالمخالفين، يا أبناء البشر، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "O Israel offer before Him, honor and glory in a joyful voice, all you priests of Emmanuel, praise Him and exalt Him above all.\nYou servants of the true God, the souls of the righteous, and the humble and the charitable, praise Him and exalt Him above all.", ar: "مجداً وإكراماً قدم أمامه، يا إسرائيل بصوت التهليل، يا كهنة عمانوئيل، سبحوه وزيدوه علواً.\nيا خدام الله الحقيقي، وأنفس الأبرار، المتواضعين المحبين، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "God my God is the One, who saved you from danger, O Sedrach Misach and Abednago, praise Him and exalt Him above all.\nHurry with great haste, O you righteous of the Lord, and all the creatures He has made, praise Him and exalt Him above all.", ar: "الله إلهي أنا، هو مخلصكم من الخطر، يا سدراك وميساك وأبدناغو، سبحوه وزيدوه علوا.\nأسرعوا بحرص عظيم، يا أتقياء الرب، وكل الطبائع التي صنعها، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Coolness and repose without ceasing, grant unto all of us, that we may joyfully proclaim, praise Him and exalt Him above all.\nAnd also Your poor servant Sarkis, make him without condemnation, that he may join all those and say, praise Him and exalt Him above all.", ar: "برودة ونياحاً أعطنا، كلنا بغير إنقطاع، لنقول بتمتُع، سبحوه وزيدوه علواً.\nكذلك عبدك المسكين سركيس، إجعله بغير دينونة، ليقول مع هؤلاء كشريك، سبحوه وزيدوه علواً." } },
      { kind: 'heading', text: { en: "Ten-oueh Ensok", ar: "تين أويه إنسوك" } },
      { kind: 'hymn', text: { en: "We follow You with all our hearts, and fear You, and we seek Your face, O God do not forsake us.", ar: "نتبعك بكل قلوبنا، ونخافك، ونطلب وجهك، يا الله لا تخزنا." } },
      { kind: 'hymn', text: { en: "But rather deal with us, according to Your meekness, and according to Your great mercy, O Lord help us.", ar: "بل إصنع معنا، بحسب دعتك، وكثرة رحمتك، يا رب أعنَّا." } },
      { kind: 'hymn', text: { en: "May our prayers ascend to You, O our Master, like burnt offerings of lambs, and fat calves.", ar: "فلتصعد صلاتنا، أمامك يا سيدنا، مثل محرقات كباش، وعجول سِمان." } },
      { kind: 'hymn', text: { en: "Do not forget the covenant, which You have made with our fathers, Abraham Isaac and Jacob, Israel Your saint.", ar: "لا تنس العهد الذي، قطعته مع آبائنا، إبراهيم وإسحق ويعقوب، إسرائيل قديسك." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you nations, the tribes and all kinds of tongues, praise Him and glorify Him, above all forever.", ar: "باركوا الرب يا جميع الشعوب، والقبائل ولغات الألسن، سبحوه ومجدوه، وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Pray to the Lord on our behalf, O three saintly children, Sedrach Misach and Abednego, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة فتية القديسين، سدراك وميساك وأبدناغو، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints", ar: "مجمع القديسين" } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the Lady of us all the Mother of God, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، يا سيدتنا كلنا السيدة والدة الإله، مريم أُم مخلصنا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Michael and Gabriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، ميخائيل وغبريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Raphael and Souriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، رافائيل وسوريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Sedakiel Sarathiel and Ananiel, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا رؤساء الملائكة الأطهار، سداكيال وسراتيال وأنانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O thrones dominions and powers, the Cherubim and the Seraphim, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، أيتها الكراسي والأرباب والقوات، والشيروبيم والسرافيم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O four incorporeal beasts, the ministering flames of fire, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها الأربعة الحيوانات غير المتجسدين، الخدام الملتهبين ناراً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O priests of the truth, the twenty four presbyters, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا كهنة الحق، الأربعة والعشرين قسيساً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O angelic hosts, and all the heavenly multitudes, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها العساكر الملائكية، والطغمات السمائية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lords the fathers the patriarchs, Abraham Isaac and Jacob, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء البطاركة، إبراهيم وإسحق ويعقوب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O perfect man, the righteous and just Enoch, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الرجل الكامل، البار أخنوخ الصديق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Elijah the tishbite, and Elisha his disciple, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيليا التسبيتي، وإليشع تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Moses the archprophet, and Isaiah and Jeremiah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا موسى رئيس الأنبياء، وأشعياء وأرميا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O David the psalmist, Ezekiel and Daniel, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا داود المرتل، وحزقيال ودانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Joachim Anna and Joseph the elder, and the righteous Job Joseph and Nicodemus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا يواقيم وحنِّة ويوسف الشيخ، والصديق أيوب ويوسف ونيقوديموس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Melchizedek and Aaron, and Zacharias and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ملكي صادق وهرون، وزكريا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the prophets, and all the righteous and the just, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الأنبياء، والأبرار والصديقين، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O forerunner and baptizer, John the Baptist, that He may forgive us our sins.", ar: "إشفع فينا (أمام الرب)، أيها السابق الصابغ، يوحنا المعمدان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the hundred and forty four thousand, and the celibate evangelist, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها المئة والأربعة والأربعين ألفاً، والبتول الإنجيلي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters and fathers the Apostles, and the rest of the Disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء الرسل، وبقية التلاميذ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O blessed archdeacon, Stephen the first martyr, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا رئيس الشمامسة المبارك، إستفانوس الشهيد الأول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the apostle, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الناظر الإله الإنجيلي، أبا مرقس الرسول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyr, my lord prince George, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الشهيد المجاهد، سيدي الملك جيؤرجيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Theodore and Theodore, Leontius and Panicharus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ثيؤدوروس وثيؤدوروس، ولاونديوس، وبانيكاروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Philopater Mercurius, and Abba Mina and Abba Victor, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا فيلوباتير مرقوريوس، وأبا مينا وأبا بقطر، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Claudius and Theodore, Abba Eschyron and Abba Isaac, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي إقلاديوس وثيئودوروس، وأبا سخيرون وأبا إسحق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basilidis and Evsebius, Macarius and Philotheos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا واسيليدس وأرسابيوس، ومكاريوس وفيلوثيؤوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pisura and Abba Epshoy, Abba Isi and his sister Thecla, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بسورة وأبا بشاي، وأبا إيسي وتكلا أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Justus Apali and Theoklia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يسطس وآبالي وثيؤكليا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Jacob the Persian, Saint Sergius and Saint Bacchus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا يعقوب الفارسي، والقديس سرجيوس وواخس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Cosmas his brothers and their mother, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، قزمان وإخوته وأمهم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Kir and his brother John, and Barbara and Juliana and Demiana, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا قير ويوحنا أخوه، وبربارة ويوليانة ودميانة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, master Apatir and his sister Iraee, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، السيد أبادير وإيرائي أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Julius and those who were with him, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يوليوس ومَن معه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Mari Pahnam and his sister Sarah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، مار بهنام وسارة أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Sarapamon the bishop, Psate and Gallinikos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صرابامون الأسقف، وإبصادي وغلينيكوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, the forty saints of Sebaste, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، الأربعون قديساً بسبسطية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Piro and Athom, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بيروه وأتوم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Abba Bishoy and his friend Peter, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، أيها الشهيدان المجاهدان، أبا بيشوي وصديقه بطرس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Eklog the priest, and Abba Epgol and Abba Kav, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا إكلوج القس، وأبا بيجول وأبا كاڤ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba John of Heraclia, master Piphamon and Pistavros, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا يوحنا الهرقلي، والسيد بفامون وبسطوروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Isidore and Panteleon, Sophia and Euphemia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيسيذوروس وبندلاون، وصوفيا وإفومية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Apanoub and Ptolomeos, Apa Ekragon and Sousennius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي أبانوب وإبطلماوس، وإبا إكراجون وسوسونيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O great high priest, Abba Peter seal of the martyrs, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا رئيس الكهنة العظيم، أنبا بطرس خاتم الشهداء، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O new martyrs, Pistavros and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان الجديدان، بسطوروس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Michael the hegumen, and Michael the monk, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، يا ميخائيل القمص، وميخائيل الراهب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the martyrs, who suffered for the sake of Christ, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الشهداء، الذين تألموا من أجل المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Antony and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا أنطونيوس وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O three saints Macarii, and all their children the cross-bearers, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة مقارات القديسون، وأولادهم لباس الصليب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers the hegumens, Abba John and Abba Daniel, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين القمصين، أنبا يوحنا وأنبا دانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Bishoy and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا بيشوي وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our saintly Roman fathers, Maximus and Dometius, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أبوينا القديسين الروميين، مكسيموس ودوماديوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O forty nine martyrs, the elders of Shiheet, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها التسعة والأربعون شهيداً، شيوخ شيهات، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O strong saint Abba Moses, and John Kame, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، أيها القوي القديس أنبا موسى، ويحنس كاما، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pachomius of the Koinonia, and Theodore his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا باخوم أبا الشركة، وثيودورس تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Shenouda the archimandrite, and Abba Wisa his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا شنودة رئيس المتوحدين، وأنبا ويصا تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Nopher and Abba Karus, and our father Paphnutius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا نفر وأنبا كاروس، وأبانا بفنوتيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Samuel the confessor, and Justus and Apollo his disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صموئيل المعترف، ويسطس وأبوللو تلميذيه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Apollo and Abba Apip, and our father Abba Pigimi, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا أبوللو وأنبا أبيب، وأبانا أنبا بيچيمي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Evkin and Abba Ehron, Abba Hor and Abba Phis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا إڤكين وأنبا إهرون، وأبا هور وأبا فيس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Parsouma and Ephraim, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا برسوما وإفريم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Epiphanius and Ammounios, and Arshillidis and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إبيفانيوس وأمونيوس، وأرشليدس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the ascetic fathers, Abba Abraam and George, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين الناسكين، أنبا أبرآم وجيؤرجي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Athanasius the apostolic, Severus and Dioscorus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أثاناسيوس الرسولي، وساويرس وديسقورس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basil and Gregory, and our father Abba Cyril, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا باسيليوس وإغريغوريوس، وأبانا أنبا كيرلس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the three hundred and eighteen gathered, at Nicea for the faith, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 318 الذين إجتمعوا، في نيقية من أجل الإيمان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O the one hundred and fifty at Constantinople, and the two hundred at Ephesus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 150 بمدينة القسطنطينية، والمائتين بأفسس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Hadid and Abba John, our great father Parsouma and Abba Roweis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا حديد وأنبا يوحنا، وأبانا العظيم أنبا برسوما وأنبا رويس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Abraam the hegumen, and our father Abba Mark, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا أبرآم القمص، وأبانا أنبا مرقس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the cross-bearers, perfected in the wilderness, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا مصاف لباس الصليب، الذين كملوا في البراري، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lord king Constantine, and his mother queen Helen, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الملك قسطنطين، وهيلانة الملكة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O wise virgin ladies, the brides of Christ, that He may forgive us our sins.", ar: "أُطلبنَّ من الرب عنا، أيتها الفتيات العذارى الحكيمات، عرائس المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the saints of this day, everyone according to his name, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا قديسي هذا اليوم، كل واحد بإسمه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Likewise we exalt you, with David the psalmist, \"You are a priest forever, according to the order of Melchizedek.\"", ar: "كذلك نعظمك، مع المرتل داود قائلين، \"أنت هو الكاهن إلى الأبد، على طقس ملكي صادق.\"" } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our holy father the patriarch, Pope Abba Shenouda the high priest, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا أبانا القديس البطريرك، أنبا شنودة رئيس الكهنة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "If a Bishop is present:\nPray to the Lord on our behalf, O our holy and righteous father, Abba (...) the Bishop (Metropolitan), that He may forgive us our sins.", ar: "في حضور الآب الأسقف:\nأطلب من الرب عنا، يا أبينا القديس البار، أنبا (...) الأسقف (المطران)، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Doxology for the Virgin Mary", ar: "ذكصولوجية العذراء مريم" } },
      { kind: 'doxology', text: { en: "Your greatness O Mary, the undefiled Virgin, is likened to the height of the palm tree, spoken of by Solomon.", ar: "عظمتِك يا مريم، العذراء غير الدنسة، تشبه عُلو النخلة التي، تكلم عنها سليمان." } },
      { kind: 'doxology', text: { en: "You are the spring of living water, that flows from Lebanon, for out of you sprang unto us, the grace of the divinity.", ar: "أنتِ ينبوع ماء الحياة، الفائض من لبنان، التي نبعت لنا منه، نعمة اللاهوت." } },
      { kind: 'doxology', text: { en: "You gave birth to Emmanuel, out of your virginal womb, and He has made us heirs, to the kingdom of heaven.", ar: "ولدتِ لنا عمانوئيل، من أحشائِك البتول، وصيرنا وارثين، في ملكوت السموات." } },
      { kind: 'doxology', text: { en: "According to the promise, He promised to our father, King David the patriarch, He came and fulfilled to us.", ar: "كالوعد الذي وعد به، أبانا رئيس الآباء، الذي هو الملك داود، أتى وأكمله لنا." } },
      { kind: 'doxology', text: { en: "Hail to you O Virgin, the very and true Queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدت لنا عمانوئيل." } },
      { kind: 'doxology', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Fourth Hoos", ar: "الهوس الرابع" } },
      { kind: 'hymn', text: { en: "(Psalm 148)", ar: "(المزمور 148)" } },
      { kind: 'hymn', text: { en: "Praise the Lord from the heavens Alleluia. Praise Him in the heights.", ar: "سبحوا الرب من السموات هلليلويا. سبحوه في الأعالي." } },
      { kind: 'hymn', text: { en: "Praise Him all His angels Alleluia. Praise Him all His hosts.", ar: "سبحوه يا جميع ملائكته هلليلويا. سبحوه يا جميع جنوده." } },
      { kind: 'hymn', text: { en: "Praise Him sun and moon Alleluia. Praise Him all you stars of light.", ar: "سبحيه أيتها الشمس والقمر هلليلويا. سبحيه يا جميع كواكب النور." } },
      { kind: 'hymn', text: { en: "Praise Him you heavens of heavens Alleluia. And you waters above the heavens.", ar: "سبحيه يا سماء السموات هلليلويا. ويا أيتها المياه التي فوق السموات." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For He commanded and they were created.", ar: "لتسبح جميعها لإسم الرب هلليلويا. لأنه قال فكانت." } },
      { kind: 'hymn', text: { en: "He has ordered and they were created Alleluia. He has established them forever and ever.", ar: "وأمر فخلقت هلليلويا. أقامها إلى الأبد وإلى أبد الأبد." } },
      { kind: 'hymn', text: { en: "He has made a decree which shall not pass away Alleluia. Praise the Lord from the earth.", ar: "وضع لها أمراً فلن تتجاوزه هلليلويا. سبحي الرب من الأرض." } },
      { kind: 'hymn', text: { en: "You great sea creatures and all the depths Alleluia. Fire and hail, snow and clouds, stormy wind fulfilling His word.", ar: "أيتها التنانين وجميع الأعماق هلليلويا. النار والبرد والثلج والجليد والريح العاصفة الصانعة كلمته." } },
      { kind: 'hymn', text: { en: "Mountains and all hills Alleluia. Fruitful trees and all cedars.", ar: "الجبال العالية وجميع الآكام هلليلويا. الأشجار المثمره وكل الأرز." } },
      { kind: 'hymn', text: { en: "Beasts and all cattle Alleluia. Creeping things and flying birds.", ar: "الوحوش وكل البهائم هلليلويا. الهوام وكل الطيور ذات الأجنحة." } },
      { kind: 'hymn', text: { en: "Kings of the earth and all people Alleluia. Princes and all judges of the earth.", ar: "ملوك الأرض وكل الشعوب هلليلويا. الرؤساء وكل حكام الأرض." } },
      { kind: 'hymn', text: { en: "Both young men and maidens Alleluia. Old men and children.", ar: "الشبان والعذارى هلليلويا. الشيوخ والصبيان." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For His name alone is exalted.", ar: "فليسبحوا جميعاً إسم الرب هلليلويا. لأنه قد تعالى إسمه وحده." } },
      { kind: 'hymn', text: { en: "His glory is above the earth and heaven Alleluia. And He has exalted the horn of His people.", ar: "شكره كائن على الأرض وفي السماء هلليلويا. ويرفع قرن شعبه." } },
      { kind: 'hymn', text: { en: "The praise of all His saints Alleluia. The children of Israel, a people near unto Him.", ar: "سُبحاً لجميع قديسيه هلليلويا. بني إسرائيل، الشعب القريب إليه." } },
      { kind: 'hymn', text: { en: "(Psalm 149)", ar: "(المزمور 149)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Sing to the Lord a new song Alleluia. And His praise in the congregation of the saints.", ar: "إنشدوا للرب نشيداً جديداً هلليلويا. لأن تسبحته في بيعة القديسين." } },
      { kind: 'hymn', text: { en: "Let Israel rejoice in his Maker Alleluia. Let the children of Zion be joyful in their King.", ar: "فليفرح إسرئيل بخالقه هلليلويا. وبنوا صهيون فليتهللوا بملكهم." } },
      { kind: 'hymn', text: { en: "Let them praise His name in a chorus Alleluia. Let them sing praises unto Him with timbrel and harp.", ar: "فليسِّبحوا إسمه القدوس بصفِ هلليلويا. بدف ومزمار فليرتلوا له." } },
      { kind: 'hymn', text: { en: "For the Lord takes pleasure in His people Alleluia. He will raise the meek with salvation.", ar: "لأن الرب يُسر بشعبه هلليلويا. يعلي الودعاء بالخلاص." } },
      { kind: 'hymn', text: { en: "Let the saints be joyful in glory Alleluia. Let them sing aloud upon their beds.", ar: "يفتخر القديسون بمجد هلليلويا. ويتهللون على مضاجعهم." } },
      { kind: 'hymn', text: { en: "Let the high praises of God be in their mouth Alleluia. And a two edged sword in their hands.", ar: "تعليات الله في حناجرهم هلليلويا. وسيوف ذات حدين في أيديهم." } },
      { kind: 'hymn', text: { en: "To execute vengeance on the nations Alleluia. And punishments on the people.", ar: "ليصنعوا نقمة في الأمم هلليلويا. وتوبيخات في الشعوب." } },
      { kind: 'hymn', text: { en: "To bind their kings with chains Alleluia. And their nobles with fetters of iron.", ar: "ليوثقوا ملوكهم بقيود هلليلويا. وإشرافهم بأغلال للأيدي من حديد." } },
      { kind: 'hymn', text: { en: "To execute on them the written judgment Alleluia. This honor have all His saints.", ar: "ليصنعوا بهم حُكماً مكتوباً هلليلويا. هذا المجد كائن في جميع قديسيه." } },
      { kind: 'hymn', text: { en: "(Psalm 150)", ar: "(المزمور 150)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise God in all His saints Alleluia.", ar: "سبحوا الله في جميع قديسيه هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him in the firmament of His power Alleluia.", ar: "سبحوه في جلد قوته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him for His mighty acts Alleluia.", ar: "سبحوه على مقدرته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him according to the multitudes of His greatness Alleluia.", ar: "سبحوه ككثرة عظمته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with the sound of the trumpet Alleluia.", ar: "سبحوه بصوت البوق هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with psaltery and harp Alleluia.", ar: "سبحوه بالمزمار والقيثار هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with timbrel and chorus Alleluia.", ar: "سبحوه بدفوف وصفوف هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with strings and organs Alleluia.", ar: "سبحوه بأوتار وأرغن هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with pleasant sounding cymbals Alleluia.", ar: "سبحوه بصنوج حسنة الصوت هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him upon the cymbals of joy Alleluia.", ar: "سبحوه بصنوج التهليل هلليلويا." } },
      { kind: 'hymn', text: { en: "Let every thing that has breath praise the name of the Lord our God Alleluia.", ar: "كل نسمة فلتسبح إسم الرب الهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son and the Holy Spirit Alleluia.", ar: "المجد للآب والإبن والروح القدس هلليلويا." } },
      { kind: 'hymn', text: { en: "Now and forever and unto the age of all ages Amen Alleluia.", ar: "الآن وكل أوان وإلى دهر الدهور آمين هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory to You, O our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لك يا إلهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory be to our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لإلهنا هلليلويا." } },
      { kind: 'heading', text: { en: "The Tuesday Psali", ar: "إبصالية الثلاثاء" } },
      { kind: 'hymn', text: { en: "Come to us today, O Christ our Master, shine upon us, with Your exalted divinity.\nSend to us, this great grace, of Your Holy Spirit, the Paraclete.", ar: "تعال إلينا اليوم، يا سيدنا المسيح، وأضئ علينا، بلاهوتك العالي.\nأرسل لنا هذه، النعمة العظيمة، التي لروحك، القدوس المُعزي." } },
      { kind: 'hymn', text: { en: "So that I may speak, with great honor, about Your holy, and blessed name.\nThis is He who was glorified, by the mouths of, Your righteous saints, who lived upon the earth.", ar: "لكى أنطق، بكرامة يسيرة، من أجل إسمك، القدوس المبارك.\nهذا الذي تمجد، في أفواه، قديسيك الأبرار، سكان الأرض." } },
      { kind: 'hymn', text: { en: "By those wandering people, in the barren mountains, threatened by hunger and thirst, frost and cold.\nThey were needy and suffering, and afflicted, according to, Paul the apostle.", ar: "هؤلاء التائهين، في الجبال المقفرة، بالجوع والعطش، والبرد والصقيع.\nمُعوَزين، مُتضايقين، مُتألِّمين كقول، بولس الرسول." } },
      { kind: 'hymn', text: { en: "But Your holy name, O my Lord Jesus, upheld and delivered them, in all their sufferings.\nYour holy name, O my Lord Jesus, saved them from all, their afflictions.", ar: "لكن أسمك القدوس، يا ربي يسوع، يكون لهم ناصراً، في جميع ضيقاتهم.\nإسمك القدوس، يا ربي يسوع، هو ينجيهم، من جميع شدائدهم." } },
      { kind: 'hymn', text: { en: "For them it was, a living food, which filled their souls, and their bodies too.\nFor them it was, a fountain of living water, sweeter than honey, in their mouths.", ar: "هو يكون لهم، طعام حياة، تقتات به نفوسهم، وأجسادهم معاً.\nهو يكون لهم، ينبوع ماء حياة، حلواً في حناجرهم، أكثر من العسل." } },
      { kind: 'hymn', text: { en: "When they call upon it, their hearts rejoiced, and their bodies, blossomed.\nWhen they uttered it, their minds were enlightened, and their hearts ascended, to the heights.", ar: "إذا أخبروا به، تفرح قلوبهم، وتزهر، أجسادهم.\nإذ نطقوا به، تستنير عقولهم، وترتفع إلى، العلاء قلوبهم." } },
      { kind: 'heading', text: { en: "Introduction to the Sunday Theotokia — Leebon", ar: "مقدمة ثيؤطوكية الأحد — ليبون" } },
      { kind: 'hymn', text: { en: "And whenever we, gather for prayer, let us bless the name, of my Lord Jesus.", ar: "وأيضاً إذا ما إجتمعنا، للصلاة، فلنبارك إسم، ربي يسوع." } },
      { kind: 'hymn', text: { en: "We bless You, O my Lord Jesus, deliver us through Your name, for we have hope in You.", ar: "لأننا نباركك، يا ربي يسوع، نجنا بإسمك، لأننا توكلنا عليك." } },
      { kind: 'hymn', text: { en: "That we may praise You, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "لكي نسبحك، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son, and the Holy Spirit, now and forever and unto, the age of all ages Amen.", ar: "المجد للآب والإبن، والروح القدوس، الآن وكل أوان، وإلى دهر الدهور آمين." } },
      { kind: 'heading', text: { en: "The Tuesday Theotokia — Adam", ar: "ثيؤطوكية الثلاثاء — آدام" } },
      { kind: 'hymn', text: { en: "The First Part", ar: "القطعة الأولى" } },
      { kind: 'hymn', text: { en: "The crown of our pride, the head of our salvation, the confirmation of our purity, is the Virgin Mary.", ar: "إكليل فخرنا، ورأس خلاصنا، وثبات طُهرنا، هي مريم العذراء." } },
      { kind: 'hymn', text: { en: "Who for us gave birth to, God the Word, who became man, for our salvation.", ar: "التي ولدت لنا، الله الكلمة، الذي صار إنساناً، لإجل خلاصنا." } },
      { kind: 'hymn', text: { en: "And after He became man, He is also God, therefore she gave birth to Him, while a virgin.", ar: "وبعد أن صار إنساناً، هو الإله أيضاً، فلهذا ولدته، وهي عذراء." } },
      { kind: 'hymn', text: { en: "Exalted is the wonder, of her pregnancy, and her delivery, is unutterable.", ar: "عالية هي الأُعجوبة، التي لحبلها، وولادتها أيضاً، لا يُنطق به." } },
      { kind: 'hymn', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والرُّوح القُدُس، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "The Second Part", ar: "القطعة الثانية" } },
      { kind: 'hymn', text: { en: "Great is the glory, of your virginity, O Virgin Mary, the perfect one.", ar: "عظيم هو مجد، بتوليتِك، يا مريم العذراء، الكاملة." } },
      { kind: 'hymn', text: { en: "You have found grace, and the Lord is with you, you are the ladder, which Jacob saw.", ar: "وجدتِ نعمة، الربُّ مَعَكِ، أنتِ هي السلم، التي رآها يعقوب." } },
      { kind: 'hymn', text: { en: "Set firmly on the earth, reaching to heaven, where the angels, come down upon it.", ar: "ثابتة على الأرض، ومرتفعة إلى السماء، والملائكة، نازلون عليها." } },
      { kind: 'hymn', text: { en: "You are the tree, which Moses has seen, flaming with fire, and was not consumed.", ar: "أنتِ هي الشجرة، التي رآها موسى، مُتَقدة بالنار، ولم تحترق." } },
      { kind: 'hymn', text: { en: "This is the Son of God, who dwelt in your womb, the fire of His divinity, did not burn your body.", ar: "أي إبن الله، الذي أتى وحلَّ في بطنِك، ونار لاهوته، لم تحرق جسدِك." } },
      { kind: 'hymn', text: { en: "You are the field, that was not planted, but you did give, the Fruit of life.", ar: "أنتِ هي الحقل، الذي لم يُزرَع، وأخرجتِ، ثمرة حياة." } },
      { kind: 'hymn', text: { en: "You are the treasure, that Joseph bought, and he found the pearl, hidden in its midst.", ar: "أنتِ هي الكنز، الذي إشتراه يوسف، فوجد الجوهر، مخفي في وسطه." } },
      { kind: 'hymn', text: { en: "Our Savior Jesus, was found in your womb, you bore Him for the world, that He may save us.", ar: "وُجد مُخلِّصنا، يسوع في بطنِك، وولدتيِه إلى العالم، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والرُّوح القُدُس، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "The Third Part", ar: "القطعة الثالثة" } },
      { kind: 'hymn', text: { en: "Hail to the Mother of God, the rejoicing of angels, hail to the chaste one, the preaching of the prophets.", ar: "السلام لوالدة الإله، تهليل الملائكة، السلام للعفيفة، كرازة الأنبياء." } },
      { kind: 'hymn', text: { en: "Hail to you who has found grace, the Lord is with you, hail to you who accepted, the Joy of the world.", ar: "السلام للتي وجدت نعمة، الربُّ مَعَكِ، السلام للتي قَبَلت من الملاك، فرح العالم." } },
      { kind: 'hymn', text: { en: "Hail to her who gave birth, to the Creator of all, hail to her who is worthy, to be called the Mother of Christ.", ar: "السلام للتي وَلَدت، خالق الكل، السلام للتي إستحقت، أن تُدعى أُم المسيح." } },
      { kind: 'hymn', text: { en: "Hail to you who brought, salvation to Adam and Eve, hail to her who nursed, the Provider of everyone.", ar: "السلام للتي أعطت، الخلاص لآدم وحواء، السلام للتي أرضعت، عائل كل أحد." } },
      { kind: 'hymn', text: { en: "Hail to the saint, the Mother of all the living, you are the one we pray to, intercede for us.", ar: "السلام للقديسة، أُم جميع الأحياء، نطلب إليكِ، أن تشفعي فينا." } },
      { kind: 'hymn', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والرُّوح القُدُس، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "The Fourth Part", ar: "القطعة الرابعة" } },
      { kind: 'hymn', text: { en: "If someone contemplates, about you, O holy Virgin, and Mother of God.", ar: "إذا تأملكِ أحدٌ، أيتها العذراء، القديسة، والدة الإله." } },
      { kind: 'hymn', text: { en: "And about the Mystery, full of wonder, which dwelt in you, for our salvation.", ar: "والسر، العجيب، الذي صار فيكِ، لأجل خلاصنا." } },
      { kind: 'hymn', text: { en: "He would keep silent, for he cannot utter, he would make us, rise up for praise.", ar: "فأنه يصمت من أجل، ما لا يُنطَق به، ويُقيمنا، إلى التسبيح." } },
      { kind: 'hymn', text: { en: "Because of the greatness, of the wonderful, Maker of all, good things.", ar: "من أجل عظمة، العجيب، صانع الخيرات، المتنوعة." } },
      { kind: 'hymn', text: { en: "For the living Word, of God the Father, came down to give the law, on Mount Sinai.", ar: "لأن كلمة الله، الحي الذي للآب، نزل ليعطي الناموس، على جبل سيناء." } },
      { kind: 'hymn', text: { en: "He covered the peak, of the mountain, with smoke and darkness, mist and storms.", ar: "غطَّى رأس الجبل، بالدخان، والظلام والضباب، والعاصف." } },
      { kind: 'hymn', text: { en: "Through the sound, of the trumpets, He was teaching the people, standing with fear.", ar: "ومن جهة، صوت الأبواق، كان يُعلِم، الواقفين بمخافة." } },
      { kind: 'hymn', text: { en: "He also descended on you, O speaking mountain, that spoke with humility, and love of mankind.", ar: "هو أيضاً نزل عليكِ، أيتها الجبل، الناطق بوداعة، ومحبة بشرية." } },
      { kind: 'hymn', text: { en: "And likewise, He took flesh from you, without alteration, a speaking body.", ar: "وهكذا أيضاً، تجسد منكِ، بغير تغيير، بجسد ناطق." } },
      { kind: 'hymn', text: { en: "Co-essential with us, and perfect, and also has, a rational soul.", ar: "مساويٍ لنا، كامل، وله نفس، عاقلة." } },
      { kind: 'hymn', text: { en: "He remained God, as He is, and became, a perfect man.", ar: "بقيَ إلهاً، على حاله، وصار، إنساناً كاملاً." } },
      { kind: 'hymn', text: { en: "So as to abolish, the iniquity of Adam, and that He may save, those who perished.", ar: "لكي يحل، زلَّة آدم، ويُخلِّص، مَنْ قد هلك." } },
      { kind: 'hymn', text: { en: "And to make him, a citizen of heaven, and restore his leadership, according to His great mercy.", ar: "ويُصَيِّره مدنيا، في السموات، ويردُّه إلى رئاسته، كعظيم رحمته." } },
      { kind: 'hymn', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والرُّوح القُدُس، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "The Fifth Part", ar: "القطعة الخامسة" } },
      { kind: 'hymn', text: { en: "The honor of the Virgin, is unutterable, for God desired her, He came and dwelt in her.", ar: "كرامة العذراء، لا يُنطق بها، لأن الله أرادها، وجاء وسكن فيها." } },
      { kind: 'hymn', text: { en: "He who abides in light, that is unapproachable, dwelt in her womb, for nine months.", ar: "الساكن في النور، غير المقترب إليه، حل في بطنها، تسعة شهور." } },
      { kind: 'hymn', text: { en: "Mary gave birth to, the Invisible, and Infinite One, and remained a virgin.", ar: "غير المنظور، غير المحدود، ولدته مريم، وهي عذراء." } },
      { kind: 'hymn', text: { en: "For this is the Rock, which Daniel saw, which was cut, from a mountain.", ar: "لأن هذا هو الحجر، الذي رآه دانيال، قد قُطع، من جبلٍ." } },
      { kind: 'hymn', text: { en: "The hands of men, never touched Him, for He is the Word, of the Father.", ar: "ولم تلمسه، يد إنسانٍ البتة، هو الكلمة، الذي من الآب." } },
      { kind: 'hymn', text: { en: "He came and took flesh, from the Virgin, without the seed of man, in order to save us.", ar: "أتى وتجسد، من العذراء، بغير زرع بشر، حتى خلصنا." } },
      { kind: 'hymn', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والرُّوح القُدُس، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "The Sixth Part", ar: "القطعة السادسة" } },
      { kind: 'hymn', text: { en: "You became a branch, of purity, and a vessel, of the faith.", ar: "صرتِ غصنا، للطهارة، وإناء، للإيمان." } },
      { kind: 'hymn', text: { en: "Of the orthodox, our holy fathers, O chaste Mother of God, the honored Virgin.", ar: "الأرثوذكسي، الذي لآبائنا القديسين، أيتها العفيفة والدة الإله، المكرمة العذراء." } },
      { kind: 'hymn', text: { en: "For you gave birth for us, God the Word, our Savior Jesus, He came and saved us.", ar: "لأنك ولدتِ لنا، الله الكلمة، مُخلِّصنا يسوع، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والرُّوح القُدُس، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "The Seventh Part", ar: "القطعة السابعة" } },
      { kind: 'hymn', text: { en: "You are the Mother of light, the honored Mother of God, you have carried, the infinite Logos.", ar: "أنتِ يا أم النور، المكرمة والدة الإله، حملتِ الكلمة، غير المحوى." } },
      { kind: 'hymn', text: { en: "After you gave birth to Him, you remained a virgin, with praises and blessings, we magnify you.", ar: "ومن بعد أن ولدتِه، بقيتِ عذراء، نعظمكِ بتسابيح، وبركات." } },
      { kind: 'hymn', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والرُّوح القُدُس، أتى وخلصنا." } },
      { kind: 'heading', text: { en: "The Tuesday Theotokia Lobsh", ar: "لبش ثيؤطوكية الثلاثاء" } },
      { kind: 'hymn', text: { en: "What bodily tongue, can describe you, O holy Virgin, and Mother of God.", ar: "أي لسان جسدي، يستطيع أن يتأملِك، أيتها العذراء القديسة، والدة الإله." } },
      { kind: 'hymn', text: { en: "For you became, a royal throne for the One, who is carried, by the Cherubim.", ar: "لأنكِ صرتِ، عرشاً ملوكياً، للمحمول، على الشاروبيم." } },
      { kind: 'hymn', text: { en: "By what means can we bless you, for you were exalted, above all the highest, and rational natures.", ar: "بأي نوع نقدر، أن نطوبِك، لأنكِ إرتفعِت عن الطبائع، العلوية العقلية." } },
      { kind: 'hymn', text: { en: "Your name is remembered, throughout all ages, O beautiful dove, and Mother of Christ.", ar: "يُذكر إسمِك، في كل الأجيال، أيتها الحمامة الحسنة، وأُم المسيح." } },
      { kind: 'hymn', text: { en: "Rejoice O Mary, the handmaiden and the Mother, for the angels praise Him, who is on your arms.", ar: "إفرحي يا مريم، العبدة والأم، لأن الذي في حجرك، الملائكة تسبحه." } },
      { kind: 'hymn', text: { en: "And the Cherubim, worthily worship Him, with the Seraphim, without ceasing.", ar: "والشاروبيم، يسجدون له بإستحقاق، والسِّرافيم، بغير فتور." } },
      { kind: 'hymn', text: { en: "They flap their wings saying, “This is the King of glory, who carries the sin of the world, according to His great mercy.”", ar: "يُرفرفون بأجنحتهم، قائلين \"هذا هو ملك المجد، رافع خطية العالم، كعظيم رحمته.\"" } },
      { kind: 'hymn', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً نطلب، أن نفوز برحمةٍ، بشفاعاتِك، عند محب البشر." } },
      { kind: 'heading', text: { en: "Introduction to the Difnar — Adam", ar: "مقدمة الدفنار — آدام" } },
      { kind: 'hymn', text: { en: "O come let us worship, the Holy Trinity, the Father and the Son, and the Holy Spirit.", ar: "تعالوا فلنسجد، للثالوث القدوس، الذي هو الآب والإبن، والروح القُدُس." } },
      { kind: 'hymn', text: { en: "Hail to you O Mary, the beautiful dove, who gave birth to, God the Word for us.", ar: "السلام لكِ يا مريم، الحمامة الحسنة، التي ولدت لنا، الله الكلمة." } },
      { kind: 'heading', text: { en: "Conclusion of the Adam Theotokias", ar: "ختام الثيؤطوكيات الآدام" } },
      { kind: 'prayer', text: { en: "Your mercies O my God, are countless, and exceedingly plenteous, are Your compassion.", ar: "مراحمك يا إلهي، غير محصاة، وكثيرة جداً، هي رأفاتك." } },
      { kind: 'prayer', text: { en: "All the rain drops, are counted by You, and the sand of the sea, is before Your eyes.", ar: "قطرات المطر، محصاة عندك جميعها، ورمل البحر، كائن أمام عينيك." } },
      { kind: 'prayer', text: { en: "How much more are, the sins of my soul, manifest before You, O my Lord.", ar: "فكم بالحري، خطايا نفسي، هذه الظاهرة، أمامك يا ربي." } },
      { kind: 'prayer', text: { en: "The sins that I have committed, do not remember my Lord, and do not count, my iniquities.", ar: "الخطايا التي صنعتها، يا ربي لا تذكرها، ولا تحسب، آثامي." } },
      { kind: 'prayer', text: { en: "For You have chosen the publican, and the adulteress You have saved, and the right-hand thief, my Lord You have remembered.", ar: "فإن العشار إخترته، والزانية خلصتها، واللص اليمين، يا سيدي ذكرته." } },
      { kind: 'prayer', text: { en: "And me too, the sinner, teach me O my Master, to offer repentance.", ar: "وأنا أيضاً الخاطئ، يا سيدي، علمني، أن أصنع توبة." } },
      { kind: 'prayer', text: { en: "For You do not desire, the death of a sinner, but rather that he returns, and that his soul may live.", ar: "لأنك لا تشاء، موت الخاطئ، مثل أن يرجع، وتحيا نفسه." } },
      { kind: 'prayer', text: { en: "Restore us O God, to Your salvation, and deal with us, according to Your goodness.", ar: "ردنا يا الله، إلى خلاصك، وعاملنا، كصلاحك." } },
      { kind: 'prayer', text: { en: "For You are good, and merciful, let Your compassion, speedily come to us.", ar: "لأنك أنت صالح، ورحوم، فلتدركنا، رأفاتك سريعاً." } },
      { kind: 'prayer', text: { en: "Have compassion upon us all, O Lord God our Savior, and have mercy upon us, according to Your great mercy.", ar: "ترأف علينا كلنا، أيها الرب الإله، مخلصنا وإرحمنا، كعظيم رحمتك." } },
      { kind: 'prayer', text: { en: "Remember those, O Christ our Master, be among us, and proclaim and say.", ar: "هؤلاء أذكرهم، يا سيدنا المسيح، كن في وسطنا، صارخاً قائلاً:" } },
      { kind: 'prayer', text: { en: "\"My peace I, give to you, the peace of My Father, I leave with you.\"", ar: "\"سلامي أنا، أعطيكم، سلام أبي، أتركه معكم.\"" } },
      { kind: 'prayer', text: { en: "O King of peace, grant us Your peace, render unto us Your peace, and forgive us our sins.", ar: "يا ملك السلام، أعطنا سلامك، قرر لنا سلامك، وإغفر لنا خطايانا." } },
      { kind: 'prayer', text: { en: "Disperse the enemies, of the Church, and fortify her that she, may not be shaken forever.", ar: "فرِّق أعداء الكنيسة، وحصنها، فلا تتزعزع، إلى الأبد." } },
      { kind: 'prayer', text: { en: "Emmanuel our God, is now in our midst, with the glory of His Father, and the Holy Spirit.", ar: "عمانوئيل إلهنا، في وسطنا الآن، بمجد أبيه، والروح القدس." } },
      { kind: 'prayer', text: { en: "May He bless us all, and purify our hearts, and heal the sicknesses, of our souls and bodies.", ar: "ليباركنا كلنا، ويطهر قلوبنا، ويشفي أمراض، نفوسنا وأجسادنا." } },
      { kind: 'prayer', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع إبيك الصالح، والروح القدس، لأنك (قمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Concluding Litany", ar: "طلبة الختام" } },
      { kind: 'litany', text: { en: "Kerie leysoun (Lord have mercy) is said three times before every part", ar: "يقال كيريي ليسون (يا رب إرحم) ثلاث مرات قبل كل ربع" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." } },
      { kind: 'litany', text: { en: "Kerie leysoun (3).", ar: "كيريي ليسون (3)." } },
      { kind: 'litany', text: { en: "O God have mercy on us.", ar: "يا الله إرحمنا." } },
      { kind: 'litany', text: { en: "O God hear us.", ar: "يا الله إسمعنا." } },
      { kind: 'litany', text: { en: "O God look to us.", ar: "يا الله أُنظر إلينا." } },
      { kind: 'litany', text: { en: "O God behold us.", ar: "يا الله إطَّلع علينا." } },
      { kind: 'litany', text: { en: "O God have compassion on us.", ar: "يا الله تراءف علينا." } },
      { kind: 'litany', text: { en: "We are Your people.", ar: "نحن شعبك." } },
      { kind: 'litany', text: { en: "We are Your creation.", ar: "نحن جبلتك." } },
      { kind: 'litany', text: { en: "Deliver us from our enemies.", ar: "نجنا من أعدائنا." } },
      { kind: 'litany', text: { en: "Deliver us from inflation.", ar: "نجنا من الغلاء." } },
      { kind: 'litany', text: { en: "We are Your servants.", ar: "نحن عبيدك." } },
      { kind: 'litany', text: { en: "You are the Son of God.", ar: "أنت إبن الله." } },
      { kind: 'litany', text: { en: "We believe in You.", ar: "آمنا بك." } },
      { kind: 'litany', text: { en: "For You have (risen/come) and saved us.", ar: "لأنك (قُمت/أتيت) وخلَّصتنا." } },
      { kind: 'litany', text: { en: "Visit us with Your salvation.", ar: "تعهدنا بخلاصك." } },
      { kind: 'litany', text: { en: "And forgive us our sins.", ar: "وإغفر لنا خطايانا." } },
      { kind: 'litany', text: { en: "Kerie leysoun.", ar: "كيريي ليسون." } },
      { kind: 'heading', text: { en: "The Morning Doxology", ar: "ذكصولوجية باكر" } },
      { kind: 'doxology', text: { en: "We worship the Father and the Son, and the Holy Spirit, hail to the church, the house of the angels.", ar: "نسجد للآب والإبن، والروح القدس، السلام للكنيسة، بيت الملائكة." } },
      { kind: 'doxology', text: { en: "Hail to the Virgin, who gave birth to our Savior, hail to Gabriel, who announced to her the good news.", ar: "السلام للعذراء، التي ولدت مخلصنا، السلام لغبريال، الذي بشرها." } },
      { kind: 'doxology', text: { en: "Hail to Michael, the archangel, hail to the twenty four, presbyters.", ar: "السلام لميخائيل، رئيس الملائكة، السلام للأربعة والعشرين، قسيساً." } },
      { kind: 'doxology', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the hosts, of the heavens.", ar: "السلام للشاروبيم، السلام للسارافيم، السلام لجميع الطغمات، السمائية." } },
      { kind: 'doxology', text: { en: "Hail to John, the great forerunner, hail to the, twelve Apostles.", ar: "السلام ليوحنا، السابق العظيم، السلام للإثنى عشر، رسولاً." } },
      { kind: 'doxology', text: { en: "Hail to our father Mark, the Evangelist, the destroyer, of the idols.", ar: "السلام لأبينا مرقس، الإنجيلي، مُبَدِد، الأوثان." } },
      { kind: 'doxology', text: { en: "Hail to Stephen, the first martyr, hail to George, the morning star.", ar: "السلام لإستفانوس، الشهيد الأول، السلام لجرجس، كوكب الصبح." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the martyrs, hail to Abba Antony, and the three Macarii.", ar: "السلام لجميع صفوف، الشهداء، السلام لأنبا أنطونيوس، والثلاثة المقارات." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the cross-bearers, hail to all the saints, who have pleased the Lord.", ar: "السلام لجميع صفوف، لُباس الصليب، السلام لجميع القديسين، الذين أرضوا الرب." } },
      { kind: 'doxology', text: { en: "Through their prayers, O Christ our King, have mercy upon us, in Your kingdom.", ar: "أيها المسيح ملكنا، بصلواتهم، إصنع معنا رحمة، في ملكوتك." } },
      { kind: 'doxology', text: { en: "(For Our Lord Jesus Christ)", ar: "(لأجل ربنا يسوع المسيح)" } },
      { kind: 'doxology', text: { en: "O true Light, that gives light, to every man, that comes into the world.", ar: "أيها النور الحقيقي، الذي يضئ، لكل إنسان، آتٍ إلى العالم." } },
      { kind: 'doxology', text: { en: "You came into the world, through Your love for man, and all the creation, rejoiced at Your coming.", ar: "أتيت إلى العالم، بمحبتك للبشر، وكل الخليقة، تهللت بمجيئك." } },
      { kind: 'doxology', text: { en: "You have saved Adam, from seduction, and delivered Eve, from the pangs of death.", ar: "خلصَّت آدم، من الغواية، وعتقت حواء، من طلقات الموت." } },
      { kind: 'doxology', text: { en: "You gave unto us, the Spirit of sonship, we praise and bless You, with Your angels.", ar: "أعطيتنا، روح النبوة، نسبحك ونباركك، مع ملائكتك." } },
      { kind: 'doxology', text: { en: "When the morning hour, comes upon us, O Christ our God, the true Light.", ar: "عندما يدخل، وقت باكر إلينا، أيها المسيح إلهنا، النور الحقيقي." } },
      { kind: 'doxology', text: { en: "Let the thought of light, shine within us, and do not let the darkness, of pain cover us.", ar: "فلتشرق فينا، حواس النور، ولا تغطينا، ظلمة الآلام." } },
      { kind: 'doxology', text: { en: "That we may praise You, with understanding, proclaiming and saying, with David.", ar: "لكي نسبحك، عقلياً، مع داود، صارخين، نحوك قائلين." } },
      { kind: 'doxology', text: { en: "\"My eyes have reached, the morning watch, that I may meditate, upon all Your words.\"", ar: "\"سبق أن بلغت، عيناي وقت السحر، لأتلو، جميع أقوالك.\"" } },
      { kind: 'doxology', text: { en: "Hear our voices, according to Your great mercy, save us O Lord our God, according to Your compassion.", ar: "إسمع صوتنا، كعظيم رحمتك، ونجنا أيها الرب إلهنا، حسب رأفاتك." } },
      { kind: 'doxology', text: { en: "O caring God, the Maker of all good things, who governs well, with His chosen ones.", ar: "يا الله المُهْتم، صانع الخيرات، مُدبر مُختاريه، حسناً." } },
      { kind: 'doxology', text: { en: "The strong Governor for those, who take refuge in Him, who longs for the salvation, and deliverance of everyone.", ar: "المدبر القوي، للملتجئين، المتشوق لخلاص، ونجاة كل أحد." } },
      { kind: 'doxology', text: { en: "Through Your goodness, You provided us the night, grant us to pass, this day without sin.", ar: "بصلاحك هيأت، لنا الليل، أنعم لنا بهذا اليوم، ونحن بغير خطية." } },
      { kind: 'doxology', text: { en: "That we may be worthy, to lift up our hands, before You without anger, or evil thoughts.", ar: "لنستحق أن نرفع، أيدينا إليك، أمامك بغير غضب، ولا فكر ردئ." } },
      { kind: 'doxology', text: { en: "At this dawn, make straight our coming in, and our going out, in the joy of Your protection.", ar: "في هذا السحر، سهل طرقنا، الداخلية والخارجية، بسترك المفرح." } },
      { kind: 'doxology', text: { en: "That we may proclaim, Your righteousness daily, and praise Your power, with David the prophet.", ar: "لننطق بعدلك، كل يوم، ونمجد قوتك، مع داود النبي." } },
      { kind: 'doxology', text: { en: "Saying \"In Your peace, O Christ our Savior, we slept and arose, for we have hoped in You.", ar: "قائلين \"بسلامك، أيها المسيح مخلصنا، رقدنا وقمنا، لأننا توكلنا عليك." } },
      { kind: 'doxology', text: { en: "Behold how beneficent, and how pleasant, it is for brethren, to dwell together in unity.\"", ar: "ها ما هو الحسن، وما هو الحلو، إلا إتفاق إخوة، ساكنين معاً.\"" } },
      { kind: 'doxology', text: { en: "United, in the true, evangelic love, like the Apostles.", ar: "مُتفقين، بمحبة حقيقية، إنجيلية، كمثل الرسل." } },
      { kind: 'doxology', text: { en: "It is like the fragrant oil, on the head of Christ, running down the beard, down to the feet.", ar: "مثل الطيب، على رأس المسيح، النازل على اللحية، إلى أسفل الرجلين." } },
      { kind: 'doxology', text: { en: "That anoints every day, the elders, the children and young men, and the deacons.", ar: "يمسح كل يوم، الشيوخ، والصبيان والفتيات، والخدام." } },
      { kind: 'doxology', text: { en: "Those whom the Holy Spirit, has attuned together, as a stringed instrument, always blessing God.", ar: "هؤلاء الذين، ألَّفهم الروح القدس معاً، مثل قيثارة مُسبحين، الله كل حين." } },
      { kind: 'doxology', text: { en: "By psalms and hymns, and spiritual songs, by day and by night, with an incessant heart.", ar: "بمزامير وتسابيح، وترانيم روحية، النهار والليل، بقلب لا يفتر." } },
      { kind: 'doxology', text: { en: "(For the Virgin)", ar: "(لأجل العذراء)" } },
      { kind: 'doxology', text: { en: "You are the Mother of the Light, the honored Mother of God, you have carried, the Uncircumscript Logos.", ar: "أنتِ يا أم النور، المكرمة والدة الإله، حملتِ الكلمة، غير المحوي." } },
      { kind: 'doxology', text: { en: "After you gave birth to Him, you remained a virgin, with praises and blessings, we magnify you.", ar: "ومن بعد أن ولدتِه، بقيتِ عذراء، نعظمكِ بتسابيح، وبركات." } },
      { kind: 'doxology', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والروح القدس، آتى وخلصنا." } },
      { kind: 'doxology', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً، نطلب أن نفوز، برحمة بشفاعاتك، لدى محب البشر." } },
      { kind: 'doxology', text: { en: "The select incense, of your virginity, ascended to the throne, of the Father.", ar: "البخور المختار، الذي لبتوليتك، صعد إلى، كرسي الآب." } },
      { kind: 'doxology', text: { en: "Better than the incense, of the Cherubim, and the Seraphim, O Virgin Mary.", ar: "أفضل من بخور، الشاروبيم، والسارافيم، يا مريم العذراء." } },
      { kind: 'doxology', text: { en: "Hail to the new heaven, whom the Father has created, and made a place of rest, for His beloved Son.", ar: "السلام للسماء الجديدة، التي صنعها الآب، وجعلها موضع راحة، لإبنه الحبيب." } },
      { kind: 'doxology', text: { en: "Hail to the royal throne, of Him who is, carried by, the Cherubim.", ar: "السلام للكرسي، الملوكي، الذي للمحمول، على الشاروبيم." } },
      { kind: 'doxology', text: { en: "Hail to the advocate, of our souls, you are indeed, the pride of our race.", ar: "السلام لشفيعة، نفوسنا، أنت بالحقيقة، فخر جنسنا." } },
      { kind: 'doxology', text: { en: "Intercede on our behalf, O full of grace, before our Savior, our Lord Jesus Christ.", ar: "إشفعي فينا، يا ممتلئة نعمة، أمام مخلصنا، ربنا يسوع المسيح." } },
      { kind: 'doxology', text: { en: "That He may confirm us, in the upright faith, and grant us the forgiveness, of our sins.", ar: "لكي يثبتنا، في الإيمان المستقيم، وينعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Angels)", ar: "(لأجل الملائكة)" } },
      { kind: 'doxology', text: { en: "Thousands of thousands, and myriads of myriads, of archangels, and holy angels.", ar: "ألوف ألوف، وربوات ربوات، رؤساء ملائكة، وملائكة مُقدسيين." } },
      { kind: 'doxology', text: { en: "They stand before, the throne, of the Pantocrator, proclaiming and saying.", ar: "وقوف أمام، كرسي، ضابط الكل، صارخين قائلين:" } },
      { kind: 'doxology', text: { en: "\"Holy holy, holy in truth, the glory and the honor, befit the Trinity.\"", ar: "\"قدوس قدوس، قدوس بالحقيقة، المجد والكرامة، يليقان بالثالوث.\"" } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the whole choir of the angels, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، جميع صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Apostles)", ar: "(لأجل الرسل)" } },
      { kind: 'doxology', text: { en: "Our fathers the Apostles, preached unto the nations, the Gospel, of Jesus Christ.", ar: "آباؤنا الرسل، بشروا في الأمم، بإنجيل، يسوع المسيح." } },
      { kind: 'doxology', text: { en: "Their voices went forth, into all the earth, and their words have reached, the ends of the world.", ar: "خرجت أصواتهم، إلى الأرض كلها، وبلغ كلامهم، إلى أقطار المسكونة." } },
      { kind: 'doxology', text: { en: "Through the prayers, of my masters the fathers the Apostles, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، سادتي الآباء الرسل، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Martyrs)", ar: "(لأجل الشهداء)" } },
      { kind: 'doxology', text: { en: "Unfading crowns, the Lord has placed, upon the whole choir, of the martyrs.", ar: "أكاليل غير مضمحلة، جعلها الرب، على جميع، صفوف الشهداء." } },
      { kind: 'doxology', text: { en: "He saved and delivered them, because they took refuge in Him, they celebrated with Him, in His kingdom.", ar: "أنقذهم وخلصهم، لأنهم إلتجأوا إليه، وعيدوا معه، في ملكوته." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the martyrs, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، جميع صفوف الشهداء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Saints)", ar: "(لأجل القديسين)" } },
      { kind: 'doxology', text: { en: "Your saints bless You, and they speak, of the glory, of Your kingdom.", ar: "قديسوك، يباركونك، وينطقون بمجد، ملكوتك." } },
      { kind: 'doxology', text: { en: "Your kingdom O my God, is an eternal kingdom, and Your Lordship, is unto all ages.", ar: "ملكوتك يا إلهي، ملكوت أبدي، وربوبيتك، إلى كل الأجيال." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the cross-bearers, the righteous and the just, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، كافة مصاف لابسي الصليب، والأبرار والصديقين، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Patriarchs and the Prophets)", ar: "(لأجل الآباء والأنبياء)" } },
      { kind: 'doxology', text: { en: "Hail to Elijah, the prophet of temperance, and Elisha, his elect disciple.", ar: "السلام لإيليا، النبي المتعفف، وإليشع، تلميذه المختار." } },
      { kind: 'doxology', text: { en: "The great Evangelist, of the land of Egypt, Mark the Apostle, the first prelate.", ar: "المبشر العظيم، في كورة مصر، مرقس الرسول، مدبرها الأول." } },
      { kind: 'doxology', text: { en: "You are the Mother of God, O Virgin Mary, ask Him on our behalf, to have mercy upon our race.", ar: "أنت هي أم الله، يا مريم العذراء، أُطلبي منه عنا، أن يرحم جنسنا." } },
      { kind: 'doxology', text: { en: "The great patriarch, our father Abba Severus, whose holy teachings, enlightened our minds.", ar: "البطريرك العظيم، أبونا أنبا ساويرس، الذي أنارت تعاليمه، المقدسة عقولنا." } },
      { kind: 'doxology', text: { en: "Our father the confessor, Abba Dioscorus, defended the faith, against the heretics.", ar: "أبونا المعترف، أنبا ديسقوروس، حارب عن الإيمان، ضد الهراطقة." } },
      { kind: 'doxology', text: { en: "And all of our fathers, who have pleased the Lord, may their holy blessings, be a guard unto us.", ar: "وكل آبائنا، الذين أرضوا الرب، بركتهم المقدسة، تكون لنا حارساً." } },
      { kind: 'doxology', text: { en: "Through their prayers, O God grant us, the forgiveness of our sins, and give us peace.", ar: "بصلواتهم، إنعم لنا يا الله، بمغفرة خطايانا، وأعطنا سلاماً." } }
    ],
  },
  {
    id: "psalmody-midnight-wednesday",
    title: { en: "Wednesday Midnight Praises", ar: "تسبحة نصف الليل ليوم الأربعاء" },
    blocks: [
      { kind: 'note', text: { en: "The complete fixed annual Wednesday (Watos) Midnight Psalmody.", ar: "النصوص الثابتة الكاملة للإبصلمودية السنوية لنصف الليل ليوم الأربعاء (واطس)." } },
      { kind: 'heading', text: { en: "Ten-theno", ar: "تين ثينو" } },
      { kind: 'prayer', text: { en: "Arise O children of the light, let us praise the Lord of hosts.", ar: "قوموا يا بني النور، لنسبح رب القوات." } },
      { kind: 'prayer', text: { en: "That He may grant us the salvation of our souls.", ar: "لكي ينعم لنا بخلاص نفوسنا." } },
      { kind: 'prayer', text: { en: "Whenever we stand before You in the flesh.", ar: "عندما نقف أمامك جسدياً." } },
      { kind: 'prayer', text: { en: "Cast away from our minds the slumber of sleep.", ar: "إنزع عن عقولنا نوم الغفلة." } },
      { kind: 'prayer', text: { en: "Grant us sobriety O Lord, that we may know how to stand before You at times of prayer.", ar: "أعطنا يا رب يقظة، لكي نفهم أن نقف أمامك وقت الصلاة." } },
      { kind: 'prayer', text: { en: "And ascribe unto You the befitting glorification, and win the forgiveness of our many sins. Glory be to You O Lover of Mankind.", ar: "ونرسل لك إلى فوق التمجيد اللائق، ونفوز بغفران خطايانا الكثيرة. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Behold bless the Lord all you servants of the Lord. Glory be to You O Lover of Mankind.", ar: "ها باركوا الرب يا عبيد الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "You who stand in the house of the Lord, in the courts of the house of our God. Glory be to You O Lover of Mankind.", ar: "القائمين في بيت الرب، في ديار بيت إلهنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "By night lift up your hands O you saints and bless the Lord. Glory be to You O Lover of Mankind.", ar: "بالليالي إرفعوا أيديكم إلى فوق أيها القديسون باركوا الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "The Lord bless you from Zion, who created heaven and earth. Glory be to You O Lover of Mankind.", ar: "يباركك الرب من صهيون، الذي خلق السماء والأرض. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my cry come before You O Lord, give me understanding according to Your word. Glory be to You O Lover of Mankind.", ar: "فلتدن وسيلتي قدامك يا رب، كقولك فهمني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my supplication come before You, deliver me according to Your word. Glory be to You O Lover of Mankind.", ar: "ليدخل إبتهالي أمامك، ككلمتك أحيني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My lips shall overflow with praise, when You have taught me Your statutes. Glory be to You O Lover of Mankind.", ar: "تفيض شفتاي السُبح، إذا ما علمتني حقوقك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My tongue shall speak of Your words for all Your commandments are righteous. Glory be to You O Lover of Mankind.", ar: "لساني يجيب بأقوالك لأن جميع وصاياك هي حق. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let Your hand help me for I have chosen Your precepts. Glory be to You O Lover of Mankind.", ar: "لتكن يدك لتخلصني لأني إشتهيت وصاياك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have longed for Your salvation O Lord, and Your Law is my delight. Glory be to You O Lover of Mankind.", ar: "إشتقت إلى خلاصك يا رب، وناموسك هو تلاوتي. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my soul live and it shall praise You, and let Your judgments help me. Glory be to You O Lover of Mankind.", ar: "تحيا نفسي وتسبحك، وأحكامك تعينني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have gone astray like a lost sheep, seek Your servant for I do not forget Your commandments. Glory be to You O Lover of Mankind.", ar: "ضللت مثل الخروف الضال، فأُطلب عبدك لأني لوصاياك لم أنس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Now and forever and unto the age of all ages Amen. Glory be to You O Lover of Mankind.", ar: "الآن وكل أوان وإلى دهر الدهور آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit, now and forever and unto all the ages Amen. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس منذ الآن وإلى أبد الأبدين كلها آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O good One the Lover of Mankind, glory be to Your Mother the Virgin and all Your saints. Glory be to You O Lover of Mankind.", ar: "المجد لك يا محب البشر الصالح، المجد لأُمك العذراء وجميع قديسيك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O only-begotten One, O holy Trinity have mercy upon us. Glory be to You O Lover of Mankind.", ar: "المجد لك أيها الوحيد، أيها الثالوث القدوس إرحمنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let God arise and let all His enemies be scattered and let all that hate His holy name flee from before His face. Glory be to You O Lover of Mankind.", ar: "ليقم الله ولتتبدَّد جميع أعدائه وليهرب من قدام وجهه كل مُبغضي إسمه القدوس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "As for Your people let them be blessed, a thousand thousand fold and ten thousand ten thousand fold, doing Your will.", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادتك." } },
      { kind: 'prayer', text: { en: "O Lord open my lips, and my mouth shall declare Your praise.", ar: "يا رب إفتح شفتيَ ولينطق فمي بتسبحتك." } },
      { kind: 'heading', text: { en: "The First Hoos", ar: "الهوس الأول" } },
      { kind: 'hymn', text: { en: "Then Moses and the children of Israel sang this song to the Lord and spoke saying, \"I will sing to the Lord for He has triumphed gloriously.\"", ar: "حينئذ سبح موسى وبنو إسرائيل بهذه التسبحة للرب وقالوا، \"فلنسبح للرب لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider He has thrown into the sea. The Lord is my strength and song, and He has become my salvation.", ar: "الفَرس وراكبه طرحهما في البحر. مُعيني وساتري، صار لي خلاصاً." } },
      { kind: 'hymn', text: { en: "He is my God and I will glorify Him, my father´s God and I will exalt Him.", ar: "هذا هو إلهي فأمجده، إله أبي فأرفعه." } },
      { kind: 'hymn', text: { en: "The Lord is a Man of war, the Lord is His name. Pharaoh's chariots and his army He has cast into the sea.", ar: "الرب مكسر الحروب، الرب إسمه. مركبات فرعون وكل قوته طرحهما في البحر." } },
      { kind: 'hymn', text: { en: "His chosen captains also are drowned in the Red Sea.", ar: "ركباناً منتخبين ذي ثلاث جنبات غرقهم في البحر الأحمر." } },
      { kind: 'hymn', text: { en: "The depths have covered them; they sank to the bottom as a stone.", ar: "غطاهم الماء، إنغمسوا إلى العمق مثل الحجر." } },
      { kind: 'hymn', text: { en: "Your right hand O Lord has become glorious in power. Your right hand O Lord has dashed the enemy in pieces.", ar: "يمينك يا رب تمجدت بالقوة. يدك اليمنى يا إلهي أهلكت أعداءك." } },
      { kind: 'hymn', text: { en: "And in the greatness of Your excellence, You have overthrown those who rose up against You, You sent forth Your wrath, it consumed them like stubble.", ar: "بكثرة مجدك، سحقت الذين يقاوموننا، أرسلت غضبك، فأكلهم مثل الهشيم." } },
      { kind: 'hymn', text: { en: "And with the blast of Your nostrils the waters were gathered together, the flood stood upright like a wall, and the depths were congealed in the heart of the sea.", ar: "وبروح غضبك وقف الماء، وإرتفعت الماء مثل السور، وجمدت الأمواج في وسط البحر." } },
      { kind: 'hymn', text: { en: "The enemy said, \"I will pursue, I will overtake, I will divide the spoil, my lust shall be satisfied upon them, I will draw my sword and my hand shall destroy them.\"", ar: "قال العدو، \"إني أسرع فأدرك، وأقسم الغنائم، وأشبع نفسي، وأقتل بسيفي ويدي تتسلط.\"" } },
      { kind: 'hymn', text: { en: "You blew with Your wind, the sea covered them, they sank like lead in the mighty waters.", ar: "أرسلت روحك، فغطاهم البحر، وغطسوا إلى أسفل كالرصاص في مياه كثيرة." } },
      { kind: 'hymn', text: { en: "Who is like You O Lord among the gods? Who is like You, glorified in His saints, amazing in glory, performing wonders.", ar: "من يشبهك في الآلهة. يا رب من يشبهك، مُمجداً في قديسيك، متعجباً منك بالمجد، صانعاً عجائب." } },
      { kind: 'hymn', text: { en: "You stretched out Your right hand, the earth swallowed them. You in Your mercy have led forth the people whom You have redeemed, You have guided them in Your strength, to Your holy habitation.", ar: "مددت يمينك فإبتلعتهم الأرض. هديت شعبك بالحقيقة، هذا الذي إخترته، وقويته بتعزيتك، إلى موضع راحة قدسك." } },
      { kind: 'hymn', text: { en: "The people will hear and be afraid, sorrow will take hold of the inhabitants of Palestine.", ar: "سمعت الأمم وغضبت، والمخاض أخذ سكان فلسطين." } },
      { kind: 'hymn', text: { en: "Then the dukes of Edom will be amazed, the mighty men of Moab trembling will take hold of them.", ar: "حينئذ أسرع وُلاة أدوم، ورؤساء المؤابيين أخذتهم الرعدة." } },
      { kind: 'hymn', text: { en: "All the inhabitants of Canaan will melt away, fear and dread will fall on them.", ar: "ذاب كل سكان كنعان، وأتت عليهم الرعدة والخوف." } },
      { kind: 'hymn', text: { en: "By the greatness of Your arm they will be as still as stone, till Your people pass over O Lord, till Your people pass over whom You have purchased.", ar: "بكثرة ساعدك فليصيروا كالحجر، حتى يجتاز شعبك يا رب، حتى يجتاز شعبك هذا الذي إقتنيته." } },
      { kind: 'hymn', text: { en: "You will bring them in and plant them in the mountain of Your inheritance, in the place O Lord, which You have made for You to dwell in.", ar: "أدخلهم وأغرسهم على جبل ميراثك، وفي مسكنك المُعَد، هذا الذي صنعته يا رب." } },
      { kind: 'hymn', text: { en: "In Your sanctuary O Lord which Your hands have established, the Lord shall reign forever and ever.", ar: "موضعك المقدس يا رب الذي أعددته يداك، يا رب تمَلُك منذ الأزل والآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "For the horses of pharaoh went with his chariots and his horsemen into the sea.", ar: "لأنه قد دخل إلى البحر خيل فرعون ومركباته وفرسانه." } },
      { kind: 'hymn', text: { en: "And the Lord brought back the waters of the sea upon them, but the children of Israel went on dry land in the midst of the sea.", ar: "والرب غمرهم بماء البحر، أما بنو إسرائيل فكانوا يمشون على اليابسة في وسط البحر." } },
      { kind: 'hymn', text: { en: "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand, and all the women went out after her with timbrels and with praises.", ar: "فأخذت مريم النبية، أخت هرون، الدُف بيديها، وخرج في إثرها جميع النسوة بالدُفوف والتسابيح." } },
      { kind: 'hymn', text: { en: "And Miriam answered them saying, \"Sing to the Lord, for He has triumphed gloriously.\"", ar: "وبدأت مريم في مقدمتهنَّ تقول، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider, He has thrown into the sea. \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "الفرس ورُاكب الفرس، طرحهما في البحر. \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'heading', text: { en: "The First Hoos Lobsh", ar: "لبش الهوس الأول" } },
      { kind: 'hymn', text: { en: "With the split, the waters of the sea split, and the very deep, became a walkway.", ar: "قطعاً إنقطع، ماء البحر، والعمق العميق، صار مَسلكاً." } },
      { kind: 'hymn', text: { en: "A hidden earth, was shone upon by the sun, and an untrodden road, was walked upon.", ar: "أرض غير ظاهرة، أشرقت الشمس عليها، وطريق غير مسلوكة، مشوا عليها." } },
      { kind: 'hymn', text: { en: "The flowing water, stood still, by a miraculous, act of wonder.", ar: "ماء مُنحل، وقف، بفِعل عجيب، مُعِجز." } },
      { kind: 'hymn', text: { en: "Pharaoh and his chariots, were drowned, and the children of Israel, crossed the sea.", ar: "غرق فرعون، ومركباته، وعبر بنو إسرائيل، البحر." } },
      { kind: 'hymn', text: { en: "And in front of them was, Moses the prophet praising, until he brought them, to the wilderness of Sinai.", ar: "وكان موسى النبي، يسبح قدامهم، حتى أدخلهم، برية سيناء." } },
      { kind: 'hymn', text: { en: "And they were praising God, with this new psalmody, saying \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "وكانوا يسبحون الله، بهذه التسبحة الجديدة قائلين، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "Through the prayers, of Moses the archprophet, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، موسى رئيس الأنبياء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع أبيك الصالح، والروح القدس، لأنك (قُمتأتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Second Hoos", ar: "الهوس الثاني" } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord for He is good, Alleluia His mercy endures forever.", ar: "أُشكروا الرب لأنه صالح وخيِّر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of gods, Alleluia His mercy endures forever.", ar: "أُشكروا إله الآلهة، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords, Alleluia His mercy endures forever.", ar: "أُشكروا رب الأرباب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who alone does great wonders, Alleluia His mercy endures forever.", ar: "الصانع العجائب العظام وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who by wisdom made the heavens, Alleluia His mercy endures forever.", ar: "الذي خلق السموات بفهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who stretched out the earth above the waters, Alleluia His mercy endures forever.", ar: "الذي ثبَّت الأرض على المياه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who made great lights, Alleluia His mercy endures forever.", ar: "الذي خلق نيرين عظيمين وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The sun to rule by day, Alleluia His mercy endures forever.", ar: "الشمس لحكم النهار، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The moon and stars to rule by night, Alleluia His mercy endures forever.", ar: "القمر والنجوم لحكم الليل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote Egypt in their firstborn, Alleluia His mercy endures forever.", ar: "الذي ضرب المصريين مع أبكارهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And brought out Israel from among them, Alleluia His mercy endures forever.", ar: "وأخرج إسرائيل من وسطهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "With a strong hand and with a stretched out arm, Alleluia His mercy endures forever.", ar: "بيد عزيزة وذراع عالية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who divided the Red Sea into parts, Alleluia His mercy endures forever.", ar: "الذي شق البحر الأحمر إلى أقسام، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And made Israel to pass through the midst of it, Alleluia His mercy endures forever.", ar: "وأجاز إسرائيل في وسطه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "But overthrew pharaoh and his hosts in the Red Sea, Alleluia His mercy endures forever.", ar: "وطرح فرعون وكل قوته في البحر الأحمر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who led His people through the wilderness, Alleluia His mercy endures forever.", ar: "الذي أخرج شعبه إلى البرية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who retrieved water from a rock, Alleluia His mercy endures forever.", ar: "الذي أخرج ماء من صخرة صماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote great kings, Alleluia His mercy endures forever.", ar: "الذي ضرب ملوكاً عُظماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And slew famous kings, Alleluia His mercy endures forever.", ar: "وقتل ملوكاً عجيبين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Sihon the king of the Amorites, Alleluia His mercy endures forever.", ar: "سيحون ملك الأموريين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And Og the king of Bashan, Alleluia His mercy endures forever.", ar: "وعوج ملك باشان، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And gave their lands for a heritage, Alleluia His mercy endures forever.", ar: "أعطى أرضهم ميراثاً، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "A heritage unto Israel His servant, Alleluia His mercy endures forever.", ar: "ميراثاً لعبده إسرائيل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who remembered us in our low estate, Alleluia His mercy endures forever.", ar: "في تواضعنا ذكرنا الرب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And has redeemed us from our enemies, Alleluia His mercy endures forever.", ar: "وخلصنا من أيدي أعدائنا، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who gives food to all flesh, Alleluia His mercy endures forever.", ar: "الذي يعطي طعاماً لكل جسد حي، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of heaven, Alleluia His mercy endures forever.", ar: "إحمدوا إله السماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords for He is good, Alleluia His mercy endures forever.", ar: "إحمدوا رب الأرباب لأنه طيب وصالح، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'heading', text: { en: "The Second Hoos Lobsh", ar: "لبش الهوس الثاني" } },
      { kind: 'hymn', text: { en: "Let us give thanks, to Christ our God, with David the prophet, and psalmist.", ar: "فلنشكر، المسيح إلهنا، مع المرتل، داود النبي." } },
      { kind: 'hymn', text: { en: "For He has made the heavens, and all its hosts, and established the earth, on the waters.", ar: "لأنه خلق السموات، وجنودها، وأسَّس الأرض، على المياه." } },
      { kind: 'hymn', text: { en: "These two great stars, the sun and the moon, He has made to enlighten, the firmament.", ar: "هذان الكوكبان العظيمان، الشمس والقمر، جعلهما ينيران، في الفلك." } },
      { kind: 'hymn', text: { en: "He brought forth the winds, out of His treasure box, He breathed unto the trees, and they blossomed.", ar: "أخرج الرياح، من خباياها، نفخ في الأشجار، حتى أزهرت." } },
      { kind: 'hymn', text: { en: "He caused the rain to fall, upon the face of the earth, and it sprouted, and gave its fruit.", ar: "أمطرا مطراً، على وجه الأرض، حتى أنبتت، وأعطت ثمرها." } },
      { kind: 'hymn', text: { en: "He brought forth water, out of a rock, and gave it to His people, in the wilderness.", ar: "أخرج ماء، من صخرة صماء، وسقى شعبه، في البرية." } },
      { kind: 'hymn', text: { en: "He made man, in His image, and His likeness, that he may praise Him.", ar: "صنع الإنسان، كشبهه، وصورته، لكي يباركه." } },
      { kind: 'hymn', text: { en: "Let us praise Him, and exalt His name, and give thanks to Him, His mercy endures forever.", ar: "فلنسبحه، ونرفع إسمه، ونشكره لأن رحمته، كائنة إلى الأبد." } },
      { kind: 'hymn', text: { en: "Through the prayers, of David the psalmist, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، المرتل داود، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله، القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of all the heavenly hosts, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، كل صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Blessed are You indeed, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "مبارك أنت بالحقيقة، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Third Hoos", ar: "الهوس الثالث" } },
      { kind: 'hymn', text: { en: "Blessed are You O Lord God of our fathers, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الرب إله أبائنا، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed is Your holy name and Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك إسم مجدك القدوس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the holy temple of Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في هيكل مجدك المقدس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You who beholds the depths and sits upon the Cherubim, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الناظر إلى الأعماق الجالس على الشاروبيم، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You on the throne of Your kingdom, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت على عرش مُلكك، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the firmament of heaven, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في فلك السماء، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you works of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع أعمال الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السموات، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you angels of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا جميع ملائكة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you waters above the heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع المياه التي فوق السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you powers of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع قوات الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O sun and moon, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها الشمس والقمر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you stars of heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا سائر نجوم السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you rain and dew, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأمطار مع الأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you clouds and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السُحب والرياح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you spirits, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع الأرواح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O fire and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها النار والحرارة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O cold and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والحر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you dew and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأهوية والأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you nights and days, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الليالي والأيام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O light and darkness, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها النور والظلمة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O frost and cold, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والصقيع، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O snow and ice, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها الجليد والثلج، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you lightnings and clouds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البروق والسحب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all the earth, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأرض كلها، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you mountains and all hills, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الجبال وجميع الآكام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you things that spring up on the earth, praise Him and exalt Him above all forever.", ar: "بارك الرب يا جميع ما يَنبت على وجه الأرض، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you fountains, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الينابيع، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you seas and rivers, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البحار والأنهار، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you whales and all that moves in the waters, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الحيتان وجميع ما يتحرك في الماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you birds of the sky, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع طيور السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you wild beasts and cattle, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الوحوش وكل البهائم، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you sons of men, worship the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا بني البشر، وأُسجدوا للرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Israel, praise Him and exalt Him above all forever.", ar: "بارك الرب يا إسرائيل، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you priests of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا كهنة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you servants of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عبيد الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you spirits and souls of the just, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا أرواح وأنفس الصديقين، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you holy and humble of heart, praise Him and exalt Him above all forever.", ar: "باركوا الرب أيها القديسون والمتواضعو القلوب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all\nforever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "The Third Hoos — Esmo Epchois", ar: "الهوس الثالث — إسمو إبشويس" } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "Psali for the Three Saintly Children", ar: "إبصالية للثلاثة فتية القديسين" } },
      { kind: 'hymn', text: { en: "O sing unto Him who was crucified, buried and resurrected, who trampled and abolished death, praise Him and exalt Him above all.\nTake off the old man, and put on the new and superior one, come closer to greatness of mercy, praise Him and exalt Him above all.", ar: "رتلوا للذي صُلب عنا، وقُبر وقام، وأبطل الموت وأهانه، سبحوه وزيدوه علواً.\nإخلعوا الإنسان العتيق، وألبسوا الجديد الفاخر، وإقتربوا إلى عِظَم الرحمة، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "All you Christian people, the priests and the deacons, glorify the Lord for He is worthy, praise Him and exalt Him above all.\nCome to us O three children, whom Christ our God has lifted, and from the Devil has delivered, praise Him and exalt Him above all.", ar: "يا جنس المسيحيين، القسوس والشمامسة، أعطوا مجداً للرب لأنه مستوجب، سبحوه وزيدوه علواً.\nهَلُمَّ إلينا أيها الثلاثة فتية، الذين رفعهم المسيح إلهنا، وأنقذهم من إبليس، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "For the sake of your God the Messiah, the Giver of all good things, come unto us O Hananiah, praise Him and exalt Him above all.\nO Azariah the zealot, morning and noon and the evening, glorify the power of the Trinity, praise Him and exalt Him above all.", ar: "من أجل إلهك ماسيا، المانح الإحسان، هَلُمَّ إلينا يا حنانيا، سبحوه وزيدوه علواً.\nيا عزاريا الغيور، عشية وبكرة والظهيرة، أعط مجداً لقوة الثالوث، سبّحه وزده علواً." } },
      { kind: 'hymn', text: { en: "Behold Emmanuel [our Lord], is now in our midst O Mishael, proclaim with the voice of joy, praise Him and exalt Him above all.\nGather now and persevere, and proclaim with the priests, bless the Lord all His works, praise Him and exalt Him above all.", ar: "فها هوذا عمانوئيل، في وسطنا يا ميصائيل، تكلم بصوت التهليل، سبّحه وزده علواً.\nإجتمعوا وثابروا جميعاً، تكلموا مع القسوس، وسبحي الرب يا جميع أعماله، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "The heavens declare the glory, of God until this day, O you angels whom He has made, praise Him and exalt Him above all.\nNow all you powers of the Lord, bless His honored name, O sun and moon and all the stars, praise Him and exalt Him above all.", ar: "ها السموات تنطق بمجد الله، إلى هذا اليوم، يا أيها الملائكة الذين أنشأهم، سبحوه وزيدوه علواً.\nوالآن يا قوات الرب، باركوا إسمه الكريم، أيتها الشمس والقمر والنجوم، سبحيه وزيديه علواً." } },
      { kind: 'hymn', text: { en: "And also you rain and dew, sing praises unto our Savior, for He is the God of our fathers, praise Him and exalt Him above all.\nGlorify the Lord O clouds and winds, together with the souls and the spirits, O you cold and fire and heat, praise Him and exalt Him above all.", ar: "وأيضاً أيتها الأمطار والأنداء، إمدحي مخلصنا، لأنه هو إله آبائنا، سبحيه وزيديه علواً.\nأعطي مجداً أيتها السحب معاً، والأهوية والنفوس والأرواح، والبرد والنار والحرارة، سبحيه وزيده علوا." } },
      { kind: 'hymn', text: { en: "You also nights and days, light and darkness and lightning, glorify the Lover of Mankind, praise Him and exalt Him above all.\nYou trees and all that springs on the earth, and all that moves in the sea, mountains and the forests, praise Him and exalt Him above all.", ar: "أيتها الليالي والأيام أيضاً، والنور والظلمة والبروق، قائلة المجد لك يا محب البشر، سبحوه وزيدوه علواً.\nأيتها الأشجار وجميع ما ينبُت، في الأرض وكل ما يتحرك، في المياه والجبال والغياض، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Praise without ceasing, the Lord the King of the kings, O you rivers and seas, praise Him and exalt Him above all.\nAnd we also seeing them, let us say with all these things, bless the Lord all you birds, praise Him and exalt Him above all.", ar: "وأيضاً سبحي بغير فتور، الرب ملك الملوك، أيتها البحار والأنهار، سبحيه وزيديه علواً.\nهكذا نحن إذ ننظر إليهم، فلنقل مع هذه الموجودات جميعها، باركي الرب يا جميع الطيور، سبحيه وزيده علواً." } },
      { kind: 'hymn', text: { en: "O snow and ice, cattle and wild beasts, bless the Lord of lords, praise Him and exalt Him above all.\nBless the Lord as befits Him, and not like the heretics, all you sons of men, praise Him and exalt Him above all.", ar: "أيها الجليد والثلج، والبهائم والوحوش، باركي رب الأرباب، سبحيه وزيديه علواً.\nسبحوا الرب كما يليق به، وليس كالمخالفين، يا أبناء البشر، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "O Israel offer before Him, honor and glory in a joyful voice, all you priests of Emmanuel, praise Him and exalt Him above all.\nYou servants of the true God, the souls of the righteous, and the humble and the charitable, praise Him and exalt Him above all.", ar: "مجداً وإكراماً قدم أمامه، يا إسرائيل بصوت التهليل، يا كهنة عمانوئيل، سبحوه وزيدوه علواً.\nيا خدام الله الحقيقي، وأنفس الأبرار، المتواضعين المحبين، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "God my God is the One, who saved you from danger, O Sedrach Misach and Abednago, praise Him and exalt Him above all.\nHurry with great haste, O you righteous of the Lord, and all the creatures He has made, praise Him and exalt Him above all.", ar: "الله إلهي أنا، هو مخلصكم من الخطر، يا سدراك وميساك وأبدناغو، سبحوه وزيدوه علوا.\nأسرعوا بحرص عظيم، يا أتقياء الرب، وكل الطبائع التي صنعها، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Coolness and repose without ceasing, grant unto all of us, that we may joyfully proclaim, praise Him and exalt Him above all.\nAnd also Your poor servant Sarkis, make him without condemnation, that he may join all those and say, praise Him and exalt Him above all.", ar: "برودة ونياحاً أعطنا، كلنا بغير إنقطاع، لنقول بتمتُع، سبحوه وزيدوه علواً.\nكذلك عبدك المسكين سركيس، إجعله بغير دينونة، ليقول مع هؤلاء كشريك، سبحوه وزيدوه علواً." } },
      { kind: 'heading', text: { en: "Ten-oueh Ensok", ar: "تين أويه إنسوك" } },
      { kind: 'hymn', text: { en: "We follow You with all our hearts, and fear You, and we seek Your face, O God do not forsake us.", ar: "نتبعك بكل قلوبنا، ونخافك، ونطلب وجهك، يا الله لا تخزنا." } },
      { kind: 'hymn', text: { en: "But rather deal with us, according to Your meekness, and according to Your great mercy, O Lord help us.", ar: "بل إصنع معنا، بحسب دعتك، وكثرة رحمتك، يا رب أعنَّا." } },
      { kind: 'hymn', text: { en: "May our prayers ascend to You, O our Master, like burnt offerings of lambs, and fat calves.", ar: "فلتصعد صلاتنا، أمامك يا سيدنا، مثل محرقات كباش، وعجول سِمان." } },
      { kind: 'hymn', text: { en: "Do not forget the covenant, which You have made with our fathers, Abraham Isaac and Jacob, Israel Your saint.", ar: "لا تنس العهد الذي، قطعته مع آبائنا، إبراهيم وإسحق ويعقوب، إسرائيل قديسك." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you nations, the tribes and all kinds of tongues, praise Him and glorify Him, above all forever.", ar: "باركوا الرب يا جميع الشعوب، والقبائل ولغات الألسن، سبحوه ومجدوه، وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Pray to the Lord on our behalf, O three saintly children, Sedrach Misach and Abednego, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة فتية القديسين، سدراك وميساك وأبدناغو، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints", ar: "مجمع القديسين" } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the Lady of us all the Mother of God, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، يا سيدتنا كلنا السيدة والدة الإله، مريم أُم مخلصنا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Michael and Gabriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، ميخائيل وغبريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Raphael and Souriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، رافائيل وسوريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Sedakiel Sarathiel and Ananiel, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا رؤساء الملائكة الأطهار، سداكيال وسراتيال وأنانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O thrones dominions and powers, the Cherubim and the Seraphim, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، أيتها الكراسي والأرباب والقوات، والشيروبيم والسرافيم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O four incorporeal beasts, the ministering flames of fire, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها الأربعة الحيوانات غير المتجسدين، الخدام الملتهبين ناراً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O priests of the truth, the twenty four presbyters, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا كهنة الحق، الأربعة والعشرين قسيساً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O angelic hosts, and all the heavenly multitudes, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها العساكر الملائكية، والطغمات السمائية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lords the fathers the patriarchs, Abraham Isaac and Jacob, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء البطاركة، إبراهيم وإسحق ويعقوب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O perfect man, the righteous and just Enoch, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الرجل الكامل، البار أخنوخ الصديق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Elijah the tishbite, and Elisha his disciple, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيليا التسبيتي، وإليشع تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Moses the archprophet, and Isaiah and Jeremiah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا موسى رئيس الأنبياء، وأشعياء وأرميا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O David the psalmist, Ezekiel and Daniel, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا داود المرتل، وحزقيال ودانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Joachim Anna and Joseph the elder, and the righteous Job Joseph and Nicodemus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا يواقيم وحنِّة ويوسف الشيخ، والصديق أيوب ويوسف ونيقوديموس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Melchizedek and Aaron, and Zacharias and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ملكي صادق وهرون، وزكريا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the prophets, and all the righteous and the just, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الأنبياء، والأبرار والصديقين، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O forerunner and baptizer, John the Baptist, that He may forgive us our sins.", ar: "إشفع فينا (أمام الرب)، أيها السابق الصابغ، يوحنا المعمدان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the hundred and forty four thousand, and the celibate evangelist, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها المئة والأربعة والأربعين ألفاً، والبتول الإنجيلي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters and fathers the Apostles, and the rest of the Disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء الرسل، وبقية التلاميذ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O blessed archdeacon, Stephen the first martyr, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا رئيس الشمامسة المبارك، إستفانوس الشهيد الأول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the apostle, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الناظر الإله الإنجيلي، أبا مرقس الرسول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyr, my lord prince George, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الشهيد المجاهد، سيدي الملك جيؤرجيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Theodore and Theodore, Leontius and Panicharus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ثيؤدوروس وثيؤدوروس، ولاونديوس، وبانيكاروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Philopater Mercurius, and Abba Mina and Abba Victor, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا فيلوباتير مرقوريوس، وأبا مينا وأبا بقطر، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Claudius and Theodore, Abba Eschyron and Abba Isaac, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي إقلاديوس وثيئودوروس، وأبا سخيرون وأبا إسحق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basilidis and Evsebius, Macarius and Philotheos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا واسيليدس وأرسابيوس، ومكاريوس وفيلوثيؤوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pisura and Abba Epshoy, Abba Isi and his sister Thecla, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بسورة وأبا بشاي، وأبا إيسي وتكلا أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Justus Apali and Theoklia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يسطس وآبالي وثيؤكليا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Jacob the Persian, Saint Sergius and Saint Bacchus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا يعقوب الفارسي، والقديس سرجيوس وواخس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Cosmas his brothers and their mother, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، قزمان وإخوته وأمهم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Kir and his brother John, and Barbara and Juliana and Demiana, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا قير ويوحنا أخوه، وبربارة ويوليانة ودميانة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, master Apatir and his sister Iraee, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، السيد أبادير وإيرائي أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Julius and those who were with him, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يوليوس ومَن معه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Mari Pahnam and his sister Sarah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، مار بهنام وسارة أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Sarapamon the bishop, Psate and Gallinikos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صرابامون الأسقف، وإبصادي وغلينيكوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, the forty saints of Sebaste, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، الأربعون قديساً بسبسطية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Piro and Athom, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بيروه وأتوم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Abba Bishoy and his friend Peter, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، أيها الشهيدان المجاهدان، أبا بيشوي وصديقه بطرس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Eklog the priest, and Abba Epgol and Abba Kav, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا إكلوج القس، وأبا بيجول وأبا كاڤ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba John of Heraclia, master Piphamon and Pistavros, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا يوحنا الهرقلي، والسيد بفامون وبسطوروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Isidore and Panteleon, Sophia and Euphemia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيسيذوروس وبندلاون، وصوفيا وإفومية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Apanoub and Ptolomeos, Apa Ekragon and Sousennius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي أبانوب وإبطلماوس، وإبا إكراجون وسوسونيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O great high priest, Abba Peter seal of the martyrs, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا رئيس الكهنة العظيم، أنبا بطرس خاتم الشهداء، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O new martyrs, Pistavros and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان الجديدان، بسطوروس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Michael the hegumen, and Michael the monk, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، يا ميخائيل القمص، وميخائيل الراهب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the martyrs, who suffered for the sake of Christ, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الشهداء، الذين تألموا من أجل المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Antony and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا أنطونيوس وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O three saints Macarii, and all their children the cross-bearers, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة مقارات القديسون، وأولادهم لباس الصليب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers the hegumens, Abba John and Abba Daniel, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين القمصين، أنبا يوحنا وأنبا دانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Bishoy and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا بيشوي وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our saintly Roman fathers, Maximus and Dometius, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أبوينا القديسين الروميين، مكسيموس ودوماديوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O forty nine martyrs, the elders of Shiheet, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها التسعة والأربعون شهيداً، شيوخ شيهات، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O strong saint Abba Moses, and John Kame, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، أيها القوي القديس أنبا موسى، ويحنس كاما، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pachomius of the Koinonia, and Theodore his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا باخوم أبا الشركة، وثيودورس تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Shenouda the archimandrite, and Abba Wisa his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا شنودة رئيس المتوحدين، وأنبا ويصا تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Nopher and Abba Karus, and our father Paphnutius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا نفر وأنبا كاروس، وأبانا بفنوتيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Samuel the confessor, and Justus and Apollo his disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صموئيل المعترف، ويسطس وأبوللو تلميذيه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Apollo and Abba Apip, and our father Abba Pigimi, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا أبوللو وأنبا أبيب، وأبانا أنبا بيچيمي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Evkin and Abba Ehron, Abba Hor and Abba Phis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا إڤكين وأنبا إهرون، وأبا هور وأبا فيس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Parsouma and Ephraim, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا برسوما وإفريم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Epiphanius and Ammounios, and Arshillidis and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إبيفانيوس وأمونيوس، وأرشليدس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the ascetic fathers, Abba Abraam and George, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين الناسكين، أنبا أبرآم وجيؤرجي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Athanasius the apostolic, Severus and Dioscorus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أثاناسيوس الرسولي، وساويرس وديسقورس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basil and Gregory, and our father Abba Cyril, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا باسيليوس وإغريغوريوس، وأبانا أنبا كيرلس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the three hundred and eighteen gathered, at Nicea for the faith, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 318 الذين إجتمعوا، في نيقية من أجل الإيمان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O the one hundred and fifty at Constantinople, and the two hundred at Ephesus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 150 بمدينة القسطنطينية، والمائتين بأفسس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Hadid and Abba John, our great father Parsouma and Abba Roweis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا حديد وأنبا يوحنا، وأبانا العظيم أنبا برسوما وأنبا رويس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Abraam the hegumen, and our father Abba Mark, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا أبرآم القمص، وأبانا أنبا مرقس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the cross-bearers, perfected in the wilderness, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا مصاف لباس الصليب، الذين كملوا في البراري، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lord king Constantine, and his mother queen Helen, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الملك قسطنطين، وهيلانة الملكة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O wise virgin ladies, the brides of Christ, that He may forgive us our sins.", ar: "أُطلبنَّ من الرب عنا، أيتها الفتيات العذارى الحكيمات، عرائس المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the saints of this day, everyone according to his name, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا قديسي هذا اليوم، كل واحد بإسمه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Likewise we exalt you, with David the psalmist, \"You are a priest forever, according to the order of Melchizedek.\"", ar: "كذلك نعظمك، مع المرتل داود قائلين، \"أنت هو الكاهن إلى الأبد، على طقس ملكي صادق.\"" } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our holy father the patriarch, Pope Abba Shenouda the high priest, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا أبانا القديس البطريرك، أنبا شنودة رئيس الكهنة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "If a Bishop is present:\nPray to the Lord on our behalf, O our holy and righteous father, Abba (...) the Bishop (Metropolitan), that He may forgive us our sins.", ar: "في حضور الآب الأسقف:\nأطلب من الرب عنا، يا أبينا القديس البار، أنبا (...) الأسقف (المطران)، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Doxology for the Virgin Mary", ar: "ذكصولوجية العذراء مريم" } },
      { kind: 'doxology', text: { en: "Your greatness O Mary, the undefiled Virgin, is likened to the height of the palm tree, spoken of by Solomon.", ar: "عظمتِك يا مريم، العذراء غير الدنسة، تشبه عُلو النخلة التي، تكلم عنها سليمان." } },
      { kind: 'doxology', text: { en: "You are the spring of living water, that flows from Lebanon, for out of you sprang unto us, the grace of the divinity.", ar: "أنتِ ينبوع ماء الحياة، الفائض من لبنان، التي نبعت لنا منه، نعمة اللاهوت." } },
      { kind: 'doxology', text: { en: "You gave birth to Emmanuel, out of your virginal womb, and He has made us heirs, to the kingdom of heaven.", ar: "ولدتِ لنا عمانوئيل، من أحشائِك البتول، وصيرنا وارثين، في ملكوت السموات." } },
      { kind: 'doxology', text: { en: "According to the promise, He promised to our father, King David the patriarch, He came and fulfilled to us.", ar: "كالوعد الذي وعد به، أبانا رئيس الآباء، الذي هو الملك داود، أتى وأكمله لنا." } },
      { kind: 'doxology', text: { en: "Hail to you O Virgin, the very and true Queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدت لنا عمانوئيل." } },
      { kind: 'doxology', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Fourth Hoos", ar: "الهوس الرابع" } },
      { kind: 'hymn', text: { en: "(Psalm 148)", ar: "(المزمور 148)" } },
      { kind: 'hymn', text: { en: "Praise the Lord from the heavens Alleluia. Praise Him in the heights.", ar: "سبحوا الرب من السموات هلليلويا. سبحوه في الأعالي." } },
      { kind: 'hymn', text: { en: "Praise Him all His angels Alleluia. Praise Him all His hosts.", ar: "سبحوه يا جميع ملائكته هلليلويا. سبحوه يا جميع جنوده." } },
      { kind: 'hymn', text: { en: "Praise Him sun and moon Alleluia. Praise Him all you stars of light.", ar: "سبحيه أيتها الشمس والقمر هلليلويا. سبحيه يا جميع كواكب النور." } },
      { kind: 'hymn', text: { en: "Praise Him you heavens of heavens Alleluia. And you waters above the heavens.", ar: "سبحيه يا سماء السموات هلليلويا. ويا أيتها المياه التي فوق السموات." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For He commanded and they were created.", ar: "لتسبح جميعها لإسم الرب هلليلويا. لأنه قال فكانت." } },
      { kind: 'hymn', text: { en: "He has ordered and they were created Alleluia. He has established them forever and ever.", ar: "وأمر فخلقت هلليلويا. أقامها إلى الأبد وإلى أبد الأبد." } },
      { kind: 'hymn', text: { en: "He has made a decree which shall not pass away Alleluia. Praise the Lord from the earth.", ar: "وضع لها أمراً فلن تتجاوزه هلليلويا. سبحي الرب من الأرض." } },
      { kind: 'hymn', text: { en: "You great sea creatures and all the depths Alleluia. Fire and hail, snow and clouds, stormy wind fulfilling His word.", ar: "أيتها التنانين وجميع الأعماق هلليلويا. النار والبرد والثلج والجليد والريح العاصفة الصانعة كلمته." } },
      { kind: 'hymn', text: { en: "Mountains and all hills Alleluia. Fruitful trees and all cedars.", ar: "الجبال العالية وجميع الآكام هلليلويا. الأشجار المثمره وكل الأرز." } },
      { kind: 'hymn', text: { en: "Beasts and all cattle Alleluia. Creeping things and flying birds.", ar: "الوحوش وكل البهائم هلليلويا. الهوام وكل الطيور ذات الأجنحة." } },
      { kind: 'hymn', text: { en: "Kings of the earth and all people Alleluia. Princes and all judges of the earth.", ar: "ملوك الأرض وكل الشعوب هلليلويا. الرؤساء وكل حكام الأرض." } },
      { kind: 'hymn', text: { en: "Both young men and maidens Alleluia. Old men and children.", ar: "الشبان والعذارى هلليلويا. الشيوخ والصبيان." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For His name alone is exalted.", ar: "فليسبحوا جميعاً إسم الرب هلليلويا. لأنه قد تعالى إسمه وحده." } },
      { kind: 'hymn', text: { en: "His glory is above the earth and heaven Alleluia. And He has exalted the horn of His people.", ar: "شكره كائن على الأرض وفي السماء هلليلويا. ويرفع قرن شعبه." } },
      { kind: 'hymn', text: { en: "The praise of all His saints Alleluia. The children of Israel, a people near unto Him.", ar: "سُبحاً لجميع قديسيه هلليلويا. بني إسرائيل، الشعب القريب إليه." } },
      { kind: 'hymn', text: { en: "(Psalm 149)", ar: "(المزمور 149)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Sing to the Lord a new song Alleluia. And His praise in the congregation of the saints.", ar: "إنشدوا للرب نشيداً جديداً هلليلويا. لأن تسبحته في بيعة القديسين." } },
      { kind: 'hymn', text: { en: "Let Israel rejoice in his Maker Alleluia. Let the children of Zion be joyful in their King.", ar: "فليفرح إسرئيل بخالقه هلليلويا. وبنوا صهيون فليتهللوا بملكهم." } },
      { kind: 'hymn', text: { en: "Let them praise His name in a chorus Alleluia. Let them sing praises unto Him with timbrel and harp.", ar: "فليسِّبحوا إسمه القدوس بصفِ هلليلويا. بدف ومزمار فليرتلوا له." } },
      { kind: 'hymn', text: { en: "For the Lord takes pleasure in His people Alleluia. He will raise the meek with salvation.", ar: "لأن الرب يُسر بشعبه هلليلويا. يعلي الودعاء بالخلاص." } },
      { kind: 'hymn', text: { en: "Let the saints be joyful in glory Alleluia. Let them sing aloud upon their beds.", ar: "يفتخر القديسون بمجد هلليلويا. ويتهللون على مضاجعهم." } },
      { kind: 'hymn', text: { en: "Let the high praises of God be in their mouth Alleluia. And a two edged sword in their hands.", ar: "تعليات الله في حناجرهم هلليلويا. وسيوف ذات حدين في أيديهم." } },
      { kind: 'hymn', text: { en: "To execute vengeance on the nations Alleluia. And punishments on the people.", ar: "ليصنعوا نقمة في الأمم هلليلويا. وتوبيخات في الشعوب." } },
      { kind: 'hymn', text: { en: "To bind their kings with chains Alleluia. And their nobles with fetters of iron.", ar: "ليوثقوا ملوكهم بقيود هلليلويا. وإشرافهم بأغلال للأيدي من حديد." } },
      { kind: 'hymn', text: { en: "To execute on them the written judgment Alleluia. This honor have all His saints.", ar: "ليصنعوا بهم حُكماً مكتوباً هلليلويا. هذا المجد كائن في جميع قديسيه." } },
      { kind: 'hymn', text: { en: "(Psalm 150)", ar: "(المزمور 150)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise God in all His saints Alleluia.", ar: "سبحوا الله في جميع قديسيه هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him in the firmament of His power Alleluia.", ar: "سبحوه في جلد قوته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him for His mighty acts Alleluia.", ar: "سبحوه على مقدرته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him according to the multitudes of His greatness Alleluia.", ar: "سبحوه ككثرة عظمته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with the sound of the trumpet Alleluia.", ar: "سبحوه بصوت البوق هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with psaltery and harp Alleluia.", ar: "سبحوه بالمزمار والقيثار هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with timbrel and chorus Alleluia.", ar: "سبحوه بدفوف وصفوف هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with strings and organs Alleluia.", ar: "سبحوه بأوتار وأرغن هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with pleasant sounding cymbals Alleluia.", ar: "سبحوه بصنوج حسنة الصوت هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him upon the cymbals of joy Alleluia.", ar: "سبحوه بصنوج التهليل هلليلويا." } },
      { kind: 'hymn', text: { en: "Let every thing that has breath praise the name of the Lord our God Alleluia.", ar: "كل نسمة فلتسبح إسم الرب الهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son and the Holy Spirit Alleluia.", ar: "المجد للآب والإبن والروح القدس هلليلويا." } },
      { kind: 'hymn', text: { en: "Now and forever and unto the age of all ages Amen Alleluia.", ar: "الآن وكل أوان وإلى دهر الدهور آمين هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory to You, O our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لك يا إلهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory be to our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لإلهنا هلليلويا." } },
      { kind: 'heading', text: { en: "The Wednesday Psali", ar: "إبصالية الأربعاء" } },
      { kind: 'hymn', text: { en: "Let them rejoice and be happy, those who seek the Lord, who are constantly, calling upon His holy name.\nThese are the trees, that David the psalmist spoke about, for they are planted by the rivers of water, bringing forth perfect fruit.", ar: "فليفرح ويتهلل، طالبوا الرب الملازمون، كل حين في تلاوة، إسمه القدوس.\nهؤلاء هم الأشجار التي، تكلم من أجلها المُرتِّل داود، أنها نابتة عند مجاري المياه، تعطي ثمرة كاملة." } },
      { kind: 'hymn', text: { en: "The river of water is our Savior, Jesus Christ our Lord, and the souls of those who abide, in Him will live forever.\nThey teach us in the holy books, the breaths of God, to be merciful to the creation, which He has created.", ar: "مجرى الماء هو مُخلِّصنا، ربنا يسوع المسيح، والملازمون له، تحيا نفوسهم.\nيعلموننا في الكتب المقدسة، أنفاس الله، أن نكون رحومين، على الخليقة التي خلقها." } },
      { kind: 'hymn', text: { en: "And also “Love, will never fail,” as said by the wise, Paul the Apostle.\nThe love that, the holy apostle speaks of, is the name of salvation, of our Lord Jesus Christ.", ar: "وأيضاً \"أن المحبة، لا تسقط أبداً،\" كقول الحكيم، بولس الرسول.\nالمحبة التي تكلم من أجلها، الرسول القديس، أي إسم الخلاص، الذي لربنا يسوع المسيح." } },
      { kind: 'hymn', text: { en: "When we love the name of salvation, of our Lord Jesus Christ, and have mercy upon each other, we fulfill all the law.\nThrough mercy, Abraham was pleased, to host God, and His holy angels.", ar: "إذا ما أحببنا إسم الخلاص، الذي لربنا يسوع المسيح، وصنعنا الرحمة بعضنا مع بعض، نُكمل كل الناموس.\nمن قِبَل الرحمة، سُرَّ إبراهيم، أن يضيف الله، مع ملائكته المقدسين." } },
      { kind: 'hymn', text: { en: "Through mercy, the righteous Lot was saved, from the tribulations, that came upon Sodom.\nThrough mercy, Cornelius was worthy, to be baptized, at the hands of our father Peter.", ar: "من قِبَل الرحمة، خَلُصَ لوط البار، من الشدة الصعبة، التي أتت على سدوم.\nمن قِبَل الرحمة، إستحق كرنيليوس، أن ينال الصبغة، من يدي أبينا بطرس." } },
      { kind: 'hymn', text: { en: "If we are needy, for the money of this world, and we have nothing, to offer as alms.\nYet we truly have, the precious pearl of great price, which is the sweet name full of glory, of our Lord Jesus Christ.", ar: "فإن كنا معوزين، من أموال هذا العالم، وليس لنا شئ، لكي نعطيه صدقة.\nفلنا الجوهرة اللؤلؤة، الكثيرة الثمن، الإسم الحلو المملوء مجداً، الذي لربنا يسوع المسيح." } },
      { kind: 'hymn', text: { en: "When we continue to keep Him, in our inner being, He will make us rich, that we can give to others.\nWe do not ask for, the wealth of this world, but for the salvation of our souls, by calling upon His holy name.", ar: "إذا ما لازمناه، في إنساننا الداخلي، فهو يجعلنا أغنياء، حتى نعطي آخرين.\nليست أموال هذا العالم، الزائل التي نطلبها، بل خلاص نفوسنا، بتلاوة إسمه القدوس." } },
      { kind: 'heading', text: { en: "Introduction to the Watos Theotokias", ar: "مقدمة الثيؤطوكيات الواطس" } },
      { kind: 'hymn', text: { en: "And whenever we sing, let us say tenderly, “O our Lord Jesus Christ, have mercy upon our souls.”", ar: "إذا ما رتلنا، فلنقل بعذوبة، \"يا ربنا يسوع المسيح، إصنع رحمة مع نفوسنا.\"" } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son, and the Holy Spirit, now and forever and unto, the age of all ages Amen.", ar: "المجد للآب والإبن، والروح القدوس، الآن وكل أوان، وإلى دهر الدهور آمين." } },
      { kind: 'heading', text: { en: "The Wednesday Theotokia — Watos", ar: "ثيؤطوكية الأربعاء — واطس" } },
      { kind: 'hymn', text: { en: "The First Part", ar: "القطعة الأولى" } },
      { kind: 'hymn', text: { en: "All the heavenly multitudes, declare your blessedness, for you are the second heaven, upon the earth.", ar: "كل الطغمات السمائية، ينطقون بطوباويتِك، لأنكِ أنتِ هي السماء الثانية، الكائنة على الأرض." } },
      { kind: 'hymn', text: { en: "The door to the East, is the Virgin Mary, the pure bridal chamber, for the pure Bridegroom.", ar: "باب المشارق، هو مريم العذراء، الخدر الطاهر، الذي للختن النقي." } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "The Second Part", ar: "القطعة الثانية" } },
      { kind: 'hymn', text: { en: "They spoke of you with honor, O city of God, for you are the dwelling place, of all the joyful.", ar: "تكلموا بكرامات من أجلِك، يا مدينة الله، لأنك أنتِ مسكن، جميع الفرحين." } },
      { kind: 'hymn', text: { en: "All the kings of the earth, walk in your light, and the nations in your brightness, O Mary the Mother of God.", ar: "كل ملوك الأرض، يسيرون في نورك، والأمم في ضيائكِ، يا مريم أم الله." } },
      { kind: 'hymn', text: { en: "Every generation calls you blessed, and we also worship Him, to whom you gave birth, and we exalt Him.", ar: "تطوِّبِك جميع الأجيال، ونحن نسجد، للذي ولدتِه، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "The Third Part", ar: "القطعة الثالثة" } },
      { kind: 'hymn', text: { en: "You are the light cloud, that has lead us to, the rain of the coming, of the only-begotten God.", ar: "أنتِ هي السحابة الخفيفة، التي دلتنا على، مطر إستعلان، الإله الوحيد." } },
      { kind: 'hymn', text: { en: "The Father created you, and the Holy Spirit came upon you, and the power of the Most High, overshadowed you O Mary.", ar: "الآب صنعِك، والرُّوح القُدُس حلَّ عليكِ، وقوة العلي، ظللتِك يا مريم." } },
      { kind: 'hymn', text: { en: "For you have given birth, to the true Word, the Son of the ever-existing Father, who came and redeemed us from our sins.", ar: "لأنكِ ولدِت، الكلمة الحقيقي، إبن الآب الدائم إلى الأبد، أتى وأنقذنا من خطايانا." } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "The Fourth Part", ar: "القطعة الرابعة" } },
      { kind: 'hymn', text: { en: "Great is the honor, which you are worthy of O Gabriel, the messenger angel, your face beams with joy.", ar: "عظيمة هي الكرامة، التي إستحققتها يا غبريال، الملاك المبشر، ووجهك يتلألأ فرحاً." } },
      { kind: 'hymn', text: { en: "For you announced to us the birth, of God who came to us, and you declared to Mary, the undefiled Virgin.", ar: "أعلنت لنا ميلاد، الله الذي أتى إلينا، وبشرتَ مريم العذراء، غير الدنسة." } },
      { kind: 'hymn', text: { en: "Saying “Hail to you O full of grace, the Lord is with you, you have found grace, the Holy Spirit shall come upon you.", ar: "قائلاً \"إفرحي يا مُمْتلئة نعمة، الربُّ مَعَكِ، لأنكِ وجدتِ نعمة، والرُّوح القُدُس يحل عليكِ.\"" } },
      { kind: 'hymn', text: { en: "The power of the Most High, will overshadow you Mary, you shall give birth to the Holy One, the Savior of the whole world.”", ar: "وقوة العلي، تظللكِ يا مريم، تلدين القدوس، مخلص العالم كله.\"" } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "The Fifth Part", ar: "القطعة الخامسة" } },
      { kind: 'hymn', text: { en: "A virginal feast, today inspires our tongues, to give praise to, Mary the Theotokos.", ar: "عيدٌ بتولي، يدعو لساننا اليوم، لكي نمدح، والدة الإله مريم." } },
      { kind: 'hymn', text: { en: "On account of Him who was born, for us in the city of David, our Savior Jesus, Christ the Lord.", ar: "مِن أجل الذي وُلد لنا، في مدينة داود، مُخلِّصنا يسوع، والمسيح الرب." } },
      { kind: 'hymn', text: { en: "Come all you nations, that we may bless her, for she has become a mother, and a virgin.", ar: "تعالوا يا جميع الشعوب، لنغبطها، لأنها صارت أماً، وعذراء معاً." } },
      { kind: 'hymn', text: { en: "Hail to you O Virgin, the pure and incorrupt one, the Word of the Father, came and took flesh from you.", ar: "السلام لكِ أيتها العذراء، النقية عديمة الفساد، التي كلمة الآب، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "Hail to the chosen vessel, which is without blemish, that is of your true, and perfect virginity.", ar: "السلام للإناء، الذي بغير عيب المختار، الذي لبتوليتِك، الحقيقية الكاملة." } },
      { kind: 'hymn', text: { en: "Hail to the paradise, speaking for Christ, who became the second Adam, for the sake of Adam the first man.", ar: "السلام للفردوس، الناطق للمسيح، الذي صار آدم الثاني، من أجل آدم الإنسان الأول." } },
      { kind: 'hymn', text: { en: "Hail to the uniting place, of the unparted natures, that came together in one place, without ever mingling.", ar: "السلام لمعمل الإتحاد، غير المفترق الذي للطبائع، التي أتت معاً إلى موضع واحد، بغير إختلاط." } },
      { kind: 'hymn', text: { en: "Hail to the bridal chamber, decorated in every way, for the true Bridegroom, who united with humanity.", ar: "السلام للخدر، المُزيَّن بكل نوع، الذي للختن الحقيقي، الذي إتحد بالبشرية." } },
      { kind: 'hymn', text: { en: "Hail to the soul of human nature, likened to the bush, which the fire of His divinity, did not burn any of it.", ar: "السلام للعليقة النفسية، التي للطبيعة، ونار لاهوته، لم تحرق شيئاً منها." } },
      { kind: 'hymn', text: { en: "Hail to the handmaiden and Mother, the Virgin and the heaven, who carried in the flesh, He who sits upon the Cherubim.", ar: "السلام للعبدة والأم، العذراء والسماء، التي حَملت جسدياً، الذي على الشاروبيم." } },
      { kind: 'hymn', text: { en: "For this we rejoice and sing, with the holy angels, and we joyfully proclaim, “Glory to God in the Highest.", ar: "بهذا نفرح ونرتل، مع الملائكة القديسين، بتهليل قائلين، \"المجد لله في الأعالي." } },
      { kind: 'hymn', text: { en: "And on earth peace, goodwill towards men, for He who is glorified forever, was pleased with you.”", ar: "وعلى الأرض السلام، وفي الناس المسرة، لأنه سُرَّ بكِ، الذي له المجد إلى الأبد.\"" } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "The Sixth Part", ar: "القطعة السادسة" } },
      { kind: 'hymn', text: { en: "Great is the honor of Mary, above all the saints, for she was found worthy to receive, God the Word.", ar: "عظيمة هي كرامة مريم، أكثر من جميع القديسين، لأنها إستحقت أن تقبل إليها، الله الكلمة." } },
      { kind: 'hymn', text: { en: "The One feared by the angels, Mary the Virgin, has carried, in her womb.", ar: "مَنْ تخافه الملائكة، حملته، مريم العذراء، في بطنها." } },
      { kind: 'hymn', text: { en: "She is exalted above the Cherubim, more honored than the Seraphim, she became a temple, for the One from the Trinity.", ar: "هي أرفع من الشاروبيم، وأجَّل من السِّرافيم، لأنها صارت هيكلاً، للواحد من الثالوث." } },
      { kind: 'hymn', text: { en: "She is Jerusalem, the city of our God, the joy of all saints, abides in her.", ar: "هذه هي أورشليم، مدينة إلهنا، وفرح جميع القديسين، كائن فيها." } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "The Seventh Part", ar: "القطعة السابعة" } },
      { kind: 'hymn', text: { en: "The Galilee of the Gentiles, who sit in darkness, and in the shadow of death, had the great Light shine to them.", ar: "جليل الأُمم، الجالسون في الظلمة، وظلال الموت، أشرق عليهم النور العظيم." } },
      { kind: 'hymn', text: { en: "God who rests, among His saints, became incarnate of the Virgin, for our salvation.", ar: "الله المستريح، في قديسيه، تجسد من العذراء، لأجل خلاصنا." } },
      { kind: 'hymn', text: { en: "Come behold and be amazed, joyfully sing on account, of this mystery, which was revealed unto us.", ar: "تعالوا أنظروا وتعجبوا، وسبحوا وهللوا، بإبتهاج لهذا السر، الذي ظهر لنا." } },
      { kind: 'hymn', text: { en: "For the Incorporeal was incarnate, and the Word became flesh, the One without beginning began, the Eternal came under time.", ar: "لأن غير المُتجسد تجسَّد، والكلمة تجسَّمت، غير المبتدئ إبتدأ، وغير الزمني صار زمنياً." } },
      { kind: 'hymn', text: { en: "The Incomprehensible has been touched, and the Unseen has been seen, and the Son of the living God, truly became the Son of Man.", ar: "غير المُدرك لمسوه، وغير المرئي رأوه، إبن الله الحي، صار بشرياً بالحقيقة." } },
      { kind: 'hymn', text: { en: "Jesus Christ the same yesterday, today and forever, in one hypostasis, we worship and glorify Him.", ar: "يسوع المسيح هو هو أمس، واليوم وإلى الأبد، بأُقنوم واحد، نسجد له ونمجده." } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'heading', text: { en: "Wednesday Theotokia — Part 7: Ti-galili-a", ar: "ثيؤطوكية الأربعاء — القطعة السابعة: تي جاليليا" } },
      { kind: 'hymn', text: { en: "The Seventh Part", ar: "القطعة السابعة" } },
      { kind: 'hymn', text: { en: "The Galilee of the Gentiles, who sit in darkness, and in the shadow of death, had the great Light shine to them.", ar: "جليل الأُمم، الجالسون في الظلمة، وظلال الموت، أشرق عليهم النور العظيم." } },
      { kind: 'hymn', text: { en: "God who rests, among His saints, became incarnate of the Virgin, for our salvation.", ar: "الله المستريح، في قديسيه، تجسد من العذراء، لأجل خلاصنا." } },
      { kind: 'hymn', text: { en: "Come behold and be amazed, joyfully sing on account, of this mystery, which was revealed unto us.", ar: "تعالوا أنظروا وتعجبوا، وسبحوا وهللوا، بإبتهاج لهذا السر، الذي ظهر لنا." } },
      { kind: 'hymn', text: { en: "For the Incorporeal was incarnate, and the Word became flesh, the One without beginning began, the Eternal came under time.", ar: "لأن غير المُتجسد تجسَّد، والكلمة تجسَّمت، غير المبتدئ إبتدأ، وغير الزمني صار زمنياً." } },
      { kind: 'hymn', text: { en: "The Incomprehensible has been touched, and the Unseen has been seen, and the Son of the living God, truly became the Son of Man.", ar: "غير المُدرك لمسوه، وغير المرئي رأوه، إبن الله الحي، صار بشرياً بالحقيقة." } },
      { kind: 'hymn', text: { en: "Jesus Christ the same yesterday, today and forever, in one hypostasis, we worship and glorify Him.", ar: "يسوع المسيح هو هو أمس، واليوم وإلى الأبد، بأُقنوم واحد، نسجد له ونمجده." } },
      { kind: 'hymn', text: { en: "The Father looked from heaven, and found no one like you, He sent His only-begotten, who came and took flesh from you.", ar: "تطَّلع الآب من السماء، فلم يجد مَنْ يُشبهكِ، أرسل وحيده، أتى وتجسد منكِ." } },
      { kind: 'heading', text: { en: "The Wednesday Theotokia Lobsh", ar: "لبش ثيؤطوكية الأربعاء" } },
      { kind: 'hymn', text: { en: "Ezekiel the prophet, has witnessed saying, “I saw a gate to the East, sealed with a mysterious seal.", ar: "حزقيال النبي، يشهد قائلاً، \"إنني رأيت باباً ناحية المشرق، مختوماً بخاتم عجيب." } },
      { kind: 'hymn', text: { en: "And no one else entered it, but the Lord of powers, He entered and went out, and the gate remained sealed.”", ar: "ولم يدخل فيه أحد، إلا رب القوات، دخل وخرج، وبقى مختوماً على حاله.\"" } },
      { kind: 'hymn', text: { en: "For the gate is the Virgin, who gave birth to our Savior, and after His birth, she remained a virgin.", ar: "الباب هو العذراء، التي ولدت مُخلِّصنا، وقد بقيت عذراء، بعد ولادته." } },
      { kind: 'hymn', text: { en: "Blessed is the Fruit of your womb, O who gave birth to God for the world, so as to redeem us from the hands, of the unmerciful tyrant.", ar: "مباركة هي ثمرتِك، يا مَنْ ولِدت الله إلى العالم، كي ينقذنا من يدي، الظالم غير الرحوم." } },
      { kind: 'hymn', text: { en: "Blessed and perfect are you, O who has found all grace, before the King of glory, our true Lord.", ar: "مباركة أنتِ وكاملة، يا مَنْ وجدِت كل نعمة، أمام ملك المجد، إلهنا الحقيقي." } },
      { kind: 'hymn', text: { en: "You deserved all honor, more than any one on earth, for the Word of the Father, came and was incarnate of you.", ar: "إستحققتِ كل كرامة، أكثر من كل مَنْ على الأرض، لأن كلمة الآب، أتى وتجسد منكِ." } },
      { kind: 'hymn', text: { en: "And He walked among men, as a compassionate Lover of Man, that He may save our souls, through His holy appearance.", ar: "ومشى مع الناس، كرؤوف ومحب للبشر، حتى خلَّص نفوسنا، بظهوره المقدس." } },
      { kind: 'hymn', text: { en: "Let us worship our Savior, the good Lover of Mankind, for He had compassion upon us, as He came and saved us.", ar: "فلنسجد لمُخلِّصنا، محب البشر الصالح، لأنه ترأف علينا، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "Hail to you O Virgin, the very and true queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدتِ لنا عمانوئيل." } },
      { kind: 'hymn', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألِك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Introduction to the Difnar — Watos", ar: "مقدمة الدفنار — واطس" } },
      { kind: 'hymn', text: { en: "We worship the good Father, and His Son Jesus Christ, and the Spirit of comfort, the holy and coessential Trinity.", ar: "نسجد للآب الصالح، ويسوع المسيح إبنه، والروح المعزي، الثالوث القدوس المساوي." } },
      { kind: 'hymn', text: { en: "Hail to you O Virgin, the very and true queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدتِ لنا عمانوئيل." } },
      { kind: 'hymn', text: { en: "We have hope, in Saint Mary, that God will have mercy upon us, through her intercessions.", ar: "لنا رجاء، في القديسة مريم، أن الله يرحمنا، بشفاعاتها." } },
      { kind: 'hymn', text: { en: "All calmness, in the world, is through the prayers, of the holy Theotokos, Saint Mary the Virgin.", ar: "كل هدوء، في العالم، من قبل صلاة، والدة الإله الطاهرة، القديسة مريم العذراء." } },
      { kind: 'heading', text: { en: "Conclusion of the Watos Theotokias", ar: "ختام الثيؤطوكيات الواطس" } },
      { kind: 'prayer', text: { en: "O our Lord Jesus Christ, who carries the sin of the world, count us with Your sheep, those who are to Your right.", ar: "يا ربنا يسوع المسيح، حامل خطية العالم، أحسبنا مع خرافك، الذين عن يمينِك." } },
      { kind: 'prayer', text: { en: "And when You come again, in Your second fearful appearance, may we never fearfully hear, You say I do not know you.", ar: "عند ظهورِك الثاني، المخوف لا نسمع، برعدةٍ \"أنَّنِي، لَستُ أعرفكم.\"" } },
      { kind: 'prayer', text: { en: "But rather may we be made worthy, to hear the voice full of joy, of Your tender mercies, proclaiming and saying.", ar: "بَل نكون مُستحقين، لسماع صوتك الحنون، المُمْتلئ فرحاً، يصرخ قائلاً." } },
      { kind: 'prayer', text: { en: "“Come unto Me, O blessed of My Father, and inherit the life, that endures forever.”", ar: "\"تعالوا إليَّ، يا مُبارَكي أبي، رثوا الحياة، الدائمة إلى الأبد.\"" } },
      { kind: 'prayer', text: { en: "The martyrs will come, bearing their afflictions, and the righteous will come, bearing their virtues.", ar: "يأتي الشهداء، حاملين عذاباتهم، ويأتي الصدِّيقون، حاملين فضائلهم." } },
      { kind: 'prayer', text: { en: "The Son of God shall come in His glory, and His Father’s glory, to give unto everyone, according to his deeds which he has done.", ar: "يأتي إبن الله، في مجده ومجد أبيه، ويُجازي كل واحدٍ، كأعماله التي عملها." } },
      { kind: 'prayer', text: { en: "O Christ the Word of the Father, the only-begotten God, grant us Your peace, that is full of joy.", ar: "أيها المسيح كلمة الآب، الإله الوحيد الجنس، أعطنا سلامك، المملوء فرحاً." } },
      { kind: 'prayer', text: { en: "As You have given, to Your saintly Apostles, likewise also say to us, “My peace I give to You.", ar: "كما أعطيته، لرُسُلِكَ القديسين، قُلْ لنا مِثلهم، \"إنِّي أعطيكم سلامي." } },
      { kind: 'prayer', text: { en: "My peace which I have taken, from My Father, I leave unto you, both now and forever.”", ar: "سلامي أنا، الذي أخذته من أبي، أنا أتركه معكم، من الأن وإلى الأبد.\"" } },
      { kind: 'prayer', text: { en: "O the angel of this day, flying up with this hymn, remember us before the Lord, that He may forgive us our sins.", ar: "يا ملاك هذا اليوم الطائر، إلى العلو بهذه التسبحة، أُذكرنا أمام الرب، ليغفر لنا خطايانا." } },
      { kind: 'prayer', text: { en: "The sick heal them, those who have slept O Lord repose them, and all of our brothers in distress, help us my Lord and all of them.", ar: "المرضى أشفهم، الذين رقدوا يا رب نَيِّحهم، وأخواتنا الذين في كل شدة، يا ربي أعنا وإيَّاهم." } },
      { kind: 'prayer', text: { en: "May God bless us, and let us bless His holy name, and may His praise continually be, always upon our mouths.", ar: "يُبارِكنا الله، ولنُبارِك إسمه القدوس، في كل حين تسبحته، دائمة في أفواهنا." } },
      { kind: 'prayer', text: { en: "For blessed is the Father, the Son and the Holy Spirit, the perfect Trinity, we worship Him and glorify Him.", ar: "مُبارَك الآب والإبن، والرُّوح القُدُس، الثالوث الكامل، نسجد له ونُمجِّدهُ." } },
      { kind: 'heading', text: { en: "The Concluding Litany", ar: "طلبة الختام" } },
      { kind: 'litany', text: { en: "Kerie leysoun (Lord have mercy) is said three times before every part", ar: "يقال كيريي ليسون (يا رب إرحم) ثلاث مرات قبل كل ربع" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." } },
      { kind: 'litany', text: { en: "Kerie leysoun (3).", ar: "كيريي ليسون (3)." } },
      { kind: 'litany', text: { en: "O God have mercy on us.", ar: "يا الله إرحمنا." } },
      { kind: 'litany', text: { en: "O God hear us.", ar: "يا الله إسمعنا." } },
      { kind: 'litany', text: { en: "O God look to us.", ar: "يا الله أُنظر إلينا." } },
      { kind: 'litany', text: { en: "O God behold us.", ar: "يا الله إطَّلع علينا." } },
      { kind: 'litany', text: { en: "O God have compassion on us.", ar: "يا الله تراءف علينا." } },
      { kind: 'litany', text: { en: "We are Your people.", ar: "نحن شعبك." } },
      { kind: 'litany', text: { en: "We are Your creation.", ar: "نحن جبلتك." } },
      { kind: 'litany', text: { en: "Deliver us from our enemies.", ar: "نجنا من أعدائنا." } },
      { kind: 'litany', text: { en: "Deliver us from inflation.", ar: "نجنا من الغلاء." } },
      { kind: 'litany', text: { en: "We are Your servants.", ar: "نحن عبيدك." } },
      { kind: 'litany', text: { en: "You are the Son of God.", ar: "أنت إبن الله." } },
      { kind: 'litany', text: { en: "We believe in You.", ar: "آمنا بك." } },
      { kind: 'litany', text: { en: "For You have (risen/come) and saved us.", ar: "لأنك (قُمت/أتيت) وخلَّصتنا." } },
      { kind: 'litany', text: { en: "Visit us with Your salvation.", ar: "تعهدنا بخلاصك." } },
      { kind: 'litany', text: { en: "And forgive us our sins.", ar: "وإغفر لنا خطايانا." } },
      { kind: 'litany', text: { en: "Kerie leysoun.", ar: "كيريي ليسون." } },
      { kind: 'heading', text: { en: "The Morning Doxology", ar: "ذكصولوجية باكر" } },
      { kind: 'doxology', text: { en: "We worship the Father and the Son, and the Holy Spirit, hail to the church, the house of the angels.", ar: "نسجد للآب والإبن، والروح القدس، السلام للكنيسة، بيت الملائكة." } },
      { kind: 'doxology', text: { en: "Hail to the Virgin, who gave birth to our Savior, hail to Gabriel, who announced to her the good news.", ar: "السلام للعذراء، التي ولدت مخلصنا، السلام لغبريال، الذي بشرها." } },
      { kind: 'doxology', text: { en: "Hail to Michael, the archangel, hail to the twenty four, presbyters.", ar: "السلام لميخائيل، رئيس الملائكة، السلام للأربعة والعشرين، قسيساً." } },
      { kind: 'doxology', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the hosts, of the heavens.", ar: "السلام للشاروبيم، السلام للسارافيم، السلام لجميع الطغمات، السمائية." } },
      { kind: 'doxology', text: { en: "Hail to John, the great forerunner, hail to the, twelve Apostles.", ar: "السلام ليوحنا، السابق العظيم، السلام للإثنى عشر، رسولاً." } },
      { kind: 'doxology', text: { en: "Hail to our father Mark, the Evangelist, the destroyer, of the idols.", ar: "السلام لأبينا مرقس، الإنجيلي، مُبَدِد، الأوثان." } },
      { kind: 'doxology', text: { en: "Hail to Stephen, the first martyr, hail to George, the morning star.", ar: "السلام لإستفانوس، الشهيد الأول، السلام لجرجس، كوكب الصبح." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the martyrs, hail to Abba Antony, and the three Macarii.", ar: "السلام لجميع صفوف، الشهداء، السلام لأنبا أنطونيوس، والثلاثة المقارات." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the cross-bearers, hail to all the saints, who have pleased the Lord.", ar: "السلام لجميع صفوف، لُباس الصليب، السلام لجميع القديسين، الذين أرضوا الرب." } },
      { kind: 'doxology', text: { en: "Through their prayers, O Christ our King, have mercy upon us, in Your kingdom.", ar: "أيها المسيح ملكنا، بصلواتهم، إصنع معنا رحمة، في ملكوتك." } },
      { kind: 'doxology', text: { en: "(For Our Lord Jesus Christ)", ar: "(لأجل ربنا يسوع المسيح)" } },
      { kind: 'doxology', text: { en: "O true Light, that gives light, to every man, that comes into the world.", ar: "أيها النور الحقيقي، الذي يضئ، لكل إنسان، آتٍ إلى العالم." } },
      { kind: 'doxology', text: { en: "You came into the world, through Your love for man, and all the creation, rejoiced at Your coming.", ar: "أتيت إلى العالم، بمحبتك للبشر، وكل الخليقة، تهللت بمجيئك." } },
      { kind: 'doxology', text: { en: "You have saved Adam, from seduction, and delivered Eve, from the pangs of death.", ar: "خلصَّت آدم، من الغواية، وعتقت حواء، من طلقات الموت." } },
      { kind: 'doxology', text: { en: "You gave unto us, the Spirit of sonship, we praise and bless You, with Your angels.", ar: "أعطيتنا، روح النبوة، نسبحك ونباركك، مع ملائكتك." } },
      { kind: 'doxology', text: { en: "When the morning hour, comes upon us, O Christ our God, the true Light.", ar: "عندما يدخل، وقت باكر إلينا، أيها المسيح إلهنا، النور الحقيقي." } },
      { kind: 'doxology', text: { en: "Let the thought of light, shine within us, and do not let the darkness, of pain cover us.", ar: "فلتشرق فينا، حواس النور، ولا تغطينا، ظلمة الآلام." } },
      { kind: 'doxology', text: { en: "That we may praise You, with understanding, proclaiming and saying, with David.", ar: "لكي نسبحك، عقلياً، مع داود، صارخين، نحوك قائلين." } },
      { kind: 'doxology', text: { en: "\"My eyes have reached, the morning watch, that I may meditate, upon all Your words.\"", ar: "\"سبق أن بلغت، عيناي وقت السحر، لأتلو، جميع أقوالك.\"" } },
      { kind: 'doxology', text: { en: "Hear our voices, according to Your great mercy, save us O Lord our God, according to Your compassion.", ar: "إسمع صوتنا، كعظيم رحمتك، ونجنا أيها الرب إلهنا، حسب رأفاتك." } },
      { kind: 'doxology', text: { en: "O caring God, the Maker of all good things, who governs well, with His chosen ones.", ar: "يا الله المُهْتم، صانع الخيرات، مُدبر مُختاريه، حسناً." } },
      { kind: 'doxology', text: { en: "The strong Governor for those, who take refuge in Him, who longs for the salvation, and deliverance of everyone.", ar: "المدبر القوي، للملتجئين، المتشوق لخلاص، ونجاة كل أحد." } },
      { kind: 'doxology', text: { en: "Through Your goodness, You provided us the night, grant us to pass, this day without sin.", ar: "بصلاحك هيأت، لنا الليل، أنعم لنا بهذا اليوم، ونحن بغير خطية." } },
      { kind: 'doxology', text: { en: "That we may be worthy, to lift up our hands, before You without anger, or evil thoughts.", ar: "لنستحق أن نرفع، أيدينا إليك، أمامك بغير غضب، ولا فكر ردئ." } },
      { kind: 'doxology', text: { en: "At this dawn, make straight our coming in, and our going out, in the joy of Your protection.", ar: "في هذا السحر، سهل طرقنا، الداخلية والخارجية، بسترك المفرح." } },
      { kind: 'doxology', text: { en: "That we may proclaim, Your righteousness daily, and praise Your power, with David the prophet.", ar: "لننطق بعدلك، كل يوم، ونمجد قوتك، مع داود النبي." } },
      { kind: 'doxology', text: { en: "Saying \"In Your peace, O Christ our Savior, we slept and arose, for we have hoped in You.", ar: "قائلين \"بسلامك، أيها المسيح مخلصنا، رقدنا وقمنا، لأننا توكلنا عليك." } },
      { kind: 'doxology', text: { en: "Behold how beneficent, and how pleasant, it is for brethren, to dwell together in unity.\"", ar: "ها ما هو الحسن، وما هو الحلو، إلا إتفاق إخوة، ساكنين معاً.\"" } },
      { kind: 'doxology', text: { en: "United, in the true, evangelic love, like the Apostles.", ar: "مُتفقين، بمحبة حقيقية، إنجيلية، كمثل الرسل." } },
      { kind: 'doxology', text: { en: "It is like the fragrant oil, on the head of Christ, running down the beard, down to the feet.", ar: "مثل الطيب، على رأس المسيح، النازل على اللحية، إلى أسفل الرجلين." } },
      { kind: 'doxology', text: { en: "That anoints every day, the elders, the children and young men, and the deacons.", ar: "يمسح كل يوم، الشيوخ، والصبيان والفتيات، والخدام." } },
      { kind: 'doxology', text: { en: "Those whom the Holy Spirit, has attuned together, as a stringed instrument, always blessing God.", ar: "هؤلاء الذين، ألَّفهم الروح القدس معاً، مثل قيثارة مُسبحين، الله كل حين." } },
      { kind: 'doxology', text: { en: "By psalms and hymns, and spiritual songs, by day and by night, with an incessant heart.", ar: "بمزامير وتسابيح، وترانيم روحية، النهار والليل، بقلب لا يفتر." } },
      { kind: 'doxology', text: { en: "(For the Virgin)", ar: "(لأجل العذراء)" } },
      { kind: 'doxology', text: { en: "You are the Mother of the Light, the honored Mother of God, you have carried, the Uncircumscript Logos.", ar: "أنتِ يا أم النور، المكرمة والدة الإله، حملتِ الكلمة، غير المحوي." } },
      { kind: 'doxology', text: { en: "After you gave birth to Him, you remained a virgin, with praises and blessings, we magnify you.", ar: "ومن بعد أن ولدتِه، بقيتِ عذراء، نعظمكِ بتسابيح، وبركات." } },
      { kind: 'doxology', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والروح القدس، آتى وخلصنا." } },
      { kind: 'doxology', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً، نطلب أن نفوز، برحمة بشفاعاتك، لدى محب البشر." } },
      { kind: 'doxology', text: { en: "The select incense, of your virginity, ascended to the throne, of the Father.", ar: "البخور المختار، الذي لبتوليتك، صعد إلى، كرسي الآب." } },
      { kind: 'doxology', text: { en: "Better than the incense, of the Cherubim, and the Seraphim, O Virgin Mary.", ar: "أفضل من بخور، الشاروبيم، والسارافيم، يا مريم العذراء." } },
      { kind: 'doxology', text: { en: "Hail to the new heaven, whom the Father has created, and made a place of rest, for His beloved Son.", ar: "السلام للسماء الجديدة، التي صنعها الآب، وجعلها موضع راحة، لإبنه الحبيب." } },
      { kind: 'doxology', text: { en: "Hail to the royal throne, of Him who is, carried by, the Cherubim.", ar: "السلام للكرسي، الملوكي، الذي للمحمول، على الشاروبيم." } },
      { kind: 'doxology', text: { en: "Hail to the advocate, of our souls, you are indeed, the pride of our race.", ar: "السلام لشفيعة، نفوسنا، أنت بالحقيقة، فخر جنسنا." } },
      { kind: 'doxology', text: { en: "Intercede on our behalf, O full of grace, before our Savior, our Lord Jesus Christ.", ar: "إشفعي فينا، يا ممتلئة نعمة، أمام مخلصنا، ربنا يسوع المسيح." } },
      { kind: 'doxology', text: { en: "That He may confirm us, in the upright faith, and grant us the forgiveness, of our sins.", ar: "لكي يثبتنا، في الإيمان المستقيم، وينعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Angels)", ar: "(لأجل الملائكة)" } },
      { kind: 'doxology', text: { en: "Thousands of thousands, and myriads of myriads, of archangels, and holy angels.", ar: "ألوف ألوف، وربوات ربوات، رؤساء ملائكة، وملائكة مُقدسيين." } },
      { kind: 'doxology', text: { en: "They stand before, the throne, of the Pantocrator, proclaiming and saying.", ar: "وقوف أمام، كرسي، ضابط الكل، صارخين قائلين:" } },
      { kind: 'doxology', text: { en: "\"Holy holy, holy in truth, the glory and the honor, befit the Trinity.\"", ar: "\"قدوس قدوس، قدوس بالحقيقة، المجد والكرامة، يليقان بالثالوث.\"" } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the whole choir of the angels, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، جميع صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Apostles)", ar: "(لأجل الرسل)" } },
      { kind: 'doxology', text: { en: "Our fathers the Apostles, preached unto the nations, the Gospel, of Jesus Christ.", ar: "آباؤنا الرسل، بشروا في الأمم، بإنجيل، يسوع المسيح." } },
      { kind: 'doxology', text: { en: "Their voices went forth, into all the earth, and their words have reached, the ends of the world.", ar: "خرجت أصواتهم، إلى الأرض كلها، وبلغ كلامهم، إلى أقطار المسكونة." } },
      { kind: 'doxology', text: { en: "Through the prayers, of my masters the fathers the Apostles, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، سادتي الآباء الرسل، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Martyrs)", ar: "(لأجل الشهداء)" } },
      { kind: 'doxology', text: { en: "Unfading crowns, the Lord has placed, upon the whole choir, of the martyrs.", ar: "أكاليل غير مضمحلة، جعلها الرب، على جميع، صفوف الشهداء." } },
      { kind: 'doxology', text: { en: "He saved and delivered them, because they took refuge in Him, they celebrated with Him, in His kingdom.", ar: "أنقذهم وخلصهم، لأنهم إلتجأوا إليه، وعيدوا معه، في ملكوته." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the martyrs, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، جميع صفوف الشهداء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Saints)", ar: "(لأجل القديسين)" } },
      { kind: 'doxology', text: { en: "Your saints bless You, and they speak, of the glory, of Your kingdom.", ar: "قديسوك، يباركونك، وينطقون بمجد، ملكوتك." } },
      { kind: 'doxology', text: { en: "Your kingdom O my God, is an eternal kingdom, and Your Lordship, is unto all ages.", ar: "ملكوتك يا إلهي، ملكوت أبدي، وربوبيتك، إلى كل الأجيال." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the cross-bearers, the righteous and the just, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، كافة مصاف لابسي الصليب، والأبرار والصديقين، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Patriarchs and the Prophets)", ar: "(لأجل الآباء والأنبياء)" } },
      { kind: 'doxology', text: { en: "Hail to Elijah, the prophet of temperance, and Elisha, his elect disciple.", ar: "السلام لإيليا، النبي المتعفف، وإليشع، تلميذه المختار." } },
      { kind: 'doxology', text: { en: "The great Evangelist, of the land of Egypt, Mark the Apostle, the first prelate.", ar: "المبشر العظيم، في كورة مصر، مرقس الرسول، مدبرها الأول." } },
      { kind: 'doxology', text: { en: "You are the Mother of God, O Virgin Mary, ask Him on our behalf, to have mercy upon our race.", ar: "أنت هي أم الله، يا مريم العذراء، أُطلبي منه عنا، أن يرحم جنسنا." } },
      { kind: 'doxology', text: { en: "The great patriarch, our father Abba Severus, whose holy teachings, enlightened our minds.", ar: "البطريرك العظيم، أبونا أنبا ساويرس، الذي أنارت تعاليمه، المقدسة عقولنا." } },
      { kind: 'doxology', text: { en: "Our father the confessor, Abba Dioscorus, defended the faith, against the heretics.", ar: "أبونا المعترف، أنبا ديسقوروس، حارب عن الإيمان، ضد الهراطقة." } },
      { kind: 'doxology', text: { en: "And all of our fathers, who have pleased the Lord, may their holy blessings, be a guard unto us.", ar: "وكل آبائنا، الذين أرضوا الرب، بركتهم المقدسة، تكون لنا حارساً." } },
      { kind: 'doxology', text: { en: "Through their prayers, O God grant us, the forgiveness of our sins, and give us peace.", ar: "بصلواتهم، إنعم لنا يا الله، بمغفرة خطايانا، وأعطنا سلاماً." } }
    ],
  },
  {
    id: "psalmody-midnight-thursday",
    title: { en: "Thursday Midnight Praises", ar: "تسبحة نصف الليل ليوم الخميس" },
    blocks: [
      { kind: 'note', text: { en: "The complete fixed annual Thursday (Watos) Midnight Psalmody.", ar: "النصوص الثابتة الكاملة للإبصلمودية السنوية لنصف الليل ليوم الخميس (واطس)." } },
      { kind: 'heading', text: { en: "Ten-theno", ar: "تين ثينو" } },
      { kind: 'prayer', text: { en: "Arise O children of the light, let us praise the Lord of hosts.", ar: "قوموا يا بني النور، لنسبح رب القوات." } },
      { kind: 'prayer', text: { en: "That He may grant us the salvation of our souls.", ar: "لكي ينعم لنا بخلاص نفوسنا." } },
      { kind: 'prayer', text: { en: "Whenever we stand before You in the flesh.", ar: "عندما نقف أمامك جسدياً." } },
      { kind: 'prayer', text: { en: "Cast away from our minds the slumber of sleep.", ar: "إنزع عن عقولنا نوم الغفلة." } },
      { kind: 'prayer', text: { en: "Grant us sobriety O Lord, that we may know how to stand before You at times of prayer.", ar: "أعطنا يا رب يقظة، لكي نفهم أن نقف أمامك وقت الصلاة." } },
      { kind: 'prayer', text: { en: "And ascribe unto You the befitting glorification, and win the forgiveness of our many sins. Glory be to You O Lover of Mankind.", ar: "ونرسل لك إلى فوق التمجيد اللائق، ونفوز بغفران خطايانا الكثيرة. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Behold bless the Lord all you servants of the Lord. Glory be to You O Lover of Mankind.", ar: "ها باركوا الرب يا عبيد الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "You who stand in the house of the Lord, in the courts of the house of our God. Glory be to You O Lover of Mankind.", ar: "القائمين في بيت الرب، في ديار بيت إلهنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "By night lift up your hands O you saints and bless the Lord. Glory be to You O Lover of Mankind.", ar: "بالليالي إرفعوا أيديكم إلى فوق أيها القديسون باركوا الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "The Lord bless you from Zion, who created heaven and earth. Glory be to You O Lover of Mankind.", ar: "يباركك الرب من صهيون، الذي خلق السماء والأرض. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my cry come before You O Lord, give me understanding according to Your word. Glory be to You O Lover of Mankind.", ar: "فلتدن وسيلتي قدامك يا رب، كقولك فهمني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my supplication come before You, deliver me according to Your word. Glory be to You O Lover of Mankind.", ar: "ليدخل إبتهالي أمامك، ككلمتك أحيني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My lips shall overflow with praise, when You have taught me Your statutes. Glory be to You O Lover of Mankind.", ar: "تفيض شفتاي السُبح، إذا ما علمتني حقوقك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My tongue shall speak of Your words for all Your commandments are righteous. Glory be to You O Lover of Mankind.", ar: "لساني يجيب بأقوالك لأن جميع وصاياك هي حق. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let Your hand help me for I have chosen Your precepts. Glory be to You O Lover of Mankind.", ar: "لتكن يدك لتخلصني لأني إشتهيت وصاياك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have longed for Your salvation O Lord, and Your Law is my delight. Glory be to You O Lover of Mankind.", ar: "إشتقت إلى خلاصك يا رب، وناموسك هو تلاوتي. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my soul live and it shall praise You, and let Your judgments help me. Glory be to You O Lover of Mankind.", ar: "تحيا نفسي وتسبحك، وأحكامك تعينني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have gone astray like a lost sheep, seek Your servant for I do not forget Your commandments. Glory be to You O Lover of Mankind.", ar: "ضللت مثل الخروف الضال، فأُطلب عبدك لأني لوصاياك لم أنس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Now and forever and unto the age of all ages Amen. Glory be to You O Lover of Mankind.", ar: "الآن وكل أوان وإلى دهر الدهور آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit, now and forever and unto all the ages Amen. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس منذ الآن وإلى أبد الأبدين كلها آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O good One the Lover of Mankind, glory be to Your Mother the Virgin and all Your saints. Glory be to You O Lover of Mankind.", ar: "المجد لك يا محب البشر الصالح، المجد لأُمك العذراء وجميع قديسيك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O only-begotten One, O holy Trinity have mercy upon us. Glory be to You O Lover of Mankind.", ar: "المجد لك أيها الوحيد، أيها الثالوث القدوس إرحمنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let God arise and let all His enemies be scattered and let all that hate His holy name flee from before His face. Glory be to You O Lover of Mankind.", ar: "ليقم الله ولتتبدَّد جميع أعدائه وليهرب من قدام وجهه كل مُبغضي إسمه القدوس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "As for Your people let them be blessed, a thousand thousand fold and ten thousand ten thousand fold, doing Your will.", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادتك." } },
      { kind: 'prayer', text: { en: "O Lord open my lips, and my mouth shall declare Your praise.", ar: "يا رب إفتح شفتيَ ولينطق فمي بتسبحتك." } },
      { kind: 'heading', text: { en: "The First Hoos", ar: "الهوس الأول" } },
      { kind: 'hymn', text: { en: "Then Moses and the children of Israel sang this song to the Lord and spoke saying, \"I will sing to the Lord for He has triumphed gloriously.\"", ar: "حينئذ سبح موسى وبنو إسرائيل بهذه التسبحة للرب وقالوا، \"فلنسبح للرب لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider He has thrown into the sea. The Lord is my strength and song, and He has become my salvation.", ar: "الفَرس وراكبه طرحهما في البحر. مُعيني وساتري، صار لي خلاصاً." } },
      { kind: 'hymn', text: { en: "He is my God and I will glorify Him, my father´s God and I will exalt Him.", ar: "هذا هو إلهي فأمجده، إله أبي فأرفعه." } },
      { kind: 'hymn', text: { en: "The Lord is a Man of war, the Lord is His name. Pharaoh's chariots and his army He has cast into the sea.", ar: "الرب مكسر الحروب، الرب إسمه. مركبات فرعون وكل قوته طرحهما في البحر." } },
      { kind: 'hymn', text: { en: "His chosen captains also are drowned in the Red Sea.", ar: "ركباناً منتخبين ذي ثلاث جنبات غرقهم في البحر الأحمر." } },
      { kind: 'hymn', text: { en: "The depths have covered them; they sank to the bottom as a stone.", ar: "غطاهم الماء، إنغمسوا إلى العمق مثل الحجر." } },
      { kind: 'hymn', text: { en: "Your right hand O Lord has become glorious in power. Your right hand O Lord has dashed the enemy in pieces.", ar: "يمينك يا رب تمجدت بالقوة. يدك اليمنى يا إلهي أهلكت أعداءك." } },
      { kind: 'hymn', text: { en: "And in the greatness of Your excellence, You have overthrown those who rose up against You, You sent forth Your wrath, it consumed them like stubble.", ar: "بكثرة مجدك، سحقت الذين يقاوموننا، أرسلت غضبك، فأكلهم مثل الهشيم." } },
      { kind: 'hymn', text: { en: "And with the blast of Your nostrils the waters were gathered together, the flood stood upright like a wall, and the depths were congealed in the heart of the sea.", ar: "وبروح غضبك وقف الماء، وإرتفعت الماء مثل السور، وجمدت الأمواج في وسط البحر." } },
      { kind: 'hymn', text: { en: "The enemy said, \"I will pursue, I will overtake, I will divide the spoil, my lust shall be satisfied upon them, I will draw my sword and my hand shall destroy them.\"", ar: "قال العدو، \"إني أسرع فأدرك، وأقسم الغنائم، وأشبع نفسي، وأقتل بسيفي ويدي تتسلط.\"" } },
      { kind: 'hymn', text: { en: "You blew with Your wind, the sea covered them, they sank like lead in the mighty waters.", ar: "أرسلت روحك، فغطاهم البحر، وغطسوا إلى أسفل كالرصاص في مياه كثيرة." } },
      { kind: 'hymn', text: { en: "Who is like You O Lord among the gods? Who is like You, glorified in His saints, amazing in glory, performing wonders.", ar: "من يشبهك في الآلهة. يا رب من يشبهك، مُمجداً في قديسيك، متعجباً منك بالمجد، صانعاً عجائب." } },
      { kind: 'hymn', text: { en: "You stretched out Your right hand, the earth swallowed them. You in Your mercy have led forth the people whom You have redeemed, You have guided them in Your strength, to Your holy habitation.", ar: "مددت يمينك فإبتلعتهم الأرض. هديت شعبك بالحقيقة، هذا الذي إخترته، وقويته بتعزيتك، إلى موضع راحة قدسك." } },
      { kind: 'hymn', text: { en: "The people will hear and be afraid, sorrow will take hold of the inhabitants of Palestine.", ar: "سمعت الأمم وغضبت، والمخاض أخذ سكان فلسطين." } },
      { kind: 'hymn', text: { en: "Then the dukes of Edom will be amazed, the mighty men of Moab trembling will take hold of them.", ar: "حينئذ أسرع وُلاة أدوم، ورؤساء المؤابيين أخذتهم الرعدة." } },
      { kind: 'hymn', text: { en: "All the inhabitants of Canaan will melt away, fear and dread will fall on them.", ar: "ذاب كل سكان كنعان، وأتت عليهم الرعدة والخوف." } },
      { kind: 'hymn', text: { en: "By the greatness of Your arm they will be as still as stone, till Your people pass over O Lord, till Your people pass over whom You have purchased.", ar: "بكثرة ساعدك فليصيروا كالحجر، حتى يجتاز شعبك يا رب، حتى يجتاز شعبك هذا الذي إقتنيته." } },
      { kind: 'hymn', text: { en: "You will bring them in and plant them in the mountain of Your inheritance, in the place O Lord, which You have made for You to dwell in.", ar: "أدخلهم وأغرسهم على جبل ميراثك، وفي مسكنك المُعَد، هذا الذي صنعته يا رب." } },
      { kind: 'hymn', text: { en: "In Your sanctuary O Lord which Your hands have established, the Lord shall reign forever and ever.", ar: "موضعك المقدس يا رب الذي أعددته يداك، يا رب تمَلُك منذ الأزل والآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "For the horses of pharaoh went with his chariots and his horsemen into the sea.", ar: "لأنه قد دخل إلى البحر خيل فرعون ومركباته وفرسانه." } },
      { kind: 'hymn', text: { en: "And the Lord brought back the waters of the sea upon them, but the children of Israel went on dry land in the midst of the sea.", ar: "والرب غمرهم بماء البحر، أما بنو إسرائيل فكانوا يمشون على اليابسة في وسط البحر." } },
      { kind: 'hymn', text: { en: "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand, and all the women went out after her with timbrels and with praises.", ar: "فأخذت مريم النبية، أخت هرون، الدُف بيديها، وخرج في إثرها جميع النسوة بالدُفوف والتسابيح." } },
      { kind: 'hymn', text: { en: "And Miriam answered them saying, \"Sing to the Lord, for He has triumphed gloriously.\"", ar: "وبدأت مريم في مقدمتهنَّ تقول، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider, He has thrown into the sea. \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "الفرس ورُاكب الفرس، طرحهما في البحر. \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'heading', text: { en: "The First Hoos Lobsh", ar: "لبش الهوس الأول" } },
      { kind: 'hymn', text: { en: "With the split, the waters of the sea split, and the very deep, became a walkway.", ar: "قطعاً إنقطع، ماء البحر، والعمق العميق، صار مَسلكاً." } },
      { kind: 'hymn', text: { en: "A hidden earth, was shone upon by the sun, and an untrodden road, was walked upon.", ar: "أرض غير ظاهرة، أشرقت الشمس عليها، وطريق غير مسلوكة، مشوا عليها." } },
      { kind: 'hymn', text: { en: "The flowing water, stood still, by a miraculous, act of wonder.", ar: "ماء مُنحل، وقف، بفِعل عجيب، مُعِجز." } },
      { kind: 'hymn', text: { en: "Pharaoh and his chariots, were drowned, and the children of Israel, crossed the sea.", ar: "غرق فرعون، ومركباته، وعبر بنو إسرائيل، البحر." } },
      { kind: 'hymn', text: { en: "And in front of them was, Moses the prophet praising, until he brought them, to the wilderness of Sinai.", ar: "وكان موسى النبي، يسبح قدامهم، حتى أدخلهم، برية سيناء." } },
      { kind: 'hymn', text: { en: "And they were praising God, with this new psalmody, saying \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "وكانوا يسبحون الله، بهذه التسبحة الجديدة قائلين، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "Through the prayers, of Moses the archprophet, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، موسى رئيس الأنبياء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع أبيك الصالح، والروح القدس، لأنك (قُمتأتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Second Hoos", ar: "الهوس الثاني" } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord for He is good, Alleluia His mercy endures forever.", ar: "أُشكروا الرب لأنه صالح وخيِّر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of gods, Alleluia His mercy endures forever.", ar: "أُشكروا إله الآلهة، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords, Alleluia His mercy endures forever.", ar: "أُشكروا رب الأرباب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who alone does great wonders, Alleluia His mercy endures forever.", ar: "الصانع العجائب العظام وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who by wisdom made the heavens, Alleluia His mercy endures forever.", ar: "الذي خلق السموات بفهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who stretched out the earth above the waters, Alleluia His mercy endures forever.", ar: "الذي ثبَّت الأرض على المياه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who made great lights, Alleluia His mercy endures forever.", ar: "الذي خلق نيرين عظيمين وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The sun to rule by day, Alleluia His mercy endures forever.", ar: "الشمس لحكم النهار، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The moon and stars to rule by night, Alleluia His mercy endures forever.", ar: "القمر والنجوم لحكم الليل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote Egypt in their firstborn, Alleluia His mercy endures forever.", ar: "الذي ضرب المصريين مع أبكارهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And brought out Israel from among them, Alleluia His mercy endures forever.", ar: "وأخرج إسرائيل من وسطهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "With a strong hand and with a stretched out arm, Alleluia His mercy endures forever.", ar: "بيد عزيزة وذراع عالية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who divided the Red Sea into parts, Alleluia His mercy endures forever.", ar: "الذي شق البحر الأحمر إلى أقسام، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And made Israel to pass through the midst of it, Alleluia His mercy endures forever.", ar: "وأجاز إسرائيل في وسطه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "But overthrew pharaoh and his hosts in the Red Sea, Alleluia His mercy endures forever.", ar: "وطرح فرعون وكل قوته في البحر الأحمر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who led His people through the wilderness, Alleluia His mercy endures forever.", ar: "الذي أخرج شعبه إلى البرية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who retrieved water from a rock, Alleluia His mercy endures forever.", ar: "الذي أخرج ماء من صخرة صماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote great kings, Alleluia His mercy endures forever.", ar: "الذي ضرب ملوكاً عُظماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And slew famous kings, Alleluia His mercy endures forever.", ar: "وقتل ملوكاً عجيبين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Sihon the king of the Amorites, Alleluia His mercy endures forever.", ar: "سيحون ملك الأموريين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And Og the king of Bashan, Alleluia His mercy endures forever.", ar: "وعوج ملك باشان، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And gave their lands for a heritage, Alleluia His mercy endures forever.", ar: "أعطى أرضهم ميراثاً، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "A heritage unto Israel His servant, Alleluia His mercy endures forever.", ar: "ميراثاً لعبده إسرائيل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who remembered us in our low estate, Alleluia His mercy endures forever.", ar: "في تواضعنا ذكرنا الرب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And has redeemed us from our enemies, Alleluia His mercy endures forever.", ar: "وخلصنا من أيدي أعدائنا، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who gives food to all flesh, Alleluia His mercy endures forever.", ar: "الذي يعطي طعاماً لكل جسد حي، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of heaven, Alleluia His mercy endures forever.", ar: "إحمدوا إله السماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords for He is good, Alleluia His mercy endures forever.", ar: "إحمدوا رب الأرباب لأنه طيب وصالح، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'heading', text: { en: "The Second Hoos Lobsh", ar: "لبش الهوس الثاني" } },
      { kind: 'hymn', text: { en: "Let us give thanks, to Christ our God, with David the prophet, and psalmist.", ar: "فلنشكر، المسيح إلهنا، مع المرتل، داود النبي." } },
      { kind: 'hymn', text: { en: "For He has made the heavens, and all its hosts, and established the earth, on the waters.", ar: "لأنه خلق السموات، وجنودها، وأسَّس الأرض، على المياه." } },
      { kind: 'hymn', text: { en: "These two great stars, the sun and the moon, He has made to enlighten, the firmament.", ar: "هذان الكوكبان العظيمان، الشمس والقمر، جعلهما ينيران، في الفلك." } },
      { kind: 'hymn', text: { en: "He brought forth the winds, out of His treasure box, He breathed unto the trees, and they blossomed.", ar: "أخرج الرياح، من خباياها، نفخ في الأشجار، حتى أزهرت." } },
      { kind: 'hymn', text: { en: "He caused the rain to fall, upon the face of the earth, and it sprouted, and gave its fruit.", ar: "أمطرا مطراً، على وجه الأرض، حتى أنبتت، وأعطت ثمرها." } },
      { kind: 'hymn', text: { en: "He brought forth water, out of a rock, and gave it to His people, in the wilderness.", ar: "أخرج ماء، من صخرة صماء، وسقى شعبه، في البرية." } },
      { kind: 'hymn', text: { en: "He made man, in His image, and His likeness, that he may praise Him.", ar: "صنع الإنسان، كشبهه، وصورته، لكي يباركه." } },
      { kind: 'hymn', text: { en: "Let us praise Him, and exalt His name, and give thanks to Him, His mercy endures forever.", ar: "فلنسبحه، ونرفع إسمه، ونشكره لأن رحمته، كائنة إلى الأبد." } },
      { kind: 'hymn', text: { en: "Through the prayers, of David the psalmist, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، المرتل داود، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله، القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of all the heavenly hosts, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، كل صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Blessed are You indeed, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "مبارك أنت بالحقيقة، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Third Hoos", ar: "الهوس الثالث" } },
      { kind: 'hymn', text: { en: "Blessed are You O Lord God of our fathers, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الرب إله أبائنا، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed is Your holy name and Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك إسم مجدك القدوس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the holy temple of Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في هيكل مجدك المقدس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You who beholds the depths and sits upon the Cherubim, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الناظر إلى الأعماق الجالس على الشاروبيم، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You on the throne of Your kingdom, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت على عرش مُلكك، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the firmament of heaven, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في فلك السماء، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you works of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع أعمال الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السموات، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you angels of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا جميع ملائكة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you waters above the heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع المياه التي فوق السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you powers of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع قوات الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O sun and moon, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها الشمس والقمر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you stars of heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا سائر نجوم السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you rain and dew, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأمطار مع الأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you clouds and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السُحب والرياح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you spirits, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع الأرواح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O fire and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها النار والحرارة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O cold and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والحر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you dew and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأهوية والأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you nights and days, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الليالي والأيام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O light and darkness, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها النور والظلمة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O frost and cold, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والصقيع، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O snow and ice, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها الجليد والثلج، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you lightnings and clouds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البروق والسحب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all the earth, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأرض كلها، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you mountains and all hills, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الجبال وجميع الآكام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you things that spring up on the earth, praise Him and exalt Him above all forever.", ar: "بارك الرب يا جميع ما يَنبت على وجه الأرض، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you fountains, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الينابيع، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you seas and rivers, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البحار والأنهار، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you whales and all that moves in the waters, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الحيتان وجميع ما يتحرك في الماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you birds of the sky, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع طيور السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you wild beasts and cattle, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الوحوش وكل البهائم، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you sons of men, worship the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا بني البشر، وأُسجدوا للرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Israel, praise Him and exalt Him above all forever.", ar: "بارك الرب يا إسرائيل، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you priests of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا كهنة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you servants of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عبيد الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you spirits and souls of the just, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا أرواح وأنفس الصديقين، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you holy and humble of heart, praise Him and exalt Him above all forever.", ar: "باركوا الرب أيها القديسون والمتواضعو القلوب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all\nforever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "The Third Hoos — Esmo Epchois", ar: "الهوس الثالث — إسمو إبشويس" } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "Psali for the Three Saintly Children", ar: "إبصالية للثلاثة فتية القديسين" } },
      { kind: 'hymn', text: { en: "O sing unto Him who was crucified, buried and resurrected, who trampled and abolished death, praise Him and exalt Him above all.\nTake off the old man, and put on the new and superior one, come closer to greatness of mercy, praise Him and exalt Him above all.", ar: "رتلوا للذي صُلب عنا، وقُبر وقام، وأبطل الموت وأهانه، سبحوه وزيدوه علواً.\nإخلعوا الإنسان العتيق، وألبسوا الجديد الفاخر، وإقتربوا إلى عِظَم الرحمة، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "All you Christian people, the priests and the deacons, glorify the Lord for He is worthy, praise Him and exalt Him above all.\nCome to us O three children, whom Christ our God has lifted, and from the Devil has delivered, praise Him and exalt Him above all.", ar: "يا جنس المسيحيين، القسوس والشمامسة، أعطوا مجداً للرب لأنه مستوجب، سبحوه وزيدوه علواً.\nهَلُمَّ إلينا أيها الثلاثة فتية، الذين رفعهم المسيح إلهنا، وأنقذهم من إبليس، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "For the sake of your God the Messiah, the Giver of all good things, come unto us O Hananiah, praise Him and exalt Him above all.\nO Azariah the zealot, morning and noon and the evening, glorify the power of the Trinity, praise Him and exalt Him above all.", ar: "من أجل إلهك ماسيا، المانح الإحسان، هَلُمَّ إلينا يا حنانيا، سبحوه وزيدوه علواً.\nيا عزاريا الغيور، عشية وبكرة والظهيرة، أعط مجداً لقوة الثالوث، سبّحه وزده علواً." } },
      { kind: 'hymn', text: { en: "Behold Emmanuel [our Lord], is now in our midst O Mishael, proclaim with the voice of joy, praise Him and exalt Him above all.\nGather now and persevere, and proclaim with the priests, bless the Lord all His works, praise Him and exalt Him above all.", ar: "فها هوذا عمانوئيل، في وسطنا يا ميصائيل، تكلم بصوت التهليل، سبّحه وزده علواً.\nإجتمعوا وثابروا جميعاً، تكلموا مع القسوس، وسبحي الرب يا جميع أعماله، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "The heavens declare the glory, of God until this day, O you angels whom He has made, praise Him and exalt Him above all.\nNow all you powers of the Lord, bless His honored name, O sun and moon and all the stars, praise Him and exalt Him above all.", ar: "ها السموات تنطق بمجد الله، إلى هذا اليوم، يا أيها الملائكة الذين أنشأهم، سبحوه وزيدوه علواً.\nوالآن يا قوات الرب، باركوا إسمه الكريم، أيتها الشمس والقمر والنجوم، سبحيه وزيديه علواً." } },
      { kind: 'hymn', text: { en: "And also you rain and dew, sing praises unto our Savior, for He is the God of our fathers, praise Him and exalt Him above all.\nGlorify the Lord O clouds and winds, together with the souls and the spirits, O you cold and fire and heat, praise Him and exalt Him above all.", ar: "وأيضاً أيتها الأمطار والأنداء، إمدحي مخلصنا، لأنه هو إله آبائنا، سبحيه وزيديه علواً.\nأعطي مجداً أيتها السحب معاً، والأهوية والنفوس والأرواح، والبرد والنار والحرارة، سبحيه وزيده علوا." } },
      { kind: 'hymn', text: { en: "You also nights and days, light and darkness and lightning, glorify the Lover of Mankind, praise Him and exalt Him above all.\nYou trees and all that springs on the earth, and all that moves in the sea, mountains and the forests, praise Him and exalt Him above all.", ar: "أيتها الليالي والأيام أيضاً، والنور والظلمة والبروق، قائلة المجد لك يا محب البشر، سبحوه وزيدوه علواً.\nأيتها الأشجار وجميع ما ينبُت، في الأرض وكل ما يتحرك، في المياه والجبال والغياض، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Praise without ceasing, the Lord the King of the kings, O you rivers and seas, praise Him and exalt Him above all.\nAnd we also seeing them, let us say with all these things, bless the Lord all you birds, praise Him and exalt Him above all.", ar: "وأيضاً سبحي بغير فتور، الرب ملك الملوك، أيتها البحار والأنهار، سبحيه وزيديه علواً.\nهكذا نحن إذ ننظر إليهم، فلنقل مع هذه الموجودات جميعها، باركي الرب يا جميع الطيور، سبحيه وزيده علواً." } },
      { kind: 'hymn', text: { en: "O snow and ice, cattle and wild beasts, bless the Lord of lords, praise Him and exalt Him above all.\nBless the Lord as befits Him, and not like the heretics, all you sons of men, praise Him and exalt Him above all.", ar: "أيها الجليد والثلج، والبهائم والوحوش، باركي رب الأرباب، سبحيه وزيديه علواً.\nسبحوا الرب كما يليق به، وليس كالمخالفين، يا أبناء البشر، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "O Israel offer before Him, honor and glory in a joyful voice, all you priests of Emmanuel, praise Him and exalt Him above all.\nYou servants of the true God, the souls of the righteous, and the humble and the charitable, praise Him and exalt Him above all.", ar: "مجداً وإكراماً قدم أمامه، يا إسرائيل بصوت التهليل، يا كهنة عمانوئيل، سبحوه وزيدوه علواً.\nيا خدام الله الحقيقي، وأنفس الأبرار، المتواضعين المحبين، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "God my God is the One, who saved you from danger, O Sedrach Misach and Abednago, praise Him and exalt Him above all.\nHurry with great haste, O you righteous of the Lord, and all the creatures He has made, praise Him and exalt Him above all.", ar: "الله إلهي أنا، هو مخلصكم من الخطر، يا سدراك وميساك وأبدناغو، سبحوه وزيدوه علوا.\nأسرعوا بحرص عظيم، يا أتقياء الرب، وكل الطبائع التي صنعها، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Coolness and repose without ceasing, grant unto all of us, that we may joyfully proclaim, praise Him and exalt Him above all.\nAnd also Your poor servant Sarkis, make him without condemnation, that he may join all those and say, praise Him and exalt Him above all.", ar: "برودة ونياحاً أعطنا، كلنا بغير إنقطاع، لنقول بتمتُع، سبحوه وزيدوه علواً.\nكذلك عبدك المسكين سركيس، إجعله بغير دينونة، ليقول مع هؤلاء كشريك، سبحوه وزيدوه علواً." } },
      { kind: 'heading', text: { en: "Ten-oueh Ensok", ar: "تين أويه إنسوك" } },
      { kind: 'hymn', text: { en: "We follow You with all our hearts, and fear You, and we seek Your face, O God do not forsake us.", ar: "نتبعك بكل قلوبنا، ونخافك، ونطلب وجهك، يا الله لا تخزنا." } },
      { kind: 'hymn', text: { en: "But rather deal with us, according to Your meekness, and according to Your great mercy, O Lord help us.", ar: "بل إصنع معنا، بحسب دعتك، وكثرة رحمتك، يا رب أعنَّا." } },
      { kind: 'hymn', text: { en: "May our prayers ascend to You, O our Master, like burnt offerings of lambs, and fat calves.", ar: "فلتصعد صلاتنا، أمامك يا سيدنا، مثل محرقات كباش، وعجول سِمان." } },
      { kind: 'hymn', text: { en: "Do not forget the covenant, which You have made with our fathers, Abraham Isaac and Jacob, Israel Your saint.", ar: "لا تنس العهد الذي، قطعته مع آبائنا، إبراهيم وإسحق ويعقوب، إسرائيل قديسك." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you nations, the tribes and all kinds of tongues, praise Him and glorify Him, above all forever.", ar: "باركوا الرب يا جميع الشعوب، والقبائل ولغات الألسن، سبحوه ومجدوه، وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Pray to the Lord on our behalf, O three saintly children, Sedrach Misach and Abednego, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة فتية القديسين، سدراك وميساك وأبدناغو، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints", ar: "مجمع القديسين" } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the Lady of us all the Mother of God, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، يا سيدتنا كلنا السيدة والدة الإله، مريم أُم مخلصنا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Michael and Gabriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، ميخائيل وغبريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Raphael and Souriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، رافائيل وسوريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Sedakiel Sarathiel and Ananiel, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا رؤساء الملائكة الأطهار، سداكيال وسراتيال وأنانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O thrones dominions and powers, the Cherubim and the Seraphim, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، أيتها الكراسي والأرباب والقوات، والشيروبيم والسرافيم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O four incorporeal beasts, the ministering flames of fire, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها الأربعة الحيوانات غير المتجسدين، الخدام الملتهبين ناراً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O priests of the truth, the twenty four presbyters, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا كهنة الحق، الأربعة والعشرين قسيساً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O angelic hosts, and all the heavenly multitudes, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها العساكر الملائكية، والطغمات السمائية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lords the fathers the patriarchs, Abraham Isaac and Jacob, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء البطاركة، إبراهيم وإسحق ويعقوب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O perfect man, the righteous and just Enoch, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الرجل الكامل، البار أخنوخ الصديق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Elijah the tishbite, and Elisha his disciple, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيليا التسبيتي، وإليشع تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Moses the archprophet, and Isaiah and Jeremiah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا موسى رئيس الأنبياء، وأشعياء وأرميا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O David the psalmist, Ezekiel and Daniel, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا داود المرتل، وحزقيال ودانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Joachim Anna and Joseph the elder, and the righteous Job Joseph and Nicodemus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا يواقيم وحنِّة ويوسف الشيخ، والصديق أيوب ويوسف ونيقوديموس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Melchizedek and Aaron, and Zacharias and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ملكي صادق وهرون، وزكريا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the prophets, and all the righteous and the just, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الأنبياء، والأبرار والصديقين، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O forerunner and baptizer, John the Baptist, that He may forgive us our sins.", ar: "إشفع فينا (أمام الرب)، أيها السابق الصابغ، يوحنا المعمدان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the hundred and forty four thousand, and the celibate evangelist, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها المئة والأربعة والأربعين ألفاً، والبتول الإنجيلي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters and fathers the Apostles, and the rest of the Disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء الرسل، وبقية التلاميذ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O blessed archdeacon, Stephen the first martyr, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا رئيس الشمامسة المبارك، إستفانوس الشهيد الأول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the apostle, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الناظر الإله الإنجيلي، أبا مرقس الرسول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyr, my lord prince George, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الشهيد المجاهد، سيدي الملك جيؤرجيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Theodore and Theodore, Leontius and Panicharus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ثيؤدوروس وثيؤدوروس، ولاونديوس، وبانيكاروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Philopater Mercurius, and Abba Mina and Abba Victor, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا فيلوباتير مرقوريوس، وأبا مينا وأبا بقطر، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Claudius and Theodore, Abba Eschyron and Abba Isaac, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي إقلاديوس وثيئودوروس، وأبا سخيرون وأبا إسحق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basilidis and Evsebius, Macarius and Philotheos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا واسيليدس وأرسابيوس، ومكاريوس وفيلوثيؤوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pisura and Abba Epshoy, Abba Isi and his sister Thecla, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بسورة وأبا بشاي، وأبا إيسي وتكلا أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Justus Apali and Theoklia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يسطس وآبالي وثيؤكليا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Jacob the Persian, Saint Sergius and Saint Bacchus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا يعقوب الفارسي، والقديس سرجيوس وواخس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Cosmas his brothers and their mother, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، قزمان وإخوته وأمهم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Kir and his brother John, and Barbara and Juliana and Demiana, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا قير ويوحنا أخوه، وبربارة ويوليانة ودميانة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, master Apatir and his sister Iraee, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، السيد أبادير وإيرائي أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Julius and those who were with him, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يوليوس ومَن معه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Mari Pahnam and his sister Sarah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، مار بهنام وسارة أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Sarapamon the bishop, Psate and Gallinikos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صرابامون الأسقف، وإبصادي وغلينيكوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, the forty saints of Sebaste, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، الأربعون قديساً بسبسطية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Piro and Athom, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بيروه وأتوم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Abba Bishoy and his friend Peter, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، أيها الشهيدان المجاهدان، أبا بيشوي وصديقه بطرس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Eklog the priest, and Abba Epgol and Abba Kav, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا إكلوج القس، وأبا بيجول وأبا كاڤ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba John of Heraclia, master Piphamon and Pistavros, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا يوحنا الهرقلي، والسيد بفامون وبسطوروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Isidore and Panteleon, Sophia and Euphemia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيسيذوروس وبندلاون، وصوفيا وإفومية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Apanoub and Ptolomeos, Apa Ekragon and Sousennius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي أبانوب وإبطلماوس، وإبا إكراجون وسوسونيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O great high priest, Abba Peter seal of the martyrs, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا رئيس الكهنة العظيم، أنبا بطرس خاتم الشهداء، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O new martyrs, Pistavros and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان الجديدان، بسطوروس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Michael the hegumen, and Michael the monk, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، يا ميخائيل القمص، وميخائيل الراهب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the martyrs, who suffered for the sake of Christ, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الشهداء، الذين تألموا من أجل المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Antony and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا أنطونيوس وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O three saints Macarii, and all their children the cross-bearers, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة مقارات القديسون، وأولادهم لباس الصليب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers the hegumens, Abba John and Abba Daniel, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين القمصين، أنبا يوحنا وأنبا دانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Bishoy and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا بيشوي وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our saintly Roman fathers, Maximus and Dometius, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أبوينا القديسين الروميين، مكسيموس ودوماديوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O forty nine martyrs, the elders of Shiheet, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها التسعة والأربعون شهيداً، شيوخ شيهات، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O strong saint Abba Moses, and John Kame, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، أيها القوي القديس أنبا موسى، ويحنس كاما، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pachomius of the Koinonia, and Theodore his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا باخوم أبا الشركة، وثيودورس تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Shenouda the archimandrite, and Abba Wisa his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا شنودة رئيس المتوحدين، وأنبا ويصا تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Nopher and Abba Karus, and our father Paphnutius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا نفر وأنبا كاروس، وأبانا بفنوتيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Samuel the confessor, and Justus and Apollo his disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صموئيل المعترف، ويسطس وأبوللو تلميذيه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Apollo and Abba Apip, and our father Abba Pigimi, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا أبوللو وأنبا أبيب، وأبانا أنبا بيچيمي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Evkin and Abba Ehron, Abba Hor and Abba Phis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا إڤكين وأنبا إهرون، وأبا هور وأبا فيس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Parsouma and Ephraim, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا برسوما وإفريم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Epiphanius and Ammounios, and Arshillidis and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إبيفانيوس وأمونيوس، وأرشليدس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the ascetic fathers, Abba Abraam and George, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين الناسكين، أنبا أبرآم وجيؤرجي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Athanasius the apostolic, Severus and Dioscorus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أثاناسيوس الرسولي، وساويرس وديسقورس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basil and Gregory, and our father Abba Cyril, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا باسيليوس وإغريغوريوس، وأبانا أنبا كيرلس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the three hundred and eighteen gathered, at Nicea for the faith, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 318 الذين إجتمعوا، في نيقية من أجل الإيمان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O the one hundred and fifty at Constantinople, and the two hundred at Ephesus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 150 بمدينة القسطنطينية، والمائتين بأفسس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Hadid and Abba John, our great father Parsouma and Abba Roweis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا حديد وأنبا يوحنا، وأبانا العظيم أنبا برسوما وأنبا رويس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Abraam the hegumen, and our father Abba Mark, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا أبرآم القمص، وأبانا أنبا مرقس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the cross-bearers, perfected in the wilderness, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا مصاف لباس الصليب، الذين كملوا في البراري، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lord king Constantine, and his mother queen Helen, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الملك قسطنطين، وهيلانة الملكة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O wise virgin ladies, the brides of Christ, that He may forgive us our sins.", ar: "أُطلبنَّ من الرب عنا، أيتها الفتيات العذارى الحكيمات، عرائس المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the saints of this day, everyone according to his name, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا قديسي هذا اليوم، كل واحد بإسمه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Likewise we exalt you, with David the psalmist, \"You are a priest forever, according to the order of Melchizedek.\"", ar: "كذلك نعظمك، مع المرتل داود قائلين، \"أنت هو الكاهن إلى الأبد، على طقس ملكي صادق.\"" } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our holy father the patriarch, Pope Abba Shenouda the high priest, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا أبانا القديس البطريرك، أنبا شنودة رئيس الكهنة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "If a Bishop is present:\nPray to the Lord on our behalf, O our holy and righteous father, Abba (...) the Bishop (Metropolitan), that He may forgive us our sins.", ar: "في حضور الآب الأسقف:\nأطلب من الرب عنا، يا أبينا القديس البار، أنبا (...) الأسقف (المطران)، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Doxology for the Virgin Mary", ar: "ذكصولوجية العذراء مريم" } },
      { kind: 'doxology', text: { en: "Your greatness O Mary, the undefiled Virgin, is likened to the height of the palm tree, spoken of by Solomon.", ar: "عظمتِك يا مريم، العذراء غير الدنسة، تشبه عُلو النخلة التي، تكلم عنها سليمان." } },
      { kind: 'doxology', text: { en: "You are the spring of living water, that flows from Lebanon, for out of you sprang unto us, the grace of the divinity.", ar: "أنتِ ينبوع ماء الحياة، الفائض من لبنان، التي نبعت لنا منه، نعمة اللاهوت." } },
      { kind: 'doxology', text: { en: "You gave birth to Emmanuel, out of your virginal womb, and He has made us heirs, to the kingdom of heaven.", ar: "ولدتِ لنا عمانوئيل، من أحشائِك البتول، وصيرنا وارثين، في ملكوت السموات." } },
      { kind: 'doxology', text: { en: "According to the promise, He promised to our father, King David the patriarch, He came and fulfilled to us.", ar: "كالوعد الذي وعد به، أبانا رئيس الآباء، الذي هو الملك داود، أتى وأكمله لنا." } },
      { kind: 'doxology', text: { en: "Hail to you O Virgin, the very and true Queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدت لنا عمانوئيل." } },
      { kind: 'doxology', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Fourth Hoos", ar: "الهوس الرابع" } },
      { kind: 'hymn', text: { en: "(Psalm 148)", ar: "(المزمور 148)" } },
      { kind: 'hymn', text: { en: "Praise the Lord from the heavens Alleluia. Praise Him in the heights.", ar: "سبحوا الرب من السموات هلليلويا. سبحوه في الأعالي." } },
      { kind: 'hymn', text: { en: "Praise Him all His angels Alleluia. Praise Him all His hosts.", ar: "سبحوه يا جميع ملائكته هلليلويا. سبحوه يا جميع جنوده." } },
      { kind: 'hymn', text: { en: "Praise Him sun and moon Alleluia. Praise Him all you stars of light.", ar: "سبحيه أيتها الشمس والقمر هلليلويا. سبحيه يا جميع كواكب النور." } },
      { kind: 'hymn', text: { en: "Praise Him you heavens of heavens Alleluia. And you waters above the heavens.", ar: "سبحيه يا سماء السموات هلليلويا. ويا أيتها المياه التي فوق السموات." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For He commanded and they were created.", ar: "لتسبح جميعها لإسم الرب هلليلويا. لأنه قال فكانت." } },
      { kind: 'hymn', text: { en: "He has ordered and they were created Alleluia. He has established them forever and ever.", ar: "وأمر فخلقت هلليلويا. أقامها إلى الأبد وإلى أبد الأبد." } },
      { kind: 'hymn', text: { en: "He has made a decree which shall not pass away Alleluia. Praise the Lord from the earth.", ar: "وضع لها أمراً فلن تتجاوزه هلليلويا. سبحي الرب من الأرض." } },
      { kind: 'hymn', text: { en: "You great sea creatures and all the depths Alleluia. Fire and hail, snow and clouds, stormy wind fulfilling His word.", ar: "أيتها التنانين وجميع الأعماق هلليلويا. النار والبرد والثلج والجليد والريح العاصفة الصانعة كلمته." } },
      { kind: 'hymn', text: { en: "Mountains and all hills Alleluia. Fruitful trees and all cedars.", ar: "الجبال العالية وجميع الآكام هلليلويا. الأشجار المثمره وكل الأرز." } },
      { kind: 'hymn', text: { en: "Beasts and all cattle Alleluia. Creeping things and flying birds.", ar: "الوحوش وكل البهائم هلليلويا. الهوام وكل الطيور ذات الأجنحة." } },
      { kind: 'hymn', text: { en: "Kings of the earth and all people Alleluia. Princes and all judges of the earth.", ar: "ملوك الأرض وكل الشعوب هلليلويا. الرؤساء وكل حكام الأرض." } },
      { kind: 'hymn', text: { en: "Both young men and maidens Alleluia. Old men and children.", ar: "الشبان والعذارى هلليلويا. الشيوخ والصبيان." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For His name alone is exalted.", ar: "فليسبحوا جميعاً إسم الرب هلليلويا. لأنه قد تعالى إسمه وحده." } },
      { kind: 'hymn', text: { en: "His glory is above the earth and heaven Alleluia. And He has exalted the horn of His people.", ar: "شكره كائن على الأرض وفي السماء هلليلويا. ويرفع قرن شعبه." } },
      { kind: 'hymn', text: { en: "The praise of all His saints Alleluia. The children of Israel, a people near unto Him.", ar: "سُبحاً لجميع قديسيه هلليلويا. بني إسرائيل، الشعب القريب إليه." } },
      { kind: 'hymn', text: { en: "(Psalm 149)", ar: "(المزمور 149)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Sing to the Lord a new song Alleluia. And His praise in the congregation of the saints.", ar: "إنشدوا للرب نشيداً جديداً هلليلويا. لأن تسبحته في بيعة القديسين." } },
      { kind: 'hymn', text: { en: "Let Israel rejoice in his Maker Alleluia. Let the children of Zion be joyful in their King.", ar: "فليفرح إسرئيل بخالقه هلليلويا. وبنوا صهيون فليتهللوا بملكهم." } },
      { kind: 'hymn', text: { en: "Let them praise His name in a chorus Alleluia. Let them sing praises unto Him with timbrel and harp.", ar: "فليسِّبحوا إسمه القدوس بصفِ هلليلويا. بدف ومزمار فليرتلوا له." } },
      { kind: 'hymn', text: { en: "For the Lord takes pleasure in His people Alleluia. He will raise the meek with salvation.", ar: "لأن الرب يُسر بشعبه هلليلويا. يعلي الودعاء بالخلاص." } },
      { kind: 'hymn', text: { en: "Let the saints be joyful in glory Alleluia. Let them sing aloud upon their beds.", ar: "يفتخر القديسون بمجد هلليلويا. ويتهللون على مضاجعهم." } },
      { kind: 'hymn', text: { en: "Let the high praises of God be in their mouth Alleluia. And a two edged sword in their hands.", ar: "تعليات الله في حناجرهم هلليلويا. وسيوف ذات حدين في أيديهم." } },
      { kind: 'hymn', text: { en: "To execute vengeance on the nations Alleluia. And punishments on the people.", ar: "ليصنعوا نقمة في الأمم هلليلويا. وتوبيخات في الشعوب." } },
      { kind: 'hymn', text: { en: "To bind their kings with chains Alleluia. And their nobles with fetters of iron.", ar: "ليوثقوا ملوكهم بقيود هلليلويا. وإشرافهم بأغلال للأيدي من حديد." } },
      { kind: 'hymn', text: { en: "To execute on them the written judgment Alleluia. This honor have all His saints.", ar: "ليصنعوا بهم حُكماً مكتوباً هلليلويا. هذا المجد كائن في جميع قديسيه." } },
      { kind: 'hymn', text: { en: "(Psalm 150)", ar: "(المزمور 150)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise God in all His saints Alleluia.", ar: "سبحوا الله في جميع قديسيه هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him in the firmament of His power Alleluia.", ar: "سبحوه في جلد قوته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him for His mighty acts Alleluia.", ar: "سبحوه على مقدرته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him according to the multitudes of His greatness Alleluia.", ar: "سبحوه ككثرة عظمته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with the sound of the trumpet Alleluia.", ar: "سبحوه بصوت البوق هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with psaltery and harp Alleluia.", ar: "سبحوه بالمزمار والقيثار هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with timbrel and chorus Alleluia.", ar: "سبحوه بدفوف وصفوف هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with strings and organs Alleluia.", ar: "سبحوه بأوتار وأرغن هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with pleasant sounding cymbals Alleluia.", ar: "سبحوه بصنوج حسنة الصوت هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him upon the cymbals of joy Alleluia.", ar: "سبحوه بصنوج التهليل هلليلويا." } },
      { kind: 'hymn', text: { en: "Let every thing that has breath praise the name of the Lord our God Alleluia.", ar: "كل نسمة فلتسبح إسم الرب الهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son and the Holy Spirit Alleluia.", ar: "المجد للآب والإبن والروح القدس هلليلويا." } },
      { kind: 'hymn', text: { en: "Now and forever and unto the age of all ages Amen Alleluia.", ar: "الآن وكل أوان وإلى دهر الدهور آمين هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory to You, O our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لك يا إلهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory be to our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لإلهنا هلليلويا." } },
      { kind: 'heading', text: { en: "The Thursday Psali", ar: "إبصالية الخميس" } },
      { kind: 'hymn', text: { en: "Once more O my beloved, let us keep away, the evil inclinations of our hearts, that lead us to sin.\nLet us incessantly, bless the name of salvation, that is for our Lord Jesus Christ, proclaiming and saying:", ar: "وأيضاً يا أحبائي، فلنطرح عنا، ميول قلوبنا الرديئة، التي تجذبنا إلى الخطية.\nولنبارك إسم الخلاص، الذي لربنا يسوع المسيح، بدون إنقطاع، صارخين قائلين:" } },
      { kind: 'hymn', text: { en: "O my Lord Jesus Christ, the Begotten of the Father, before all ages, have mercy upon us according to Your great mercy.\nO my Lord Jesus Christ, who was born of the Virgin, in Bethlehem of Judea, save us and have mercy upon us.", ar: "يا ربي يسوع المسيح، المولود من الآب، قبل كل الدهور، إرحمنا كعظيم رحمتك.\nيا ربي يسوع المسيح، الذي ولدته العذراء، في بيت لحم اليهودية، خلِّصنا وإرحمنا." } },
      { kind: 'hymn', text: { en: "O my Lord Jesus Christ, who was baptized in the Jordan, purify our souls, from the defilement of sin.\nO my Lord Jesus Christ, who fasted on our behalf, forty days and forty nights, save us and have mercy upon us.", ar: "يا ربي يسوع المسيح، الذي إعتمد في الأردن، طَهِّر نفوسنا، من دنس الخطية.\nيا ربي يسوع المسيح، الذي صام عنا، أربعين يوماً وأربعين ليلة، خلِّصنا وإرحمنا." } },
      { kind: 'hymn', text: { en: "O my Lord Jesus Christ, who was crucified upon the Cross, crush Satan down, under our feet.\nO my Lord Jesus Christ, who was placed in the tomb, trample down for us, the sting of death.", ar: "يا ربي يسوع المسيح، الذي صُلب على الصليب، إسحق الشيطان، تحت أقدامنا.\nيا ربي يسوع المسيح، الذي وُضع في القبر، إسحق عنا، شوكة الموت." } },
      { kind: 'hymn', text: { en: "O my Lord Jesus Christ, who rose from the dead, and ascended to the heavens, raise us with Your power.\nO my Lord Jesus Christ, who will come in His Second Appearance, deal with us lovingly, as we stand before Your fearful throne.", ar: "يا ربي يسوع المسيح، الذي قام من بين الأموات، وصعد إلى السموات، أقِمنا بقوتك.\nيا ربي يسوع المسيح، الآتي في ظهوره الثاني، إصنع معنا محبة، في منبرك المخوف." } },
      { kind: 'hymn', text: { en: "For by Your own will, and the pleasure of Your Father, and the Holy Spirit, You came and saved us.", ar: "لأنك بإرادتك وحدك، ومسرة أبيك، والرُّوح القُدُس، أتيت وخلَّصتنا." } },
      { kind: 'heading', text: { en: "Introduction to the Watos Theotokias", ar: "مقدمة الثيؤطوكيات الواطس" } },
      { kind: 'hymn', text: { en: "And whenever we sing, let us say tenderly, “O our Lord Jesus Christ, have mercy upon our souls.”", ar: "إذا ما رتلنا، فلنقل بعذوبة، \"يا ربنا يسوع المسيح، إصنع رحمة مع نفوسنا.\"" } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son, and the Holy Spirit, now and forever and unto, the age of all ages Amen.", ar: "المجد للآب والإبن، والروح القدوس، الآن وكل أوان، وإلى دهر الدهور آمين." } },
      { kind: 'heading', text: { en: "The Thursday Theotokia — Watos", ar: "ثيؤطوكية الخميس — واطس" } },
      { kind: 'hymn', text: { en: "The First Part", ar: "القطعة الأولى" } },
      { kind: 'hymn', text: { en: "The bush which Moses, has seen in the wilderness, and the fire that was in it, did not burn its branches.", ar: "العليقة التي رآها، موسى في البرية، والنار مشتعلة فيها، ولم تحترق أغصانها." } },
      { kind: 'hymn', text: { en: "This is a symbol of Mary, the undefiled Virgin, which the Word of the Father, came and took flesh from her.", ar: "هي مثال مريم، العذراء غير الدنسة، التي أتى وتجسد منها، كلمة الآب." } },
      { kind: 'hymn', text: { en: "The fire of His divinity, did not burn the womb of the Virgin, and after she bore Him, she remained a virgin.", ar: "ونار لاهوته، لم تحرق بطن العذراء، وأيضاً بعد ما ولدته، بقيت عذراء." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Second Part", ar: "القطعة الثانية" } },
      { kind: 'hymn', text: { en: "The pride of all virgins, is Mary the Mother of God, for her sake He has revoked, the first curse.", ar: "فخر جميع العذارى، هي مريم والدة الإله، من أجلها أيضاً، نُقضت اللعنة الأولى." } },
      { kind: 'hymn', text: { en: "Which was pronounced upon our race, through the violation, incurred by the first woman, when she ate from the fruit of the tree.", ar: "التي جاءت على جنسنا، من قِبَل المخالفة، التي وقعت فيها المرأة، لما أكلت من ثمرة الشجرة." } },
      { kind: 'hymn', text: { en: "Because of Eve, the door of Paradise was closed, and through the Virgin Mary, it was opened to us once more.", ar: "من أجل حواء، أُغلق باب الفردوس، ومن قِبَل مريم العذراء، فتح لنا مرة أخرى." } },
      { kind: 'hymn', text: { en: "We have become worthy to have, the tree of life to eat from, which is the Body of God, and His true Blood.", ar: "إستحققنا شجرة الحياة، لنأكل منها، أي جسد الله، ودمه الحقيقيين." } },
      { kind: 'hymn', text: { en: "Let us worship our Savior, the good Lover of Mankind, for He had compassion upon us, He came and saved us.", ar: "فلنسجد لمُخلِّصنا، محب البشر الصالح، لأنه ترأف علينا، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Third Part", ar: "القطعة الثالثة" } },
      { kind: 'hymn', text: { en: "Which mind or which speech, or sound can attain, the unutterable expression, of Your love for mankind O God.", ar: "أي عقل أو أي قول، أو أي سمع يقدر أن ينهض، باللجة التي لا تُوصف، التي لمحبتك للبشر يا الله." } },
      { kind: 'hymn', text: { en: "The One and only Word, begotten before all ages, as the divinity without body, from the only Father.", ar: "الواحد وحده الكلمة، المولود قبل كل الدهور، باللاهوت بغير جسد، من الآب وحده." } },
      { kind: 'hymn', text: { en: "And He Himself also, was born bodily, without change or alteration, from His Mother only.", ar: "هو ذاته أيضاً، وُلد جسدياً، بغير تغيير ولا تحول، من أمه وحدها." } },
      { kind: 'hymn', text: { en: "And also after she bore Him, she remained a virgin, and thus He has showed, that she is the Theotokos.", ar: "وأيضاً بعد أن ولدته، لم يحل بتوليتها، وبهذا أظهرها، بأنها والدة الإله." } },
      { kind: 'hymn', text: { en: "O the depth of the riches, and wisdom of God, for the womb under punishment, bore children with deep pain.", ar: "يا لَعُمْقِ غِنَى، وحكمة الله، لأن البطن الواقع تحت الحكم، وولد الأولاد بوجع القلب." } },
      { kind: 'hymn', text: { en: "He became the source of immortality, she gave birth to Emmanuel, without the seed of man, to revoke the corruption of our race.", ar: "صار ينبوعاً لعدم الموت، ولدِت لنا عمانوئيل، بغير زرع بشر، ونقض فساد جنسنا." } },
      { kind: 'hymn', text: { en: "Let us proclaim and say unto Him, “Glory be to the Incomprehensible One, the good Lover of Man the Savior of our souls, He came and saved us.”", ar: "فلنصرخ نحوه قائلين، \"المجد لك أيها الغير مُدرَك، محب البشر الصالح مخلص نفوسنا، لأنه أتى وخلصنا.\"" } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Fourth Part", ar: "القطعة الرابعة" } },
      { kind: 'hymn', text: { en: "O what an honor to the conception, of the virginal womb, that bore God without seed, as the angel witnessed.", ar: "يا لكرامة الحبل، الذي للبطن البتولي، والوالد الإله بغير زرع، إذ شهد الملاك." } },
      { kind: 'hymn', text: { en: "When he appeared to Joseph, he likewise said, “The One she will give birth to, is from the Holy Spirit.”", ar: "لما ظهر ليوسف، قائلاً هكذا ، \"أن الذي ستلده هو، من الرُّوح القُدُس.\"" } },
      { kind: 'hymn', text: { en: "For the Word of the Father, came and took flesh from her, she bore Him without change, the angel said to him.", ar: "وأيضاً كلمة الآب، أتى وتجسد منها، ولدته بغير تغيير، وزاد هذا الآخر الملاك قائلاً." } },
      { kind: 'hymn', text: { en: "“She shall give birth to a Son, and He shall be called Emmanuel, which means, God with us.”", ar: "\"إنها تلد إبناً، ويُدعى إسمه عمانوئيل، الذي تفسيره، الله معنا.\"" } },
      { kind: 'hymn', text: { en: "And you will also call, His name Jesus, for He will save His people, from their iniquities.", ar: "وأيضاً تدعو، إسمه يسوع، وهو الذي يخلِّص شعبه، من خطاياهم." } },
      { kind: 'hymn', text: { en: "So when we become His people, He will save us with power, He will forgive us our sins, let us be confirmed in Him.", ar: "فإذ صرنا نحن شعبه، فهو يخلصنا بقوة، ويغفر آثامنا، فلنعرفه بثبات." } },
      { kind: 'hymn', text: { en: "For He is God in truth, He became man without change, glory be to Him, both now and forever.", ar: "لأنه هو الله بالحقيقة، تأنس بغير تغيير، المجد يليق به، من الآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Fifth Part", ar: "القطعة الخامسة" } },
      { kind: 'hymn', text: { en: "O what mysterious contractions, of God that are for, Mary the Theotokos, the ever-Virgin.", ar: "يا للطلقات الإلهية، العجيبة التي، لوالدة الإله مريم، العذراء كل حين." } },
      { kind: 'hymn', text: { en: "For she is where, two were united, the undefiled virginity, and the true Birth.", ar: "هذه التي منها، إجتمع معاً، بتولية بلا دنس، وميلاد حقيقي." } },
      { kind: 'hymn', text: { en: "For marriage, did not precede birth, neither did the Birth, loosen her virginity.", ar: "لأنه لم يسبق، الميلاد زواج، ولم يحل الميلاد، أيضاً بتوليتها." } },
      { kind: 'hymn', text: { en: "For He who was born is God, born without pain from the Father, and He was also born according to the flesh, without pain from the Virgin.", ar: "لأن الذي وُلد إله، بغير ألم من الآب، وُلد أيضاً حسب الجسد، بغير ألم من العذراء." } },
      { kind: 'hymn', text: { en: "One nature out of two, divinity and humanity, therefore the Magi silently, worship uttering His divinity.", ar: "هو إتحاد الإثنين، لاهوت وناسوت، ولهذا سجد له المجوس، ساكتين وناطقين بلاهوته." } },
      { kind: 'hymn', text: { en: "They offered Him frankincense for He is God, and gold for He is King, and myrrh as a sign, of His life-giving Death.", ar: "قدموا له لباناً كإله، وذهباً كملك، ومُراً علامة، على موته المحيي." } },
      { kind: 'hymn', text: { en: "This He accepted was for our sake, through His own will, the One and only good Lover of Mankind the Savior of our souls, He came and saved us.", ar: "هذا الذي قَبَله من أجلنا، بإرادته وحده، والواحد وحده محب البشر الصالح مخلص نفوسنا، أتى وخلصنا." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Sixth Part", ar: "القطعة السادسة" } },
      { kind: 'hymn', text: { en: "O what a great wonder, He took a rib, from Adam's side, and created a woman from it.", ar: "يا لِعِظَم أعجوبة، أخذ الضلع من جنب، أدم وجُبلت، منه إمرأة." } },
      { kind: 'hymn', text: { en: "She gave all the form of humanity, with perfection to the Lord, the Creator, the Word of the Father.", ar: "كل عجينة البشرية، أعطتها بالكمال، لله الخالق، وكلمة الآب." } },
      { kind: 'hymn', text: { en: "This is He who took flesh, from her without change, she gave birth to Him as a human, and He was called Emmanuel.", ar: "هذا الذي تجسد منها، بغير تغيير، ولدته كإنسان، ودُعيَّ إسمه عمانوئيل." } },
      { kind: 'hymn', text: { en: "Let us also entreat her, as the ever-Theotokos, to intercede on our behalf, before her beloved Son.", ar: "هي أيضاً فلنطلب إليها، كوالدة الإله كل حين، أن تشفع فينا، لدى إبنها الحبيب." } },
      { kind: 'hymn', text: { en: "For she is greatly honored, by all the saints and patriarchs, for she has brought to them, the One whom they were waiting for.", ar: "لأنها مكرمة جداً، عند جميع القديسين ورؤساء الآباء، لأنها أتت لهم بمَنْ، كانوا ينتظرونه." } },
      { kind: 'hymn', text: { en: "And likewise all the prophets, who prophesied about Him, in many ways and various analogies, saying “He will come and save us.”", ar: "كذلك الأنبياء، الذين تنبأوا من أجله، بأنواع كثيرة وأشباه، شتى بأنه يأتي ويخلصنا." } },
      { kind: 'hymn', text: { en: "And all the Apostles, for she is the Mother, of the One they preached about, all over the world.", ar: "والرسل معاً، لأنها هي والدة، الذي كرزوا به، في كل المسكونة." } },
      { kind: 'hymn', text: { en: "The struggling martyrs, for out of her came, the Founder of the true struggle, our Lord Jesus Christ.", ar: "والشهداء المجاهدين، لأنه قد خرج منها، واضع جهادهم الحقيقي، ربنا يسوع المسيح." } },
      { kind: 'hymn', text: { en: "Therefore let us glorify, the greatness of His wealth, and His infinite wisdom, pleading for His great mercy.", ar: "هذا فلنمجد، عظمة غناه الجزيل، وحكمته التي لا تحد، سائلين رحمته العظيمة." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Seventh Part", ar: "القطعة السابعة" } },
      { kind: 'hymn', text: { en: "The Lord has sworn in truth to David, and did not turn from it saying, “From the Fruit of your body, I will set upon your throne.”", ar: "أقسم الرب لداود، بالحق ولم يحنث، \"أن من ثمرة بطنك، أضع على كرسيك.\"" } },
      { kind: 'hymn', text: { en: "So when the righteous one, asked with all his heart, that Christ be born there according to the flesh, he asked earnestly.", ar: "فلهذا لما، طلب البار قلباً، أن منه يولد المسيح حسب الجسد، طلب بإجتهاد." } },
      { kind: 'hymn', text: { en: "To find a dwelling place, for the Lord God the Word, and this was completed, with a great mystery.", ar: "أن يجِد مسكناً، للرب الإله الكلمة، وهذا أكمله، بسر عظيم." } },
      { kind: 'hymn', text: { en: "And he instantly cried out, through the Spirit saying, “We have heard it in Ephrathah, which is Bethlehem.”", ar: "وللوقت صرخ، بالروح قائلاً، \"إننا قد سمعنا في إفراثة، التي هي بيت لحم.\"" } },
      { kind: 'hymn', text: { en: "The place where our God Emmanuel, has chosen to be born, according to the flesh, for our salvation.", ar: "الموضع الذي تفضل عمانوئيل، إلهنا أن يُولد فيه، حسب الجسد، من أجل خلاصنا." } },
      { kind: 'hymn', text: { en: "As Micah the prophet, also proclaimed saying, “You also O Bethlehem, the land of Ephrathah.", ar: "كما قال أيضاً، ميخا النبي، \"وأنتِ أيضاً يا بيت لحم، أرض إفراثة." } },
      { kind: 'hymn', text: { en: "Are by no means the least, among the rulers of Judah, for out of you shall come a ruler, who will shepherd My people Israel.”", ar: "لست الصغرى، بين ولايات يهوذا، لأنه منكِ يخرج مدبر، يرعى شعبي إسرائيل.\"" } },
      { kind: 'hymn', text: { en: "Oh what are these symphonies, of all these prophets, who prophesied with this one Spirit, for the coming of Christ.", ar: "يا لهذه الإتفاقات، الذي لأولئك الأنبياء، الذين تنبأوا بهذا الروح الواحد، من أجل مجيئ المسيح." } },
      { kind: 'hymn', text: { en: "This is He who is worthy of glory, with His good Father, and the Holy Spirit, both now and forever.", ar: "هذا الذي ينبغي له المجد، مع أبيه الصالح، والرُّوح القُدُس، منذ الآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Eighth Part", ar: "القطعة الثامنة" } },
      { kind: 'hymn', text: { en: "The One of the Trinity, co-essential to the Father, when He looked upon our tribulation, and our bitter slavery.", ar: "الواحد من الثالوث، المساوي للآب في الجوهر، لما نظر إلى مذلتنا، وعبوديتنا المرة." } },
      { kind: 'hymn', text: { en: "He bowed the heaven of heavens, and came to the womb of the Virgin, He became man like us, save for sin only.", ar: "طأطأ سموات السموات، وأتى إلى بطن العذراء، وصار إنساناً مثلنا، ما خلا الخطية وحدها." } },
      { kind: 'hymn', text: { en: "When He was born in Bethlehem, according to the prophecies, He saved and redeemed us, for we are His people.", ar: "لما وُلد في بيت لحم، كأخبار الأنبياء، أنقدنا وخلصنا، لأننا نحن شعبه." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'hymn', text: { en: "The Ninth Part", ar: "القطعة التاسعة" } },
      { kind: 'hymn', text: { en: "I saw a miracle that appeared in heaven, a woman is clothed with the sun, and the moon also, was under her feet.", ar: "رأيت آية ظهرت في السماء، إذ بإمرأة متسربلة، بالشمس والقمر أيضاً، تحت رجليها." } },
      { kind: 'hymn', text: { en: "And a crown of twelve stars, upon her head, being pregnant she cried out, in pain to give birth.", ar: "وإثنا عشر كوكباً، تكلل رأسها، وهي حُبلى تتمخض، صارخة لتلد." } },
      { kind: 'hymn', text: { en: "This is Mary, the new heaven on earth, the Sun of Righteousness, shines upon us from her.", ar: "هي مريم، السماء الجديدة التي على الأرض، المشرقة لنا منها، شمس البر." } },
      { kind: 'hymn', text: { en: "For the Sun that is clothing her, is our Lord Jesus Christ, and the moon under her feet, is John the Baptist.", ar: "لأن الشمس المتسربلة بها، هي ربنا يسوع المسيح، والقمر الذي تحت رجليها، هو يوحنا المعمدان." } },
      { kind: 'hymn', text: { en: "For the crown of twelve stars, upon her head are the twelve Apostles, who surround her, and honor her.", ar: "والإثنا عشر كوكباً، المكللة رأسها، هي الإثنا عشر رسولاً، يحيطون بها ويكرمونها." } },
      { kind: 'hymn', text: { en: "Therefore all you nations, let us glorify the Virgin, for she gave birth to God, and her virginity remained sealed.", ar: "فلهذا يا جميع الشعوب، نمجد العذراء، لأنها ولدت لنا الله، وبتوليتها مختومة." } },
      { kind: 'hymn', text: { en: "He did not cease to be divine, He came and became the Son of Man, for He is the true God, who came and saved us.", ar: "لم يزل إلهاً، أتى وصار إبن بشر، لكنه هو الإله الحقيقي، أتى وخلَّصنا." } },
      { kind: 'heading', text: { en: "The Thursday Theotokia Lobsh", ar: "لبش ثيؤطوكية الخميس" } },
      { kind: 'hymn', text: { en: "God the Invisible, who was before all ages, Moses was worthy to see, His glory upon the mountain.", ar: "الله الغير المنظور، قبل كل الدهور، إستحق أن يرى موسى، مجده على الجبل." } },
      { kind: 'hymn', text: { en: "For he saw the bush, and the fire in it, its branches did not burn, and its leaves were not damaged.", ar: "لأنه رأى العليقة، والنار مشتعلة فيها، ولم تحترق أغصانها، ولم يفسد ورقها." } },
      { kind: 'hymn', text: { en: "Though the fire was aflame, the bush did not burn, that is because God was within it, and talking to the prophet.", ar: "فالنار كانت تشتعل، في العليقة ولم تحترق، لأن الله داخلها، وهو يخاطب النبي." } },
      { kind: 'hymn', text: { en: "Saying “O Moses O Moses, O Moses the one I love, I am the God of your fathers, and there is no other besides me.", ar: "قائلاً \"يا موسى يا موسى، يا موسى الذي أنا أحبه، أنا هو إله آبائك، وليس آخر سواي." } },
      { kind: 'hymn', text: { en: "Take off your sandals, which are upon your feet, for the place where you are standing, is holy ground O prophet.", ar: "حِل الحذاء، الذي في رجليك، لأن الموضع الذي أنت واقف عليه، أرض مقدسة أيها النبي." } },
      { kind: 'hymn', text: { en: "Contemplate on the bush, and the fire within it, its branches did not burn, and its leaves were not damaged.”", ar: "تأمل العليقة، والنار مشتعلة فيها، ولم تحترق أغصانها، ولم يفسد ورقها.\"" } },
      { kind: 'hymn', text: { en: "This is a symbol of Mary, the undefiled virgin, from whom the Word of the Father, came and took flesh.", ar: "هي مثال لمريم، العذراء غير الدنسة، التي تجسد منها، كلمة الآب." } },
      { kind: 'hymn', text: { en: "Therefore we praise, with John the celibate, saying “Pure is this Bride, decorated for the Lamb.”", ar: "من أجل هذا نمدح، مع يوحنا البتول قائلين، \"طاهرة هي هذه العروس، التي زُينت للحمل.\"" } },
      { kind: 'hymn', text: { en: "Hail to you O Virgin, the very and true queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدتِ لنا عمانوئيل." } },
      { kind: 'hymn', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألِك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Introduction to the Difnar — Watos", ar: "مقدمة الدفنار — واطس" } },
      { kind: 'hymn', text: { en: "We worship the good Father, and His Son Jesus Christ, and the Spirit of comfort, the holy and coessential Trinity.", ar: "نسجد للآب الصالح، ويسوع المسيح إبنه، والروح المعزي، الثالوث القدوس المساوي." } },
      { kind: 'hymn', text: { en: "Hail to you O Virgin, the very and true queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدتِ لنا عمانوئيل." } },
      { kind: 'hymn', text: { en: "We have hope, in Saint Mary, that God will have mercy upon us, through her intercessions.", ar: "لنا رجاء، في القديسة مريم، أن الله يرحمنا، بشفاعاتها." } },
      { kind: 'hymn', text: { en: "All calmness, in the world, is through the prayers, of the holy Theotokos, Saint Mary the Virgin.", ar: "كل هدوء، في العالم، من قبل صلاة، والدة الإله الطاهرة، القديسة مريم العذراء." } },
      { kind: 'heading', text: { en: "Conclusion of the Watos Theotokias", ar: "ختام الثيؤطوكيات الواطس" } },
      { kind: 'prayer', text: { en: "O our Lord Jesus Christ, who carries the sin of the world, count us with Your sheep, those who are to Your right.", ar: "يا ربنا يسوع المسيح، حامل خطية العالم، أحسبنا مع خرافك، الذين عن يمينِك." } },
      { kind: 'prayer', text: { en: "And when You come again, in Your second fearful appearance, may we never fearfully hear, You say I do not know you.", ar: "عند ظهورِك الثاني، المخوف لا نسمع، برعدةٍ \"أنَّنِي، لَستُ أعرفكم.\"" } },
      { kind: 'prayer', text: { en: "But rather may we be made worthy, to hear the voice full of joy, of Your tender mercies, proclaiming and saying.", ar: "بَل نكون مُستحقين، لسماع صوتك الحنون، المُمْتلئ فرحاً، يصرخ قائلاً." } },
      { kind: 'prayer', text: { en: "“Come unto Me, O blessed of My Father, and inherit the life, that endures forever.”", ar: "\"تعالوا إليَّ، يا مُبارَكي أبي، رثوا الحياة، الدائمة إلى الأبد.\"" } },
      { kind: 'prayer', text: { en: "The martyrs will come, bearing their afflictions, and the righteous will come, bearing their virtues.", ar: "يأتي الشهداء، حاملين عذاباتهم، ويأتي الصدِّيقون، حاملين فضائلهم." } },
      { kind: 'prayer', text: { en: "The Son of God shall come in His glory, and His Father’s glory, to give unto everyone, according to his deeds which he has done.", ar: "يأتي إبن الله، في مجده ومجد أبيه، ويُجازي كل واحدٍ، كأعماله التي عملها." } },
      { kind: 'prayer', text: { en: "O Christ the Word of the Father, the only-begotten God, grant us Your peace, that is full of joy.", ar: "أيها المسيح كلمة الآب، الإله الوحيد الجنس، أعطنا سلامك، المملوء فرحاً." } },
      { kind: 'prayer', text: { en: "As You have given, to Your saintly Apostles, likewise also say to us, “My peace I give to You.", ar: "كما أعطيته، لرُسُلِكَ القديسين، قُلْ لنا مِثلهم، \"إنِّي أعطيكم سلامي." } },
      { kind: 'prayer', text: { en: "My peace which I have taken, from My Father, I leave unto you, both now and forever.”", ar: "سلامي أنا، الذي أخذته من أبي، أنا أتركه معكم، من الأن وإلى الأبد.\"" } },
      { kind: 'prayer', text: { en: "O the angel of this day, flying up with this hymn, remember us before the Lord, that He may forgive us our sins.", ar: "يا ملاك هذا اليوم الطائر، إلى العلو بهذه التسبحة، أُذكرنا أمام الرب، ليغفر لنا خطايانا." } },
      { kind: 'prayer', text: { en: "The sick heal them, those who have slept O Lord repose them, and all of our brothers in distress, help us my Lord and all of them.", ar: "المرضى أشفهم، الذين رقدوا يا رب نَيِّحهم، وأخواتنا الذين في كل شدة، يا ربي أعنا وإيَّاهم." } },
      { kind: 'prayer', text: { en: "May God bless us, and let us bless His holy name, and may His praise continually be, always upon our mouths.", ar: "يُبارِكنا الله، ولنُبارِك إسمه القدوس، في كل حين تسبحته، دائمة في أفواهنا." } },
      { kind: 'prayer', text: { en: "For blessed is the Father, the Son and the Holy Spirit, the perfect Trinity, we worship Him and glorify Him.", ar: "مُبارَك الآب والإبن، والرُّوح القُدُس، الثالوث الكامل، نسجد له ونُمجِّدهُ." } },
      { kind: 'heading', text: { en: "The Concluding Litany", ar: "طلبة الختام" } },
      { kind: 'litany', text: { en: "Kerie leysoun (Lord have mercy) is said three times before every part", ar: "يقال كيريي ليسون (يا رب إرحم) ثلاث مرات قبل كل ربع" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." } },
      { kind: 'litany', text: { en: "Kerie leysoun (3).", ar: "كيريي ليسون (3)." } },
      { kind: 'litany', text: { en: "O God have mercy on us.", ar: "يا الله إرحمنا." } },
      { kind: 'litany', text: { en: "O God hear us.", ar: "يا الله إسمعنا." } },
      { kind: 'litany', text: { en: "O God look to us.", ar: "يا الله أُنظر إلينا." } },
      { kind: 'litany', text: { en: "O God behold us.", ar: "يا الله إطَّلع علينا." } },
      { kind: 'litany', text: { en: "O God have compassion on us.", ar: "يا الله تراءف علينا." } },
      { kind: 'litany', text: { en: "We are Your people.", ar: "نحن شعبك." } },
      { kind: 'litany', text: { en: "We are Your creation.", ar: "نحن جبلتك." } },
      { kind: 'litany', text: { en: "Deliver us from our enemies.", ar: "نجنا من أعدائنا." } },
      { kind: 'litany', text: { en: "Deliver us from inflation.", ar: "نجنا من الغلاء." } },
      { kind: 'litany', text: { en: "We are Your servants.", ar: "نحن عبيدك." } },
      { kind: 'litany', text: { en: "You are the Son of God.", ar: "أنت إبن الله." } },
      { kind: 'litany', text: { en: "We believe in You.", ar: "آمنا بك." } },
      { kind: 'litany', text: { en: "For You have (risen/come) and saved us.", ar: "لأنك (قُمت/أتيت) وخلَّصتنا." } },
      { kind: 'litany', text: { en: "Visit us with Your salvation.", ar: "تعهدنا بخلاصك." } },
      { kind: 'litany', text: { en: "And forgive us our sins.", ar: "وإغفر لنا خطايانا." } },
      { kind: 'litany', text: { en: "Kerie leysoun.", ar: "كيريي ليسون." } },
      { kind: 'heading', text: { en: "The Morning Doxology", ar: "ذكصولوجية باكر" } },
      { kind: 'doxology', text: { en: "We worship the Father and the Son, and the Holy Spirit, hail to the church, the house of the angels.", ar: "نسجد للآب والإبن، والروح القدس، السلام للكنيسة، بيت الملائكة." } },
      { kind: 'doxology', text: { en: "Hail to the Virgin, who gave birth to our Savior, hail to Gabriel, who announced to her the good news.", ar: "السلام للعذراء، التي ولدت مخلصنا، السلام لغبريال، الذي بشرها." } },
      { kind: 'doxology', text: { en: "Hail to Michael, the archangel, hail to the twenty four, presbyters.", ar: "السلام لميخائيل، رئيس الملائكة، السلام للأربعة والعشرين، قسيساً." } },
      { kind: 'doxology', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the hosts, of the heavens.", ar: "السلام للشاروبيم، السلام للسارافيم، السلام لجميع الطغمات، السمائية." } },
      { kind: 'doxology', text: { en: "Hail to John, the great forerunner, hail to the, twelve Apostles.", ar: "السلام ليوحنا، السابق العظيم، السلام للإثنى عشر، رسولاً." } },
      { kind: 'doxology', text: { en: "Hail to our father Mark, the Evangelist, the destroyer, of the idols.", ar: "السلام لأبينا مرقس، الإنجيلي، مُبَدِد، الأوثان." } },
      { kind: 'doxology', text: { en: "Hail to Stephen, the first martyr, hail to George, the morning star.", ar: "السلام لإستفانوس، الشهيد الأول، السلام لجرجس، كوكب الصبح." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the martyrs, hail to Abba Antony, and the three Macarii.", ar: "السلام لجميع صفوف، الشهداء، السلام لأنبا أنطونيوس، والثلاثة المقارات." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the cross-bearers, hail to all the saints, who have pleased the Lord.", ar: "السلام لجميع صفوف، لُباس الصليب، السلام لجميع القديسين، الذين أرضوا الرب." } },
      { kind: 'doxology', text: { en: "Through their prayers, O Christ our King, have mercy upon us, in Your kingdom.", ar: "أيها المسيح ملكنا، بصلواتهم، إصنع معنا رحمة، في ملكوتك." } },
      { kind: 'doxology', text: { en: "(For Our Lord Jesus Christ)", ar: "(لأجل ربنا يسوع المسيح)" } },
      { kind: 'doxology', text: { en: "O true Light, that gives light, to every man, that comes into the world.", ar: "أيها النور الحقيقي، الذي يضئ، لكل إنسان، آتٍ إلى العالم." } },
      { kind: 'doxology', text: { en: "You came into the world, through Your love for man, and all the creation, rejoiced at Your coming.", ar: "أتيت إلى العالم، بمحبتك للبشر، وكل الخليقة، تهللت بمجيئك." } },
      { kind: 'doxology', text: { en: "You have saved Adam, from seduction, and delivered Eve, from the pangs of death.", ar: "خلصَّت آدم، من الغواية، وعتقت حواء، من طلقات الموت." } },
      { kind: 'doxology', text: { en: "You gave unto us, the Spirit of sonship, we praise and bless You, with Your angels.", ar: "أعطيتنا، روح النبوة، نسبحك ونباركك، مع ملائكتك." } },
      { kind: 'doxology', text: { en: "When the morning hour, comes upon us, O Christ our God, the true Light.", ar: "عندما يدخل، وقت باكر إلينا، أيها المسيح إلهنا، النور الحقيقي." } },
      { kind: 'doxology', text: { en: "Let the thought of light, shine within us, and do not let the darkness, of pain cover us.", ar: "فلتشرق فينا، حواس النور، ولا تغطينا، ظلمة الآلام." } },
      { kind: 'doxology', text: { en: "That we may praise You, with understanding, proclaiming and saying, with David.", ar: "لكي نسبحك، عقلياً، مع داود، صارخين، نحوك قائلين." } },
      { kind: 'doxology', text: { en: "\"My eyes have reached, the morning watch, that I may meditate, upon all Your words.\"", ar: "\"سبق أن بلغت، عيناي وقت السحر، لأتلو، جميع أقوالك.\"" } },
      { kind: 'doxology', text: { en: "Hear our voices, according to Your great mercy, save us O Lord our God, according to Your compassion.", ar: "إسمع صوتنا، كعظيم رحمتك، ونجنا أيها الرب إلهنا، حسب رأفاتك." } },
      { kind: 'doxology', text: { en: "O caring God, the Maker of all good things, who governs well, with His chosen ones.", ar: "يا الله المُهْتم، صانع الخيرات، مُدبر مُختاريه، حسناً." } },
      { kind: 'doxology', text: { en: "The strong Governor for those, who take refuge in Him, who longs for the salvation, and deliverance of everyone.", ar: "المدبر القوي، للملتجئين، المتشوق لخلاص، ونجاة كل أحد." } },
      { kind: 'doxology', text: { en: "Through Your goodness, You provided us the night, grant us to pass, this day without sin.", ar: "بصلاحك هيأت، لنا الليل، أنعم لنا بهذا اليوم، ونحن بغير خطية." } },
      { kind: 'doxology', text: { en: "That we may be worthy, to lift up our hands, before You without anger, or evil thoughts.", ar: "لنستحق أن نرفع، أيدينا إليك، أمامك بغير غضب، ولا فكر ردئ." } },
      { kind: 'doxology', text: { en: "At this dawn, make straight our coming in, and our going out, in the joy of Your protection.", ar: "في هذا السحر، سهل طرقنا، الداخلية والخارجية، بسترك المفرح." } },
      { kind: 'doxology', text: { en: "That we may proclaim, Your righteousness daily, and praise Your power, with David the prophet.", ar: "لننطق بعدلك، كل يوم، ونمجد قوتك، مع داود النبي." } },
      { kind: 'doxology', text: { en: "Saying \"In Your peace, O Christ our Savior, we slept and arose, for we have hoped in You.", ar: "قائلين \"بسلامك، أيها المسيح مخلصنا، رقدنا وقمنا، لأننا توكلنا عليك." } },
      { kind: 'doxology', text: { en: "Behold how beneficent, and how pleasant, it is for brethren, to dwell together in unity.\"", ar: "ها ما هو الحسن، وما هو الحلو، إلا إتفاق إخوة، ساكنين معاً.\"" } },
      { kind: 'doxology', text: { en: "United, in the true, evangelic love, like the Apostles.", ar: "مُتفقين، بمحبة حقيقية، إنجيلية، كمثل الرسل." } },
      { kind: 'doxology', text: { en: "It is like the fragrant oil, on the head of Christ, running down the beard, down to the feet.", ar: "مثل الطيب، على رأس المسيح، النازل على اللحية، إلى أسفل الرجلين." } },
      { kind: 'doxology', text: { en: "That anoints every day, the elders, the children and young men, and the deacons.", ar: "يمسح كل يوم، الشيوخ، والصبيان والفتيات، والخدام." } },
      { kind: 'doxology', text: { en: "Those whom the Holy Spirit, has attuned together, as a stringed instrument, always blessing God.", ar: "هؤلاء الذين، ألَّفهم الروح القدس معاً، مثل قيثارة مُسبحين، الله كل حين." } },
      { kind: 'doxology', text: { en: "By psalms and hymns, and spiritual songs, by day and by night, with an incessant heart.", ar: "بمزامير وتسابيح، وترانيم روحية، النهار والليل، بقلب لا يفتر." } },
      { kind: 'doxology', text: { en: "(For the Virgin)", ar: "(لأجل العذراء)" } },
      { kind: 'doxology', text: { en: "You are the Mother of the Light, the honored Mother of God, you have carried, the Uncircumscript Logos.", ar: "أنتِ يا أم النور، المكرمة والدة الإله، حملتِ الكلمة، غير المحوي." } },
      { kind: 'doxology', text: { en: "After you gave birth to Him, you remained a virgin, with praises and blessings, we magnify you.", ar: "ومن بعد أن ولدتِه، بقيتِ عذراء، نعظمكِ بتسابيح، وبركات." } },
      { kind: 'doxology', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والروح القدس، آتى وخلصنا." } },
      { kind: 'doxology', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً، نطلب أن نفوز، برحمة بشفاعاتك، لدى محب البشر." } },
      { kind: 'doxology', text: { en: "The select incense, of your virginity, ascended to the throne, of the Father.", ar: "البخور المختار، الذي لبتوليتك، صعد إلى، كرسي الآب." } },
      { kind: 'doxology', text: { en: "Better than the incense, of the Cherubim, and the Seraphim, O Virgin Mary.", ar: "أفضل من بخور، الشاروبيم، والسارافيم، يا مريم العذراء." } },
      { kind: 'doxology', text: { en: "Hail to the new heaven, whom the Father has created, and made a place of rest, for His beloved Son.", ar: "السلام للسماء الجديدة، التي صنعها الآب، وجعلها موضع راحة، لإبنه الحبيب." } },
      { kind: 'doxology', text: { en: "Hail to the royal throne, of Him who is, carried by, the Cherubim.", ar: "السلام للكرسي، الملوكي، الذي للمحمول، على الشاروبيم." } },
      { kind: 'doxology', text: { en: "Hail to the advocate, of our souls, you are indeed, the pride of our race.", ar: "السلام لشفيعة، نفوسنا، أنت بالحقيقة، فخر جنسنا." } },
      { kind: 'doxology', text: { en: "Intercede on our behalf, O full of grace, before our Savior, our Lord Jesus Christ.", ar: "إشفعي فينا، يا ممتلئة نعمة، أمام مخلصنا، ربنا يسوع المسيح." } },
      { kind: 'doxology', text: { en: "That He may confirm us, in the upright faith, and grant us the forgiveness, of our sins.", ar: "لكي يثبتنا، في الإيمان المستقيم، وينعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Angels)", ar: "(لأجل الملائكة)" } },
      { kind: 'doxology', text: { en: "Thousands of thousands, and myriads of myriads, of archangels, and holy angels.", ar: "ألوف ألوف، وربوات ربوات، رؤساء ملائكة، وملائكة مُقدسيين." } },
      { kind: 'doxology', text: { en: "They stand before, the throne, of the Pantocrator, proclaiming and saying.", ar: "وقوف أمام، كرسي، ضابط الكل، صارخين قائلين:" } },
      { kind: 'doxology', text: { en: "\"Holy holy, holy in truth, the glory and the honor, befit the Trinity.\"", ar: "\"قدوس قدوس، قدوس بالحقيقة، المجد والكرامة، يليقان بالثالوث.\"" } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the whole choir of the angels, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، جميع صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Apostles)", ar: "(لأجل الرسل)" } },
      { kind: 'doxology', text: { en: "Our fathers the Apostles, preached unto the nations, the Gospel, of Jesus Christ.", ar: "آباؤنا الرسل، بشروا في الأمم، بإنجيل، يسوع المسيح." } },
      { kind: 'doxology', text: { en: "Their voices went forth, into all the earth, and their words have reached, the ends of the world.", ar: "خرجت أصواتهم، إلى الأرض كلها، وبلغ كلامهم، إلى أقطار المسكونة." } },
      { kind: 'doxology', text: { en: "Through the prayers, of my masters the fathers the Apostles, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، سادتي الآباء الرسل، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Martyrs)", ar: "(لأجل الشهداء)" } },
      { kind: 'doxology', text: { en: "Unfading crowns, the Lord has placed, upon the whole choir, of the martyrs.", ar: "أكاليل غير مضمحلة، جعلها الرب، على جميع، صفوف الشهداء." } },
      { kind: 'doxology', text: { en: "He saved and delivered them, because they took refuge in Him, they celebrated with Him, in His kingdom.", ar: "أنقذهم وخلصهم، لأنهم إلتجأوا إليه، وعيدوا معه، في ملكوته." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the martyrs, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، جميع صفوف الشهداء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Saints)", ar: "(لأجل القديسين)" } },
      { kind: 'doxology', text: { en: "Your saints bless You, and they speak, of the glory, of Your kingdom.", ar: "قديسوك، يباركونك، وينطقون بمجد، ملكوتك." } },
      { kind: 'doxology', text: { en: "Your kingdom O my God, is an eternal kingdom, and Your Lordship, is unto all ages.", ar: "ملكوتك يا إلهي، ملكوت أبدي، وربوبيتك، إلى كل الأجيال." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the cross-bearers, the righteous and the just, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، كافة مصاف لابسي الصليب، والأبرار والصديقين، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Patriarchs and the Prophets)", ar: "(لأجل الآباء والأنبياء)" } },
      { kind: 'doxology', text: { en: "Hail to Elijah, the prophet of temperance, and Elisha, his elect disciple.", ar: "السلام لإيليا، النبي المتعفف، وإليشع، تلميذه المختار." } },
      { kind: 'doxology', text: { en: "The great Evangelist, of the land of Egypt, Mark the Apostle, the first prelate.", ar: "المبشر العظيم، في كورة مصر، مرقس الرسول، مدبرها الأول." } },
      { kind: 'doxology', text: { en: "You are the Mother of God, O Virgin Mary, ask Him on our behalf, to have mercy upon our race.", ar: "أنت هي أم الله، يا مريم العذراء، أُطلبي منه عنا، أن يرحم جنسنا." } },
      { kind: 'doxology', text: { en: "The great patriarch, our father Abba Severus, whose holy teachings, enlightened our minds.", ar: "البطريرك العظيم، أبونا أنبا ساويرس، الذي أنارت تعاليمه، المقدسة عقولنا." } },
      { kind: 'doxology', text: { en: "Our father the confessor, Abba Dioscorus, defended the faith, against the heretics.", ar: "أبونا المعترف، أنبا ديسقوروس، حارب عن الإيمان، ضد الهراطقة." } },
      { kind: 'doxology', text: { en: "And all of our fathers, who have pleased the Lord, may their holy blessings, be a guard unto us.", ar: "وكل آبائنا، الذين أرضوا الرب، بركتهم المقدسة، تكون لنا حارساً." } },
      { kind: 'doxology', text: { en: "Through their prayers, O God grant us, the forgiveness of our sins, and give us peace.", ar: "بصلواتهم، إنعم لنا يا الله، بمغفرة خطايانا، وأعطنا سلاماً." } }
    ],
  },
  {
    id: "psalmody-midnight-friday",
    title: { en: "Friday Midnight Praises", ar: "تسبحة نصف الليل ليوم الجمعة" },
    blocks: [
      { kind: 'note', text: { en: "The complete fixed annual Friday (Watos) Midnight Psalmody.", ar: "النصوص الثابتة الكاملة للإبصلمودية السنوية لنصف الليل ليوم الجمعة (واطس)." } },
      { kind: 'heading', text: { en: "Ten-theno", ar: "تين ثينو" } },
      { kind: 'prayer', text: { en: "Arise O children of the light, let us praise the Lord of hosts.", ar: "قوموا يا بني النور، لنسبح رب القوات." } },
      { kind: 'prayer', text: { en: "That He may grant us the salvation of our souls.", ar: "لكي ينعم لنا بخلاص نفوسنا." } },
      { kind: 'prayer', text: { en: "Whenever we stand before You in the flesh.", ar: "عندما نقف أمامك جسدياً." } },
      { kind: 'prayer', text: { en: "Cast away from our minds the slumber of sleep.", ar: "إنزع عن عقولنا نوم الغفلة." } },
      { kind: 'prayer', text: { en: "Grant us sobriety O Lord, that we may know how to stand before You at times of prayer.", ar: "أعطنا يا رب يقظة، لكي نفهم أن نقف أمامك وقت الصلاة." } },
      { kind: 'prayer', text: { en: "And ascribe unto You the befitting glorification, and win the forgiveness of our many sins. Glory be to You O Lover of Mankind.", ar: "ونرسل لك إلى فوق التمجيد اللائق، ونفوز بغفران خطايانا الكثيرة. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Behold bless the Lord all you servants of the Lord. Glory be to You O Lover of Mankind.", ar: "ها باركوا الرب يا عبيد الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "You who stand in the house of the Lord, in the courts of the house of our God. Glory be to You O Lover of Mankind.", ar: "القائمين في بيت الرب، في ديار بيت إلهنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "By night lift up your hands O you saints and bless the Lord. Glory be to You O Lover of Mankind.", ar: "بالليالي إرفعوا أيديكم إلى فوق أيها القديسون باركوا الرب. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "The Lord bless you from Zion, who created heaven and earth. Glory be to You O Lover of Mankind.", ar: "يباركك الرب من صهيون، الذي خلق السماء والأرض. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my cry come before You O Lord, give me understanding according to Your word. Glory be to You O Lover of Mankind.", ar: "فلتدن وسيلتي قدامك يا رب، كقولك فهمني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my supplication come before You, deliver me according to Your word. Glory be to You O Lover of Mankind.", ar: "ليدخل إبتهالي أمامك، ككلمتك أحيني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My lips shall overflow with praise, when You have taught me Your statutes. Glory be to You O Lover of Mankind.", ar: "تفيض شفتاي السُبح، إذا ما علمتني حقوقك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "My tongue shall speak of Your words for all Your commandments are righteous. Glory be to You O Lover of Mankind.", ar: "لساني يجيب بأقوالك لأن جميع وصاياك هي حق. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let Your hand help me for I have chosen Your precepts. Glory be to You O Lover of Mankind.", ar: "لتكن يدك لتخلصني لأني إشتهيت وصاياك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have longed for Your salvation O Lord, and Your Law is my delight. Glory be to You O Lover of Mankind.", ar: "إشتقت إلى خلاصك يا رب، وناموسك هو تلاوتي. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let my soul live and it shall praise You, and let Your judgments help me. Glory be to You O Lover of Mankind.", ar: "تحيا نفسي وتسبحك، وأحكامك تعينني. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "I have gone astray like a lost sheep, seek Your servant for I do not forget Your commandments. Glory be to You O Lover of Mankind.", ar: "ضللت مثل الخروف الضال، فأُطلب عبدك لأني لوصاياك لم أنس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Now and forever and unto the age of all ages Amen. Glory be to You O Lover of Mankind.", ar: "الآن وكل أوان وإلى دهر الدهور آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to the Father and the Son and the Holy Spirit, now and forever and unto all the ages Amen. Glory be to You O Lover of Mankind.", ar: "المجد للآب والإبن والروح القدس منذ الآن وإلى أبد الأبدين كلها آمين. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O good One the Lover of Mankind, glory be to Your Mother the Virgin and all Your saints. Glory be to You O Lover of Mankind.", ar: "المجد لك يا محب البشر الصالح، المجد لأُمك العذراء وجميع قديسيك. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Glory be to You O only-begotten One, O holy Trinity have mercy upon us. Glory be to You O Lover of Mankind.", ar: "المجد لك أيها الوحيد، أيها الثالوث القدوس إرحمنا. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "Let God arise and let all His enemies be scattered and let all that hate His holy name flee from before His face. Glory be to You O Lover of Mankind.", ar: "ليقم الله ولتتبدَّد جميع أعدائه وليهرب من قدام وجهه كل مُبغضي إسمه القدوس. المجد لك يا محب البشر." } },
      { kind: 'prayer', text: { en: "As for Your people let them be blessed, a thousand thousand fold and ten thousand ten thousand fold, doing Your will.", ar: "وأما شعبك فليكن بالبركة، ألوف ألوف وربوات ربوات، يصنعون إرادتك." } },
      { kind: 'prayer', text: { en: "O Lord open my lips, and my mouth shall declare Your praise.", ar: "يا رب إفتح شفتيَ ولينطق فمي بتسبحتك." } },
      { kind: 'heading', text: { en: "The First Hoos", ar: "الهوس الأول" } },
      { kind: 'hymn', text: { en: "Then Moses and the children of Israel sang this song to the Lord and spoke saying, \"I will sing to the Lord for He has triumphed gloriously.\"", ar: "حينئذ سبح موسى وبنو إسرائيل بهذه التسبحة للرب وقالوا، \"فلنسبح للرب لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider He has thrown into the sea. The Lord is my strength and song, and He has become my salvation.", ar: "الفَرس وراكبه طرحهما في البحر. مُعيني وساتري، صار لي خلاصاً." } },
      { kind: 'hymn', text: { en: "He is my God and I will glorify Him, my father´s God and I will exalt Him.", ar: "هذا هو إلهي فأمجده، إله أبي فأرفعه." } },
      { kind: 'hymn', text: { en: "The Lord is a Man of war, the Lord is His name. Pharaoh's chariots and his army He has cast into the sea.", ar: "الرب مكسر الحروب، الرب إسمه. مركبات فرعون وكل قوته طرحهما في البحر." } },
      { kind: 'hymn', text: { en: "His chosen captains also are drowned in the Red Sea.", ar: "ركباناً منتخبين ذي ثلاث جنبات غرقهم في البحر الأحمر." } },
      { kind: 'hymn', text: { en: "The depths have covered them; they sank to the bottom as a stone.", ar: "غطاهم الماء، إنغمسوا إلى العمق مثل الحجر." } },
      { kind: 'hymn', text: { en: "Your right hand O Lord has become glorious in power. Your right hand O Lord has dashed the enemy in pieces.", ar: "يمينك يا رب تمجدت بالقوة. يدك اليمنى يا إلهي أهلكت أعداءك." } },
      { kind: 'hymn', text: { en: "And in the greatness of Your excellence, You have overthrown those who rose up against You, You sent forth Your wrath, it consumed them like stubble.", ar: "بكثرة مجدك، سحقت الذين يقاوموننا، أرسلت غضبك، فأكلهم مثل الهشيم." } },
      { kind: 'hymn', text: { en: "And with the blast of Your nostrils the waters were gathered together, the flood stood upright like a wall, and the depths were congealed in the heart of the sea.", ar: "وبروح غضبك وقف الماء، وإرتفعت الماء مثل السور، وجمدت الأمواج في وسط البحر." } },
      { kind: 'hymn', text: { en: "The enemy said, \"I will pursue, I will overtake, I will divide the spoil, my lust shall be satisfied upon them, I will draw my sword and my hand shall destroy them.\"", ar: "قال العدو، \"إني أسرع فأدرك، وأقسم الغنائم، وأشبع نفسي، وأقتل بسيفي ويدي تتسلط.\"" } },
      { kind: 'hymn', text: { en: "You blew with Your wind, the sea covered them, they sank like lead in the mighty waters.", ar: "أرسلت روحك، فغطاهم البحر، وغطسوا إلى أسفل كالرصاص في مياه كثيرة." } },
      { kind: 'hymn', text: { en: "Who is like You O Lord among the gods? Who is like You, glorified in His saints, amazing in glory, performing wonders.", ar: "من يشبهك في الآلهة. يا رب من يشبهك، مُمجداً في قديسيك، متعجباً منك بالمجد، صانعاً عجائب." } },
      { kind: 'hymn', text: { en: "You stretched out Your right hand, the earth swallowed them. You in Your mercy have led forth the people whom You have redeemed, You have guided them in Your strength, to Your holy habitation.", ar: "مددت يمينك فإبتلعتهم الأرض. هديت شعبك بالحقيقة، هذا الذي إخترته، وقويته بتعزيتك، إلى موضع راحة قدسك." } },
      { kind: 'hymn', text: { en: "The people will hear and be afraid, sorrow will take hold of the inhabitants of Palestine.", ar: "سمعت الأمم وغضبت، والمخاض أخذ سكان فلسطين." } },
      { kind: 'hymn', text: { en: "Then the dukes of Edom will be amazed, the mighty men of Moab trembling will take hold of them.", ar: "حينئذ أسرع وُلاة أدوم، ورؤساء المؤابيين أخذتهم الرعدة." } },
      { kind: 'hymn', text: { en: "All the inhabitants of Canaan will melt away, fear and dread will fall on them.", ar: "ذاب كل سكان كنعان، وأتت عليهم الرعدة والخوف." } },
      { kind: 'hymn', text: { en: "By the greatness of Your arm they will be as still as stone, till Your people pass over O Lord, till Your people pass over whom You have purchased.", ar: "بكثرة ساعدك فليصيروا كالحجر، حتى يجتاز شعبك يا رب، حتى يجتاز شعبك هذا الذي إقتنيته." } },
      { kind: 'hymn', text: { en: "You will bring them in and plant them in the mountain of Your inheritance, in the place O Lord, which You have made for You to dwell in.", ar: "أدخلهم وأغرسهم على جبل ميراثك، وفي مسكنك المُعَد، هذا الذي صنعته يا رب." } },
      { kind: 'hymn', text: { en: "In Your sanctuary O Lord which Your hands have established, the Lord shall reign forever and ever.", ar: "موضعك المقدس يا رب الذي أعددته يداك، يا رب تمَلُك منذ الأزل والآن وإلى الأبد." } },
      { kind: 'hymn', text: { en: "For the horses of pharaoh went with his chariots and his horsemen into the sea.", ar: "لأنه قد دخل إلى البحر خيل فرعون ومركباته وفرسانه." } },
      { kind: 'hymn', text: { en: "And the Lord brought back the waters of the sea upon them, but the children of Israel went on dry land in the midst of the sea.", ar: "والرب غمرهم بماء البحر، أما بنو إسرائيل فكانوا يمشون على اليابسة في وسط البحر." } },
      { kind: 'hymn', text: { en: "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand, and all the women went out after her with timbrels and with praises.", ar: "فأخذت مريم النبية، أخت هرون، الدُف بيديها، وخرج في إثرها جميع النسوة بالدُفوف والتسابيح." } },
      { kind: 'hymn', text: { en: "And Miriam answered them saying, \"Sing to the Lord, for He has triumphed gloriously.\"", ar: "وبدأت مريم في مقدمتهنَّ تقول، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "The horse and its rider, He has thrown into the sea. \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "الفرس ورُاكب الفرس، طرحهما في البحر. \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'heading', text: { en: "The First Hoos Lobsh", ar: "لبش الهوس الأول" } },
      { kind: 'hymn', text: { en: "With the split, the waters of the sea split, and the very deep, became a walkway.", ar: "قطعاً إنقطع، ماء البحر، والعمق العميق، صار مَسلكاً." } },
      { kind: 'hymn', text: { en: "A hidden earth, was shone upon by the sun, and an untrodden road, was walked upon.", ar: "أرض غير ظاهرة، أشرقت الشمس عليها، وطريق غير مسلوكة، مشوا عليها." } },
      { kind: 'hymn', text: { en: "The flowing water, stood still, by a miraculous, act of wonder.", ar: "ماء مُنحل، وقف، بفِعل عجيب، مُعِجز." } },
      { kind: 'hymn', text: { en: "Pharaoh and his chariots, were drowned, and the children of Israel, crossed the sea.", ar: "غرق فرعون، ومركباته، وعبر بنو إسرائيل، البحر." } },
      { kind: 'hymn', text: { en: "And in front of them was, Moses the prophet praising, until he brought them, to the wilderness of Sinai.", ar: "وكان موسى النبي، يسبح قدامهم، حتى أدخلهم، برية سيناء." } },
      { kind: 'hymn', text: { en: "And they were praising God, with this new psalmody, saying \"Let us sing to the Lord, for He has triumphed gloriously.\"", ar: "وكانوا يسبحون الله، بهذه التسبحة الجديدة قائلين، \"فلنسبح الرب، لأنه بالمجد قد تمجد.\"" } },
      { kind: 'hymn', text: { en: "Through the prayers, of Moses the archprophet, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، موسى رئيس الأنبياء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "We worship You O Christ, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "نسجد لك أيها المسيح، مع أبيك الصالح، والروح القدس، لأنك (قُمتأتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Second Hoos", ar: "الهوس الثاني" } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord for He is good, Alleluia His mercy endures forever.", ar: "أُشكروا الرب لأنه صالح وخيِّر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of gods, Alleluia His mercy endures forever.", ar: "أُشكروا إله الآلهة، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords, Alleluia His mercy endures forever.", ar: "أُشكروا رب الأرباب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who alone does great wonders, Alleluia His mercy endures forever.", ar: "الصانع العجائب العظام وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who by wisdom made the heavens, Alleluia His mercy endures forever.", ar: "الذي خلق السموات بفهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who stretched out the earth above the waters, Alleluia His mercy endures forever.", ar: "الذي ثبَّت الأرض على المياه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who made great lights, Alleluia His mercy endures forever.", ar: "الذي خلق نيرين عظيمين وحده، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The sun to rule by day, Alleluia His mercy endures forever.", ar: "الشمس لحكم النهار، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "The moon and stars to rule by night, Alleluia His mercy endures forever.", ar: "القمر والنجوم لحكم الليل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote Egypt in their firstborn, Alleluia His mercy endures forever.", ar: "الذي ضرب المصريين مع أبكارهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And brought out Israel from among them, Alleluia His mercy endures forever.", ar: "وأخرج إسرائيل من وسطهم، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "With a strong hand and with a stretched out arm, Alleluia His mercy endures forever.", ar: "بيد عزيزة وذراع عالية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who divided the Red Sea into parts, Alleluia His mercy endures forever.", ar: "الذي شق البحر الأحمر إلى أقسام، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And made Israel to pass through the midst of it, Alleluia His mercy endures forever.", ar: "وأجاز إسرائيل في وسطه، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "But overthrew pharaoh and his hosts in the Red Sea, Alleluia His mercy endures forever.", ar: "وطرح فرعون وكل قوته في البحر الأحمر، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who led His people through the wilderness, Alleluia His mercy endures forever.", ar: "الذي أخرج شعبه إلى البرية، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who retrieved water from a rock, Alleluia His mercy endures forever.", ar: "الذي أخرج ماء من صخرة صماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "To Him who smote great kings, Alleluia His mercy endures forever.", ar: "الذي ضرب ملوكاً عُظماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And slew famous kings, Alleluia His mercy endures forever.", ar: "وقتل ملوكاً عجيبين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Sihon the king of the Amorites, Alleluia His mercy endures forever.", ar: "سيحون ملك الأموريين، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And Og the king of Bashan, Alleluia His mercy endures forever.", ar: "وعوج ملك باشان، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And gave their lands for a heritage, Alleluia His mercy endures forever.", ar: "أعطى أرضهم ميراثاً، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "A heritage unto Israel His servant, Alleluia His mercy endures forever.", ar: "ميراثاً لعبده إسرائيل، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who remembered us in our low estate, Alleluia His mercy endures forever.", ar: "في تواضعنا ذكرنا الرب، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "And has redeemed us from our enemies, Alleluia His mercy endures forever.", ar: "وخلصنا من أيدي أعدائنا، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "Who gives food to all flesh, Alleluia His mercy endures forever.", ar: "الذي يعطي طعاماً لكل جسد حي، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the God of heaven, Alleluia His mercy endures forever.", ar: "إحمدوا إله السماء، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'hymn', text: { en: "O give thanks to the Lord of lords for He is good, Alleluia His mercy endures forever.", ar: "إحمدوا رب الأرباب لأنه طيب وصالح، هلليلويا لأن إلى الأبد رحمته." } },
      { kind: 'heading', text: { en: "The Second Hoos Lobsh", ar: "لبش الهوس الثاني" } },
      { kind: 'hymn', text: { en: "Let us give thanks, to Christ our God, with David the prophet, and psalmist.", ar: "فلنشكر، المسيح إلهنا، مع المرتل، داود النبي." } },
      { kind: 'hymn', text: { en: "For He has made the heavens, and all its hosts, and established the earth, on the waters.", ar: "لأنه خلق السموات، وجنودها، وأسَّس الأرض، على المياه." } },
      { kind: 'hymn', text: { en: "These two great stars, the sun and the moon, He has made to enlighten, the firmament.", ar: "هذان الكوكبان العظيمان، الشمس والقمر، جعلهما ينيران، في الفلك." } },
      { kind: 'hymn', text: { en: "He brought forth the winds, out of His treasure box, He breathed unto the trees, and they blossomed.", ar: "أخرج الرياح، من خباياها، نفخ في الأشجار، حتى أزهرت." } },
      { kind: 'hymn', text: { en: "He caused the rain to fall, upon the face of the earth, and it sprouted, and gave its fruit.", ar: "أمطرا مطراً، على وجه الأرض، حتى أنبتت، وأعطت ثمرها." } },
      { kind: 'hymn', text: { en: "He brought forth water, out of a rock, and gave it to His people, in the wilderness.", ar: "أخرج ماء، من صخرة صماء، وسقى شعبه، في البرية." } },
      { kind: 'hymn', text: { en: "He made man, in His image, and His likeness, that he may praise Him.", ar: "صنع الإنسان، كشبهه، وصورته، لكي يباركه." } },
      { kind: 'hymn', text: { en: "Let us praise Him, and exalt His name, and give thanks to Him, His mercy endures forever.", ar: "فلنسبحه، ونرفع إسمه، ونشكره لأن رحمته، كائنة إلى الأبد." } },
      { kind: 'hymn', text: { en: "Through the prayers, of David the psalmist, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، المرتل داود، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله، القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Through the intercessions, of all the heavenly hosts, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، كل صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "Blessed are You indeed, with Your good Father, and the Holy Spirit, for You have (risen/come) and saved us.", ar: "مبارك أنت بالحقيقة، مع أبيك الصالح، والروح القدس، لأنك (قُمت/أتيت) وخلصتنا." } },
      { kind: 'heading', text: { en: "The Third Hoos", ar: "الهوس الثالث" } },
      { kind: 'hymn', text: { en: "Blessed are You O Lord God of our fathers, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الرب إله أبائنا، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed is Your holy name and Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك إسم مجدك القدوس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the holy temple of Your glory, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في هيكل مجدك المقدس، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You who beholds the depths and sits upon the Cherubim, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت أيها الناظر إلى الأعماق الجالس على الشاروبيم، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You on the throne of Your kingdom, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت على عرش مُلكك، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Blessed are You in the firmament of heaven, and exceedingly to be blessed and exalted above all forever.", ar: "مبارك أنت في فلك السماء، ومتزايد بركة ومتزايد علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you works of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع أعمال الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السموات، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you angels of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا جميع ملائكة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you waters above the heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع المياه التي فوق السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you powers of the Lord, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع قوات الرب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O sun and moon, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها الشمس والقمر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you stars of heaven, praise Him and exalt Him above all forever.", ar: "باركي الرب يا سائر نجوم السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you rain and dew, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأمطار مع الأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you clouds and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها السُحب والرياح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you spirits, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع الأرواح، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O fire and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيتها النار والحرارة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O cold and heat, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والحر، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you dew and winds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأهوية والأنداء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you nights and days, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الليالي والأيام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O light and darkness, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها النور والظلمة، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O frost and cold, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها البرد والصقيع، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O snow and ice, praise Him and exalt Him above all forever.", ar: "باركا الرب أيها الجليد والثلج، سبحاه وزيداه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you lightnings and clouds, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البروق والسحب، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all the earth, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الأرض كلها، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you mountains and all hills, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الجبال وجميع الآكام، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you things that spring up on the earth, praise Him and exalt Him above all forever.", ar: "بارك الرب يا جميع ما يَنبت على وجه الأرض، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you fountains, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الينابيع، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you seas and rivers, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها البحار والأنهار، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you whales and all that moves in the waters, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الحيتان وجميع ما يتحرك في الماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you birds of the sky, praise Him and exalt Him above all forever.", ar: "باركي الرب يا جميع طيور السماء، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you wild beasts and cattle, praise Him and exalt Him above all forever.", ar: "باركي الرب أيتها الوحوش وكل البهائم، سبحيه وزيديه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you sons of men, worship the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا بني البشر، وأُسجدوا للرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Israel, praise Him and exalt Him above all forever.", ar: "بارك الرب يا إسرائيل، سبحه وزده علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you priests of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا كهنة الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you servants of the Lord, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عبيد الرب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you spirits and souls of the just, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا أرواح وأنفس الصديقين، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you holy and humble of heart, praise Him and exalt Him above all forever.", ar: "باركوا الرب أيها القديسون والمتواضعو القلوب، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all\nforever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "The Third Hoos — Esmo Epchois", ar: "الهوس الثالث — إسمو إبشويس" } },
      { kind: 'hymn', text: { en: "Bless the Lord O Hananiah Azariah Mishael and Daniel, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا حنانيا وعزاريا وميصائيل ودانيال، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Bless the Lord O you who worship the Lord the God of our fathers, praise Him and exalt Him above all forever.", ar: "باركوا الرب يا عابدي الرب إله أبائنا، سبحوه وزيدوه علواً إلى الآباد." } },
      { kind: 'heading', text: { en: "Psali for the Three Saintly Children", ar: "إبصالية للثلاثة فتية القديسين" } },
      { kind: 'hymn', text: { en: "O sing unto Him who was crucified, buried and resurrected, who trampled and abolished death, praise Him and exalt Him above all.\nTake off the old man, and put on the new and superior one, come closer to greatness of mercy, praise Him and exalt Him above all.", ar: "رتلوا للذي صُلب عنا، وقُبر وقام، وأبطل الموت وأهانه، سبحوه وزيدوه علواً.\nإخلعوا الإنسان العتيق، وألبسوا الجديد الفاخر، وإقتربوا إلى عِظَم الرحمة، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "All you Christian people, the priests and the deacons, glorify the Lord for He is worthy, praise Him and exalt Him above all.\nCome to us O three children, whom Christ our God has lifted, and from the Devil has delivered, praise Him and exalt Him above all.", ar: "يا جنس المسيحيين، القسوس والشمامسة، أعطوا مجداً للرب لأنه مستوجب، سبحوه وزيدوه علواً.\nهَلُمَّ إلينا أيها الثلاثة فتية، الذين رفعهم المسيح إلهنا، وأنقذهم من إبليس، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "For the sake of your God the Messiah, the Giver of all good things, come unto us O Hananiah, praise Him and exalt Him above all.\nO Azariah the zealot, morning and noon and the evening, glorify the power of the Trinity, praise Him and exalt Him above all.", ar: "من أجل إلهك ماسيا، المانح الإحسان، هَلُمَّ إلينا يا حنانيا، سبحوه وزيدوه علواً.\nيا عزاريا الغيور، عشية وبكرة والظهيرة، أعط مجداً لقوة الثالوث، سبّحه وزده علواً." } },
      { kind: 'hymn', text: { en: "Behold Emmanuel [our Lord], is now in our midst O Mishael, proclaim with the voice of joy, praise Him and exalt Him above all.\nGather now and persevere, and proclaim with the priests, bless the Lord all His works, praise Him and exalt Him above all.", ar: "فها هوذا عمانوئيل، في وسطنا يا ميصائيل، تكلم بصوت التهليل، سبّحه وزده علواً.\nإجتمعوا وثابروا جميعاً، تكلموا مع القسوس، وسبحي الرب يا جميع أعماله، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "The heavens declare the glory, of God until this day, O you angels whom He has made, praise Him and exalt Him above all.\nNow all you powers of the Lord, bless His honored name, O sun and moon and all the stars, praise Him and exalt Him above all.", ar: "ها السموات تنطق بمجد الله، إلى هذا اليوم، يا أيها الملائكة الذين أنشأهم، سبحوه وزيدوه علواً.\nوالآن يا قوات الرب، باركوا إسمه الكريم، أيتها الشمس والقمر والنجوم، سبحيه وزيديه علواً." } },
      { kind: 'hymn', text: { en: "And also you rain and dew, sing praises unto our Savior, for He is the God of our fathers, praise Him and exalt Him above all.\nGlorify the Lord O clouds and winds, together with the souls and the spirits, O you cold and fire and heat, praise Him and exalt Him above all.", ar: "وأيضاً أيتها الأمطار والأنداء، إمدحي مخلصنا، لأنه هو إله آبائنا، سبحيه وزيديه علواً.\nأعطي مجداً أيتها السحب معاً، والأهوية والنفوس والأرواح، والبرد والنار والحرارة، سبحيه وزيده علوا." } },
      { kind: 'hymn', text: { en: "You also nights and days, light and darkness and lightning, glorify the Lover of Mankind, praise Him and exalt Him above all.\nYou trees and all that springs on the earth, and all that moves in the sea, mountains and the forests, praise Him and exalt Him above all.", ar: "أيتها الليالي والأيام أيضاً، والنور والظلمة والبروق، قائلة المجد لك يا محب البشر، سبحوه وزيدوه علواً.\nأيتها الأشجار وجميع ما ينبُت، في الأرض وكل ما يتحرك، في المياه والجبال والغياض، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Praise without ceasing, the Lord the King of the kings, O you rivers and seas, praise Him and exalt Him above all.\nAnd we also seeing them, let us say with all these things, bless the Lord all you birds, praise Him and exalt Him above all.", ar: "وأيضاً سبحي بغير فتور، الرب ملك الملوك، أيتها البحار والأنهار، سبحيه وزيديه علواً.\nهكذا نحن إذ ننظر إليهم، فلنقل مع هذه الموجودات جميعها، باركي الرب يا جميع الطيور، سبحيه وزيده علواً." } },
      { kind: 'hymn', text: { en: "O snow and ice, cattle and wild beasts, bless the Lord of lords, praise Him and exalt Him above all.\nBless the Lord as befits Him, and not like the heretics, all you sons of men, praise Him and exalt Him above all.", ar: "أيها الجليد والثلج، والبهائم والوحوش، باركي رب الأرباب، سبحيه وزيديه علواً.\nسبحوا الرب كما يليق به، وليس كالمخالفين، يا أبناء البشر، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "O Israel offer before Him, honor and glory in a joyful voice, all you priests of Emmanuel, praise Him and exalt Him above all.\nYou servants of the true God, the souls of the righteous, and the humble and the charitable, praise Him and exalt Him above all.", ar: "مجداً وإكراماً قدم أمامه، يا إسرائيل بصوت التهليل، يا كهنة عمانوئيل، سبحوه وزيدوه علواً.\nيا خدام الله الحقيقي، وأنفس الأبرار، المتواضعين المحبين، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "God my God is the One, who saved you from danger, O Sedrach Misach and Abednago, praise Him and exalt Him above all.\nHurry with great haste, O you righteous of the Lord, and all the creatures He has made, praise Him and exalt Him above all.", ar: "الله إلهي أنا، هو مخلصكم من الخطر، يا سدراك وميساك وأبدناغو، سبحوه وزيدوه علوا.\nأسرعوا بحرص عظيم، يا أتقياء الرب، وكل الطبائع التي صنعها، سبحوه وزيدوه علواً." } },
      { kind: 'hymn', text: { en: "Coolness and repose without ceasing, grant unto all of us, that we may joyfully proclaim, praise Him and exalt Him above all.\nAnd also Your poor servant Sarkis, make him without condemnation, that he may join all those and say, praise Him and exalt Him above all.", ar: "برودة ونياحاً أعطنا، كلنا بغير إنقطاع، لنقول بتمتُع، سبحوه وزيدوه علواً.\nكذلك عبدك المسكين سركيس، إجعله بغير دينونة، ليقول مع هؤلاء كشريك، سبحوه وزيدوه علواً." } },
      { kind: 'heading', text: { en: "Ten-oueh Ensok", ar: "تين أويه إنسوك" } },
      { kind: 'hymn', text: { en: "We follow You with all our hearts, and fear You, and we seek Your face, O God do not forsake us.", ar: "نتبعك بكل قلوبنا، ونخافك، ونطلب وجهك، يا الله لا تخزنا." } },
      { kind: 'hymn', text: { en: "But rather deal with us, according to Your meekness, and according to Your great mercy, O Lord help us.", ar: "بل إصنع معنا، بحسب دعتك، وكثرة رحمتك، يا رب أعنَّا." } },
      { kind: 'hymn', text: { en: "May our prayers ascend to You, O our Master, like burnt offerings of lambs, and fat calves.", ar: "فلتصعد صلاتنا، أمامك يا سيدنا، مثل محرقات كباش، وعجول سِمان." } },
      { kind: 'hymn', text: { en: "Do not forget the covenant, which You have made with our fathers, Abraham Isaac and Jacob, Israel Your saint.", ar: "لا تنس العهد الذي، قطعته مع آبائنا، إبراهيم وإسحق ويعقوب، إسرائيل قديسك." } },
      { kind: 'hymn', text: { en: "Bless the Lord all you nations, the tribes and all kinds of tongues, praise Him and glorify Him, above all forever.", ar: "باركوا الرب يا جميع الشعوب، والقبائل ولغات الألسن، سبحوه ومجدوه، وزيدوه علواً إلى الآباد." } },
      { kind: 'hymn', text: { en: "Pray to the Lord on our behalf, O three saintly children, Sedrach Misach and Abednego, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة فتية القديسين، سدراك وميساك وأبدناغو، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Commemoration of the Saints", ar: "مجمع القديسين" } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the Lady of us all the Mother of God, Mary the Mother of our Savior, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، يا سيدتنا كلنا السيدة والدة الإله، مريم أُم مخلصنا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Michael and Gabriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، ميخائيل وغبريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Raphael and Souriel, that He may forgive us our sins.", ar: "إشفعا فينا (أمام الرب)، يا رئيسي الملائكة الطاهرين، رافائيل وسوريال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O holy archangels, Sedakiel Sarathiel and Ananiel, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا رؤساء الملائكة الأطهار، سداكيال وسراتيال وأنانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O thrones dominions and powers, the Cherubim and the Seraphim, that He may forgive us our sins.", ar: "إشفعي فينا (أمام الرب)، أيتها الكراسي والأرباب والقوات، والشيروبيم والسرافيم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O four incorporeal beasts, the ministering flames of fire, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها الأربعة الحيوانات غير المتجسدين، الخدام الملتهبين ناراً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O priests of the truth, the twenty four presbyters, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، يا كهنة الحق، الأربعة والعشرين قسيساً، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O angelic hosts, and all the heavenly multitudes, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها العساكر الملائكية، والطغمات السمائية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lords the fathers the patriarchs, Abraham Isaac and Jacob, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء البطاركة، إبراهيم وإسحق ويعقوب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O perfect man, the righteous and just Enoch, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الرجل الكامل، البار أخنوخ الصديق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Elijah the tishbite, and Elisha his disciple, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيليا التسبيتي، وإليشع تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Moses the archprophet, and Isaiah and Jeremiah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا موسى رئيس الأنبياء، وأشعياء وأرميا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O David the psalmist, Ezekiel and Daniel, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا داود المرتل، وحزقيال ودانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Joachim Anna and Joseph the elder, and the righteous Job Joseph and Nicodemus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا يواقيم وحنِّة ويوسف الشيخ، والصديق أيوب ويوسف ونيقوديموس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Melchizedek and Aaron, and Zacharias and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ملكي صادق وهرون، وزكريا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the prophets, and all the righteous and the just, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الأنبياء، والأبرار والصديقين، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O forerunner and baptizer, John the Baptist, that He may forgive us our sins.", ar: "إشفع فينا (أمام الرب)، أيها السابق الصابغ، يوحنا المعمدان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Intercede on our behalf, O the hundred and forty four thousand, and the celibate evangelist, that He may forgive us our sins.", ar: "إشفعوا فينا (أمام الرب)، أيها المئة والأربعة والأربعين ألفاً، والبتول الإنجيلي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters and fathers the Apostles, and the rest of the Disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سادتي الآباء الرسل، وبقية التلاميذ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O blessed archdeacon, Stephen the first martyr, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا رئيس الشمامسة المبارك، إستفانوس الشهيد الأول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O beholder of God the Evangelist, Abba Mark the apostle, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الناظر الإله الإنجيلي، أبا مرقس الرسول، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyr, my lord prince George, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، أيها الشهيد المجاهد، سيدي الملك جيؤرجيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Theodore and Theodore, Leontius and Panicharus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا ثيؤدوروس وثيؤدوروس، ولاونديوس، وبانيكاروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Philopater Mercurius, and Abba Mina and Abba Victor, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا فيلوباتير مرقوريوس، وأبا مينا وأبا بقطر، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Claudius and Theodore, Abba Eschyron and Abba Isaac, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي إقلاديوس وثيئودوروس، وأبا سخيرون وأبا إسحق، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basilidis and Evsebius, Macarius and Philotheos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا واسيليدس وأرسابيوس، ومكاريوس وفيلوثيؤوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pisura and Abba Epshoy, Abba Isi and his sister Thecla, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بسورة وأبا بشاي، وأبا إيسي وتكلا أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Justus Apali and Theoklia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يسطس وآبالي وثيؤكليا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Jacob the Persian, Saint Sergius and Saint Bacchus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا يعقوب الفارسي، والقديس سرجيوس وواخس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Cosmas his brothers and their mother, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، قزمان وإخوته وأمهم، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Kir and his brother John, and Barbara and Juliana and Demiana, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا قير ويوحنا أخوه، وبربارة ويوليانة ودميانة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, master Apatir and his sister Iraee, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، السيد أبادير وإيرائي أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Julius and those who were with him, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، يوليوس ومَن معه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Mari Pahnam and his sister Sarah, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان المجاهدان، مار بهنام وسارة أخته، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Sarapamon the bishop, Psate and Gallinikos, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صرابامون الأسقف، وإبصادي وغلينيكوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, the forty saints of Sebaste, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهداء المجاهدون، الأربعون قديساً بسبسطية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Piro and Athom, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا بيروه وأتوم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O struggle-mantled martyrs, Abba Bishoy and his friend Peter, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، أيها الشهيدان المجاهدان، أبا بيشوي وصديقه بطرس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Eklog the priest, and Abba Epgol and Abba Kav, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا إكلوج القس، وأبا بيجول وأبا كاڤ، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba John of Heraclia, master Piphamon and Pistavros, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أبا يوحنا الهرقلي، والسيد بفامون وبسطوروس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Isidore and Panteleon, Sophia and Euphemia, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إيسيذوروس وبندلاون، وصوفيا وإفومية، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, master Apanoub and Ptolomeos, Apa Ekragon and Sousennius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا سيدي أبانوب وإبطلماوس، وإبا إكراجون وسوسونيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O great high priest, Abba Peter seal of the martyrs, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا رئيس الكهنة العظيم، أنبا بطرس خاتم الشهداء، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O new martyrs, Pistavros and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الشهيدان الجديدان، بسطوروس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O Michael the hegumen, and Michael the monk, that He may forgive us our sins.", ar: "أطلبا من الرب عنا، يا ميخائيل القمص، وميخائيل الراهب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the martyrs, who suffered for the sake of Christ, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا صفوف الشهداء، الذين تألموا من أجل المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Antony and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا أنطونيوس وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O three saints Macarii, and all their children the cross-bearers, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الثلاثة مقارات القديسون، وأولادهم لباس الصليب، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers the hegumens, Abba John and Abba Daniel, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين القمصين، أنبا يوحنا وأنبا دانيال، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the fathers who loved their children, Abba Bishoy and Abba Paul, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين محبي أولادهما، أنبا بيشوي وأنبا بولا، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our saintly Roman fathers, Maximus and Dometius, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أبوينا القديسين الروميين، مكسيموس ودوماديوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O forty nine martyrs, the elders of Shiheet, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها التسعة والأربعون شهيداً، شيوخ شيهات، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O strong saint Abba Moses, and John Kame, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، أيها القوي القديس أنبا موسى، ويحنس كاما، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Pachomius of the Koinonia, and Theodore his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا باخوم أبا الشركة، وثيودورس تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Shenouda the archimandrite, and Abba Wisa his disciple, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا شنودة رئيس المتوحدين، وأنبا ويصا تلميذه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Nopher and Abba Karus, and our father Paphnutius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا نفر وأنبا كاروس، وأبانا بفنوتيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Samuel the confessor, and Justus and Apollo his disciples, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا صموئيل المعترف، ويسطس وأبوللو تلميذيه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Apollo and Abba Apip, and our father Abba Pigimi, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا أبوللو وأنبا أبيب، وأبانا أنبا بيچيمي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Evkin and Abba Ehron, Abba Hor and Abba Phis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا إڤكين وأنبا إهرون، وأبا هور وأبا فيس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Parsouma and Ephraim, and John and Simeon, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا برسوما وإفريم، ويوحنا وسمعان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Epiphanius and Ammounios, and Arshillidis and Arsenius, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا إبيفانيوس وأمونيوس، وأرشليدس وأرسانيوس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our masters the ascetic fathers, Abba Abraam and George, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الأبوين الناسكين، أنبا أبرآم وجيؤرجي، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Athanasius the apostolic, Severus and Dioscorus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أثاناسيوس الرسولي، وساويرس وديسقورس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Basil and Gregory, and our father Abba Cyril, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا باسيليوس وإغريغوريوس، وأبانا أنبا كيرلس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the three hundred and eighteen gathered, at Nicea for the faith, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 318 الذين إجتمعوا، في نيقية من أجل الإيمان، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O the one hundred and fifty at Constantinople, and the two hundred at Ephesus, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، أيها الـ 150 بمدينة القسطنطينية، والمائتين بأفسس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Hadid and Abba John, our great father Parsouma and Abba Roweis, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا أنبا حديد وأنبا يوحنا، وأبانا العظيم أنبا برسوما وأنبا رويس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, Abba Abraam the hegumen, and our father Abba Mark, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا أنبا أبرآم القمص، وأبانا أنبا مرقس، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O choirs of the cross-bearers, perfected in the wilderness, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا مصاف لباس الصليب، الذين كملوا في البراري، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, my lord king Constantine, and his mother queen Helen, that He may forgive us our sins.", ar: "أُطلبا من الرب عنا، يا سيدي الملك قسطنطين، وهيلانة الملكة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, O wise virgin ladies, the brides of Christ, that He may forgive us our sins.", ar: "أُطلبنَّ من الرب عنا، أيتها الفتيات العذارى الحكيمات، عرائس المسيح، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, the saints of this day, everyone according to his name, that He may forgive us our sins.", ar: "أُطلبوا من الرب عنا، يا قديسي هذا اليوم، كل واحد بإسمه، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "Likewise we exalt you, with David the psalmist, \"You are a priest forever, according to the order of Melchizedek.\"", ar: "كذلك نعظمك، مع المرتل داود قائلين، \"أنت هو الكاهن إلى الأبد، على طقس ملكي صادق.\"" } },
      { kind: 'reading', text: { en: "Pray to the Lord on our behalf, our holy father the patriarch, Pope Abba Shenouda the high priest, that He may forgive us our sins.", ar: "أُطلب من الرب عنا، يا أبانا القديس البطريرك، أنبا شنودة رئيس الكهنة، ليغفر لنا خطايانا." } },
      { kind: 'reading', text: { en: "If a Bishop is present:\nPray to the Lord on our behalf, O our holy and righteous father, Abba (...) the Bishop (Metropolitan), that He may forgive us our sins.", ar: "في حضور الآب الأسقف:\nأطلب من الرب عنا، يا أبينا القديس البار، أنبا (...) الأسقف (المطران)، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Doxology for the Virgin Mary", ar: "ذكصولوجية العذراء مريم" } },
      { kind: 'doxology', text: { en: "Your greatness O Mary, the undefiled Virgin, is likened to the height of the palm tree, spoken of by Solomon.", ar: "عظمتِك يا مريم، العذراء غير الدنسة، تشبه عُلو النخلة التي، تكلم عنها سليمان." } },
      { kind: 'doxology', text: { en: "You are the spring of living water, that flows from Lebanon, for out of you sprang unto us, the grace of the divinity.", ar: "أنتِ ينبوع ماء الحياة، الفائض من لبنان، التي نبعت لنا منه، نعمة اللاهوت." } },
      { kind: 'doxology', text: { en: "You gave birth to Emmanuel, out of your virginal womb, and He has made us heirs, to the kingdom of heaven.", ar: "ولدتِ لنا عمانوئيل، من أحشائِك البتول، وصيرنا وارثين، في ملكوت السموات." } },
      { kind: 'doxology', text: { en: "According to the promise, He promised to our father, King David the patriarch, He came and fulfilled to us.", ar: "كالوعد الذي وعد به، أبانا رئيس الآباء، الذي هو الملك داود، أتى وأكمله لنا." } },
      { kind: 'doxology', text: { en: "Hail to you O Virgin, the very and true Queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدت لنا عمانوئيل." } },
      { kind: 'doxology', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألك أن تذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "The Fourth Hoos", ar: "الهوس الرابع" } },
      { kind: 'hymn', text: { en: "(Psalm 148)", ar: "(المزمور 148)" } },
      { kind: 'hymn', text: { en: "Praise the Lord from the heavens Alleluia. Praise Him in the heights.", ar: "سبحوا الرب من السموات هلليلويا. سبحوه في الأعالي." } },
      { kind: 'hymn', text: { en: "Praise Him all His angels Alleluia. Praise Him all His hosts.", ar: "سبحوه يا جميع ملائكته هلليلويا. سبحوه يا جميع جنوده." } },
      { kind: 'hymn', text: { en: "Praise Him sun and moon Alleluia. Praise Him all you stars of light.", ar: "سبحيه أيتها الشمس والقمر هلليلويا. سبحيه يا جميع كواكب النور." } },
      { kind: 'hymn', text: { en: "Praise Him you heavens of heavens Alleluia. And you waters above the heavens.", ar: "سبحيه يا سماء السموات هلليلويا. ويا أيتها المياه التي فوق السموات." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For He commanded and they were created.", ar: "لتسبح جميعها لإسم الرب هلليلويا. لأنه قال فكانت." } },
      { kind: 'hymn', text: { en: "He has ordered and they were created Alleluia. He has established them forever and ever.", ar: "وأمر فخلقت هلليلويا. أقامها إلى الأبد وإلى أبد الأبد." } },
      { kind: 'hymn', text: { en: "He has made a decree which shall not pass away Alleluia. Praise the Lord from the earth.", ar: "وضع لها أمراً فلن تتجاوزه هلليلويا. سبحي الرب من الأرض." } },
      { kind: 'hymn', text: { en: "You great sea creatures and all the depths Alleluia. Fire and hail, snow and clouds, stormy wind fulfilling His word.", ar: "أيتها التنانين وجميع الأعماق هلليلويا. النار والبرد والثلج والجليد والريح العاصفة الصانعة كلمته." } },
      { kind: 'hymn', text: { en: "Mountains and all hills Alleluia. Fruitful trees and all cedars.", ar: "الجبال العالية وجميع الآكام هلليلويا. الأشجار المثمره وكل الأرز." } },
      { kind: 'hymn', text: { en: "Beasts and all cattle Alleluia. Creeping things and flying birds.", ar: "الوحوش وكل البهائم هلليلويا. الهوام وكل الطيور ذات الأجنحة." } },
      { kind: 'hymn', text: { en: "Kings of the earth and all people Alleluia. Princes and all judges of the earth.", ar: "ملوك الأرض وكل الشعوب هلليلويا. الرؤساء وكل حكام الأرض." } },
      { kind: 'hymn', text: { en: "Both young men and maidens Alleluia. Old men and children.", ar: "الشبان والعذارى هلليلويا. الشيوخ والصبيان." } },
      { kind: 'hymn', text: { en: "Let them praise the name of the Lord Alleluia. For His name alone is exalted.", ar: "فليسبحوا جميعاً إسم الرب هلليلويا. لأنه قد تعالى إسمه وحده." } },
      { kind: 'hymn', text: { en: "His glory is above the earth and heaven Alleluia. And He has exalted the horn of His people.", ar: "شكره كائن على الأرض وفي السماء هلليلويا. ويرفع قرن شعبه." } },
      { kind: 'hymn', text: { en: "The praise of all His saints Alleluia. The children of Israel, a people near unto Him.", ar: "سُبحاً لجميع قديسيه هلليلويا. بني إسرائيل، الشعب القريب إليه." } },
      { kind: 'hymn', text: { en: "(Psalm 149)", ar: "(المزمور 149)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Sing to the Lord a new song Alleluia. And His praise in the congregation of the saints.", ar: "إنشدوا للرب نشيداً جديداً هلليلويا. لأن تسبحته في بيعة القديسين." } },
      { kind: 'hymn', text: { en: "Let Israel rejoice in his Maker Alleluia. Let the children of Zion be joyful in their King.", ar: "فليفرح إسرئيل بخالقه هلليلويا. وبنوا صهيون فليتهللوا بملكهم." } },
      { kind: 'hymn', text: { en: "Let them praise His name in a chorus Alleluia. Let them sing praises unto Him with timbrel and harp.", ar: "فليسِّبحوا إسمه القدوس بصفِ هلليلويا. بدف ومزمار فليرتلوا له." } },
      { kind: 'hymn', text: { en: "For the Lord takes pleasure in His people Alleluia. He will raise the meek with salvation.", ar: "لأن الرب يُسر بشعبه هلليلويا. يعلي الودعاء بالخلاص." } },
      { kind: 'hymn', text: { en: "Let the saints be joyful in glory Alleluia. Let them sing aloud upon their beds.", ar: "يفتخر القديسون بمجد هلليلويا. ويتهللون على مضاجعهم." } },
      { kind: 'hymn', text: { en: "Let the high praises of God be in their mouth Alleluia. And a two edged sword in their hands.", ar: "تعليات الله في حناجرهم هلليلويا. وسيوف ذات حدين في أيديهم." } },
      { kind: 'hymn', text: { en: "To execute vengeance on the nations Alleluia. And punishments on the people.", ar: "ليصنعوا نقمة في الأمم هلليلويا. وتوبيخات في الشعوب." } },
      { kind: 'hymn', text: { en: "To bind their kings with chains Alleluia. And their nobles with fetters of iron.", ar: "ليوثقوا ملوكهم بقيود هلليلويا. وإشرافهم بأغلال للأيدي من حديد." } },
      { kind: 'hymn', text: { en: "To execute on them the written judgment Alleluia. This honor have all His saints.", ar: "ليصنعوا بهم حُكماً مكتوباً هلليلويا. هذا المجد كائن في جميع قديسيه." } },
      { kind: 'hymn', text: { en: "(Psalm 150)", ar: "(المزمور 150)" } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia, Alleluia.", ar: "هلليلويا، هلليلويا، هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise God in all His saints Alleluia.", ar: "سبحوا الله في جميع قديسيه هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him in the firmament of His power Alleluia.", ar: "سبحوه في جلد قوته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him for His mighty acts Alleluia.", ar: "سبحوه على مقدرته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him according to the multitudes of His greatness Alleluia.", ar: "سبحوه ككثرة عظمته هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with the sound of the trumpet Alleluia.", ar: "سبحوه بصوت البوق هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with psaltery and harp Alleluia.", ar: "سبحوه بالمزمار والقيثار هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with timbrel and chorus Alleluia.", ar: "سبحوه بدفوف وصفوف هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with strings and organs Alleluia.", ar: "سبحوه بأوتار وأرغن هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him with pleasant sounding cymbals Alleluia.", ar: "سبحوه بصنوج حسنة الصوت هلليلويا." } },
      { kind: 'hymn', text: { en: "Praise Him upon the cymbals of joy Alleluia.", ar: "سبحوه بصنوج التهليل هلليلويا." } },
      { kind: 'hymn', text: { en: "Let every thing that has breath praise the name of the Lord our God Alleluia.", ar: "كل نسمة فلتسبح إسم الرب الهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son and the Holy Spirit Alleluia.", ar: "المجد للآب والإبن والروح القدس هلليلويا." } },
      { kind: 'hymn', text: { en: "Now and forever and unto the age of all ages Amen Alleluia.", ar: "الآن وكل أوان وإلى دهر الدهور آمين هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory to You, O our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لك يا إلهنا هلليلويا." } },
      { kind: 'hymn', text: { en: "Alleluia, Alleluia. Glory be to our God Alleluia.", ar: "هلليلويا، هلليلويا. المجد لإلهنا هلليلويا." } },
      { kind: 'heading', text: { en: "The Friday Psali", ar: "إبصالية الجمعة" } },
      { kind: 'hymn', text: { en: "For truly I approached, a great Prince, which is the name of salvation, of our Lord Jesus Christ.\nOur Lord Jesus Christ, gave a sign to His servants, who do fear him, to escape from the face of the bows.", ar: "بالحقيقة قد تقدمت، إلى رأس عظيم، هو إسم الخلاص الذي، لربنا يسوع المسيح.\nربنا يسوع المسيح، أعطى علامة لعبيده، الذين يخافونه، لكي يهربوا من وجه القوس." } },
      { kind: 'hymn', text: { en: "Our Lord Jesus Christ, gave a sign to His servants, who do fear Him, to shut the mouths of the lions.\nOur Lord Jesus Christ, gave a sign to His servants, who do fear Him, to put out the power of the fire.", ar: "ربنا يسوع المسيح، أعطى علامة لعبيده، الذين يخافونه، لكي يسدوا أفواه الأسود.\nربنا يسوع المسيح، أعطى علامة لعبيده، الذين يخافونه، لكي يطفئوا قوة النار." } },
      { kind: 'hymn', text: { en: "Our Lord Jesus Christ, gave a sign to His servants, who do fear Him, to cast out the devils.\nOur Lord Jesus Christ, gave a sign to His servants, who do fear Him, to prevail over their enemies.", ar: "ربنا يسوع المسيح، أعطى علامة لعبيده، الذين يخافونه، لكي يُخرجوا الشياطين.\nربنا يسوع المسيح، أعطى علامة لعبيده، الذين يخافونه، لكي يتسلطوا على أعدائهم." } },
      { kind: 'hymn', text: { en: "Our Lord Jesus Christ, gave a sign to His servants, who do fear Him, to heal every sickness.\nTherefore let us glorify, our Lord Jesus Christ, and His good Father, and the Holy Spirit.", ar: "ربنا يسوع المسيح، أعطى علامة لعبيده، الذين يخافونه، أن يشفوا كل مرض.\nمن أجل هذا نمجد، ربنا يسوع المسيح، مع أبيه الصالح، والرُّوح القُدُس." } },
      { kind: 'hymn', text: { en: "This is the name of salvation, of our Lord Jesus Christ, and His life-giving Cross, which He was crucified upon.\nBlessed is the man who forsakes this life, and its vain pleasures, that are full of suffering, that kill the soul.", ar: "وهذا هو إسم الخلاص، الذي لربنا يسوع المسيح، وصليبه المحيي، الذي صُلب عليه.\nطوبى للإنسان الذي، يترك عنه هذا العمر، وإهتماماته المملؤة تعباً، القاتلة للنفس." } },
      { kind: 'hymn', text: { en: "And he who carries his Cross day after day, and keeps his mind and heart, on the name of salvation, of our Lord Jesus Christ.\nOur hearts are happy, and our tongues rejoice, whenever we sing to the name, of salvation of our Lord Jesus Christ.", ar: "ويحمل صليبه يوماً فيوماً، ويلصق عقله وقلبه، بإسم الخلاص، الذي لربنا يسوع المسيح.\nيفرح قلبنا، ويتهلل لساننا، إذا ما تلونا إسم الخلاص، الذي لربنا يسوع المسيح." } },
      { kind: 'heading', text: { en: "Introduction to the Watos Theotokias", ar: "مقدمة الثيؤطوكيات الواطس" } },
      { kind: 'hymn', text: { en: "And whenever we sing, let us say tenderly, “O our Lord Jesus Christ, have mercy upon our souls.”", ar: "إذا ما رتلنا، فلنقل بعذوبة، \"يا ربنا يسوع المسيح، إصنع رحمة مع نفوسنا.\"" } },
      { kind: 'hymn', text: { en: "Glory be to the Father and the Son, and the Holy Spirit, now and forever and unto, the age of all ages Amen.", ar: "المجد للآب والإبن، والروح القدوس، الآن وكل أوان، وإلى دهر الدهور آمين." } },
      { kind: 'heading', text: { en: "The Friday Theotokia — Watos", ar: "ثيؤطوكية الجمعة — واطس" } },
      { kind: 'hymn', text: { en: "The First Part", ar: "القطعة الأولى" } },
      { kind: 'hymn', text: { en: "Blessed are you among women, and blessed is your Fruit, O Mary the Mother of God, the undefiled Virgin.", ar: "مباركة أنتِ في النساء، ومباركة ثمرتكِ، يا مريم أم الله، العذراء غير الدنسة." } },
      { kind: 'hymn', text: { en: "For the Sun of Righteousness, shone unto us from you, with healing under His wings, for He is the Creator.", ar: "لأنه قد أشرقت لنا منكِ، شمس البر، والشفاء في جناحيها، لأنه الخالق." } },
      { kind: 'hymn', text: { en: "He took what is ours, and gave us what is His, we praise and glorify Him, and exalt Him.", ar: "هو أخذ الذي لنا، وأعطانا الذي له، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "The Second Part", ar: "القطعة الثانية" } },
      { kind: 'hymn', text: { en: "You are blessed more favored than heaven, and more honored than earth, you exceed every thought, who can speak of your honor.", ar: "مباركة أنتِ أفضل من السماء، ومكرمة أفضل من الأرض، أنت فُقتِ كل فكر، مَنْ يقدر أن يصف كرامتك." } },
      { kind: 'hymn', text: { en: "No one is like you, O Mary the Virgin, the angels honor you, and the Seraphim glorify you.", ar: "ليس من يُشبهِك، يا مريم العذراء، الملائكة تكرمِك، والسِّرافيم تُمجدِك." } },
      { kind: 'hymn', text: { en: "For He who sits upon the Cherubim, came and was incarnate of you, and He united us with Him, through His goodness.", ar: "لأن الذي على الشاروبيم، أتى وتجسد منكِ، حتى إتحدنا به، من قِبَل صلاحه." } },
      { kind: 'hymn', text: { en: "He took what is ours, and gave us what is His, we praise and glorify Him, and exalt Him.", ar: "هو أخذ الذي لنا، وأعطانا الذي له، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "The Third Part", ar: "القطعة الثالثة" } },
      { kind: 'hymn', text: { en: "Blessed are you O Mary, and blessed is your Fruit, O Virgin Mother of God, the pride of virginity.", ar: "مباركة أنتِ يا مريم، ومباركة ثمرتِك، أيتها العذراء أم الله، فخر البتولية." } },
      { kind: 'hymn', text: { en: "He who existed before all ages, came and was incarnate of you, and the Ancient of Days, came out of your womb.", ar: "الكائن قبل الدهور، أتى وتجسد منكِ، عتيق الأيام، خرج من بطنِك." } },
      { kind: 'hymn', text: { en: "He took our body, and gave us His Holy Spirit, and made us one with Him, through His goodness.", ar: "هو أخذ جسدنا، وأعطانا روحه القدوس، وجعلنا واحداً معه، من قِبَل صلاحه." } },
      { kind: 'hymn', text: { en: "He took what is ours, and gave us what is His, we praise and glorify Him, and exalt Him.", ar: "هو أخذ الذي لنا، وأعطانا الذي له، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "The Fourth Part", ar: "القطعة الرابعة" } },
      { kind: 'hymn', text: { en: "Many women received honor, yet you exceeded them all, for you are the pride of virgins, O Mary the Theotokos.", ar: "نساء كثيرات نلنَّ كرامات، تعاليت أنتِ أكثر من جميعهنَ، لأنكِ أنتِ فخر العذارى، يا مريم والدة الإله." } },
      { kind: 'hymn', text: { en: "You are the soul's city, where the Most High lived, who sits upon the throne, of the Cherubim.", ar: "المدينة النفسية، التي سكن فيها العلي، الجالس على، مركبة الشاروبيم." } },
      { kind: 'hymn', text: { en: "The Seraphim glorify Him, and you held Him in your arms, He who gives food to all flesh, through His great kindness.", ar: "والسِّرافيم يمجدونه، حَملتِه على ذراعيكِ، المعطي طعاماً لكل ذي جسد، من قِبَل تحننه." } },
      { kind: 'hymn', text: { en: "He held to your breasts, and you fed Him, for He is our God, and the Savior of everyone.", ar: "مسكَ ثدييكِ، وأرضعتيه اللبن، لأنه هو إلهنا، ومخلص كل أحد." } },
      { kind: 'hymn', text: { en: "He shepherds all of us, forever and ever, we praise and glorify Him, and exalt Him.", ar: "هو يرعانا، إلى أبد الأبد، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "He took what is ours, and gave us what is His, we praise and glorify Him, and exalt Him.", ar: "هو أخذ الذي لنا، وأعطانا الذي له، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "The Fifth Part", ar: "القطعة الخامسة" } },
      { kind: 'hymn', text: { en: "O Virgin Mary, the wise Mother of God, the garden of fragrance, the holy fountain of the living water.", ar: "أيتها العذراء مريم، والدة الإله الحكيمة، بُستان العطر، ينبوع ماء الحياة المقدس." } },
      { kind: 'hymn', text: { en: "The Fruit of your womb, came and saved the world, and He abolished all enmity, and established for us His peace.", ar: "ثمرة بطنِك، أتى وخلَّص المسكونة، ونقض العداوة عنا، وقرر لنا سلامه." } },
      { kind: 'hymn', text: { en: "Through His Cross, and His holy Resurrection, He restored man once again, to the Paradise.", ar: "من قِبَل صليبه، وقيامته المقدسة، رد الإنسان مرة أُخرى، إلى الفردوس." } },
      { kind: 'hymn', text: { en: "He took what is ours, and gave us what is His, we praise and glorify Him, and exalt Him.", ar: "هو أخذ الذي لنا، وأعطانا الذي له، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "The Sixth Part", ar: "القطعة السادسة" } },
      { kind: 'hymn', text: { en: "O Virgin Mary, the holy Mother of God, the trusted advocate, of the human race.", ar: "أيتها العذراء مريم، والده الإله القديسة، الشفيعة الأمينة، التي لجنس البشر." } },
      { kind: 'hymn', text: { en: "Intercede on our behalf, before Christ whom you have born, that He may grant unto us, the forgiveness of our sins.", ar: "إشفعي فينا، أمام المسيح الذي ولدتِه، لكي ينعم علينا، بمغفرة خطايانا." } },
      { kind: 'hymn', text: { en: "He took what is ours, and gave us what is His, we praise and glorify Him, and exalt Him.", ar: "هو أخذ الذي لنا، وأعطانا الذي له، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'hymn', text: { en: "The Seventh Part", ar: "القطعة السابعة" } },
      { kind: 'hymn', text: { en: "The Virgin Mary has proclaimed, in the altar, saying “My peace, God does know.", ar: "العذراء مريم، تصرخ في الهيكل، قائلة \"سلامي أنا، يَعلمه الله." } },
      { kind: 'hymn', text: { en: "For I know nothing, other than the voice of the angel, announcing the joy, coming to me from heaven.”", ar: "لأني لا أعرف شيئاً، سوى صوت الملاك، يبشرني بفرح، آتٍ إليَّ من السماء.\"" } },
      { kind: 'hymn', text: { en: "He took what is ours, and gave us what is His, we praise and glorify Him, and exalt Him.", ar: "هو أخذ الذي لنا، وأعطانا الذي له، نسبحه ونمجده، ونزيده علواً." } },
      { kind: 'heading', text: { en: "The Friday Theotokia Lobsh", ar: "لبش ثيؤطوكية الجمعة" } },
      { kind: 'hymn', text: { en: "What do I call you, O all-holy Virgin, who gave birth to the Incomprehensible, and Infinite One.", ar: "بماذا أدعوكِ، أيتها العذراء الكلية القداسة، التي حملت غير المُدرَك، وغير المحوى أيضاً." } },
      { kind: 'hymn', text: { en: "Many are your praises, O who is adorned with honor, for you became a dwelling, for the wisdom of God.", ar: "تكثر مدائحِك، أيتها المزينة بكل كرامة، لأنكِ صرتِ مسكناً، لحكمة الله." } },
      { kind: 'hymn', text: { en: "You are the rational net, that catches Christians, and teaches them to worship, the life-giving Trinity.", ar: "أنتِ هي الصنارة العقلية، التي تصطاد المسيحيين، وتعلمهم السجود، للثالوث المحيي." } },
      { kind: 'hymn', text: { en: "You are the one who carried, the Pillar which Moses saw, who is the Son of God, who came and dwelt in your womb.", ar: "أنتِ التي حملتِ العامود، الذي رآه موسى، هو إبن الله، أتى وحلَّ في بطنِك." } },
      { kind: 'hymn', text: { en: "You became the ark, for Him who created heaven and earth, you carried Him in your womb, for nine full months.", ar: "صرتِ تابوتاً، لخالق السماء والأرض، حملته في بطنِك، تسعة أشهر عدداً." } },
      { kind: 'hymn', text: { en: "You were also entrusted with, the fullness of heaven and earth, and you became our reason, to progress to heaven.", ar: "وأنتِ أيضاً أؤتمنتِ، على سعة السماء والأرض، وصرتِ لنا سبباً، للإرتقاء إلى السماء." } },
      { kind: 'hymn', text: { en: "You are brighter than the sun, you are the East, toward which the righteous look, with happiness and joy.", ar: "أنتِ مضيئة أكثر من الشمس، أنتِ هي ناحية المشرق، التي ينظرها الأبرار، بفرح وتهليل." } },
      { kind: 'hymn', text: { en: "Eve was sentenced, to give birth with deep pain, while to you it was said, “Hail to you O full of grace.”", ar: "حُكِم على حواء، بالولادة بوجع القلب، أما أنتِ فسمعتِ، \"إفرحي يا مُمْتلئة نعمة.\"" } },
      { kind: 'hymn', text: { en: "You gave birth to the King for us, the Lord of all creation, He came and redeemed us from our sins, as a Good One and Lover of Man.", ar: "ولدتِ لنا الملك، رب كل البرية، أتى وخلصنا من خطايانا، كصالح ومحب البشر." } },
      { kind: 'hymn', text: { en: "Therefore we sing, with Elizabeth your cousin saying, “Blessed are you among women, and blessed is the Fruit of your womb.”", ar: "من أجل هذا نرتل، مع أليصابات نسيبتِك قائلين، \"مباركة أنتِ في النساء، ومباركة هي ثمرة بطنِك.\"" } },
      { kind: 'hymn', text: { en: "Hail to you O Virgin, the very and true queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدتِ لنا عمانوئيل." } },
      { kind: 'hymn', text: { en: "We ask you to remember us, O our trusted advocate, before our Lord Jesus Christ, that He may forgive us our sins.", ar: "نسألِك أن تذكرينا، أيتهالمؤتمنةا الشفيعة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا." } },
      { kind: 'heading', text: { en: "Introduction to the Difnar — Watos", ar: "مقدمة الدفنار — واطس" } },
      { kind: 'hymn', text: { en: "We worship the good Father, and His Son Jesus Christ, and the Spirit of comfort, the holy and coessential Trinity.", ar: "نسجد للآب الصالح، ويسوع المسيح إبنه، والروح المعزي، الثالوث القدوس المساوي." } },
      { kind: 'hymn', text: { en: "Hail to you O Virgin, the very and true queen, hail to the pride of our race, who gave birth to Emmanuel.", ar: "السلام لكِ أيتها العذراء، الملكة الحقيقية الحقانية، السلام لفخر جنسنا، ولدتِ لنا عمانوئيل." } },
      { kind: 'hymn', text: { en: "We have hope, in Saint Mary, that God will have mercy upon us, through her intercessions.", ar: "لنا رجاء، في القديسة مريم، أن الله يرحمنا، بشفاعاتها." } },
      { kind: 'hymn', text: { en: "All calmness, in the world, is through the prayers, of the holy Theotokos, Saint Mary the Virgin.", ar: "كل هدوء، في العالم، من قبل صلاة، والدة الإله الطاهرة، القديسة مريم العذراء." } },
      { kind: 'heading', text: { en: "Conclusion of the Watos Theotokias", ar: "ختام الثيؤطوكيات الواطس" } },
      { kind: 'prayer', text: { en: "O our Lord Jesus Christ, who carries the sin of the world, count us with Your sheep, those who are to Your right.", ar: "يا ربنا يسوع المسيح، حامل خطية العالم، أحسبنا مع خرافك، الذين عن يمينِك." } },
      { kind: 'prayer', text: { en: "And when You come again, in Your second fearful appearance, may we never fearfully hear, You say I do not know you.", ar: "عند ظهورِك الثاني، المخوف لا نسمع، برعدةٍ \"أنَّنِي، لَستُ أعرفكم.\"" } },
      { kind: 'prayer', text: { en: "But rather may we be made worthy, to hear the voice full of joy, of Your tender mercies, proclaiming and saying.", ar: "بَل نكون مُستحقين، لسماع صوتك الحنون، المُمْتلئ فرحاً، يصرخ قائلاً." } },
      { kind: 'prayer', text: { en: "“Come unto Me, O blessed of My Father, and inherit the life, that endures forever.”", ar: "\"تعالوا إليَّ، يا مُبارَكي أبي، رثوا الحياة، الدائمة إلى الأبد.\"" } },
      { kind: 'prayer', text: { en: "The martyrs will come, bearing their afflictions, and the righteous will come, bearing their virtues.", ar: "يأتي الشهداء، حاملين عذاباتهم، ويأتي الصدِّيقون، حاملين فضائلهم." } },
      { kind: 'prayer', text: { en: "The Son of God shall come in His glory, and His Father’s glory, to give unto everyone, according to his deeds which he has done.", ar: "يأتي إبن الله، في مجده ومجد أبيه، ويُجازي كل واحدٍ، كأعماله التي عملها." } },
      { kind: 'prayer', text: { en: "O Christ the Word of the Father, the only-begotten God, grant us Your peace, that is full of joy.", ar: "أيها المسيح كلمة الآب، الإله الوحيد الجنس، أعطنا سلامك، المملوء فرحاً." } },
      { kind: 'prayer', text: { en: "As You have given, to Your saintly Apostles, likewise also say to us, “My peace I give to You.", ar: "كما أعطيته، لرُسُلِكَ القديسين، قُلْ لنا مِثلهم، \"إنِّي أعطيكم سلامي." } },
      { kind: 'prayer', text: { en: "My peace which I have taken, from My Father, I leave unto you, both now and forever.”", ar: "سلامي أنا، الذي أخذته من أبي، أنا أتركه معكم، من الأن وإلى الأبد.\"" } },
      { kind: 'prayer', text: { en: "O the angel of this day, flying up with this hymn, remember us before the Lord, that He may forgive us our sins.", ar: "يا ملاك هذا اليوم الطائر، إلى العلو بهذه التسبحة، أُذكرنا أمام الرب، ليغفر لنا خطايانا." } },
      { kind: 'prayer', text: { en: "The sick heal them, those who have slept O Lord repose them, and all of our brothers in distress, help us my Lord and all of them.", ar: "المرضى أشفهم، الذين رقدوا يا رب نَيِّحهم، وأخواتنا الذين في كل شدة، يا ربي أعنا وإيَّاهم." } },
      { kind: 'prayer', text: { en: "May God bless us, and let us bless His holy name, and may His praise continually be, always upon our mouths.", ar: "يُبارِكنا الله، ولنُبارِك إسمه القدوس، في كل حين تسبحته، دائمة في أفواهنا." } },
      { kind: 'prayer', text: { en: "For blessed is the Father, the Son and the Holy Spirit, the perfect Trinity, we worship Him and glorify Him.", ar: "مُبارَك الآب والإبن، والرُّوح القُدُس، الثالوث الكامل، نسجد له ونُمجِّدهُ." } },
      { kind: 'heading', text: { en: "The Concluding Litany", ar: "طلبة الختام" } },
      { kind: 'litany', text: { en: "Kerie leysoun (Lord have mercy) is said three times before every part", ar: "يقال كيريي ليسون (يا رب إرحم) ثلاث مرات قبل كل ربع" } },
      { kind: 'litany', text: { en: "Amen.", ar: "آمين." } },
      { kind: 'litany', text: { en: "Kerie leysoun (3).", ar: "كيريي ليسون (3)." } },
      { kind: 'litany', text: { en: "O God have mercy on us.", ar: "يا الله إرحمنا." } },
      { kind: 'litany', text: { en: "O God hear us.", ar: "يا الله إسمعنا." } },
      { kind: 'litany', text: { en: "O God look to us.", ar: "يا الله أُنظر إلينا." } },
      { kind: 'litany', text: { en: "O God behold us.", ar: "يا الله إطَّلع علينا." } },
      { kind: 'litany', text: { en: "O God have compassion on us.", ar: "يا الله تراءف علينا." } },
      { kind: 'litany', text: { en: "We are Your people.", ar: "نحن شعبك." } },
      { kind: 'litany', text: { en: "We are Your creation.", ar: "نحن جبلتك." } },
      { kind: 'litany', text: { en: "Deliver us from our enemies.", ar: "نجنا من أعدائنا." } },
      { kind: 'litany', text: { en: "Deliver us from inflation.", ar: "نجنا من الغلاء." } },
      { kind: 'litany', text: { en: "We are Your servants.", ar: "نحن عبيدك." } },
      { kind: 'litany', text: { en: "You are the Son of God.", ar: "أنت إبن الله." } },
      { kind: 'litany', text: { en: "We believe in You.", ar: "آمنا بك." } },
      { kind: 'litany', text: { en: "For You have (risen/come) and saved us.", ar: "لأنك (قُمت/أتيت) وخلَّصتنا." } },
      { kind: 'litany', text: { en: "Visit us with Your salvation.", ar: "تعهدنا بخلاصك." } },
      { kind: 'litany', text: { en: "And forgive us our sins.", ar: "وإغفر لنا خطايانا." } },
      { kind: 'litany', text: { en: "Kerie leysoun.", ar: "كيريي ليسون." } },
      { kind: 'heading', text: { en: "The Morning Doxology", ar: "ذكصولوجية باكر" } },
      { kind: 'doxology', text: { en: "We worship the Father and the Son, and the Holy Spirit, hail to the church, the house of the angels.", ar: "نسجد للآب والإبن، والروح القدس، السلام للكنيسة، بيت الملائكة." } },
      { kind: 'doxology', text: { en: "Hail to the Virgin, who gave birth to our Savior, hail to Gabriel, who announced to her the good news.", ar: "السلام للعذراء، التي ولدت مخلصنا، السلام لغبريال، الذي بشرها." } },
      { kind: 'doxology', text: { en: "Hail to Michael, the archangel, hail to the twenty four, presbyters.", ar: "السلام لميخائيل، رئيس الملائكة، السلام للأربعة والعشرين، قسيساً." } },
      { kind: 'doxology', text: { en: "Hail to the Cherubim, hail to the Seraphim, hail to all the hosts, of the heavens.", ar: "السلام للشاروبيم، السلام للسارافيم، السلام لجميع الطغمات، السمائية." } },
      { kind: 'doxology', text: { en: "Hail to John, the great forerunner, hail to the, twelve Apostles.", ar: "السلام ليوحنا، السابق العظيم، السلام للإثنى عشر، رسولاً." } },
      { kind: 'doxology', text: { en: "Hail to our father Mark, the Evangelist, the destroyer, of the idols.", ar: "السلام لأبينا مرقس، الإنجيلي، مُبَدِد، الأوثان." } },
      { kind: 'doxology', text: { en: "Hail to Stephen, the first martyr, hail to George, the morning star.", ar: "السلام لإستفانوس، الشهيد الأول، السلام لجرجس، كوكب الصبح." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the martyrs, hail to Abba Antony, and the three Macarii.", ar: "السلام لجميع صفوف، الشهداء، السلام لأنبا أنطونيوس، والثلاثة المقارات." } },
      { kind: 'doxology', text: { en: "Hail to the whole choir, of the cross-bearers, hail to all the saints, who have pleased the Lord.", ar: "السلام لجميع صفوف، لُباس الصليب، السلام لجميع القديسين، الذين أرضوا الرب." } },
      { kind: 'doxology', text: { en: "Through their prayers, O Christ our King, have mercy upon us, in Your kingdom.", ar: "أيها المسيح ملكنا، بصلواتهم، إصنع معنا رحمة، في ملكوتك." } },
      { kind: 'doxology', text: { en: "(For Our Lord Jesus Christ)", ar: "(لأجل ربنا يسوع المسيح)" } },
      { kind: 'doxology', text: { en: "O true Light, that gives light, to every man, that comes into the world.", ar: "أيها النور الحقيقي، الذي يضئ، لكل إنسان، آتٍ إلى العالم." } },
      { kind: 'doxology', text: { en: "You came into the world, through Your love for man, and all the creation, rejoiced at Your coming.", ar: "أتيت إلى العالم، بمحبتك للبشر، وكل الخليقة، تهللت بمجيئك." } },
      { kind: 'doxology', text: { en: "You have saved Adam, from seduction, and delivered Eve, from the pangs of death.", ar: "خلصَّت آدم، من الغواية، وعتقت حواء، من طلقات الموت." } },
      { kind: 'doxology', text: { en: "You gave unto us, the Spirit of sonship, we praise and bless You, with Your angels.", ar: "أعطيتنا، روح النبوة، نسبحك ونباركك، مع ملائكتك." } },
      { kind: 'doxology', text: { en: "When the morning hour, comes upon us, O Christ our God, the true Light.", ar: "عندما يدخل، وقت باكر إلينا، أيها المسيح إلهنا، النور الحقيقي." } },
      { kind: 'doxology', text: { en: "Let the thought of light, shine within us, and do not let the darkness, of pain cover us.", ar: "فلتشرق فينا، حواس النور، ولا تغطينا، ظلمة الآلام." } },
      { kind: 'doxology', text: { en: "That we may praise You, with understanding, proclaiming and saying, with David.", ar: "لكي نسبحك، عقلياً، مع داود، صارخين، نحوك قائلين." } },
      { kind: 'doxology', text: { en: "\"My eyes have reached, the morning watch, that I may meditate, upon all Your words.\"", ar: "\"سبق أن بلغت، عيناي وقت السحر، لأتلو، جميع أقوالك.\"" } },
      { kind: 'doxology', text: { en: "Hear our voices, according to Your great mercy, save us O Lord our God, according to Your compassion.", ar: "إسمع صوتنا، كعظيم رحمتك، ونجنا أيها الرب إلهنا، حسب رأفاتك." } },
      { kind: 'doxology', text: { en: "O caring God, the Maker of all good things, who governs well, with His chosen ones.", ar: "يا الله المُهْتم، صانع الخيرات، مُدبر مُختاريه، حسناً." } },
      { kind: 'doxology', text: { en: "The strong Governor for those, who take refuge in Him, who longs for the salvation, and deliverance of everyone.", ar: "المدبر القوي، للملتجئين، المتشوق لخلاص، ونجاة كل أحد." } },
      { kind: 'doxology', text: { en: "Through Your goodness, You provided us the night, grant us to pass, this day without sin.", ar: "بصلاحك هيأت، لنا الليل، أنعم لنا بهذا اليوم، ونحن بغير خطية." } },
      { kind: 'doxology', text: { en: "That we may be worthy, to lift up our hands, before You without anger, or evil thoughts.", ar: "لنستحق أن نرفع، أيدينا إليك، أمامك بغير غضب، ولا فكر ردئ." } },
      { kind: 'doxology', text: { en: "At this dawn, make straight our coming in, and our going out, in the joy of Your protection.", ar: "في هذا السحر، سهل طرقنا، الداخلية والخارجية، بسترك المفرح." } },
      { kind: 'doxology', text: { en: "That we may proclaim, Your righteousness daily, and praise Your power, with David the prophet.", ar: "لننطق بعدلك، كل يوم، ونمجد قوتك، مع داود النبي." } },
      { kind: 'doxology', text: { en: "Saying \"In Your peace, O Christ our Savior, we slept and arose, for we have hoped in You.", ar: "قائلين \"بسلامك، أيها المسيح مخلصنا، رقدنا وقمنا، لأننا توكلنا عليك." } },
      { kind: 'doxology', text: { en: "Behold how beneficent, and how pleasant, it is for brethren, to dwell together in unity.\"", ar: "ها ما هو الحسن، وما هو الحلو، إلا إتفاق إخوة، ساكنين معاً.\"" } },
      { kind: 'doxology', text: { en: "United, in the true, evangelic love, like the Apostles.", ar: "مُتفقين، بمحبة حقيقية، إنجيلية، كمثل الرسل." } },
      { kind: 'doxology', text: { en: "It is like the fragrant oil, on the head of Christ, running down the beard, down to the feet.", ar: "مثل الطيب، على رأس المسيح، النازل على اللحية، إلى أسفل الرجلين." } },
      { kind: 'doxology', text: { en: "That anoints every day, the elders, the children and young men, and the deacons.", ar: "يمسح كل يوم، الشيوخ، والصبيان والفتيات، والخدام." } },
      { kind: 'doxology', text: { en: "Those whom the Holy Spirit, has attuned together, as a stringed instrument, always blessing God.", ar: "هؤلاء الذين، ألَّفهم الروح القدس معاً، مثل قيثارة مُسبحين، الله كل حين." } },
      { kind: 'doxology', text: { en: "By psalms and hymns, and spiritual songs, by day and by night, with an incessant heart.", ar: "بمزامير وتسابيح، وترانيم روحية، النهار والليل، بقلب لا يفتر." } },
      { kind: 'doxology', text: { en: "(For the Virgin)", ar: "(لأجل العذراء)" } },
      { kind: 'doxology', text: { en: "You are the Mother of the Light, the honored Mother of God, you have carried, the Uncircumscript Logos.", ar: "أنتِ يا أم النور، المكرمة والدة الإله، حملتِ الكلمة، غير المحوي." } },
      { kind: 'doxology', text: { en: "After you gave birth to Him, you remained a virgin, with praises and blessings, we magnify you.", ar: "ومن بعد أن ولدتِه، بقيتِ عذراء، نعظمكِ بتسابيح، وبركات." } },
      { kind: 'doxology', text: { en: "For of His own will, and the pleasure of His Father, and the Holy Spirit, He came and saved us.", ar: "لأنه بإرادته، ومسرة أبيه، والروح القدس، آتى وخلصنا." } },
      { kind: 'doxology', text: { en: "And we too, hope to win mercy, through your intercessions, with the Lover of Mankind.", ar: "ونحن أيضاً، نطلب أن نفوز، برحمة بشفاعاتك، لدى محب البشر." } },
      { kind: 'doxology', text: { en: "The select incense, of your virginity, ascended to the throne, of the Father.", ar: "البخور المختار، الذي لبتوليتك، صعد إلى، كرسي الآب." } },
      { kind: 'doxology', text: { en: "Better than the incense, of the Cherubim, and the Seraphim, O Virgin Mary.", ar: "أفضل من بخور، الشاروبيم، والسارافيم، يا مريم العذراء." } },
      { kind: 'doxology', text: { en: "Hail to the new heaven, whom the Father has created, and made a place of rest, for His beloved Son.", ar: "السلام للسماء الجديدة، التي صنعها الآب، وجعلها موضع راحة، لإبنه الحبيب." } },
      { kind: 'doxology', text: { en: "Hail to the royal throne, of Him who is, carried by, the Cherubim.", ar: "السلام للكرسي، الملوكي، الذي للمحمول، على الشاروبيم." } },
      { kind: 'doxology', text: { en: "Hail to the advocate, of our souls, you are indeed, the pride of our race.", ar: "السلام لشفيعة، نفوسنا، أنت بالحقيقة، فخر جنسنا." } },
      { kind: 'doxology', text: { en: "Intercede on our behalf, O full of grace, before our Savior, our Lord Jesus Christ.", ar: "إشفعي فينا، يا ممتلئة نعمة، أمام مخلصنا، ربنا يسوع المسيح." } },
      { kind: 'doxology', text: { en: "That He may confirm us, in the upright faith, and grant us the forgiveness, of our sins.", ar: "لكي يثبتنا، في الإيمان المستقيم، وينعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the Mother of God Saint Mary, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، والدة الإله القديسة مريم، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Angels)", ar: "(لأجل الملائكة)" } },
      { kind: 'doxology', text: { en: "Thousands of thousands, and myriads of myriads, of archangels, and holy angels.", ar: "ألوف ألوف، وربوات ربوات، رؤساء ملائكة، وملائكة مُقدسيين." } },
      { kind: 'doxology', text: { en: "They stand before, the throne, of the Pantocrator, proclaiming and saying.", ar: "وقوف أمام، كرسي، ضابط الكل، صارخين قائلين:" } },
      { kind: 'doxology', text: { en: "\"Holy holy, holy in truth, the glory and the honor, befit the Trinity.\"", ar: "\"قدوس قدوس، قدوس بالحقيقة، المجد والكرامة، يليقان بالثالوث.\"" } },
      { kind: 'doxology', text: { en: "Through the intercessions, of the whole choir of the angels, O Lord grant us, the forgiveness of our sins.", ar: "بشفاعات، جميع صفوف الملائكة، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Apostles)", ar: "(لأجل الرسل)" } },
      { kind: 'doxology', text: { en: "Our fathers the Apostles, preached unto the nations, the Gospel, of Jesus Christ.", ar: "آباؤنا الرسل، بشروا في الأمم، بإنجيل، يسوع المسيح." } },
      { kind: 'doxology', text: { en: "Their voices went forth, into all the earth, and their words have reached, the ends of the world.", ar: "خرجت أصواتهم، إلى الأرض كلها، وبلغ كلامهم، إلى أقطار المسكونة." } },
      { kind: 'doxology', text: { en: "Through the prayers, of my masters the fathers the Apostles, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، سادتي الآباء الرسل، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Martyrs)", ar: "(لأجل الشهداء)" } },
      { kind: 'doxology', text: { en: "Unfading crowns, the Lord has placed, upon the whole choir, of the martyrs.", ar: "أكاليل غير مضمحلة، جعلها الرب، على جميع، صفوف الشهداء." } },
      { kind: 'doxology', text: { en: "He saved and delivered them, because they took refuge in Him, they celebrated with Him, in His kingdom.", ar: "أنقذهم وخلصهم، لأنهم إلتجأوا إليه، وعيدوا معه، في ملكوته." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the martyrs, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، جميع صفوف الشهداء، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Saints)", ar: "(لأجل القديسين)" } },
      { kind: 'doxology', text: { en: "Your saints bless You, and they speak, of the glory, of Your kingdom.", ar: "قديسوك، يباركونك، وينطقون بمجد، ملكوتك." } },
      { kind: 'doxology', text: { en: "Your kingdom O my God, is an eternal kingdom, and Your Lordship, is unto all ages.", ar: "ملكوتك يا إلهي، ملكوت أبدي، وربوبيتك، إلى كل الأجيال." } },
      { kind: 'doxology', text: { en: "Through the prayers, of the whole choir of the cross-bearers, the righteous and the just, O Lord grant us, the forgiveness of our sins.", ar: "بصلوات، كافة مصاف لابسي الصليب، والأبرار والصديقين، يا رب إنعم لنا، بمغفرة خطايانا." } },
      { kind: 'doxology', text: { en: "(For the Patriarchs and the Prophets)", ar: "(لأجل الآباء والأنبياء)" } },
      { kind: 'doxology', text: { en: "Hail to Elijah, the prophet of temperance, and Elisha, his elect disciple.", ar: "السلام لإيليا، النبي المتعفف، وإليشع، تلميذه المختار." } },
      { kind: 'doxology', text: { en: "The great Evangelist, of the land of Egypt, Mark the Apostle, the first prelate.", ar: "المبشر العظيم، في كورة مصر، مرقس الرسول، مدبرها الأول." } },
      { kind: 'doxology', text: { en: "You are the Mother of God, O Virgin Mary, ask Him on our behalf, to have mercy upon our race.", ar: "أنت هي أم الله، يا مريم العذراء، أُطلبي منه عنا، أن يرحم جنسنا." } },
      { kind: 'doxology', text: { en: "The great patriarch, our father Abba Severus, whose holy teachings, enlightened our minds.", ar: "البطريرك العظيم، أبونا أنبا ساويرس، الذي أنارت تعاليمه، المقدسة عقولنا." } },
      { kind: 'doxology', text: { en: "Our father the confessor, Abba Dioscorus, defended the faith, against the heretics.", ar: "أبونا المعترف، أنبا ديسقوروس، حارب عن الإيمان، ضد الهراطقة." } },
      { kind: 'doxology', text: { en: "And all of our fathers, who have pleased the Lord, may their holy blessings, be a guard unto us.", ar: "وكل آبائنا، الذين أرضوا الرب، بركتهم المقدسة، تكون لنا حارساً." } },
      { kind: 'doxology', text: { en: "Through their prayers, O God grant us, the forgiveness of our sins, and give us peace.", ar: "بصلواتهم، إنعم لنا يا الله، بمغفرة خطايانا، وأعطنا سلاماً." } }
    ],
  }
];
